const ARTISTS = [
  // ===== NU METAL / ALT METAL / GROOVE =====
  { name: "Five Finger Death Punch", genre: "Groove / Alt Metal", desc: "Groove metal moderno, pesado y directo, con ganchos. Más formuláico que lo que sueles preferir, pero potente. Cercano a Disturbed.", origin: "lista", p: 4, y: 2005 },
  { name: "System of a Down", genre: "Nu Metal / Alt Metal", desc: "Caótico y político, con saltos bruscos de lo brutal a lo melódico dentro del mismo compás y escalas armenias en los riffs de Daron Malakian, que además canta contrapunto contra Serj Tankian en vez de coros. John Dolmayan cambia de patrón constantemente por debajo. Riqueza e imprevisibilidad altísimas en canciones de tres minutos. Entrada: Toxicity o Mezmerize.", origin: "lista", pick: true, p: 1, y: 1994 },
  { name: "Disturbed", genre: "Nu Metal / Alt Metal", desc: "Metal alternativo robusto y melódico. Más directo, menos experimental. Vibe cercano a FFDP.", origin: "lista", p: 4, y: 1994 },
  { name: "Korn", genre: "Nu Metal", desc: "Padres del nu metal: bajo de 7 cuerdas, groove enfermo y angustia. Cercano a Limp Bizkit, Coal Chamber, Mudvayne.", origin: "lista", p: 2, y: 1993 },
  { name: "Limp Bizkit", genre: "Nu Metal", desc: "Nu metal con rap, festivo y crudo. Menos sobre instrumental compleja, más sobre actitud.", origin: "lista", p: 4, y: 1994 },
  { name: "Mudvayne", genre: "Nu Metal", desc: "Ryan Martinie redefinió el bajo en el metal: polirritmias, compases impares, slaps y taps percusivos, dobles y triples cuerdas y arpegios melódicos, con técnica propia de tapping y afinaciones raras (F# B F# B E). El bajo va por delante de la guitarra en la mezcla y lleva las líneas principales. Entrada: L.D. 50.", origin: "lista", pick: true, p: 1, y: 1996 },
  { name: "Coal Chamber", genre: "Nu Metal", desc: "Nu metal gótico de los 90. Atmosférico y oscuro. Cercano a Korn temprano.", origin: "lista", p: 3, y: 1993 },
  { name: "Mushroomhead", genre: "Nu Metal / Industrial", desc: "Nu metal con máscaras, teclados e industrial. Comparado siempre con Slipknot pero más experimental y teatral.", origin: "lista", p: 3, y: 1993 },
  { name: "Static-X", genre: "Industrial Metal", desc: "Metal industrial 'evil disco': ritmos mecánicos y veloces. Cercano a Rob Zombie.", origin: "lista", p: 3, y: 1994 },
  { name: "Rob Zombie", genre: "Industrial Metal", desc: "Metal industrial con estética de cine de terror: samples de películas usados como parte del arreglo, groove pegajoso y producción muy comprimida. La escritura por debajo es de canción con estribillo. Entrada: Hellbilly Deluxe.", origin: "lista", p: 3, y: 1997 },
  { name: "Rammstein", genre: "Industrial Metal", desc: "Industrial alemán (Neue Deutsche Härte): riffs pesados, teatralidad operística y humor oscuro. Único. Cada disco tiene su carácter.", origin: "lista", pick: true, p: 3, y: 1994 },
  { name: "Sevendust", genre: "Alt Metal", desc: "Metal alternativo de groove con la voz de Lajon Witherspoon, que canta con fraseo de soul en lugar de gritar, sobre riffs graves a medio tiempo y la batería de Morgan Rose muy adelante en la mezcla. Melódico y pesado a la vez, dentro de una estructura de canción bastante fija. Entrada: Home.", origin: "lista", p: 3, y: 1994 },
  { name: "Sick Puppies", genre: "Alt Rock / Alt Metal", desc: "Rock alternativo australiano melódico y de gancho fácil, con estructura de estrofa y estribillo y producción de radio. Trío de guitarra, bajo y batería sin adornos. Está en nivel de contexto porque es lo más directo y menos ambicioso de esta sección. Entrada: Tri-Polar.", origin: "lista", p: 4, y: 1997 },

  // ===== EXPERIMENTAL / AVANT-GARDE / FUNK ROCK =====
  { name: "Mr. Bungle", genre: "Avant-garde / Experimental", desc: "Los cortes están escritos, no improvisados: cada sección dura pocos compases y encaja con la siguiente por métrica, no por transición, con arreglos de viento y percusión escritos nota a nota sobre esos saltos. Mr. Bungle (1991) es funk metal de circo, Disco Volante (1995) lo lleva al extremo, California (1999) ordena esa técnica en canciones, y The Raging Wrath of the Easter Bunny Demo (2020), con Dave Lombardo y Scott Ian, regraba su demo thrash de 1986 con una precisión brutal. Entrada: California, luego Disco Volante.", origin: "lista", pick: true, p: 1, y: 1985, c: 1 },
  { name: "Faith No More", genre: "Alt Metal / Experimental", desc: "Mike Patton usa la voz como instrumento con un rango absurdo, pasando de crooner a grito gutural dentro de un compás. Angel Dust salta de rap a lounge, a funk, a metal y a coros infantiles sin transición, con Mike Bordin tocando una batería de pulso tribal y platos abiertos que no se parece a la de nadie del género. Entrada: Angel Dust.", origin: "lista", pick: true, p: 1, y: 1979, c: 1 },
  { name: "Frank Zappa", genre: "Avant-garde / Experimental", desc: "Escribía partitura completa para banda de rock, con métricas que cambian compás a compás y líneas al unísono entre guitarra, marimba y vientos que hay que leer, no sacar de oído, con baterías como Terry Bozzio o Vinnie Colaiuta tocando esa escritura. De Hot Rats (1969) a The Grand Wazoo, Over-Nite Sensation, Apostrophe ('), One Size Fits All y Joe's Garage (1979) hay una década de discos a altísimo nivel cruzando rock, jazz y orquestal. En los ochenta baja mucho, entre discos de humor de estudio y el Synclavier (Thing-Fish es lo más flojo), y cierra con The Yellow Shark (1993), escrito para el Ensemble Modern. Entrada: Hot Rats o One Size Fits All.", origin: "lista", pick: true, p: 1, y: 1966, c: 1 },
  { name: "Dog Fashion Disco", genre: "Avant-garde Metal", desc: "Metal experimental teatral de Maryland: saxo, teclados de cabaret, saltos de género dentro de la canción y la voz de Todd Smith como narrador, en la órbita de Mr. Bungle pero con estructura más cercana al metal alternativo. The Embryo's in Bloom (1999), Anarchists of Good Taste (2001) y Committed to a Bright Future (2003). Entrada: Anarchists of Good Taste.", p: 3, origin: "lista", pick: true, y: 1995 },
  { name: "Pinkly Smooth", genre: "Avant-garde / Experimental", desc: "Vodevil oscuro y excéntrico: cabaret macabro con cambios de compás, piano de circo y estructuras que se descosen. Un solo EP, y no se parece a nada de lo que hicieron sus miembros después.", p: 3, origin: "lista", pick: true, y: 2001 },
  { name: "Fishbone", genre: "Funk / Ska / Punk", desc: "Ska, funk, punk, metal y soul cruzados a velocidad frenética, con una sección de vientos muy apretada y el bajo de Norwood Fisher al frente. Truth and Soul (1988) y The Reality of My Surroundings (1991) son la cumbre; desde mediados de los noventa bajan. Influyeron en Red Hot Chili Peppers y No Doubt. Entrada: The Reality of My Surroundings.", origin: "lista", p: 2, y: 1979 },
  { name: "Oingo Boingo", genre: "New Wave / Experimental", desc: "La banda de Danny Elfman antes del cine: new wave teatral con sección de vientos, ritmos nerviosos que cambian de pulso y arreglos que ya apuntan a sus bandas sonoras. Only a Lad (1981), Nothing to Fear y Good for Your Soul (1983) son lo más afilado; desde mediados de los ochenta se vuelven más pop y bajan. Entrada: Nothing to Fear.", origin: "lista", p: 2, y: 1979 },
  { name: "Red Hot Chili Peppers", genre: "Funk Rock", desc: "Funk rock con el bajo de Flea al frente, slap y líneas melódicas, y la guitarra de John Frusciante. Blood Sugar Sex Magik (1991), Californication (1999) y By the Way (2002) son la cumbre; los discos de los ochenta y los últimos bajan. Entrada: Blood Sugar Sex Magik.", origin: "lista", p: 3, y: 1983 },
  { name: "Thundercat", genre: "Jazz / Funk", desc: "Toca armonía de jazz completa en un bajo de seis cuerdas, acordes y no solo líneas, a velocidad de fusión y con groove de funk, mientras canta en falsete por encima. Y lo mantiene disco a disco: Apocalypse, Drunk, It Is What It Is y Distracted (abril de 2026) son el mismo planteamiento con distinta paleta. Entrada: Drunk o Apocalypse.", origin: "lista", pick: true, p: 1, y: 2011 },

  // ===== PROG ROCK / PROG METAL CLÁSICO =====
  { name: "Pink Floyd", genre: "Prog Rock", desc: "Gilmour toca doblando y sosteniendo notas largas en vez de acumular velocidad, dejando huecos enormes; Nick Mason toca contenido y muy atrás, casi sin adornos, y esa quietud es la que sostiene las piezas largas; Roger Waters escribe líneas de bajo simples y repetitivas que hacen de ancla mientras todo lo demás se mueve encima. De Meddle a The Dark Side of the Moon a Wish You Were Here y Animals, cinco discos seguidos con esa misma lógica de espacio. Entra por Wish You Were Here.", origin: "lista", pick: true, p: 1, y: 1965 },
  { name: "Yes", genre: "Prog Rock", desc: "Chris Squire toca un bajo Rickenbacker con púa y sonido metálico y agudo, tan al frente que funciona como segunda guitarra, y Bill Bruford aporta un fraseo de jazz con acentos desplazados. Encima, Wakeman con varios teclados a la vez y armonías vocales a tres voces. Fragile, Close to the Edge y Relayer son tres discos seguidos con suites de veinte minutos que se desarrollan de verdad. Entra por Close to the Edge.", origin: "lista", pick: true, p: 1, y: 1968 },
  { name: "Genesis", genre: "Prog Rock", desc: "En la era Gabriel: Tony Banks escribe en los teclados como si fueran la sección principal, Steve Hackett usaba tapping a dos manos años antes de que se popularizara, y Phil Collins toca la batería con formación de jazz mientras Gabriel narra personajes. Supper's Ready son veintitrés minutos en siete secciones encadenadas. Luego viraron a pop de estadio con Collins cantando, y ahí se parte la banda en dos según a quién preguntes. Entrada: Selling England by the Pound o Foxtrot.", origin: "lista", p: 2, y: 1967 },
  { name: "Rush", genre: "Prog Rock", desc: "Trío donde los tres son solistas a la vez: Neil Peart toca una batería enorme con arreglos escritos como composición y no como base, Geddy Lee canta agudísimo mientras toca líneas de bajo independientes y pedales de sintetizador con los pies, y Lifeson rellena con acordes abiertos. Compases impares constantes y suites largas. Entrada: Moving Pictures o Hemispheres.", origin: "lista", pick: true, p: 1, y: 1968 },
  { name: "Tool", genre: "Prog Metal", desc: "Los compases raros no son adorno: Danny Carey monta patrones que se cruzan con el bajo en ciclos que tardan varios compases en volver a coincidir, y las piezas se levantan por acumulación durante diez minutos antes de estallar. De Ænima (1996) a Lateralus, 10,000 Days y Fear Inoculum (2019) lo sostienen; Undertow (1993), el debut, todavía es metal alternativo más directo. Entrada: Lateralus.", origin: "lista", pick: true, p: 1, y: 1990, c: 2 },
  { name: "A Perfect Circle", genre: "Prog / Alt Metal", desc: "El proyecto más melódico de Maynard James Keenan y Billy Howerdel: rock alternativo oscuro y elegante, sin la complejidad rítmica de Tool. Entrada: Mer de Noms.", p: 3, origin: "lista", pick: true, y: 1999 },
  { name: "Porcupine Tree", genre: "Prog Rock / Metal", desc: "Prog moderno de Steven Wilson: producción limpísima y melódica con punzadas pesadas, y desde 2002 Gavin Harrison a la batería tocando polirritmias y desplazamientos de acento por debajo de riffs aparentemente simples. De The Sky Moves Sideways (1995) a Stupid Dream, Lightbulb Sun, In Absentia, Deadwing y Fear of a Blank Planet (2007) encadenan seis discos a gran nivel, pasando del space rock al prog metal; The Incident (2009) y Closure/Continuation (2022) bajan un escalón sin romper la línea. Entrada: In Absentia o Fear of a Blank Planet.", origin: "lista", pick: true, p: 1, y: 1987, c: 2 },
  { name: "Opeth", genre: "Prog Death / Prog Rock", desc: "Death metal y prog setentero dentro del mismo tema, con Åkerfeldt pasando de gutural a voz limpia y de riff pesado a guitarra acústica sin costura, y Martín López tocando una batería de raíz latina y jazz en vez de blast beats. De Orchid (1995) a Still Life, Blackwater Park (2001), Deliverance, Damnation, Ghost Reveries y Watershed (2008) es una racha enorme; Heritage (2011) abandona los guturales por el prog rock y es el más discutido, y The Last Will and Testament (2024) los recupera. Entrada: Blackwater Park.", origin: "lista", pick: true, p: 1, y: 1990 },
  { name: "Arcturus", genre: "Avant-garde Black / Prog", desc: "Black noruego convertido en metal teatral: teclados sinfónicos llevando la armonía, cambios de sección bruscos y la voz operística de Garm en La Masquerade Infernale (1997), que sigue siendo de lo más raro del metal. Sideshow Symphonies y Arcturian (2015) mantienen la excentricidad con otra formación. Entrada: La Masquerade Infernale.", origin: "lista", p: 2, y: 1991, c: 1 },

  // ===== PROG METAL MODERNO (la veta Dream Theater / Haken) =====
  { name: "Haken", genre: "Prog Metal", desc: "Prog metal moderno y técnico, con humor deliberado: alternan secciones de djent con pasajes de piano y armonías vocales a varias voces, y cada disco cambia de enfoque (The Mountain es narrativo, Affinity imita la producción de los ochenta). Aquarius (2010), Visions y The Mountain (2013) son la cumbre, y Affinity y Fauna (2023) están cerca; la pareja Vector y Virus, más pesada y de riff más directo, es lo único que baja. Entrada: The Mountain.", origin: "lista", pick: true, p: 1, y: 2007, c: 2 },
  { name: "Caligula's Horse", genre: "Prog Metal", desc: "Australianos: Sam Vallen escribe guitarras en compases cambiantes con legato y contrapunto, y los temas se construyen en arcos largos bajo la voz de Jim Grey. Bloom (2015), In Contact (2017) y Charcoal Grace (2024). Entrada: In Contact.", p: 2, origin: "lista", pick: true, y: 2011 },
  { name: "Leprous", genre: "Prog Metal", desc: "Riffs en compases impares que se resuelven tarde, con la batería de Baard Kolstad (desde 2014) desplazando el acento respecto a la guitarra y, desde Malina, un chelo integrado como voz armónica: la tensión se construye por acumulación rítmica, no por volumen. De Tall Poppy Syndrome (2009) a Bilateral, Coal, The Congregation, Malina y Pitfalls (2019) son seis discos seguidos al mismo nivel, cada uno con su enfoque. Aphelion (2021) y Melodies of Atonement (2024) simplifican hacia un rock más electrónico y son lo más flojo. Entrada: The Congregation, luego Coal.", origin: "lista", pick: true, p: 1, y: 2001, c: 1 },
  { name: "Einar Solberg", genre: "Prog / Art", desc: "Prog sinfónico de cámara con orquesta y cuerdas escritas, y capas vocales de una complejidad real: 16 (2023) y Vox Occulta (2026). Entrada: 16.", origin: "lista", p: 2, y: 2023 },
  { name: "Devin Townsend", genre: "Prog Metal / Experimental", desc: "La sustancia es la arquitectura del sonido: decenas de capas de guitarra y coro apiladas hasta formar un muro con armonía interna, no ruido. En Strapping Young Lad esa pared va sobre el doble bombo compositivo de Gene Hoglan; en Ocean Machine y Empath la misma técnica se usa para pasajes ambientales y orquestales, y The Moth (2026) la lleva a otro disco conceptual. Entrada: Ocean Machine.", origin: "lista", pick: true, p: 1, y: 1996, c: 1 },
  { name: "Ayreon", genre: "Prog Metal / Rock Opera", desc: "Óperas rock de Arjen Lucassen con decenas de cantantes invitados y ciencia ficción épica: ambición de escala más que complejidad de escritura. Entrada: The Human Equation.", p: 3, origin: "lista", pick: true, y: 1995 },
  { name: "Symphony X", genre: "Prog / Power Metal", desc: "Prog metal neoclásico: Michael Romeo escribe líneas de guitarra de armonía barroca dobladas con el teclado, y los discos se organizan en suites largas, como The Divine Wings of Tragedy (veinte minutos) o The Odyssey (veinticuatro). Russell Allen aporta una voz potente de heavy clásico. Entrada: The Divine Wings of Tragedy.", p: 2, origin: "lista", pick: true, y: 1994 },
  { name: "Shadow Gallery", genre: "Prog Metal", desc: "Prog metal melódico de los noventa con suites largas, armonías vocales a varias voces y teclados sinfónicos: cuidado y ambicioso, pero dentro de la plantilla de Dream Theater. Entrada: Tyranny.", p: 3, origin: "lista", y: 1985 },
  { name: "Redemption", genre: "Prog Metal", desc: "Prog metal estadounidense denso y melódico, de temas largos y emotivos. Entrada: The Origins of Ruin.", p: 3, origin: "lista", y: 2001 },
  { name: "Pain of Salvation", genre: "Prog Metal", desc: "Daniel Gildenlöw escribe con un rango dinámico enorme dentro del mismo disco: del riff pesado en compás impar a la guitarra acústica y la voz desnuda sin que suene a collage, con la voz como instrumento principal y la instrumental moviéndose debajo en métricas cambiantes. Entropia (1997), One Hour by the Concrete Lake, The Perfect Element, Remedy Lane y Be (2004), con orquesta, son cinco discos seguidos a ese nivel. Scarsick y los dos Road Salt bajan a un rock setentero más directo, e In the Passing Light of Day (2017) y Panther (2020) recuperan la tensión. Entrada: Remedy Lane.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Threshold", genre: "Prog Metal", desc: "Prog metal británico melódico y robusto, de riff sólido y estribillos grandes: consistente, pero de estructura clásica. Entrada: Subsurface.", p: 3, origin: "lista", y: 1988 },
  { name: "Vanden Plas", genre: "Prog Metal", desc: "Prog metal alemán teatral y melódico (han escrito para musicales), con teclados y voz dramática: competente dentro del molde. Entrada: Christ 0.", p: 3, origin: "lista", y: 1986 },
  { name: "Daydream XI", genre: "Prog Metal", desc: "Prog metal brasileño moderno, dramático y técnico, en la escuela de Dream Theater y Symphony X. Entrada: The Grand Disguise.", p: 3, origin: "lista", y: 2010 },
  { name: "Circus Maximus", genre: "Prog Metal", desc: "Prog metal noruego melódico y accesible, con buena voz y estructura cercana a Dream Theater. Entrada: Isolate.", p: 3, origin: "lista", y: 2000 },
  { name: "Fates Warning", genre: "Prog Metal", desc: "Prog metal de Connecticut que se volvió propio con Ray Alder a la voz y con dos baterías de primera: Mark Zonder, que en Perfect Symmetry y Parallels cambia de subdivisión bajo riffs contenidos, y Bobby Jarzombek desde 2007. A Pleasant Shade of Gray (1997) es una sola pieza de más de cincuenta minutos. Obra cerrada y sostenida durante trece discos, hasta Long Day Good Night (2020), el último. Más sobrios que Dream Theater, con la tensión en la estructura y no en el virtuosismo. Entrada: Parallels.", origin: "lista", p: 1, y: 1982 },
  { name: "Transatlantic", genre: "Prog Rock", desc: "Supergrupo prog (Mike Portnoy, Neal Morse...). Suites épicas larguísimas en clave 70s moderna.", origin: "lista", p: 3, y: 1999 },
  { name: "Seventh Wonder", genre: "Prog Metal", desc: "Prog metal sueco luminoso con la voz de Tommy Karevik y un bajo melódico que se deja oír: técnico, pero de canción clásica. Entrada: Mercy Falls.", p: 3, origin: "lista", pick: true, y: 2000 },
  { name: "Flying Colors", genre: "Prog Rock / Pop", desc: "Supergrupo prog accesible y melódico (Steve Morse, Mike Portnoy), pero el material es prog amable con ganchos pop: la ambición instrumental está muy por debajo de lo que hacen esos mismos músicos en Dixie Dregs o Dream Theater. El cartel no compensa la falta de complejidad.", origin: "lista", p: 3, y: 2011 },
  { name: "Art by Numbers", genre: "Prog Metal", desc: "Prog metal técnico de Fresno, California, con influencias de jazz en los solos y estructura de canción larga: competente dentro del molde del género.", p: 3, origin: "lista", y: 2009 },

  // ===== DJENT / PROG TÉCNICO MODERNO (veta Periphery) =====
  { name: "Tesseract", genre: "Djent / Prog", desc: "Djent atmosférico: riffs sincopados en métricas largas sobre la batería de Jay Postones, que desplaza acentos bajo guitarras de sostenido, y la voz limpia de Daniel Tompkins flotando por encima. De One (2011) a Altered State y War of Being (2023) han ido ganando espacio y textura. Entrada: Altered State.", p: 2, origin: "lista", pick: true, y: 2003 },
  { name: "Monuments", genre: "Djent / Prog", desc: "Djent británico de riff sincopado y groove, con ganchos melódicos y voz limpia potente: técnico, pero dentro del molde que definieron Periphery y Tesseract. Entrada: The Amanuensis.", p: 3, origin: "lista", y: 2010, c: 2 },
  { name: "Erra", genre: "Metalcore / Djent", desc: "Metalcore progresivo con djent: riffs de ocho cuerdas en métricas desplazadas, guitarras melódicas en capas y alternancia de voz limpia y gritada. Muy parejos de Augment (2013) a Drift, Neon, Erra, Cure (2024) y Silence Outlives the Earth (marzo de 2026). Entrada: Neon.", p: 2, origin: "lista", pick: true, y: 2009 },
  { name: "Animals as Leaders", genre: "Prog / Instrumental", desc: "Instrumental puro, sin una sola voz: Tosin Abasi usa el thumping y el tapping a dos manos como técnica compositiva, sobre armonía de jazz en métrica desplazada, y desde The Joy of Motion Matt Garstka toca a la batería subdivisiones que se cruzan con las guitarras en vez de seguirlas. Del debut (2009) a Weightless, The Joy of Motion (2014) y Parrhesia (2022) cambian de paleta, más electrónica o más acústica, sin bajar la exigencia; The Madness of Many (2016) es el menos redondo. Entrada: The Joy of Motion.", origin: "lista", pick: true, p: 1, y: 2007, c: 2 },
  { name: "The Contortionist", genre: "Prog Metal / Djent", desc: "Empezaron en deathcore técnico y acabaron en prog atmosférico con teclados y voz limpia, cambiando de sonido cada disco hasta volverse irreconocibles. Language es el punto de giro. Entrada: Language.", p: 2, origin: "lista", pick: true, y: 2007, c: 1 },
  { name: "Sikth", genre: "Tech Metal / Mathcore", desc: "Dos vocalistas que no se turnan sino que se solapan y se contestan dentro de la misma frase, uno gritando y otro hablando o cantando agudo, sobre riffs de guitarra que saltan entre intervalos incómodos con la batería subdividiendo por debajo en otra métrica. Suena desordenado y está escrito al milímetro. Británicos. Entra por The Trees Are Dead & Dried Out Wait for Something Wild.", origin: "rec", p: 1, y: 1999, c: 2 },
  { name: "Intronaut", genre: "Prog / Post Metal", desc: "Metal progresivo de Los Ángeles donde los dos instrumentos que suelen acompañar son los que llevan: el bajo de Joe Lester toca líneas melódicas y acordes en lugar de raíces, y la batería de fraseo jazzístico (Danny Walker hasta 2018, luego Alex Rüdinger) conduce los cambios, sobre riffs de post-metal. Seis discos y ninguno baja: Void (2006), Prehistoricisms, Valley of Smoke, Habitual Levitations, The Direction of Last Things y Fluid Existential Inversions (2020). Entrada: Valley of Smoke, luego Prehistoricisms.", origin: "lista", p: 1, y: 2004 },
  { name: "Mandroid Echostar", genre: "Prog Metal", desc: "Prog metal de Guelph, Ontario, técnico y melódico, con historias de ciencia ficción de cómic. Coral Throne es su disco largo.", p: 3, origin: "lista", y: 2010 },
  { name: "Corelia", genre: "Prog Metal / Djent", desc: "Djent melódico de San Diego: riffs sincopados y voz limpia muy al frente, dentro del molde del género.", p: 3, origin: "lista", y: 2010 },
  { name: "The Human Abstract", genre: "Prog Metalcore", desc: "Metalcore técnico con guitarra neoclásica de verdad, con arpegios y contrapunto barroco dentro del riff, y estructuras progresivas. Nocturne (2006) y Digital Veil (2011) son lo mejor; Midheaven (2008), más convencional, es el bajón. Entrada: Digital Veil.", origin: "lista", p: 2, y: 2004 },

  // ===== METALCORE / POST-HARDCORE (veta Avenged / Trivium) =====
  { name: "Trivium", genre: "Metalcore / Thrash", desc: "Metalcore y thrash con muchísima técnica de guitarra: Matt Heafy y Corey Beaulieu trabajan armonías gemelas y solos largos, y en Shogun (2008) llevan la ambición estructural más lejos, con temas de diez minutos. Evolucionan mucho entre discos. Tu mapa: te quedas con Ascendancy, The Crusade, Shogun, In Waves e In the Court of the Dragon, y Vengeance Falls y Silence in the Snow te parecieron metal de fórmula aburrido; The Sin and the Sentence (2017) y What the Dead Men Say (2020) están en la línea buena. Desde octubre de 2025 el batería es Alex Rüdinger. Entrada: Shogun o Ascendancy.", origin: "heard", p: 1, y: 1999, c: 1 },
  { name: "All That Remains", genre: "Metalcore", desc: "Metalcore melódico de Massachusetts con los solos de Oli Herbert, que murió en 2018, como mejor argumento; el resto es estribillo y estructura de manual. Entrada: The Fall of Ideals.", p: 3, origin: "lista", y: 1998 },
  { name: "Parkway Drive", genre: "Metalcore", desc: "Metalcore australiano que fue creciendo hacia lo épico y melódico: Horizons (2007) y Deep Blue son su mejor metalcore, e Ire (2015) y Reverence lo abren a un heavy más grande y más simple. Entrada: Horizons.", p: 3, origin: "lista", y: 2003 },
  { name: "Bury Tomorrow", genre: "Metalcore", desc: "Metalcore británico melódico con equilibrio de voz limpia y gutural, sólido y dentro del molde. Entrada: Cannibal.", p: 3, origin: "lista", y: 2006 },
  { name: "August Burns Red", genre: "Metalcore", desc: "Metalcore técnico de los más instrumentales del género: JB Brubaker y Brent Rambler escriben riffs que cambian de compás dentro del estribillo y Matt Greiner mete fills con acentos desplazados donde el género pone un breakdown recto. Muy parejos de Thrill Seeker (2005) y Constellations (2009), la cumbre, a Leveler, Found in Far Away Places, Phantom Anthem, Death Below y Season of Surrender (junio de 2026). Entrada: Constellations.", p: 2, origin: "lista", pick: true, y: 2003 },
  { name: "Bring Me the Horizon", genre: "Metalcore / Alt", desc: "De deathcore brutal a pop-rock electrónico: pocos han cambiado tanto de disco a disco. Count Your Blessings (2006) es lo más flojo; Suicide Season, There Is a Hell... y Sempiternal (2013), con Jordan Fish integrando teclados y electrónica, son la cumbre metalcore; That's the Spirit y amo lo llevan al pop y Post Human: Nex Gen (2024) vuelve a mezclarlo todo. En 2026 regrabaron Count Your Blessings. Entrada: Sempiternal.", origin: "lista", pick: true, p: 2, y: 2004, c: 1 },
  { name: "Motionless in White", genre: "Metalcore / Industrial", desc: "Metalcore gótico e industrial con teclados al frente y estética muy marcada: ganchos claros y estructura de estrofa y estribillo, sin ambición instrumental. Entrada: Graveyard Shift.", p: 3, origin: "lista", y: 2005 },
  { name: "Of Mice & Men", genre: "Metalcore", desc: "Metalcore melódico californiano con alternancia de limpio y gutural, accesible y de estructura directa. Entrada: Restoring Force.", p: 3, origin: "lista", y: 2009 },
  { name: "Beartooth", genre: "Hardcore / Metalcore", desc: "Hardcore melódico y metalcore de Ohio, enérgico y catártico, de estructura directa de estribillo. Entrada: Disgusting.", p: 3, origin: "lista", y: 2012 },
  { name: "A Day to Remember", genre: "Pop Punk / Metalcore", desc: "Pop punk con breakdowns de metalcore y estribillos pegajosos: híbrido divertido y muy sencillo por dentro. Entrada: Homesick.", origin: "lista", p: 4, y: 2003 },
  { name: "Architects", genre: "Metalcore", desc: "Metalcore británico técnico que fue puliendo un sonido enorme y atmosférico, con la batería de Dan Searle como motor. El mapa es desigual: los primeros discos son más verdes, Lost Forever // Lost Together (2014), All Our Gods Have Abandoned Us (2016) y Holy Hell (2018), tras la muerte de Tom Searle, son la cumbre, y desde For Those That Wish to Exist (2021) a The Sky, the Earth & All Between (2025) giran a algo más directo y bajan. Entrada: All Our Gods Have Abandoned Us.", p: 2, origin: "lista", pick: true, y: 2004, c: 1 },
  { name: "While She Sleeps", genre: "Metalcore", desc: "Metalcore británico enérgico, de riffs grandes y espíritu comunitario: You Are We (2017) es lo mejor y los últimos discos bajan. Entrada: You Are We.", p: 3, origin: "lista", y: 2006 },
  { name: "The Devil Wears Prada", genre: "Metalcore", desc: "Metalcore de Ohio con teclados atmosféricos que ha madurado su sonido: With Roots Above and Branches Below (2009) y los EP Zombie y Space son lo mejor, bien escritos pero dentro del molde. Entrada: With Roots Above and Branches Below.", p: 3, origin: "lista", y: 2005 },
  { name: "Fit for a King", genre: "Metalcore", desc: "Metalcore moderno de Texas, melódico y pesado, consistente y bien producido, dentro de la plantilla. Entrada: The Path.", p: 3, origin: "lista", y: 2007 },
  { name: "Miss May I", genre: "Metalcore", desc: "Metalcore melódico clásico de los 2010, con pegada y estructura de manual. Entrada: Apologies Are for the Weak.", origin: "lista", p: 4, y: 2007 },
  { name: "Light the Torch", genre: "Metalcore / Hard Rock", desc: "El proyecto de Howard Jones, ex Killswitch Engage: metalcore melódico con el peso en los estribillos y la voz limpia. Entrada: Revival.", p: 3, origin: "lista", y: 2012 },
  { name: "War of Ages", genre: "Metalcore", desc: "Metalcore de Pensilvania con solos melódicos y buen trabajo de guitarra, dentro de la plantilla del género. Entrada: Fire from the Sky.", p: 3, origin: "lista", y: 2002 },
  { name: "Demon Hunter", genre: "Metalcore / Alt Metal", desc: "Metalcore de Seattle que va de lo brutal a baladas con estribillos grandes, con identidad propia pero estructura clásica de canción. Entrada: The Triptych.", p: 3, origin: "lista", y: 2000 },
  { name: "Shadows Fall", genre: "Metalcore / Thrash", desc: "Metalcore de Massachusetts con raíz thrash y solos melódicos, de la ola de Nueva Inglaterra: guitarras gemelas bien trabajadas dentro de una estructura clásica de estrofa y estribillo. Entrada: The War Within.", p: 3, origin: "lista", y: 1996 },
  { name: "Bad Wolves", genre: "Alt Metal / Metalcore", desc: "Metal moderno melódico de ganchos radiables, muy accesible y sin ambición instrumental. Entrada: Disobey.", origin: "lista", p: 4, y: 2017 },
  { name: "I Prevail", genre: "Metalcore", desc: "Metalcore moderno con electrónica y estribillos pop, energía y gancho, muy simple por dentro. Entrada: Trauma.", origin: "lista", p: 4, y: 2013 },
  { name: "Asking Alexandria", genre: "Metalcore", desc: "De metalcore con electrónica a rock más convencional; en todas sus etapas la escritura es de estribillo y breakdown, sin ambición instrumental. Entrada: Stand Up and Scream.", origin: "lista", p: 4, y: 2008 },
  { name: "Disciple", genre: "Hard Rock / Metalcore", desc: "Rock y metal cristiano de Tennessee, melódico y enérgico, de estructura radiable y muy simple por dentro. Entrada: Scars Remain.", origin: "lista", p: 4, y: 1992 },
  { name: "The Raven Age", genre: "Metalcore / Melodic", desc: "Metalcore melódico británico con guitarras gemelas y ambiente, de estructura clásica de canción. Entrada: Darkness Will Rise.", p: 3, origin: "lista", y: 2009 },
  { name: "Bleed from Within", genre: "Metalcore", desc: "Metalcore escocés moderno, técnico y con groove, muy sólido en los últimos discos, Fracture (2020) y Zenith (2022), pero de estructura estándar. Entrada: Fracture.", p: 3, origin: "lista", y: 2005 },
  { name: "Hope for the Dying", genre: "Prog Metalcore / Death", desc: "Metalcore progresivo y sinfónico con death melódico, de estructuras largas y teclados, ambicioso pero dentro del molde. Entrada: Aletheia.", p: 3, origin: "lista", y: 2006 },
  { name: "Blinded by Faith", genre: "Melodic Death / Symphonic", desc: "Death sinfónico melódico canadiense. Oscuro y orquestal.", origin: "lista", p: 3, y: 1996 },

  // ===== POST-HARDCORE / SCREAMO / MELÓDICO RARO =====
  { name: "Underoath", genre: "Post-Hardcore", desc: "Post-hardcore y metalcore de Florida con teclados y atmósfera, y la batería de Aaron Gillespie cantando a la vez. Define the Great Line (2006) y Lost in the Sound of Separation (2008), densos y oscuros, son la cumbre, y Ø (Disambiguation) (2010) está cerca; los primeros discos son más verdes y desde Erase Me (2018) a The Place After This One (2025) giran a algo más directo y bajan. Entrada: Define the Great Line.", origin: "lista", p: 2, y: 1997 },
  { name: "Chiodos", genre: "Post-Hardcore", desc: "Post-hardcore teatral de Michigan con piano, dramatismo y la voz aguda de Craig Owens: cambios de sección dinámicos dentro de canciones de estribillo. Entrada: Bone Palace Ballet.", p: 3, origin: "lista", y: 2001 },
  { name: "Alesana", genre: "Post-Hardcore / Screamo", desc: "Post-hardcore narrativo y teatral de Carolina del Norte con conceptos literarios, tres guitarras y dos voces, dentro de la estructura del género. Entrada: The Emptiness.", p: 3, origin: "lista", y: 2004 },
  { name: "Closure in Moscow", genre: "Prog / Post-Hardcore", desc: "Prog rock australiano excéntrico con groove: cambios de compás dentro del estribillo, falsete teatral y armonías que se van por sitios raros, todo con una ligereza que disimula lo complicado que es. Entrada: First Temple.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Fall of Troy", genre: "Post-Hardcore / Math", desc: "Trío donde Thomas Erak toca líneas de guitarra retorcidas y canta a la vez: estructuras caóticas, cambios de tempo constantes y tapping sobre disonancia. The Fall of Troy (2003), Doppelgänger (2005) y Manipulator (2007) son la cumbre; In the Unlikely Event (2009) baja claramente, y OK (2016) y Mukiltearth (2020) no vuelven a ese nivel. Entrada: Doppelgänger.", origin: "lista", pick: true, p: 2, y: 2002, c: 2 },
  { name: "Every Time I Die", genre: "Metalcore / Southern", desc: "Metalcore con groove sureño y riffs angulares mucho más raros de lo que aparentan: Jordan Buckley cruza blues sureño con disonancia caótica bajo las letras de Keith Buckley. Nueve discos muy parejos, de Last Night in Town (2001) y Hot Damn! a Gutter Phenomenon, The Big Dirty, Ex Lives, Low Teens (2016) y Radical (2021), el último: la banda se separó en enero de 2022. Entrada: Low Teens.", origin: "lista", p: 2, y: 1998 },
  { name: "Dance Gavin Dance", genre: "Post-Hardcore / Math", desc: "Post-hardcore con math rock y funk: la guitarra de Will Swan toca líneas de tapping y fraseo casi de jazz, bajo una voz limpia de soul y otra gritada. Downtown Battle Mountain (2007), el disco homónimo y Happiness (2009) son lo mejor; desde Instant Gratification la estructura se vuelve más fija y los últimos discos bajan. Entrada: Downtown Battle Mountain.", p: 3, origin: "rec", y: 2005, via: "PTH" },

  // ===== POWER / SYMPHONIC / FOLK METAL =====
  { name: "Helloween", genre: "Power Metal", desc: "Padres del power metal europeo: veloz, melódico, épico y optimista. Clásico fundacional.", origin: "lista", p: 2, y: 1984 },
  { name: "Blind Guardian", genre: "Power Metal", desc: "Hansi Kürsch graba su propia voz en decenas de capas hasta formar un coro entero él solo, y pasa de esos muros a línea solista limpia y a grito sin costura, mientras las guitarras hacen contrapunto a dos voces en vez de doblarse. Los discos están arreglados con detalle casi orquestal, con interludios acústicos y narrados que hacen de estructura. Entra por Nightfall in Middle-Earth o Somewhere Far Beyond.", origin: "rec", p: 1, y: 1984, c: 2 },
  { name: "Dragonforce", genre: "Power Metal", desc: "Power metal extremo: velocidad absurda y solos de videojuego. Diversión técnica.", origin: "lista", p: 3, y: 1999 },
  { name: "Sabaton", genre: "Power Metal", desc: "Power metal sobre historia bélica, himnos pegajosos. Cada disco, un tema histórico.", origin: "lista", pick: true, p: 3, y: 1999 },
  { name: "Nightwish", genre: "Symphonic Metal", desc: "Tuomas Holopainen escribe partes orquestales de verdad, grabadas con orquesta y coro reales, y ahí sí hay trabajo; pero lo que hay debajo son canciones de estrofa y estribillo de power metal, con la orquesta encima como capa y no como parte de la estructura. Cuando la voz cambió de operística (Tarja) a más rock (Floor Jansen) el esqueleto siguió siendo el mismo. Espectacular de producción, convencional de escritura. Entra por Once o Endless Forms Most Beautiful. (voz femenina)", origin: "rec", p: 2, y: 1996, c: 2, female: true },
  { name: "Unleash the Archers", genre: "Power Metal", desc: "Power metal con vocalista potentísima (Brittney Slayes) que canta limpio y épico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2007 },
  { name: "Holy Grail", genre: "Power / Thrash", desc: "Power-thrash con solos veloces y melódicos. Energía clásica.", origin: "lista", p: 3, y: 2008 },
  { name: "Imperanon", genre: "Melodic / Power Metal", desc: "Melodic metal finlandés veloz y técnico, con teclados. Raro de encontrar, en la veta Children of Bodom.", origin: "lista", p: 3, y: 1999 },
  { name: "Eluveitie", genre: "Folk Melodic Death", desc: "Melodeath de Gotemburgo con gaita, zanfona, violín y flautas celtas llevando la melodía por encima. La mezcla es vistosa, pero debajo el riff y la estructura son plantilla del género, y los instrumentos folk decoran más de lo que cambian. Spirit (2006) y Ategnatos (2019) son lo mejor; Ànv (2025) es el último. Entrada: Ategnatos.", origin: "lista", female: true, p: 3, y: 2002 },
  { name: "Alestorm", genre: "Folk / Pirate Metal", desc: "Power/folk metal pirata: divertido, festivo y autoconsciente. Para soltar.", origin: "lista", p: 4, y: 2004 },

  // ===== HEAVY / THRASH / CLÁSICO =====
  { name: "Black Sabbath", genre: "Heavy Metal (clásico)", desc: "Bill Ward se formó con bateristas de jazz y entra y sale del tempo en vez de clavarlo, con un swing que ninguna banda pesada tenía; Geezer Butler no dobla el riff, toca líneas propias por debajo; e Iommi construyó todo sobre el tritono, con las cuerdas destensadas para poder tocar tras perder las yemas de dos dedos. Y eso se sostiene seis discos seguidos, de Black Sabbath y Paranoid (1970) a Sabotage (1975), sin repetirse. Technical Ecstasy y Never Say Die bajan; con Dio, Heaven and Hell (1980) vuelve arriba, y la etapa con Tony Martin (Headless Cross, Tyr) está mejor de lo que se dice. Ozzy murió en julio de 2025, diecisiete días después del concierto de despedida en Birmingham con la formación original. Entrada: Master of Reality o Vol. 4.", origin: "rec", p: 1, y: 1968, c: 2 },
  { name: "Judas Priest", genre: "Heavy Metal (clásico)", desc: "Fijaron la plantilla de las dos guitarras armonizando en terceras que copió el género entero, con Halford cantando en un registro agudísimo por encima y una base rítmica que va recta y sin adornos. Las canciones son himnos de estructura simple y directa, hechos para corearse: esa claridad es su virtud y también su límite para lo que tú buscas. De Sad Wings of Destiny (1976) a Screaming for Vengeance, Defenders of the Faith y Painkiller (1990) está lo mejor; Turbo y Ram It Down bajan, y Firepower (2018) e Invincible Shield (2024) volvieron a buen nivel. Entrada: Painkiller o Sad Wings of Destiny.", origin: "rec", p: 2, y: 1969, c: 2 },
  { name: "Dio", genre: "Heavy Metal (clásico)", desc: "La voz de Ronnie James Dio, épica y de mucho rango, sobre heavy melódico con Vivian Campbell a la guitarra en los primeros discos. Holy Diver (1983) y The Last in Line (1984) son la cumbre, y Dream Evil, Strange Highways y Magica (2000) están cerca; Angry Machines (1996) baja. Murió en 2010. Entrada: Holy Diver.", origin: "lista", p: 2, y: 1982 },
  { name: "Ozzy Osbourne", genre: "Heavy Metal (clásico)", desc: "La carrera en solitario de Ozzy, con guitarristas que llevan el peso instrumental: Randy Rhoads en Blizzard of Ozz (1980) y Diary of a Madman (1981), con riffs y solos de armonía neoclásica, y luego Jake E. Lee y Zakk Wylde. De 1980 a No More Tears (1991) está a buen nivel; después baja mucho. Murió en julio de 2025. Entrada: Diary of a Madman.", origin: "lista", p: 2, y: 1979 },
  { name: "Grim Reaper", genre: "Heavy Metal (NWOBHM)", desc: "Heavy metal británico de los ochenta, directo y enérgico, de culto por la voz aguda de Steve Grimmett, muerto en 2022. Entrada: See You in Hell.", origin: "lista", p: 4, y: 1979 },
  { name: "Anthrax", genre: "Thrash Metal", desc: "Thrash neoyorquino con la batería de Charlie Benante como motor, doble bombo y cambios de figura muy rápidos, y riffs con groove de hardcore; pioneros del crossover con el rap. De Spreading the Disease (1985) a Persistence of Time (1990) está lo mejor; los noventa bajan y vuelven bien con Worship Music (2011) y For All Kings (2016). Cursum Perficio (18 de septiembre de 2026) es su primer disco en diez años. Entrada: Among the Living.", origin: "lista", p: 2, y: 1981 },
  { name: "Exodus", genre: "Thrash Metal", desc: "Thrash de la Bay Area de riff veloz y agresivo, con Gary Holt escribiendo casi todo: Bonded by Blood (1985) es un clásico del género, y Tempo of the Damned (2004) y Persona Non Grata (2021) están a buen nivel, siempre muy dentro del molde. Goliath (marzo de 2026) marca la vuelta de Rob Dukes a la voz. Entrada: Bonded by Blood.", origin: "lista", p: 2, y: 1979 },
  { name: "Slayer", genre: "Thrash Metal", desc: "El thrash más extremo y oscuro de los Big Four: tempos al límite, riffs cromáticos sin melodía y solos atonales de Hanneman y King que suenan a ruido controlado, con Lombardo tocando blast beats antes de que existiera el término. Directo y sin adornos, y esa crudeza es el punto. De Show No Mercy (1983) a Seasons in the Abyss (1990) está lo que importa; desde los noventa bajan. Entrada: Reign in Blood.", origin: "lista", p: 2, y: 1981 },
  { name: "Sepultura", genre: "Thrash / Groove", desc: "De thrash brutal a groove tribal: en Roots (1996) Igor Cavalera reconstruyó su forma de tocar alrededor de la percusión indígena brasileña, grabando con los Xavante, y el disco se afinó gravísimo para que el ritmo pesara más que el riff. De Schizophrenia (1987) a Arise (1991) está su thrash, y Chaos A.D. y Roots son el cambio; con Derrick Green bajan mucho, hasta Quadra (2020). Se despiden con el EP The Cloud of Unknowing (abril de 2026) y una gira que termina este año. Entrada: Chaos A.D. o Roots.", origin: "lista", pick: true, p: 2, y: 1984, c: 1 },
  { name: "Soulfly", genre: "Groove / Tribal Metal", desc: "El proyecto de Max Cavalera tras Sepultura: groove tribal con percusión y ritmos del mundo encima del riff, pesado y rítmico pero de escritura sencilla. Prophecy (2004) y Chama (2025) son lo mejor. Entrada: Prophecy.", origin: "lista", p: 3, y: 1997 },
  { name: "Exhorder", genre: "Thrash / Groove", desc: "Pioneros del groove metal, anteriores a Pantera en ese sonido: Slaughter in the Vatican (1990) mezcla thrash rapidísimo con los medios tiempos sincopados que luego definirían el género, y The Law (1992) va más a lo pesado. Volvieron con Mourn the Southern Skies (2019). Entrada: Slaughter in the Vatican.", origin: "lista", p: 3, y: 1985 },
  { name: "Hatebreed", genre: "Metalcore / Hardcore", desc: "Hardcore metálico de breakdowns y adrenalina: directo, catártico y deliberadamente simple. Entrada: Perseverance.", origin: "lista", p: 4, y: 1994 },
  { name: "Down", genre: "Sludge / Doom", desc: "Supergrupo de sludge sureño de Phil Anselmo, de riffs pantanosos y pesados y estructura directa. Entrada: NOLA.", origin: "lista", p: 4, y: 1991 },
  { name: "Crowbar", genre: "Sludge / Doom", desc: "Sludge de Nueva Orleans: lento, demoledor y emotivo, de pesadez física. Muy parejo; Odd Fellows Rest (1998) y Sonic Excess in Its Purest Form (2001) son lo mejor. Entrada: Odd Fellows Rest.", origin: "lista", p: 3, y: 1990 },

  // ===== DEATH METAL / TÉCNICO / EXTREMO =====
  { name: "Death", genre: "Death Metal (clásico)", desc: "Chuck Schuldiner reescribió su propia banda varias veces: del riff primitivo de Scream Bloody Gore (1987) y Leprosy a la escritura modal y de métrica impar de Human (1991) en adelante, con Steve DiGiorgio al bajo fretless y Gene Hoglan a la batería en Individual Thought Patterns. Human, Individual Thought Patterns, Symbolic (1995) y The Sound of Perseverance (1998) sostienen un nivel altísimo, con solos que pasan del cromatismo a una construcción armónica real. Entrada: Human, luego Symbolic.", origin: "lista", pick: true, p: 1, y: 1984 },
  { name: "Morbid Angel", genre: "Death Metal", desc: "Death metal de Florida con los solos de Trey Azagthoth, que suenan a otro planeta, y la batería de Pete Sandoval marcando velocidad y precisión. Altars of Madness (1989), Blessed Are the Sick, Covenant (1993) y Domination son la cumbre, y Formulas Fatal to the Flesh y Gateways to Annihilation (2000) siguen a buen nivel; Illud Divinum Insanus (2011), con industrial, fue muy mal recibido. Entrada: Covenant.", origin: "lista", p: 2, y: 1983 },
  { name: "Necrophagist", genre: "Technical Death", desc: "Muhammed Suiçmez escribe los solos como piezas neoclásicas completas, con armonía funcional dentro del death técnico, y los riffs siguen esa misma conducción de voces. Solo tienen dos discos, Onset of Putrefaction (1999) y Epitaph (2004), y los dos están a ese nivel. Entrada: Epitaph.", origin: "lista", p: 1, y: 1992 },
  { name: "Revocation", genre: "Technical Death / Thrash", desc: "Death técnico con thrash y armonía de jazz, con la guitarra de Dave Davidson, que estudió jazz, como centro. Muy parejos de Existence Is Futile (2009) a Deathless, Great Is Our Sin, The Outer Ones, Netherheaven (2022) y New Gods, New Masters (2025). Entrada: Deathless.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Decapitated", genre: "Technical Death", desc: "Death técnico polaco de Vogg: riffs precisos y con groove, cambios de tempo y una batería (Vitek en los primeros discos, muerto en 2007) de mucha técnica. Winds of Creation (2000), Nihility, The Negation y Organic Hallucinosis (2006) son la cumbre; lo posterior es más directo y desigual, con Cancer Culture (2022) como buen regreso. Entrada: Nihility.", p: 2, origin: "lista", y: 1996 },
  { name: "Cattle Decapitation", genre: "Death / Grind", desc: "Deathgrind con mensaje ecologista y la voz de Travis Ryan, que va del gutural a un falsete distorsionado casi melódico. Los primeros discos son grind tosco; de The Harvest Floor (2009) a Monolith of Inhumanity, The Anthropocene Extinction (2015), Death Atlas y Terrasite (2023) la escritura se vuelve técnica y ambiciosa. Entrada: Monolith of Inhumanity.", p: 2, origin: "lista", pick: true, y: 1996 },
  { name: "Job for a Cowboy", genre: "Death Metal", desc: "Pasaron del deathcore de Genesis (2007) a un death técnico y progresivo con el bajo fretless de Nick Schendzielos muy al frente, compases cambiantes y guitarras disonantes. Demonocracy (2012), Sun Eater (2014) y Moon Healer (2024), tras diez años, son su mejor etapa. Entrada: Sun Eater, luego Moon Healer.", p: 2, origin: "lista", y: 2003 },
  { name: "Cannibal Corpse", genre: "Death Metal", desc: "Se queda en nivel de contexto: death metal rápido y directo, con Alex Webster al bajo haciendo líneas bastante más elaboradas de lo que la fama de la banda sugiere, pero riffs que priorizan el impacto sobre el desarrollo. Históricamente imprescindible; para tu gusto, no.", origin: "heard", p: 4, y: 1988, c: 2 },
  { name: "Slugdge", genre: "Progressive Death", desc: "Death progresivo británico con mitología de babosas, en serio, y muchísima melodía y técnica: riffs de raíz sludge, guitarras melódicas en capas y voz limpia épica. Gastronomicon (2014), Dim & Slimeridden Kingdoms y Esoteric Malacology (2018). Entrada: Esoteric Malacology.", p: 2, origin: "lista", pick: true, y: 2012 },
  { name: "Anciients", genre: "Prog Death / Sludge", desc: "Death progresivo canadiense con groove y sludge, voces limpias y guturales y guitarras gemelas en la línea de Mastodon y Opeth. Heart of Oak (2013), Voice of the Void (2016) y Beyond the Reach of the Sun (2024). Entrada: Heart of Oak.", p: 2, origin: "lista", pick: true, y: 2010 },
  { name: "Inter Arma", genre: "Post / Sludge / Death", desc: "Metal extremo que cruza sludge, death, doom y post dentro del mismo disco, con T.J. Childers cambiando de lenguaje de batería entero según la sección (blast, marcha lenta, redoble tribal). Temas largos que no vuelven al punto de partida. Entrada: Sulphur English.", p: 2, origin: "lista", pick: true, y: 2006 },
  { name: "Rivers of Nihil", genre: "Progressive Death", desc: "Death progresivo de Pensilvania con saxofón y atmósfera, en discos conceptuales sobre las estaciones. Monarchy (2015) y Where Owls Know My Name (2018) son lo más logrado; The Work (2021) y Rivers of Nihil (2025) dividen más. Entrada: Where Owls Know My Name.", p: 2, origin: "lista", pick: true, y: 2009 },
  { name: "Fit for an Autopsy", genre: "Deathcore", desc: "Will Putney, que además produce a media escena, escribe los riffs alternando pasajes graves a medio tiempo con secciones de guitarra limpia y melódica, y dejan que los temas bajen de intensidad de verdad en lugar de encadenar breakdowns. Letras de crítica social sin gore. Es de los pocos del género con dinámica real. Entrada: The Sea of Tragic Beasts.", origin: "lista", pick: true, p: 2, y: 2008 },
  { name: "Whitechapel", genre: "Deathcore", desc: "Tienen tres guitarristas, lo que les permite superponer una línea melódica sobre dos rítmicas a la vez en vez de doblar el mismo riff, y en los últimos discos han metido voz limpia y pasajes atmosféricos que cambian bastante el peso de la banda. Entrada: The Valley.", origin: "lista", pick: true, p: 2, y: 2006 },
  { name: "Slaughter to Prevail", genre: "Deathcore", desc: "Cierto que Alex Terrible tiene uno de los registros guturales más graves y potentes del género, pero por debajo la escritura es deathcore de manual, riff grave, breakdown y vuelta, con producción enorme y muy poco desarrollo. Funciona por impacto, no por composición. Entrada: Kostolom.", origin: "lista", p: 3, y: 2014 },
  { name: "Slice the Cake", genre: "Prog Deathcore", desc: "Banda internacional con miembros de Inglaterra, Suecia y Australia. Odyssey to the West (1 de abril de 2016) son setenta y siete minutos concebidos como una sola obra continua, con orquesta, coro y pasajes acústicos entre lo pesado. Se formaron en 2009, se separaron ese mismo 2016, volvieron en 2019 y se separaron de nuevo en 2022. Entrada: Odyssey to the West.", origin: "lista", p: 2, y: 2009, c: 2 },
  { name: "Within the Ruins", genre: "Technical Deathcore", desc: "Joe Cocchi escribe la guitarra como si fuera un instrumento solista dentro del deathcore, con líneas melódicas rapidísimas, barridos y armonías a dos voces por encima de la base, en vez de limitarse al riff grave. Los discos son cortos y sin relleno. Entrada: Elite o Halfway Human.", origin: "lista", pick: true, p: 2, y: 2003 },
  { name: "Enterprise Earth", genre: "Deathcore", desc: "Deathcore sinfónico con orquestación programada por encima de riffs técnicos y blast beats, y voces que alternan gutural profundo con agudo. Bien ejecutado y con producción enorme, pero se mueve dentro de la plantilla sinfónica que Lorna Shore y Shadow of Intent hacen con más personalidad. Entrada: The Chosen.", origin: "lista", p: 3, y: 2014 },
  { name: "Future Corpse", genre: "Progressive Metal / Prog Rock", desc: "Prog metal independiente de Melbourne con temas de distopía y misantropía: Another World to Consume (2016) y Culture Ruins Everything Around Me (2018).", origin: "lista", p: 3, y: 2018, c: 2 },
  { name: "Physics of Demise", genre: "Melodic Death Metal", desc: "Danbury, Connecticut, 2011. Melodeath de escena local con debut en 2012, Farewell to Better Days. Ejecucion correcta dentro del molde de Gotemburgo, sin nada que lo separe del resto.", origin: "lista", p: 3, y: 2012, c: 2 },
  { name: "Car Bomb", genre: "Mathcore / Tech", desc: "Desplazan el acento del riff respecto al pulso de la batería de forma que el oído pierde dónde está el uno, y usan silencios cortados en seco a mitad de frase como elemento rítmico. Greg Kubacki toca figuras que se repiten con una nota de diferencia cada vuelta, y eso produce la sensación de máquina averiada que los define. Entra por Meta.", origin: "rec", p: 1, y: 2000, c: 2 },
  { name: "Dillinger Escape Plan", genre: "Mathcore", desc: "Calculating Infinity está escrito en compases que cambian casi por compás, con la guitarra y la batería ejecutando al unísono figuras que suenan aleatorias y no lo son, y armonía tomada del jazz (acordes disminuidos y alterados) puesta a velocidad de hardcore. Chris Pennie escribía las partes de batería como composición, no como acompañamiento. Con Greg Puciato metieron después limpios y electrónica sin soltar el caos. Entra por Calculating Infinity, luego Ire Works.", origin: "rec", p: 1, y: 1997, c: 2 },
  { name: "Tony Danza Tapdance Extravaganza", genre: "Mathcore", desc: "Mathcore caótico con nombre absurdo. Técnico y feroz.", origin: "lista", p: 3, y: 2004 },
  { name: "Portal", genre: "Dissonant Death", desc: "Death disonante y atonal australiano, aterrador y abstracto: riffs que se descomponen en zumbido, tempos que se deshacen y una producción deliberadamente enterrada. Outré (2007), Swarth, ION (2018), el más nítido, y la pareja Avow y Hagbulbia (2021). Experiencia abrasiva. Entrada: ION.", p: 2, origin: "lista", y: 1994 },
  { name: "Vein", genre: "Mathcore / Nu Metalcore", desc: "Mathcore caótico con toques nu metal de los 90. Vértigo y agresión modernos.", origin: "lista", p: 3, y: 2013 },

  // ===== MELODIC DEATH METAL (tu zona declarada) =====
  { name: "At the Gates", genre: "Melodic Death", desc: "Melodeath rápido y directo, construido sobre riffs de tresillos y armonías de guitarra a dos voces muy cortas y memorables, con Tomas Lindberg gritando en un registro alto y seco. Slaughter of the Soul es deliberadamente conciso y sin grasa, y esa concisión es su virtud y su techo: es la plantilla que copiaron mil bandas, no un ejercicio de complejidad. Lindberg murió en septiembre de 2025, y The Ghost of a Future Dead (abril de 2026), con su voz ya grabada y Anders Björler de vuelta, es el último disco. Entrada: Slaughter of the Soul, y The Red in the Sky Is Ours si quieres su lado raro.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Dark Tranquillity", genre: "Melodic Death", desc: "Melodeath melódico con teclados que llevan contramelodía en vez de hacer colchón, y Mikael Stanne alternando gutural y limpio con más rango que la media del género. Muy bien hechos y con una carrera sin discos malos, hasta Endtime Signals (2024), pero trabajan dentro de la plantilla que ellos mismos ayudaron a fijar. Entrada: The Gallery o Character.", origin: "rec", p: 2, y: 1989, c: 2 },
  { name: "Soilwork", genre: "Melodic Death", desc: "Melodeath sueco que fue metiendo estribillo limpio y groove, y que cambia de verdad entre discos: de Steelbath Suicide (1998) y The Chainheart Machine a The Living Infinite (2013), un doble, y Övergivenheten (2022). Entrada: The Living Infinite.", origin: "lista", p: 3, y: 1995, c: 1 },
  { name: "Sylosis", genre: "Melodic Thrash / Death", desc: "Thrash y death melódico británico técnico, con los riffs y solos de Josh Middleton: bien escrito y con mucha guitarra, pero dentro de la estructura del género. Edge of the Earth (2011) y Cycle of Suffering (2020) son lo mejor. Entrada: Edge of the Earth.", p: 3, origin: "lista", pick: true, y: 2000 },
  { name: "Arch Enemy", genre: "Melodic Death", desc: "Melodeath con solos de guitarra de corte clásico de Michael Amott. Alissa White-Gluz dejó el grupo a finales de 2025 y desde febrero de 2026 canta Lauren Hart, antes en Once Human. Entrada: Wages of Sin.", origin: "lista", female: true, p: 3, y: 1995 },
  { name: "The Halo Effect", genre: "Melodic Death", desc: "Melodeath de Gotemburgo clásico y bien hecho, pero es deliberadamente un regreso al sonido dorado: su atractivo es la nostalgia y el linaje ex-In Flames, no una propuesta instrumental propia.", origin: "lista", pick: true, p: 3, y: 2021 },
  { name: "The Haunted", genre: "Melodic Death / Thrash", desc: "Thrash/melodeath sueco agresivo (ex-At the Gates). Filo y groove.", origin: "lista", p: 3, y: 1996 },
  { name: "Insomnium", genre: "Melodic Death", desc: "Melodeath finlandés melancólico con guitarras limpias en arpegio bajo el riff, tempos medios y mucho espacio. Llevan veinticinco años sin sacar un mal disco y encadenan buena racha con Winter's Gate, Heart Like a Grave y Anno 1696, pero la paleta armónica es bastante fija: lo constante es la calidad, no la ambición. Winter's Gate, una sola pieza de cuarenta minutos, es la excepción y no la norma. El 16 de octubre sale Netherworlds. Entrada: Winter's Gate.", origin: "rec", p: 2, y: 1997, c: 2 },
  { name: "Before the Dawn", genre: "Melodic Death", desc: "Melodeath finlandés melódico y oscuro, con limpio/gutural. Sólido.", origin: "lista", p: 3, y: 1999 },
  { name: "Bloodred Hourglass", genre: "Melodic Death", desc: "Melodeath finlandés moderno con ganchos y pegada. Energético.", origin: "lista", p: 3, y: 2005 },
  { name: "Rise to Fall", genre: "Melodic Death", desc: "Melodeath español técnico y sinfónico. Poco conocido.", origin: "lista", p: 3, y: 2006 },
  { name: "Zonaria", genre: "Melodic Death", desc: "Melodeath sueco agresivo con toque sinfónico. Veloz.", origin: "lista", p: 3, y: 2001 },
  { name: "Scar Symmetry", genre: "Melodic Death / Prog", desc: "Melodeath progresivo sueco con la guitarra técnica de Per Nilsson y estribillos limpios muy pop: el contraste entre riffs complejos y ganchos fáciles es su marca, y también su límite. The Singularity (Phase I – Neohumanity) (2014) y Phase II – Xenotaph (2023) son lo mejor. Entrada: The Singularity (Phase I).", origin: "lista", pick: true, p: 2, y: 2004 },
  { name: "Amon Amarth", genre: "Melodic Death (Viking)", desc: "Melodeath vikingo épico e himnódico, de riffs heroicos a medio tiempo: muy consistente, pero dentro de una plantilla fija. Entrada: Versus the World.", origin: "lista", pick: true, p: 3, y: 1992 },
  { name: "Heaven Shall Burn", genre: "Melodic Death / Metalcore", desc: "Melodeath-metalcore alemán con mensaje político y pegada masiva.", origin: "lista", p: 3, y: 1996 },
  { name: "Amaranthe", genre: "Melodic / Pop Metal", desc: "Híbrido de melodeath con estructura de pop y electrónica, y su rasgo propio es la formación: tres vocalistas a la vez (femenina limpia, masculina limpia y gutural) que se turnan frases dentro del mismo estribillo, lo que casi nadie hace. Debajo, riffs melodeath y bases de dance. Divisivo a propósito y muy fórmula una vez pasada la sorpresa, por eso queda en nivel de contexto. (voz femenina compartida) Entrada: The Nexus.", origin: "lista", female: true, p: 4, y: 2008 },
  { name: "Dagoba", genre: "Industrial Melodic Death", desc: "Melodeath francés con groove industrial. Moderno y pesado.", origin: "lista", p: 3, y: 1997 },
  { name: "Epicurean", genre: "Melodic Death", desc: "Melodeath estadounidense de escena pequeña, correcto dentro del molde.", origin: "lista", p: 3, y: 2001 },

  // ===== METALCORE/DEATHCORE FEMENINO + METAL FEMENINO =====
  { name: "Make Them Suffer", genre: "Metalcore / Symphonic", desc: "Metalcore sinfónico australiano con teclados, voz femenina y guturales, alternando belleza y brutalidad dentro de estructuras de metalcore. Entrada: Worlds Apart.", p: 3, origin: "lista", female: true, y: 2008 },
  { name: "The Agonist", genre: "Melodic Death / Metalcore", desc: "Metalcore melódico con vocalista femenina versátil (limpio operístico + gutural). (voz femenina)", origin: "lista", female: true, p: 3, y: 2004 },
  { name: "Flyleaf", genre: "Alt Metal / Post-Hardcore", desc: "Metal alternativo tejano con Lacey Sturm a la voz: emotivo y enérgico, de estructura de canción radiable. Entrada: Flyleaf.", p: 3, origin: "lista", female: true, y: 2002 },
  { name: "Red Handed Denial", genre: "Prog Metalcore", desc: "Metalcore progresivo canadiense con Lauren Babic a la voz: riffs técnicos y cambios de sección bien escritos, pero dentro del molde del género. Entrada: I'd Rather Be Asleep.", p: 3, origin: "lista", female: true, y: 2013 },
  { name: "Burning Witches", genre: "Heavy / Power Metal", desc: "Heavy/power metal clásico con formación femenina, en la veta Judas Priest. (voz femenina)", origin: "lista", female: true, p: 3, y: 2015 },
  { name: "Huntress", genre: "Heavy / Thrash", desc: "Heavy y thrash con la voz de soprano de Jill Janus. Oscuro y clásico. Janus murió en 2018. Entrada: Spell Eater.", origin: "lista", female: true, p: 3, y: 2009 },
  { name: "Frozen Crown", genre: "Power Metal", desc: "Power metal italiano melódico y veloz con voz femenina. Épico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2017 },
  { name: "Halestorm", genre: "Hard Rock", desc: "Hard rock directo con Lzzy Hale, que canta con un registro muy amplio y un rasgado potente, y toca la guitarra rítmica ella misma. Estructura de canción clásica y producción de radio: eficaz y sin sorpresas instrumentales. Entrada: The Strange Case Of... (voz femenina)", origin: "lista", female: true, p: 3, y: 1997 },

  // ===== INDUSTRIAL / NU / EXPERIMENTAL MODERNO =====
  { name: "Nine Inch Nails", genre: "Industrial / Electronic", desc: "Trent Reznor trata el ruido como material armónico y no como capa de suciedad: los sonidos están afinados y cumplen función de acorde. Y el arco va de la agresión de Broken al ambient de Ghosts y a las bandas sonoras, cambiando de sistema en cada disco. Entrada: The Downward Spiral.", origin: "lista", pick: true, p: 1, y: 1988, c: 1 },
  { name: "Tallah", genre: "Nu Metalcore", desc: "Nu metal moderno caótico y técnico: riffs que saltan de groove a disonancia, samples y scratches integrados en la mezcla y la batería de Max Portnoy cambiando de figura sin parar, bajo una voz que pasa del rap al grito. Matriphagy (2020) y The Generation of Danger (2022), los dos muy bien recibidos. Entrada: Matriphagy.", p: 2, origin: "lista", y: 2017 },
  { name: "Dance with the Dead", genre: "Synthwave / Darksynth", desc: "Bajado con el resto del synthwave, y de paso quitada una frase que te atribuía el gusto por adelantado. Synthwave con guitarras metaleras encima, instrumental y cinematográfico, orientado al cine de terror ochentero. Bien hecho dentro de un molde muy fijo. Entra por Loveless Encounter.", origin: "rec", p: 3, y: 2013, c: 2 },
  { name: "Code Orange", genre: "Hardcore / Industrial", desc: "Hardcore con industrial y glitch: cortan la mezcla en seco, meten fallos digitales como si el archivo se corrompiera y cambian de tempo de golpe, con Jami Morgan tocando la batería y cantando a la vez en los primeros discos. Forever (2017) y Underneath (2020) son la cumbre, cada uno rompiendo el molde del anterior; The Above (2023), más disperso, queda por debajo. Están en pausa indefinida desde 2025. Entrada: Forever.", p: 2, origin: "lista", pick: true, y: 2008, c: 1 },

  // ===== DOOM/BLACK/EXTREMO ATMOSFÉRICO =====
  { name: "Immortal", genre: "Black Metal", desc: "Black metal noruego épico e invernal, de trémolo veloz y atmósfera helada. At the Heart of Winter (1999) y Sons of Northern Darkness (2002) son lo mejor. Entrada: At the Heart of Winter.", origin: "lista", p: 3, y: 1991 },
  { name: "Cradle of Filth", genre: "Symphonic Black", desc: "Black metal sinfónico teatral y gótico, con voz aguda característica. Dramático y excesivo.", origin: "lista", p: 3, y: 1991 },
  { name: "Skeletonwitch", genre: "Blackened Thrash", desc: "Thrash con black metal y melodía de Ohio, veloz y pegadizo dentro de lo extremo. Entrada: Breathing the Fire.", origin: "lista", p: 3, y: 2003 },

  // ===== SLEEP TOKEN / SLEEP-ADJACENT / ATMOSFÉRICO MODERNO =====
  { name: "Sleep Token", genre: "Alt Metal / Atmospheric", desc: "Pasa de piano y voz susurrada a djent pesadísimo dentro del mismo tema, con la batería de II tocando patrones sincopados por debajo de secciones muy quietas. El contraste es el recurso principal. Sigue en alta afinidad a la espera de que lo escuches. Entrada: Take Me Back to Eden.", origin: "lista", pick: true, p: 2, y: 2016, c: 2 },
  { name: "Avatar", genre: "Avant-garde Metal", desc: "Metal sueco teatral de estética circense oscura: riffs de groove y de heavy clásico, estribillos grandes y un cantante que actúa más que canta. Más espectáculo que escritura, bien hecho dentro del molde. Entrada: Hail the Apocalypse.", p: 3, origin: "lista", pick: true, y: 2001 },

  // ===== POST-ROCK / INSTRUMENTAL ATMOSFÉRICO =====
  { name: "Caspian", genre: "Post-Rock", desc: "Post-rock instrumental sin voz: crescendos largos construidos por capas de guitarra con delay hasta el estallido, y batería que entra tarde y transforma la pieza. Cinematográfico. Entrada: Waking Season.", origin: "lista", p: 3, y: 2004 },
  { name: "Audrey Fall", genre: "Post-Metal", desc: "De Jelgava, Letonia. Post-metal instrumental sin voz, con temas largos que crecen por densidad en vez de por cambio de riff. Su debut, Mitau, es de 2014. Entrada: Mitau.", origin: "lista", p: 3, y: 2010 },

  // ===== HARD ROCK / STONER / ALTERNATIVO 90s-2000s =====
  { name: "Soundgarden", genre: "Grunge / Alt Metal", desc: "Kim Thayil trabaja con afinaciones alternativas raras (llegó a usar una donde todas las cuerdas van a la misma nota) y escribe en compases impares sin que se noten: Spoonman va en siete, My Wave en cinco, Outshined en siete. Y Matt Cameron toca esos compases con un swing pesado que hace que suenen naturales, no a ejercicio. Encima la voz de Chris Cornell con un rango enorme. Bastante más sofisticado de lo que su etiqueta de grunge sugiere. Entrada: Superunknown o Badmotorfinger.", origin: "lista", pick: true, p: 1, y: 1984 },
  { name: "Alice in Chains", genre: "Grunge / Alt Metal", desc: "Jerry Cantrell y Layne Staley armonizan casi todo el tiempo, no solo en los estribillos, y lo hacen en intervalos que chirrían a propósito en vez de sonar dulces, así que la melodía siempre lleva una segunda voz incómoda encima. Debajo, riffs en afinación grave a medio tiempo con mucho wah y talk-box, y Sean Kinney tocando lento y arrastrado. Esa mezcla de armonía vocal y pesadez lenta no la tiene nadie más del movimiento. Entrada: Dirt.", origin: "lista", pick: true, p: 1, y: 1987 },
  { name: "Queens of the Stone Age", genre: "Stoner / Alt Rock", desc: "Homme afina la guitarra a do y toca riffs cortos que repite sin variar durante todo el tema, lo que él llama robot rock, dejando que el groove hipnotice en lugar de desarrollarse; sobre eso mete armonías vocales dulces que chocan con lo áspero del riff. La formación cambia constantemente y en Songs for the Deaf toca Dave Grohl la batería. Entrada: Rated R o Songs for the Deaf.", origin: "lista", pick: true, p: 2, y: 1996, c: 1 },
  { name: "Deftones", genre: "Alt Metal / Shoegaze", desc: "Alt metal donde el peso y la belleza conviven: guitarras de siete y ocho cuerdas afinadas gravísimo bajo capas de shoegaze, la voz de Chino pasando de susurro a grito, y Abe Cunningham tocando con un swing y un uso del charles que casi nadie en el género tiene. Entrada: White Pony o Koi No Yokan.", origin: "lista", pick: true, p: 1, y: 1988 },
  { name: "Lamb of God", genre: "Groove Metal", desc: "Groove metal moderno con la batería técnica de Chris Adler, hasta 2019, y riffs de Mark Morton y Willie Adler con mucho desplazamiento rítmico. Ashes of the Wake (2004) y Sacrament (2006) son lo mejor; Into Oblivion (marzo de 2026) es el último. Entrada: Ashes of the Wake.", origin: "lista", p: 3, y: 1994 },

  // ===== HARD ROCK / PUNK / SKA / VARIOS LISTA =====
  { name: "NOFX", genre: "Punk Rock", desc: "Punk californiano veloz y melódico, con Fat Mike escribiendo letras sarcásticas sobre estructuras rápidas y simples. Entrada: Punk in Drublic.", origin: "lista", p: 3, y: 1983 },
  { name: "Billy Talent", genre: "Punk / Alt Rock", desc: "Punk rock canadiense con la guitarra de Ian D'Sa haciendo figuras angulares en vez de acordes rasgueados, y una voz muy aguda y nasal que divide. Por debajo, escritura de canción con estribillo. Entrada: Billy Talent II.", origin: "lista", p: 3, y: 1993 },
  { name: "Meat Loaf", genre: "Rock teatral", desc: "Rock operístico escrito por Jim Steinman: canciones de ocho y diez minutos con estructura de varias partes, piano wagneriano, coros enormes y cambios de tempo teatrales. Grandilocuente a propósito. Entrada: Bat Out of Hell.", origin: "lista", pick: true, p: 2, y: 1977 },
  { name: "Jellyfish", genre: "Power Pop", desc: "Los arreglos son objetivamente exquisitos (armonías vocales a cuatro y cinco voces, metales, mellotron, cambios de tonalidad dentro del estribillo) y Spilt Milk es una maravilla de producción en la línea de Queen, los Beach Boys y 10cc. Pero es la trampa Queen otra vez: armonía sofisticada no es complejidad instrumental, y por debajo son canciones pop de tres minutos con forma clásica. Delicioso, no exigente. Entra por Spilt Milk.", origin: "rec", p: 2, y: 1989, c: 2 },
  { name: "The Beatles", genre: "Rock (clásico)", desc: "McCartney toca el bajo como línea melódica independiente que va contra la voz en vez de seguir la raíz (Something, Rain, Dear Prudence), y Ringo aporta un fraseo raro por ser zurdo tocando un kit de diestro, lo que le hace liderar los redobles con la mano débil y desplazar el acento. Encima, invención de estudio real: bucles de cinta en Tomorrow Never Knows, guitarra grabada al revés, y el medley de la cara B de Abbey Road encadenando fragmentos sin cerrar ninguno. Entrada: Revolver o Abbey Road.", origin: "lista", p: 1, y: 1960, c: 1 },

  // ===== THE DEAR HUNTER / NARRATIVO PROG-INDIE =====
  { name: "The Dear Hunter", genre: "Prog / Indie Rock", desc: "Proyecto narrativo ambicioso (la saga Acts más el Color Spectrum, nueve EPs de un color cada uno): mezcla indie, prog, soul y orquestal, con arreglos de metales y cuerda escritos y motivos que reaparecen entre discos. Entrada: Act III.", p: 2, origin: "lista", pick: true, y: 2005 },

  // ===== INDIE / ALT ROCK / GARAGE (gran bloque de tu lista) =====
  { name: "The Strokes", genre: "Indie Rock / Garage", desc: "Indie rock neoyorquino que definió el sonido de los dos mil: dos guitarras entrelazadas y secas sobre una batería de precisión de caja de ritmos. Is This It (2001) y Room on Fire son lo mejor, y The New Abnormal (2020) está cerca. Entrada: Is This It.", p: 3, origin: "lista", y: 1998 },
  { name: "Arctic Monkeys", genre: "Indie Rock", desc: "De indie veloz a lounge sofisticado en Tranquility Base, con Alex Turner cambiando de registro vocal y de instrumentación entera entre discos. Entrada: AM.", p: 3, origin: "lista", pick: true, y: 2002, c: 1 },
  { name: "The Last Shadow Puppets", genre: "Indie / Baroque Pop", desc: "Proyecto de Alex Turner (Arctic Monkeys) con orquestaciones cinematográficas. Elegante y dramático.", origin: "lista", p: 3, y: 2007 },
  { name: "Tame Impala", genre: "Psych Pop", desc: "La psicodelia de Kevin Parker, que graba casi todo él solo: capas de guitarra con fase, batería muy comprimida y bajo melódico al frente, del rock psicodélico de InnerSpeaker (2010) y Lonerism (2012) al pop electrónico de Currents (2015), la cumbre, y The Slow Rush; Deadbeat (2025) baja claramente. Entrada: Lonerism, luego Currents.", p: 2, origin: "lista", pick: true, y: 2007, c: 1 },
  { name: "King Gizzard & the Lizard Wizard", genre: "Psych Rock / Experimental", desc: "Rock psicodélico de riff, tocado con energía y muy poca ornamentación. Lo genuinamente valioso está en discos concretos, sobre todo cuando se afinaron guitarras microtonales para trabajar con intervalos fuera del temperamento occidental, y en Polygondwanaland con sus compases impares. El resto es garage sólido pero sencillo. Entra por Polygondwanaland.", origin: "rec", p: 2, y: 2010, c: 1 },
  { name: "MGMT", genre: "Psych Pop", desc: "Psych pop de Brooklyn que pasó de los éxitos de Oracular Spectacular (2007) a la rareza deliberada de Congratulations (2010), al synth pop de Little Dark Age (2018) y a Loss of Life (2024). Entrada: Congratulations.", p: 3, origin: "lista", y: 2002, c: 1 },
  { name: "Portugal. The Man", genre: "Psych / Alt Rock", desc: "Rock psicodélico de Alaska que pasó del art rock enrevesado de sus primeros discos al pop de Woodstock (2017). The Satanic Satanist (2009). Entrada: The Satanic Satanist.", p: 3, origin: "lista", y: 2004 },
  { name: "Nothing but Thieves", genre: "Alt Rock", desc: "Alt rock británico con la voz aguda de Conor Mason, en la órbita de Muse, de estructura directa. Entrada: Broken Machine.", p: 3, origin: "lista", y: 2012 },
  { name: "Royal Blood", genre: "Hard Rock / Blues", desc: "Dúo de bajo y batería sin guitarra: Mike Kerr divide la señal del bajo con un octavador y la manda a varios amplificadores a la vez, unos de bajo y otros de guitarra, para cubrir los dos registros y sonar como si hubiera guitarrista, mientras Ben Thatcher toca un groove muy pesado y simple que deja el hueco. Entrada: Royal Blood (2014).", origin: "lista", pick: true, p: 2, y: 2011 },
  { name: "The Black Keys", genre: "Blues Rock / Garage", desc: "Dúo de blues rock crudo de Ohio, de groove sucio y riff directo. Brothers (2010) y El Camino (2011) son lo mejor; lo posterior baja. Entrada: Brothers.", p: 3, origin: "lista", y: 2001 },
  { name: "Death from Above 1979", genre: "Dance Punk / Noise", desc: "Dúo de bajo y batería, sin guitarra: Jesse Keeler toca el bajo por amplificadores de guitarra con distorsión y pedales de octava para cubrir todo el rango, y Sebastien Grainger toca la batería y canta a la vez, con un groove bailable dentro de algo que suena a ruido. Es tu combinación de instrumentos favorita reducida al mínimo posible. Entrada: You're a Woman, I'm a Machine.", origin: "lista", p: 2, y: 2001 },
  { name: "The Killers", genre: "Indie / Arena Rock", desc: "Rock de estadio de Las Vegas con sintetizadores ochenteros y estribillos enormes, de estructura muy directa. Hot Fuss (2004) y Sam's Town (2006). Entrada: Hot Fuss.", p: 3, origin: "lista", y: 2001 },
  { name: "Catfish and the Bottlemen", genre: "Indie Rock", desc: "Indie rock galés directo, de estribillos grandes. Entrada: The Balcony.", p: 3, origin: "lista", y: 2007 },
  { name: "Kasabian", genre: "Indie / Electronic Rock", desc: "Rock británico con groove electrónico y psicodelia, bailable y directo. West Ryder Pauper Lunatic Asylum (2009) es lo mejor. Entrada: West Ryder Pauper Lunatic Asylum.", p: 3, origin: "lista", y: 1997 },
  { name: "Two Door Cinema Club", genre: "Indie Pop", desc: "Indie pop norirlandés bailable con guitarras brillantes. Entrada: Tourist History.", p: 3, origin: "lista", y: 2007 },
  { name: "Wolf Alice", genre: "Alt Rock / Dream Pop", desc: "Británicos que van del dream pop al grunge en un mismo disco, con Ellie Rowsell a la voz. Visions of a Life (2017) ganó el Mercury. Entrada: Visions of a Life.", p: 3, origin: "lista", female: true, pick: true, y: 2010 },
  { name: "Franz Ferdinand", genre: "Indie / Post-Punk Revival", desc: "Post-punk bailable con riffs angulares y un bajo que marca el groove por encima del bombo. Muy eficaz y muy dentro de fórmula. Entrada: Franz Ferdinand.", origin: "lista", p: 3, y: 2002 },
  { name: "Foals", genre: "Math Rock / Indie", desc: "Indie con math rock: las dos guitarras tocan líneas cortas entrelazadas que se desfasan en vez de acordes, sobre el groove de Jack Bevan, y de ahí crecen a lo épico. Entrada: Antidotes o Holy Fire.", origin: "rec", p: 3, y: 2005, via: "Indie" },
  { name: "The 1975", genre: "Pop / Alt", desc: "Pop alternativo camaleónico y autoconsciente: cada disco cambia de paleta entera (synth-pop ochentero, ambient instrumental, country, garage), con George Daniel produciendo y tocando la batería, y arreglos de saxofón y cuerda metidos donde no se esperan. Matty Healy escribe letras que comentan el propio disco mientras suena. Ecléctico de verdad, aunque la escritura por debajo es de canción pop. Entrada: A Brief Inquiry Into Online Relationships.", origin: "lista", p: 3, y: 2002, c: 1 },
  { name: "The Wombats", genre: "Indie Pop", desc: "Indie pop británico ingenioso y bailable, con letras de humor. Entrada: A Guide to Love, Loss & Desperation.", p: 3, origin: "lista", y: 2003 },
  { name: "FIDLAR", genre: "Garage Punk", desc: "Garage punk californiano crudo y rápido, grabado sucio a propósito. Divertido y directo, sin ambición instrumental por debajo. Entrada: FIDLAR.", origin: "lista", p: 3, y: 2009 },
  { name: "SWMRS", genre: "Garage Punk", desc: "Garage punk juvenil de California, crudo y directo, con producción deliberadamente barata. Poco que rascar por debajo. Entrada: Drive North.", origin: "lista", p: 3, y: 2004 },
  { name: "The Districts", genre: "Indie Rock", desc: "Indie rock de Pensilvania con raíz folk y crescendos. Entrada: A Flourish and a Spoil.", p: 3, origin: "lista", y: 2009 },
  { name: "Rolling Blackouts Coastal Fever", genre: "Indie / Jangle", desc: "Indie australiano de tres guitarras entrelazadas y ritmo constante, luminoso y literario. Entrada: Hope Downs.", p: 3, origin: "lista", y: 2013 },
  { name: "The Growlers", genre: "Surf / Psych Rock", desc: "Surf y psych de California, relajado y de groove raro. Entrada: Chinese Fountain.", p: 3, origin: "lista", y: 2006 },
  { name: "Black Box Revelation", genre: "Garage / Blues Rock", desc: "Dúo belga de garage blues crudo, de riffs sucios. Entrada: Set Your Head on Fire.", p: 3, origin: "lista", y: 2005 },
  { name: "Sticky Fingers", genre: "Indie / Reggae Rock", desc: "Indie australiano con reggae y psicodelia, relajado. Entrada: Land of Pleasure.", p: 3, origin: "lista", y: 2008 },
  { name: "The Garden", genre: "Experimental Punk", desc: "Dúo de los gemelos Shears, de California: punk minimalista y excéntrico que salta a electrónica, hip-hop y ruido en canciones de un minuto. Raro y enérgico, pero muy sencillo por dentro. Entrada: Haha.", p: 3, origin: "lista", y: 2011 },
  { name: "Vundabar", genre: "Indie Rock", desc: "Indie de Boston con guitarras nerviosas y dinámica tensa y suelta. Entrada: Smell Smoke.", p: 3, origin: "lista", y: 2013 },
  { name: "Saint Motel", genre: "Indie Pop", desc: "Indie pop de Los Ángeles con vientos y groove, elegante y divertido. Entrada: saintmotelevision.", p: 3, origin: "lista", y: 2007 },
  { name: "Walk the Moon", genre: "Indie Pop / Synth", desc: "Indie pop con sintetizadores y estribillos de estadio. Entrada: Talking Is Hard.", p: 3, origin: "lista", y: 2006 },

  // ===== INDIE / ELECTRÓNICO / CHILL / SOUL =====
  { name: "alt-J", genre: "Indie / Art Pop", desc: "Indie experimental con armonías raras, folktrónica y estructuras peculiares. Muy distintivo.", origin: "lista", pick: true, p: 3, y: 2007 },
  { name: "Phantogram", genre: "Electro / Dream Pop", desc: "Dúo de electro rock con Sarah Barthel a la voz y beats densos, oscuro y pegadizo. Entrada: Voices.", p: 3, origin: "lista", female: true, y: 2007 },
  { name: "Jungle", genre: "Modern Funk / Soul", desc: "Colectivo británico de funk y soul bailable, con falsetes y una producción muy pulida. Luminoso, pero dentro de un molde. For Ever (2018) y Volcano (2023). Entrada: For Ever.", origin: "lista", p: 3, y: 2013 },
  { name: "Local Natives", genre: "Indie Folk / Rock", desc: "Indie de Los Ángeles con armonías vocales exuberantes y percusión, cálido y melódico. Entrada: Gorilla Manor.", origin: "lista", p: 3, y: 2005 },
  { name: "Still Woozy", genre: "Bedroom Pop", desc: "Bedroom pop groovy y juguetón, producción casera cálida. Relajado.", p: 3, origin: "lista", y: 2017 },
  { name: "Slenderbodies", genre: "Indie / R&B", desc: "Indie-R&B etéreo y suave, falsetes y atmósfera. Chill.", p: 3, origin: "lista", y: 2016 },
  { name: "Crooked Colours", genre: "Electronic / Dance", desc: "Electrónica indie australiana bailable y atmosférica, con groove claro y estructura de canción. Bien producida, sin ambición instrumental por debajo. Entrada: Vera.", origin: "lista", p: 3, y: 2013 },
  { name: "Coast Modern", genre: "Indie Pop", desc: "Indie pop soleado y ecléctico, mezcla estilos con actitud relajada.", p: 3, origin: "lista", y: 2015 },

  // ===== ART POP / SINGER-SONGWRITER / TEATRAL =====
  { name: "Radiohead", genre: "Art Rock / Experimental", desc: "Jonny Greenwood mete ondas Martenot y arreglos orquestales escritos por él, y la banda trabaja compases raros sin anunciarlos (15 Step va en cinco, Pyramid Song tiene un pulso deliberadamente ambiguo), con Phil Selway tocando patrones que desplazan el acento. De The Bends (1995) a OK Computer, Kid A y Amnesiac, que cambian la instrumentación por electrónica y metales de jazz, In Rainbows y A Moon Shaped Pool (2016) sostienen el nivel; Pablo Honey, el debut, y The King of Limbs, más de bucle que de canción, son lo más flojo. Entrada: Kid A o In Rainbows.", origin: "rec", p: 1, y: 1985, c: 1 },
  { name: "Depeche Mode", genre: "Synth-Pop / Dark Wave", desc: "Synth-pop oscuro que fue endureciéndose hasta lo industrial y lo bluesero: Martin Gore escribe casi todo y Alan Wilder, mientras estuvo, construía los arreglos a base de samples de percusión metálica grabados por él en vez de cajas de ritmo de catálogo, lo que da ese sonido áspero de Violator y Songs of Faith and Devotion. Voz de barítono de Dave Gahan encima. Entrada: Violator.", origin: "lista", p: 2, y: 1980 },
  { name: "Jeff Buckley", genre: "Singer-Songwriter / Art Rock", desc: "Voz angelical de rango enorme y guitarra etérea. 'Grace' es un disco de culto absoluto. Emotivo y único.", origin: "lista", p: 2, y: 1991 },
  { name: "The Dresden Dolls", genre: "Cabaret Punk", desc: "Punk cabaret de dos personas: Amanda Palmer al piano tocado con violencia percusiva y Brian Viglione a la batería haciendo de banda entera, con dinámicas de casi silencio a golpe seco y un fraseo de cabaret alemán. Sin bajo y sin guitarra. Entrada: The Dresden Dolls (2003). (voz femenina)", origin: "lista", female: true, pick: true, p: 2, y: 2000 },
  { name: "The Hush Sound", genre: "Indie / Piano Pop", desc: "Indie pop con piano y dos voces, masculina y femenina, melódico y cálido. Entrada: Like Vines.", p: 3, origin: "lista", female: true, y: 2004 },
  { name: "Marianas Trench", genre: "Pop Rock / Theatrical", desc: "Pop rock canadiense teatral con armonías vocales muy densas a varias voces y discos conceptuales montados como suite, con reprises que recuperan melodías de temas anteriores al final del álbum. Muy elaborado para ser pop. Entrada: Masterpiece Theatre.", origin: "lista", pick: true, p: 3, y: 2001 },
  { name: "Sarah and the Safe Word", genre: "Theatrical / Cabaret Rock", desc: "Rock teatral de cabaret con dramatismo y vientos. Excéntrico y enérgico. (voz femenina)", origin: "lista", female: true, p: 3, y: 2016 },

  // ===== EMO / POP PUNK / ALT MODERNO =====
  { name: "My Chemical Romance", genre: "Emo / Alt Rock", desc: "Emo teatral y conceptual: The Black Parade está construido como ópera rock, con banda de marcha, piano, orquestación y personajes, y las canciones encadenan secciones en vez de repetir estribillo. Entrada: The Black Parade.", origin: "lista", pick: true, p: 2, y: 2001 },
  { name: "Paramore", genre: "Pop Punk / Alt", desc: "De pop punk a new wave y pop sofisticado, con un cambio real de sonido en After Laughter: guitarras limpias con delay al estilo Talking Heads y la batería de Zac Farro tocando figuras sincopadas y ligeras en vez de marcar. Hayley Williams canta con un control de registro poco común en el género. Entrada: After Laughter.", origin: "lista", female: true, pick: true, p: 2, y: 2004, c: 1 },
  { name: "Palaye Royale", genre: "Glam / Alt Rock", desc: "Glam rock teatral moderno con estética visual fuerte. Dramático.", origin: "lista", p: 3, y: 2008 },
  { name: "I Don't Know How But They Found Me", genre: "Retro Pop Rock", desc: "Pop rock retro de estética setentera y ochentera montado por Dallon Weekes, que toca bajo y canta a la vez y escribe casi todo: bajo muy melódico y adelante en la mezcla, teclados antiguos y estructuras de canción corta con giros teatrales. Pegadizo y peculiar, sin más ambición que esa. (IDKHOW) Entrada: Razzmatazz.", origin: "lista", p: 3, y: 2016 },
  { name: "The Brobecks", genre: "Indie / Power Pop", desc: "El proyecto previo de Dallon Weekes: power pop excéntrico y melódico, de culto. Entrada: Violent Things.", origin: "lista", p: 3, y: 2002 },
  { name: "Set It Off", genre: "Pop Rock / Pop Punk", desc: "Pop punk teatral con arreglos orquestales encima de canciones de estructura convencional. Dramático y pegadizo. Entrada: Cinematics.", origin: "lista", p: 3, y: 2008 },
  { name: "Måneskin", genre: "Glam Rock", desc: "Glam rock italiano enérgico y sensual que revivió el rock mainstream. Actitud.", origin: "lista", p: 3, y: 2016 },
  { name: "Jhariah", genre: "Experimental / Theatrical", desc: "Mezcla emo, teatral, hyperpop y prog con energía caótica: cambios bruscos de estilo dentro del mismo tema, voz procesada y arreglos densos hechos en casa. Joven y muy creativo. Entrada: A Beginner's Guide to Faking Your Death.", p: 3, origin: "lista", pick: true, y: 2019 },

  // ===== NOMBRES POR CONFIRMAR / RAROS =====
  { name: "Ghost Ship Octavius", genre: "Prog / Melodic Metal", desc: "Prog metal melódico y atmosférico, de temas largos y voz limpia, con músicos que pasaron por Nevermore y God Forbid.", p: 3, origin: "lista", y: 2012 },
  { name: "Hell or Highwater", genre: "Hard Rock", desc: "Hard rock melódico de estructura convencional y producción de radio, montado por el batería de Atreyu. Entrada: Begin Again.", origin: "lista", p: 3, y: 2011 },
  { name: "Andrelamusia", genre: "Deathcore / Symphonic / Djent", desc: "Haifa, Israel, 2016 (se estilizan AndrelamusiA). Deathcore melodico con capas sinfonicas y ritmica djent, con letras basadas en el manga Berserk. Ganaron el Metal Battle israeli y representaron al pais en Wacken. Su unico disco, Pandemonium (2022), esta bien ejecutado, pero se mueve dentro del molde de Shadow of Intent y Periphery: la complejidad es heredada, no propia.", origin: "lista", p: 3, y: 2022, c: 2 },
  { name: "2 Shadows", genre: "Alt Rock / Post-Grunge", desc: "Banda canadiense de rock alternativo, no metalcore como figuraba aqui. Se hicieron virales con Goths in Ungothly Places y publicaron el EP Bring the Cold Inside (2022) antes de girar por Estados Unidos con The Veer Union. Rock alternativo de radio, correcto y sin aristas.", origin: "lista", p: 3, y: 2022, c: 2 },
  { name: "DVL", genre: "Heavy Metal / Metalcore", desc: "Metal moderno de Glasgow que alterna limpios y guturales. Dos discos, The Pawn That Took the King y Hush (2023), este un conceptual de relatos cortos sobre salud mental: sólido y bien producido, pero dentro del molde.", origin: "lista", p: 3, y: 2023, c: 2 },
  { name: "Defecto", genre: "Prog / Power Metal", desc: "Prog y power metal danés melódico y técnico, con buena voz: competente dentro del molde.", p: 3, origin: "lista", y: 2014 },
  { name: "Eastern High", genre: "Progressive Metal (SE)", desc: "Metal progresivo sueco nacido en 2016 de una banda de melodeath y thrash: mezcla melodía, riff de raíz death y pasajes prog. Debut: Garden of Heathens (2017).", p: 3, origin: "lista", y: 2016 },
  { name: "Nekrogoblikon", genre: "Melodic Death / Folk", desc: "Melodeath cómico sobre goblins, con teclados y mucho gancho. Divertido y técnico.", origin: "lista", pick: true, p: 3, y: 2006 },
  { name: "Damage Control", genre: "Hard Rock", desc: "Supergrupo britanico de 2007: Spike (The Quireboys) a la voz, Pete Way (UFO) al bajo, Chris Slade (AC/DC) a la bateria y Robin George a la guitarra. Dos discos entre 2007 y 2008. Curriculum enorme y hard rock clasico y directo: el cartel no compensa la falta de ambicion instrumental, asi que se queda donde le corresponde por lo que suena, no por quien lo toca.", origin: "lista", p: 3, y: 2007, c: 2 },
  { name: "CrazyEightyEight", genre: "Post-Hardcore / Metalcore", desc: "Proyecto nacido por internet con Lauren Babic a la voz junto a Jarrod Alonge y Patty Walters: post-hardcore agresivo y melódico, con Babic alternando limpios y guturales. La escritura es de género, no instrumentalmente ambiciosa.", origin: "lista", p: 3, y: 2021, c: 2 },
  { name: "Hacride", genre: "Prog / Groove Metal", desc: "Metal progresivo francés denso, de la órbita de Gojira: riffs de groove con disonancia y cambios de métrica, texturas atmosféricas y temas largos en Amoeba (2007) y Lazarus (2009). Entrada: Amoeba.", p: 2, origin: "lista", pick: true, y: 2001 },
  { name: "Klone", genre: "Prog / Atmospheric Metal", desc: "Prog francés que pasó del groove metal cercano a Gojira a un rock atmosférico de guitarras limpias y voz melódica, con saxo en algunos temas. Bien producido y consistente, pero la escritura es de canción larga y ambiental más que de complejidad instrumental. Entrada: Here Comes the Sun.", p: 3, origin: "lista", pick: true, y: 1995, c: 2 },
  { name: "Trepalium", genre: "Groove / Jazz Metal", desc: "Groove metal francés que mete swing y jazz dentro del riff: pasajes de swing de verdad entre muros de groove pesado y técnico, sobre todo en H.N.O.P. (2009) y Voodoo Moonshine (2012). Entrada: H.N.O.P.", origin: "lista", pick: true, p: 2, y: 2000 },
  { name: "I, Omega", genre: "Progressive Metalcore", desc: "Quinteto de Los Ángeles: metalcore progresivo con un punto de metal sureño en los riffs y cambios de compás, pero digerible por diseño. Su disco es Transients.", origin: "lista", p: 3, y: 2014, c: 2 },
  { name: "Unparalleled Height", genre: "Progressive Metalcore", desc: "Quinteto autogestionado de Pittsburgh activo desde 2010: metalcore con inclinación progresiva, correcto dentro del molde. Entrada: Rise of the Voiceless.", origin: "lista", p: 3, y: 2013, c: 2 },
  { name: "Ember Oceans", genre: "Synth Rock / Indie Pop", desc: "Proyecto de Chicago liderado por Freddy Tyler Paul: synth rock colorido de producción densa y voz deliberadamente teatral. EP Sleepwalk.", origin: "lista", p: 3, y: 2023, c: 2 }
];

// Recomendaciones previas de Claude que NO estaban en la lista original (para no perderlas)
const PRIOR_RECS = [
  // Veta Queen
  { name: "Kate Bush", genre: "Art Pop / Experimental", desc: "Art pop con arreglos poco ortodoxos, usando el Fairlight como instrumento y no como truco, y en la segunda cara de Hounds of Love una suite continua con instrumentación folk irlandesa (uilleann pipes, fiddle) sobre estructuras que no vuelven al estribillo. Sofisticada de arreglo y de producción más que compleja de ejecución. Entra por Hounds of Love. (voz femenina)", origin: "rec", p: 2, y: 1978, c: 1, female: true },
  { name: "Renaissance", genre: "Symphonic Prog Rock", desc: "Prog sinfónico setentero con Annie Haslam, soprano de cinco octavas de rango, cantando sobre arreglos orquestales escritos y piano de raíz clásica en vez de guitarra: la banda apenas usa distorsión y construye a base de cuerda, coro y contrapunto. Scheherazade es una suite de veinticuatro minutos basada en Rimski-Kórsakov. (voz femenina)", origin: "rec", female: true, p: 3, y: 1969, via: "Queen" },
  { name: "Florence + The Machine", genre: "Art Pop / Baroque", desc: "Art pop de escala coral: arpa como instrumento principal en lugar de guitarra, percusión de tambor grande muy adelante, y capas de voz propias apiladas hasta sonar a coro. Florence Welch canta con una proyección enorme y las canciones crecen por acumulación en vez de por estribillo. Entrada: Lungs o Ceremonials. (voz femenina)", origin: "rec", female: true, p: 3, y: 2007, via: "Queen" },
  { name: "Heart", genre: "Hard Rock", desc: "Las hermanas Wilson: Ann canta con un rango y una potencia enormes y Nancy toca guitarra acústica de digitación abierta, algo poco común en el hard rock de los setenta, así que los discos alternan riffs pesados con pasajes casi folk (Crazy on You lo hace dentro del mismo tema). Entrada: Dreamboat Annie o Little Queen. (voz femenina)", origin: "rec", female: true, p: 2, y: 1973, via: "Queen" },
  { name: "Sparks", genre: "Art Pop / Glam", desc: "Seis décadas reinventándose sin repetirse: glam, synth-pop, ópera, pop de cámara. Lil' Beethoven (2002) abandonó por completo el beat electrónico por repetición y arreglos casi clasicistas, y funcionó. Su disco 26, Mad! (2025), fue el más alto en listas de toda su carrera. Armonía retorcida bajo apariencia camp. Entrada: Kimono My House, luego Lil' Beethoven.", origin: "rec", p: 1, y: 1971, via: "Queen", c: 1 },
  { name: "Annie Lennox / Eurythmics", genre: "Synth Pop / Art", desc: "Synth pop construido por dos personas: Dave Stewart programaba secuencias y cajas de ritmo mientras Annie Lennox cantaba con un registro de contralto muy grave para el pop de la época, alternando frialdad mecánica de la base con interpretación teatral encima. Ese contraste es todo el asunto. Entrada: Sweet Dreams (Are Made of This). (voz femenina)", origin: "rec", female: true, p: 2, y: 1980, via: "Queen" },
  { name: "Bat for Lashes", genre: "Art Pop / Dream", desc: "Art pop atmosférico de Natasha Khan: construye sobre clavicémbalo, arpa, percusión de mano y sintetizador antiguo en vez de banda de rock, con armonías modales y estructuras que no vuelven al estribillo. Onírico y con narrativa de personajes. Entrada: Two Suns. (voz femenina)", origin: "rec", female: true, p: 3, y: 2006, via: "Queen" },
  { name: "Grace Slick / Jefferson Airplane", genre: "Psych Rock", desc: "Psicodelia de San Francisco con dos voces al frente, Grace Slick y Marty Balin, el bajo de Jack Casady con líneas melódicas propias y la guitarra de Jorma Kaukonen en contrapunto. Surrealistic Pillow (1967), After Bathing at Baxter's, el más experimental, Crown of Creation y Volunteers (1969) son la cumbre; los setenta bajan. Entrada: After Bathing at Baxter's.", p: 2, origin: "rec", female: true, y: 1965, via: "Queen" },
  { name: "St. Vincent", genre: "Art Rock / Experimental", desc: "Annie Clark: guitarrista de fraseo anguloso y sonido propio, con fuzz y ataques secos, dentro de canciones de art rock con arreglos de cuerda y electrónica muy controlados. De Marry Me (2007) a Strange Mercy, St. Vincent (2014), Masseduction y All Born Screaming (2024) cambia de piel en cada disco. Entrada: Strange Mercy.", p: 2, origin: "rec", female: true, y: 2006, via: "Queen" },
  // Veta A7X / PTH
  { name: "Coheed and Cambria", genre: "Prog Rock", desc: "Veta A7X: prog con saga conceptual gigante, voz aguda y complejidad con ganchos.", origin: "rec", p: 3, y: 1995, via: "A7X" },
  { name: "Ne Obliviscaris", genre: "Prog / Extreme Metal", desc: "Prog extremo con el violín de Tim Charles como instrumento co-líder, no de adorno, contestando a las guitarras en piezas de diez y doce minutos que pasan del blast beat al flamenco y al jazz, con la batería descomunal de Dan Presland (que volvió en 2024). Portal of I (2012), Citadel (2014), Urn (2017) y Exul (2023): cuatro discos y ninguno baja. Australianos como Be'lakor, pero mucho más ambiciosos. Entrada: Portal of I, luego Exul.", origin: "rec", p: 1, y: 2003, via: "A7X", c: 2 },
  { name: "Be'lakor", genre: "Melodic Death / Prog", desc: "Escriben temas de ocho a doce minutos con desarrollo real, donde un tema de guitarra vuelve transformado varios minutos después y las secciones instrumentales largas llevan el peso en vez de rellenar entre estrofas, con piano y guitarra limpia entretejidos dentro del riff. Australianos, y de lo más compositivamente ambicioso del melodeath actual. Entra por Vessels o Stone's Reach.", origin: "heard", p: 1, y: 2004, c: 2 },
  { name: "Omnium Gatherum", genre: "Melodic Death", desc: "Melodeath con teclados atmosféricos y melodías enormes, mucho gancho.", origin: "rec", p: 3, y: 1996, via: "A7X" },
  // Veta PTH técnico
  { name: "The Safety Fire", genre: "Prog Metal", desc: "Prog británico técnico de riffs angulosos en compases impares, con dos guitarras que se cruzan en vez de doblarse y voz limpia por encima. Grind the Ocean (2012) y Mouth of Swords (2013) son toda su obra. Entrada: Grind the Ocean.", p: 2, origin: "rec", y: 2006, via: "PTH" },
  { name: "Periphery", genre: "Djent / Prog", desc: "Te gustan y los ves muy únicos: no has escuchado otra banda con ese sonido. Te gusta todo desde Periphery II, con los dos Juggernaut (Alpha y Omega) como favoritos; A Pale White Dot y Periphery V te parecieron solo correctos, sin salir de su terreno. La sustancia: contrapunto de tres guitarras con líneas distintas en vez de dobladas, sobre la batería de Matt Halpern, que frasea contra el riff y no con él.", origin: "rec", pick: true, y: 2005, via: "PTH", p: 1, c: 2 },
  { name: "Spiritbox", genre: "Metalcore / Djent", desc: "Metalcore y djent con la voz de Courtney LaPlante, que pasa del limpio etéreo al gutural dentro de la misma frase, sobre riffs de ocho cuerdas y capas electrónicas. Eternal Blue (2021) y Tsunami Sea (2025). Entrada: Eternal Blue.", p: 2, origin: "rec", female: true, y: 2017, via: "PTH" },
  { name: "Jinjer", genre: "Groove / Prog Metal", desc: "Ucranianos: el bajo de Eugene Abdukhanov toca líneas propias con slap y acordes, la batería de Vlad Ulasevich cambia de subdivisión dentro del riff, y Tatiana Shmayluk pasa de voz limpia a gutural en la misma frase. De Macro (2019) a Wallflowers y Duél (2025). Entrada: Macro.", p: 2, origin: "rec", female: true, y: 2008, via: "PTH" }
];

// Bandas que Ken YA escuchó y que no estaban en el catálogo. Se precargan como escuchadas.
const HEARD_SEED = [
  { name: "Avenged Sevenfold", genre: "Metalcore / Hard Rock", desc: "Tu vara de medir, y la música lo sostiene: The Rev escribía partes de batería con forma propia, con dobles bombos en tresillos y fills que reordenan el compás en vez de rellenarlo, y Synyster Gates y Zacky Vengeance trabajan armonías gemelas y solos sobre progresiones de raíz neoclásica. City of Evil abandona el screamo por completo y The Stage estira las estructuras hasta los quince minutos con orquesta. Tus favoritos: City of Evil, el homónimo, The Stage, Nightmare, Waking the Fallen y Life Is But a Dream; menos Hail to the King. Entrada: City of Evil.", origin: "heard", y: 1999, p: 1, c: 1 },
  { name: "Mastodon", genre: "Prog / Sludge Metal", desc: "La batería de Brann Dailor es melódica: toca frases con forma propia en vez de marcar, y buena parte de los temas se sostienen sobre ella. Guitarras en armonía a dos voces sobre métrica cambiante y estructuras que no repiten estribillo, de Leviathan a Crack the Skye y Emperor of Sand. Brent Hinds dejó la banda en marzo de 2025 y murió en un accidente de moto el 20 de agosto de ese año; Marrow Deep (agosto de 2026), con Nick Johnston a la guitarra, es el primer disco sin él. Entrada: Crack the Skye, luego Leviathan.", origin: "heard", pick: true, y: 2000, p: 1, c: 1 },
  { name: "Between the Buried and Me", genre: "Prog Metal / Tech", desc: "Death técnico, prog, jazz, bluegrass y pasajes acústicos dentro de una misma canción, con cambios de compás constantes, sin repetir estructura y con Blake Richardson a la batería sosteniendo esos saltos. Colors (2007) son sesenta y cinco minutos continuos, sin cortes reales entre temas, y The Blue Nowhere (2025), el primero como cuarteto, mantiene la mezcla. Entrada: Colors.", origin: "rec", pick: true, y: 2000, p: 1, c: 1 },
  { name: "Dream Theater", genre: "Prog Metal", desc: "Suites de veinte minutos con desarrollo temático de verdad, cambios de compás dentro de la frase y unísonos escritos entre teclado y guitarra que exigen precisión de conjunto. Lo hacen desde Images and Words hasta hoy, con Scenes from a Memory como obra conceptual entera. Mike Portnoy volvió a la batería en 2023 y Parasomnia (2025) es el primer disco con él desde 2009. Entrada: Metropolis Pt. 2.", origin: "heard", y: 1985, p: 1, c: 2 },
  { name: "Protest the Hero", genre: "Tech Metalcore / Prog", desc: "Luke Hoskin y Tim Millar escriben líneas de guitarra que van por su cuenta en vez de doblarse, con cambios de compás constantes dentro del mismo tema y armonías casi neoclásicas, mientras Rody Walker canta melodías limpias muy agudas por encima de todo ese lío. Canadienses. Siete discos sin bajón: Kezia (2005), Fortress (2008), Scurrilous, Volition (2013), con Chris Adler a la batería, Pacific Myth, Palimpsest (2020) y Within (julio de 2026), el primero totalmente independiente. Entrada: Fortress o Kezia.", origin: "rec", p: 1, y: 1999, c: 2 },
  { name: "Meshuggah", genre: "Djent / Extreme Prog", desc: "Riffs en ciclos de longitud impar sobre un charles fijo en 4/4, así que el patrón tarda varios compases en cuadrar otra vez: la polirritmia es la estructura, no un efecto. Y llevan de Destroy Erase Improve a Immutable puliendo esa idea sin repetir disco. Entrada: obZen.", origin: "heard", pick: true, y: 1987, p: 1 , c: 2 },
  { name: "Gojira", genre: "Prog / Groove Metal", desc: "Franceses, y el motor es la batería: Mario Duplantier toca patrones que cambian de subdivisión bajo el mismo riff y usa el bombo como elemento melódico, mientras Joe hace pick slides y armónicos que suenan a ballena. Groove pesadísimo con atmósfera, y cada disco lo mueve: From Mars to Sirius (2005) y The Way of All Flesh son los más largos y densos, L'Enfant sauvage y Magma lo aprietan en temas más cortos, y Fortitude (2021) lo abre a ritmos tribales. Entrada: From Mars to Sirius o Magma.", origin: "heard", pick: true, y: 1996, p: 1, c: 2 },
  { name: "Destrage", genre: "Tech / Math Metal", desc: "Italianos: metal técnico hiperactivo que salta de riff mathcore a estribillo melódico y a groove funk en segundos, con la batería cambiando de estilo a la misma velocidad. Caótico y pegadizo a la vez. Entrada: Are You Kidding Me? No.", p: 2, origin: "heard", pick: true, y: 2007 },
  { name: "Killswitch Engage", genre: "Metalcore", desc: "La referencia del metalcore melódico moderno: equilibrio entre gutural y estribillo limpio, riffs de raíz sueca y solos de Adam Dutkiewicz. Alive or Just Breathing (2002), The End of Heartache y As Daylight Dies (2006) son la cumbre; lo posterior es más irregular. Entrada: The End of Heartache.", p: 3, origin: "heard", y: 1999 },
  { name: "Alter Bridge", genre: "Hard Rock / Alt Metal", desc: "Hard rock con Mark Tremonti escribiendo riffs armonizados a dos guitarras y solos con desarrollo, y Myles Kennedy cantando en un registro muy alto sostenido. Bien tocado y melódico, pero la estructura es de canción con estribillo en casi todo el catálogo. Entrada: Blackbird.", origin: "heard", p: 3, y: 2004 },
  { name: "Bullet for My Valentine", genre: "Metalcore", desc: "Metalcore galés melódico con solos y estribillos grandes, de guitarras gemelas en la línea de Iron Maiden. The Poison (2005) y Scream Aim Fire son lo mejor; Temper Temper (2013) y Gravity (2018) son el bajón. Entrada: The Poison.", p: 3, origin: "heard", y: 1998 },
  { name: "Ice Nine Kills", genre: "Metalcore / Theatrical", desc: "Metalcore teatral y conceptual: cada canción es una película de terror, con orquestación, coros y cambios de sección que siguen la historia y la voz de Spencer Charnas como narrador. The Silver Scream (2018) y The Silver Scream 2: Welcome to Horrorwood (2021) son la cumbre, y los primeros discos quedan por debajo. Entrada: The Silver Scream.", p: 2, origin: "heard", pick: true, y: 2006 },
  { name: "Behemoth", genre: "Blackened Death", desc: "Riffs de trémolo rápidos, batería de Inferno muy técnica al doble bombo y, a partir de ahí, coros, orquestación y arreglos que sí cambian de disco a disco. Tu mapa: de Evangelion (2009) hacia atrás lo ves repetitivo y con poca sustancia, salvo los primerísimos; de The Satanist (2014) en adelante hay experimentación real, y cada disco trae algo propio: I Loved You at Your Darkest (2018), Opvs Contra Natvram (2022) y The Shit ov God (2025). Entrada: The Satanist.", origin: "heard", p: 2, y: 1991, c: 2 },
  { name: "Atreyu", genre: "Metalcore", desc: "Metalcore melódico californiano de los dos mil con solos y estribillos limpios, y la batería cantada de Brandon Saller. The Curse (2004) y A Death-Grip on Yesterday son lo mejor. Entrada: The Curse.", p: 3, origin: "heard", y: 1998 },
  { name: "Machine Head", genre: "Groove / Thrash Metal", desc: "Groove metal robusto con momentos épicos y técnicos. Ya lo escuchaste. The Blackening (2007) es su disco más ambicioso; el último es Unatoned (2025).", origin: "heard", p: 3, y: 1991 },
  { name: "Mutiny Within", genre: "Melodic Death / Prog", desc: "Melodeath progresivo estadounidense con teclados y limpio/gutural. Subestimado.", origin: "heard", p: 3, y: 2002 },
  { name: "Pentakill", genre: "Power / Heavy Metal", desc: "Banda virtual de League of Legends: power metal épico con invitados de lujo. Divertido y bien hecho.", origin: "heard", p: 4, y: 2014 },
  { name: "Metallica", genre: "Thrash / Heavy Metal", desc: "En su gran mayoría no te gusta: la encuentras aburrida muchas veces y lo reciente directamente mediocre. Lo medio salvable son los primeros discos y, de lo moderno, Death Magnetic. Aun en sus mejores momentos se queda por debajo de tu nivel de exigencia instrumental. Se conserva por contexto histórico, no como recomendación. Prefieres Megadeth.", origin: "heard", y: 1981, p: 4 },
  { name: "Megadeth", genre: "Thrash Metal", desc: "Te gusta más que Metallica: una pizca más técnica y más ambiciosa, sobre todo en el trabajo de guitarra a dos voces y en los cambios de Rust in Peace. Aun así no entra entre tus pilares. Se despiden: Megadeth (enero de 2026) es su último disco y ahora hacen la gira de despedida.", origin: "heard", y: 1983, p: 3 },
  { name: "Pantera", genre: "Groove Metal", desc: "Los reyes del groove metal. Ya lo escuchaste. Dimebag Darrell murió en 2004 y Vinnie Paul en 2018; desde 2022 Phil Anselmo y Rex Brown giran con Zakk Wylde y Charlie Benante.", origin: "heard", p: 3, y: 1981 },
  { name: "Iron Maiden", genre: "Heavy Metal (clásico)", desc: "El bajo de Steve Harris toca líneas melódicas propias al galope que discuten con la guitarra, y desde 1999 son tres guitarristas armonizando a tres voces. Escriben largo de verdad: Rime of the Ancient Mariner son trece minutos y medio. Tu mapa por etapas: muy buenos hasta Seventh Son, luego un bloque más flojo, y con la vuelta de Bruce en Brave New World una evolución real sobre lo que ya hacían, de donde salen tus favoritos, A Matter of Life and Death y Dance of Death. Su punto más débil para ti es la batería. Entra por A Matter of Life and Death.", origin: "heard", p: 1, y: 1975, c: 2 },
  { name: "Slipknot", genre: "Nu Metal", desc: "Nu metal brutal y teatral de nueve miembros. Ya escuchado.", origin: "heard", p: 3, y: 1995 },
  { name: "In Flames", genre: "Melodic Death", desc: "Tus favoritos son los primeros discos, y aunque de Reroute to Remain en adelante siguen teniendo cosas buenas (te gusta el más reciente), siempre vuelves a los primeros. Esa etapa clásica de The Jester Race, Whoracle y Colony son armonías gemelas de guitarra con giros de folk sueco sobre riffs rápidos y batería contenida. De Reroute en adelante se fueron a estribillos limpios, electrónica y estructura de rock alternativo. La categoría 1 se queda porque el cambio es real, aunque el resultado te convenza menos. Ya tienen grabado su disco número quince, con Jon Rice a la batería. Entrada: The Jester Race.", origin: "heard", p: 2, y: 1990, c: 1 },
  { name: "Dethklok", genre: "Melodic Death (Metalocalypse)", desc: "Te parece muy bueno, con sustancia de disco a disco y bastante consistente, y no hay ningún álbum que te desagrade. No es una broma tocada de cualquier manera: lo escribe y lo toca Brendon Small con Gene Hoglan a la batería, con riffs de verdad, armonías gemelas y solos con desarrollo, bajo una producción limpia y muy tocada. Nació como banda de una serie pero se sostiene sola. Entra por Dethalbum II.", origin: "heard", p: 2, y: 2006, c: 2 },
  { name: "Guns N' Roses", genre: "Hard Rock", desc: "Hard rock clásico con el fraseo suelto y bluesero de Slash frente a Izzy Stradlin haciendo la rítmica, y la voz nasal y agudísima de Axl. Appetite for Destruction es directo y sin adornos; Use Your Illusion se va a canciones largas con piano y orquesta. Entrada: Appetite for Destruction.", origin: "heard", p: 3, y: 1985 },
  { name: "Rise Against", genre: "Melodic Hardcore / Punk", desc: "Punk y hardcore melódico de Chicago con mensaje social: tempos rápidos, estribillos grandes y guitarras directas. The Sufferer & the Witness (2006) es lo mejor. Entrada: The Sufferer & the Witness.", p: 3, origin: "heard", y: 1999 },
  { name: "Muse", genre: "Alt Rock / Prog", desc: "Tu mapa: te quedas con Showbiz, Origin of Symmetry, Absolution y The Resistance, y de The 2nd Law sobre todo Animals y Explorers; de Simulation Theory en adelante no te convence. Es rock de estadio con gestos de prog más que prog: los cambios entre discos son de estilo, no de estructura, pero Bellamy escribe piano de raíz clásica y riffs que hacen de motor. The Wow! Signal salió en 2026.", origin: "rec", p: 2, y: 1994, c: 2 },
  { name: "Ghost", genre: "Occult Rock / Metal", desc: "Rock melódico de raíz doom con estribillos enormes y armonías de guitarra a dos voces, muy bien escrito, con estructura de canción clásica y producción limpia. Prequelle es su disco con más peso instrumental: Miasma lleva un solo de saxofón y Helvetesfönster es otra pieza sin voz, y es justo el que te había gustado. Entrada: Prequelle o Meliora.", origin: "heard", p: 2, y: 2006, c: 1 },
  { name: "Cage the Elephant", genre: "Alt Rock / Garage", desc: "Rock alternativo de riff directo con estribillos grandes, que va del garage sucio de los primeros discos al pop rock pulido de Social Cues, siempre en formato canción de cuatro minutos. Bien tocado y con energía, pero sin ambición instrumental. Entra por Melophobia.", origin: "heard", p: 3, y: 2006, c: 1 },
  { name: "Glass Animals", genre: "Indie / Psych Pop", desc: "Indie pop psicodélico británico de texturas, groove y producción muy trabajada. How to Be a Human Being (2016) y Dreamland (2020). Entrada: How to Be a Human Being.", p: 3, origin: "heard", y: 2010 },
  { name: "Siames", genre: "Indie / Alt Rock", desc: "Proyecto argentino de indie atmosférico y narrativo, oscuro y melódico, conocido por sus videos animados.", p: 3, origin: "heard", y: 2011 },
  { name: "Panic! at the Disco", genre: "Pop Rock / Theatrical", desc: "En general te gustan, pero sobre todo lo primero, y Pretty. Odd. es tu favorito de todo el artista; del último dices que sorprende y que sientes que vuelven a sus raíces. Lo que hay de verdad: A Fever You Can't Sweat Out mete acordeón, electrónica y arreglos de cabaret dentro del pop-punk, y Pretty. Odd. es un disco orquestal de vientos y cuerdas con escritura muy de los Beatles tardíos, grabado con banda entera. De Vices & Virtues en adelante se concentra en Brendon Urie y se vuelve pop más directo. Entra por Pretty. Odd.", origin: "heard", p: 2, y: 2004, c: 1 },
  { name: "BTS", genre: "K-Pop", desc: "Producción de pop de altísimo presupuesto que cambia de registro entre discos (hip-hop, EDM, disco, R&B, balada orquestal), con arreglos vocales repartidos entre siete voces de timbres distintos y coreografía pensada junto a la música. La escritura es de canción pop con equipos de compositores; la ambición está en la producción y en el concepto de álbum, no en la ejecución instrumental. Miembros suyos ya están aparte en el catálogo (RM y Agust D). Entrada: Wings o Map of the Soul: 7.", origin: "heard", y: 2013, p: 2, c: 1 }
];

const NEW_RECS = [
  { name: "RM", genre: "Hip-Hop / Art Pop", desc: "El líder de BTS en solitario, moviéndose entre hip-hop, folk, R&B y city pop con invitados de cada terreno. Funciona más como curaduría de estilos que como escritura propia. Entrada: Indigo.", origin: "rec", pick: true, p: 3, y: 2015, via: "BTS", c: 1 },
  { name: "Agust D (Suga)", genre: "Hip-Hop / Rap", desc: "El lado rap del miembro de BTS en solitario, con bases atmosféricas y temas personales duros. La escritura de rap es correcta, pero sin ambición instrumental por debajo. Entrada: D-Day.", origin: "rec", pick: true, p: 3, y: 2016, via: "BTS" },
  { name: "Hadestown", genre: "Musical / Folk-Jazz", desc: "Folk americano cruzado con jazz de Nueva Orleans, con trombón, banjo, acordeón y contrabajo tocados por una banda visible en escena, y motivos melódicos que vuelven transformados para reflejar que el mito se repite en bucle. Anaïs Mitchell escribe melodías preciosas y la instrumentación es orgánica. Pero es un musical de canciones, no de contrapunto: al lado de Sondheim o Bernstein la escritura es mucho menos densa. ▸ Versión: el Original Broadway Cast Recording de 2019 (con André De Shields y Patrick Page); para el origen más folk e íntimo, el álbum concepto de Anaïs Mitchell de 2010.", origin: "rec", p: 2, y: 2019, c: 2 },
  { name: "Sweeney Todd", genre: "Musical (Sondheim)", desc: "Sondheim construye casi toda la partitura sobre el Dies Irae, el canto gregoriano de difuntos, transformándolo por toda la obra hasta dentro de las canciones cómicas; escribe contrapunto real, con personajes cantando líneas melódicas distintas a la vez que encajan (el dúo de A Little Priest, el cuarteto de Kiss Me), y usa disonancia sin resolver para sostener la tensión. Está más cerca de la ópera que del musical. ▸ Versión: el Original Broadway Cast de 1979 (completo, con Angela Lansbury y Len Cariou); la película de Tim Burton de 2007 recorta varias canciones, no la tomes como entrada.", origin: "rec", p: 1, y: 1979, c: 2 },
  { name: "Jesus Christ Superstar", genre: "Musical / Rock Opera", desc: "Rock opera de Andrew Lloyd Webber: guitarras electricas, dramatismo y voces gritadas. Teatralidad-Queen. ▸ Versión: el álbum concepto original de 1970 con Ian Gillan (Deep Purple) como Jesús, la mas rockera; el Live in Concert de 2018 para una toma moderna.", origin: "rec", pick: true, p: 2, y: 1970, via: "Musicales" },
  { name: "Tommy (The Who)", genre: "Musical / Rock Opera", desc: "Rock opera fundacional de The Who: album de rock hecho musical, narrativa surrealista con riffs. ▸ Versión: el álbum original de The Who de 1969 (el esencial); el soundtrack de la película de 1975 es divertido pero irregular.", origin: "rec", pick: true, p: 3, y: 1969, via: "Musicales" },
  { name: "Hedwig and the Angry Inch", genre: "Musical / Glam Rock", desc: "Glam rock musical (Bowie/Iggy/Velvet). La banda sonora funciona como un disco de rock real. ▸ Versión: el soundtrack de la película de 2001 (John Cameron Mitchell, la mejor en producción) o el Original Cast de 1998 mas crudo.", origin: "rec", pick: true, p: 2, y: 1998, via: "Musicales" },
  { name: "Repo! The Genetic Opera", genre: "Musical / Industrial Rock", desc: "Distopía gótica cantada casi de principio a fin, con partitura que mezcla rock industrial y recitativo de ópera. De culto, teatral y camp oscuro. ▸ Versión: el soundtrack de la película de 2008 (es cine antes que teatro; esa es la grabación a buscar).", origin: "rec", pick: true, p: 3, y: 2008, via: "Musicales" },
  { name: "Hamilton", genre: "Musical / Hip-Hop", desc: "El motor es el rap: la densidad de rima interna y el cambio de flow marcan quién es cada personaje, y los motivos musicales vuelven transformados a lo largo de las dos horas y media. La orquestación es de musical clásico por debajo del hip-hop. ▸ Versión: el Original Broadway Cast Recording de 2015 con Lin-Manuel Miranda (la definitiva); el film de Disney+ es ese mismo elenco filmado.", origin: "rec", pick: true, p: 2, y: 2015, via: "Musicales", c: 1 },
  { name: "American Idiot", genre: "Musical / Punk Rock", desc: "El álbum de Green Day adaptado a musical de punk rock, con la banda en escena y los temas encadenados sin pausa. ▸ Versión: el álbum original de Green Day de 2004 (el núcleo); el Original Broadway Cast de 2010 si quieres la expansión teatral con temas extra.", origin: "rec", pick: true, p: 3, y: 2004, via: "Musicales" },
  { name: "Spring Awakening", genre: "Musical / Alt Rock", desc: "Rock alternativo (Duncan Sheik) con libreto sobre adolescentes del siglo XIX. ▸ Versión: el Original Broadway Cast Recording de 2006 (Lea Michele y Jonathan Groff, la definitiva).", origin: "rec", pick: true, p: 3, y: 2006, via: "Musicales" },
  { name: "Beetlejuice the Musical", genre: "Musical / Comedy Rock", desc: "Ingenioso, oscuro-divertido y muy teatral. ▸ Versión: el Original Broadway Cast Recording de 2019 (Alex Brightman y Sophia Anne Caruso).", origin: "rec", pick: true, p: 3, y: 2018, via: "Musicales" },
  { name: "The Lightning Thief Musical", genre: "Musical / Rock", desc: "Musical de rock solido basado en Percy Jackson. ▸ Versión: el Original Cast Album (Chris McCarrell); elenco pequeño y sonido rock crudo a propósito.", origin: "rec", pick: true, p: 3, y: 2017, via: "Musicales" },
  { name: "Heathers the Musical", genre: "Musical / Pop Rock", desc: "Satirico y oscuro. ▸ Versión: el Original Off-Broadway Cast de 2014 (Barrett Wilbert Weed, la clásica); la versión del West End de Londres tiene canciones añadidas/distintas si quieres comparar.", origin: "rec", pick: true, p: 3, y: 2014, via: "Musicales" },
  { name: "Savatage", genre: "Heavy / Power Metal", desc: "A partir de Streets meten cambios de tempo dentro del tema, piano como instrumento principal en vez de adorno, orquestación y coro, y estructuras de varias partes que no vuelven al estribillo. Criss Oliva tocaba solos melódicos largos con desarrollo, no ráfagas; murió en un accidente en 1993 y el sonido de la banda cambió después. De aquí salió Trans-Siberian Orchestra. Entra por Streets o Dead Winter Dead.", origin: "rec", p: 1, y: 1983, c: 2 },
  { name: "Avantasia", genre: "Power Metal / Rock Opera", desc: "Rock operas melodicas/sinfonicas de Tobias Sammet con muchos vocalistas invitados. Idea coral-operistica tipo Queen. The Scarecrow.", origin: "rec", pick: true, p: 3, y: 2001, via: "Queen pesado" },
  { name: "Queensryche", genre: "Prog Metal", desc: "Prog metal de voz dominante: Geoff Tate canta como protagonista sobre arreglos de dos guitarras armonizadas y cambios de sección teatrales. Rage for Order (1986) y Operation: Mindcrime (1988), una ópera rock entera con coros y orquesta, son el pico; desde mediados de los noventa la escritura se simplifica mucho. Entrada: Operation: Mindcrime.", p: 2, origin: "rec", pick: true, y: 1982, via: "Queen pesado" },
  { name: "Therion", genre: "Symphonic Metal", desc: "Symphonic metal con coros operisticos reales y orquesta completa. Opera con guitarras. Vovin, Theli.", origin: "rec", pick: true, p: 2, y: 1987, via: "Queen pesado" },
  { name: "Kamelot", genre: "Symphonic Power Metal", desc: "Symphonic power metal con discos conceptuales y voz dramatica (Roy Khan). Elegante y oscuro. The Black Halo.", origin: "rec", pick: true, p: 3, y: 1991, via: "Queen pesado" },
  { name: "Epica", genre: "Symphonic Metal", desc: "Symphonic metal con Simone Simons (operistica limpia) mas guturales y orquesta/coro enormes. Epico y barroco.", origin: "rec", pick: true, female: true, p: 3, y: 2002, via: "Queen pesado" },
  { name: "Battle Beast", genre: "Power Metal", desc: "Power metal teatral con Noora Louhimo, vibra glam-ochentera. Descaro escenico melodico tipo Queen/Meat Loaf.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "Queen pesado" },
  { name: "Diablo Swing Orchestra", genre: "Avant-garde Metal", desc: "Swing, vals, clásico y voz operística mezclados, con arreglos de cuerda y metales bien trabajados, pero por debajo las canciones tienen forma convencional con estribillo: la sorpresa es de timbre, no de estructura. Mr. Bungle, Unexpect y Estradasphere hacen el mismo collage con más riesgo. Entrada: The Butcher's Ballroom.", origin: "rec", p: 2, y: 2003, c: 2 },
  { name: "Sigh", genre: "Avant-garde Metal", desc: "[Comodín] Black metal japonés que Mirai Kawashima abrió a todo: orquesta, saxo, sintetizadores de los setenta, psicodelia y música tradicional japonesa, con cada disco montado sobre otra idea, del collage psicodélico de Imaginary Sonicscape al thrash sinfónico de Hangman's Hymn. Lo sostiene treinta años, de Hail Horror Hail (1997) a Imaginary Sonicscape (2001), Scenes from Hell, In Somniphobia, Heir to Despair y Shiki (2022); solo el debut, Scorn Defeat, queda por debajo. Entrada: Imaginary Sonicscape.", p: 1, origin: "rec", pick: true, y: 1989, via: "Queen pesado", c: 3 },
  { name: "Unexpect", genre: "Avant-garde Metal", desc: "Metal avant-garde canadiense: violín, bajo de nueve cuerdas, teclados y dos voces, una femenina operística, en temas que saltan de blast beat a vals y a pasajes de circo con cambios de compás constantes. In a Flesh Aquarium (2006) y Fables of the Sleepless Empire (2011) son la cumbre; el debut, Utopia, queda por debajo. Entrada: In a Flesh Aquarium.", p: 2, origin: "rec", pick: true, female: true, y: 1996, via: "Queen pesado", c: 2 },
  { name: "The Ocean", genre: "Post-Metal / Atmosférico", desc: "En Pelagial la estructura ES el descenso: una pieza continua que empieza clara y ligera y se va volviendo más lenta, grave y disonante conforme baja de capa, con la tonalidad oscureciéndose de verdad. Y en Phanerozoic alternan riffs de compás cambiante con pasajes de piano y cuerda escritos, no de relleno. Robin Staps compone para la obra entera y no por canciones, y lleva haciéndolo disco tras disco. Entra por Pelagial.", origin: "rec", p: 1, y: 2000, c: 2 },
  { name: "Enslaved", genre: "Prog Black Metal", desc: "Treinta años yendo de black y viking a prog sin que ningún disco repita al anterior: voces limpias en armonía contra guturales, teclados haciendo contrapunto y estructuras largas. Below the Lights, RIITIIR y Utgard son tres etapas distintas y las tres funcionan; Mið está anunciado para el 30 de octubre de 2026. Entrada: RIITIIR.", origin: "rec", pick: true, p: 1, y: 1991, via: "Gojira/Behemoth", c: 1 },
  { name: "Cult of Luna", genre: "Post-Metal", desc: "Post-metal monolitico y atmosferico: construcciones lentas que estallan, capas densas. Vertikal.", origin: "rec", pick: true, p: 2, y: 1998, via: "Gojira/Behemoth" },
  { name: "Persefone", genre: "Progressive Death Metal", desc: "Death progresivo de Andorra: los teclados de Miguel Espinosa en contrapunto con guitarras técnicas, voz limpia y gutural, y piezas largas que pasan del blast al piano y a pasajes casi de jazz. Core (2006), Shin-Ken (2009), Spiritual Migration (2013), la cumbre, Aathma (2017) y metanoia (2022) sostienen el nivel; el debut, Truth Inside the Shades, es más verde. Entrada: Spiritual Migration.", p: 1, origin: "rec", pick: true, y: 2001, via: "Gojira/Behemoth" },
  { name: "Fallujah", genre: "Atmospheric Death Metal", desc: "Death atmosférico y progresivo californiano con texturas etéreas casi de shoegaze sobre la brutalidad y solos de guitarra muy melódicos. The Flesh Prevails (2014) es la referencia, Dreamless y Undying Light bajan, y Empyrean (2022) y Xenotaph (2025) son su mejor etapa. Entrada: Empyrean.", p: 2, origin: "rec", pick: true, y: 2007, via: "Gojira/Behemoth" },
  { name: "Septicflesh", genre: "Symphonic Death Metal", desc: "Death sinfónico griego con orquesta y coro reales escritos por Christos Antoniou, que tiene formación de compositor: arreglos cinematográficos que no son decorado sino parte de la estructura. Esoptron (1995) y Sumerian Daemons (2003) marcan la primera etapa, y Communion (2008), The Great Mass y Codex Omega (2017) son la cumbre; Titan y Modern Primitive bajan algo. Entrada: The Great Mass.", p: 2, origin: "rec", pick: true, y: 1990, via: "Gojira/Behemoth" },
  { name: "Fleshgod Apocalypse", genre: "Symphonic Death Metal", desc: "Death técnico italiano con orquestación clásica, piano, soprano operística y la batería de Francesco Paoli a velocidades enormes: death metal barroco, teatral y denso. Agony (2011), King (2016) y Opera (2024) son lo mejor; Labyrinth (2013) es el más plano. Entrada: King.", p: 2, origin: "rec", pick: true, y: 2007, via: "Gojira/Behemoth" },
  { name: "Zeal & Ardor", genre: "Avant-garde Metal", desc: "[Comodín] Manuel Gagneux cruza black metal con cantos de trabajo y spirituals afroamericanos: coros de llamada y respuesta, palmas y cadenas sobre blast beats y trémolo, y cada disco empuja la mezcla hacia otro lado. Devil Is Fine (2016), Stranger Fruit (2018), Zeal & Ardor (2022) y Greif (2024), el más abierto al rock y al prog. Entrada: Stranger Fruit.", p: 2, origin: "rec", pick: true, y: 2013, via: "Gojira/Behemoth", c: 3 },
  { name: "Rotting Christ", genre: "Atmospheric Black Metal", desc: "Veteranos griegos que pasaron del black crudo a un sonido ritual y atmosférico con cantos casi tribales y medios tiempos repetidos. Theogonia (2007) y Rituals (2016). Entrada: Theogonia.", origin: "rec", pick: true, p: 3, y: 1987, via: "Gojira/Behemoth" },
  { name: "Ihsahn", genre: "Progressive Extreme Metal", desc: "El compositor de Emperor en solitario: metal extremo con saxo (Jørgen Munkeby en After), prog setentero y electrónica, cada disco con una idea distinta. Das Seelenbrechen (2013) llega a secciones improvisadas y el disco homónimo de 2024 salió también en versión orquestal completa. Entrada: After.", p: 2, origin: "rec", pick: true, y: 2005, via: "Gojira/Behemoth", c: 1 },
  { name: "Wilderun", genre: "Symphonic Folk Metal", desc: "Death sinfonico/folk progresivo con arreglos orquestales enormes y pasajes acusticos. Veil of Imagination.", origin: "rec", pick: true, p: 2, y: 2012, via: "Gojira/Behemoth" },
  { name: "Venom Prison", genre: "Death Metal / Hardcore", desc: "Death metal con hardcore galés, con Larissa Stupar al frente: brutal y técnico, con letras viscerales, pero de estructura bastante directa. Entrada: Samsara.", p: 3, origin: "rec", pick: true, female: true, y: 2015, via: "Gojira/Behemoth" },
  { name: "Svalbard", genre: "Blackgaze / Post-Hardcore", desc: "Post-metal y blackgaze con hardcore: trémolos de guitarra en capas, ritmos de hardcore que se abren a pasajes lentos y la voz de Serena Cherry alternando grito y limpio. It's Hard to Have Hope (2018), When I Die, Will I Get Better? (2020) y The Weight of the Mask (2023). Anunciaron que 2026 es su último año. Entrada: When I Die, Will I Get Better?", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Gojira/Behemoth" },
  { name: "Infected Rain", genre: "Nu Metal / Alt", desc: "Lena Scissorhands alternando limpio y gutural sobre groove/nu metal moldavo. Conecta con Jinjer.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "Gojira/Behemoth" },
  { name: "Hail the Sun", genre: "Post-Hardcore / Swancore", desc: "Swancore de Chico, California, con Donovan Melero cantando y tocando la batería a la vez: guitarras de tapping en contrapunto, compases que cambian dentro del estribillo y ritmos con swing bajo melodías agudísimas. Siete discos muy parejos, de Wake (2014), la cumbre, a Culture Scars, Mental Knife, New Age Filth, Divine Inner Tension (2023) y cut. turn. (2025). Entrada: Wake.", p: 2, origin: "rec", pick: true, y: 2009, via: "PTH" },
  { name: "A Lot Like Birds", genre: "Post-Hardcore", desc: "Post-hardcore teatral y técnico de Sacramento, de lo íntimo a lo explosivo, con dos voces y narrativa conceptual. Conversation Piece (2011) y No Place (2013), un disco sobre la casa de la infancia del cantante, son lo mejor. Entrada: No Place.", p: 3, origin: "rec", pick: true, y: 2009, via: "PTH" },
  { name: "Sianvar", genre: "Post-Hardcore / Swancore", desc: "Supergrupo de swancore con miembros de Hail the Sun, Stolas y Dance Gavin Dance: técnico, melódico y frenético, con guitarras de tapping entrelazadas. Un solo disco largo, Stay Lost (2016). Entrada: Stay Lost.", p: 3, origin: "rec", pick: true, y: 2013, via: "PTH" },
  { name: "Stolas", genre: "Progressive Post-Hardcore", desc: "Swancore de California: guitarras de tapping en contrapunto, cambios de compás y voces agudas, técnico y melódico dentro de la escuela de Dance Gavin Dance. Living Creatures (2013), Allomaternal y Stolas (2017). Entrada: Living Creatures.", p: 3, origin: "rec", pick: true, y: 2012, via: "PTH" },
  { name: "Eidola", genre: "Progressive Post-Hardcore", desc: "Swancore progresivo y conceptual de Utah, con guitarras de tapping en capas y voces agudas en estructuras largas. Degeneraterra (2015), To Speak, to Listen (2017) y The Architect (2022). Entrada: To Speak, to Listen.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Native Construct", genre: "Progressive Metalcore", desc: "Tres estudiantes de Berklee que escribieron Quiet World (2015) durante la carrera: armonía de jazz con improvisación real, técnicas de composición clásica y dramaturgia de teatro musical metidas dentro de una estructura de prog metal, con guitarras de rango extendido, voces operísticas y orquestación completa, sin respiro entre giro y giro. Es su único disco y llevan inactivos desde entonces. Entrada: Come Hell or High Water.", origin: "rec", p: 2, y: 2011, c: 2 },
  { name: "Last Chance to Reason", genre: "Technical Metalcore", desc: "Metalcore técnico y progresivo de Maine con teclados: riffs en compases cambiantes, solos de guitarra y teclado y discos conceptuales montados como un videojuego. Level 2 (2011) y Level 3 (2013) son lo mejor. Entrada: Level 2.", p: 2, origin: "rec", pick: true, y: 2004, via: "PTH" },
  { name: "Polyphia", genre: "Prog / Instrumental", desc: "Guitarra instrumental que cruza técnica de prog con producción de trap y pop: Tim Henson y Scott LePage escriben líneas de acústica de nailon y tapping sobre la batería de Clay Aeschliman. La técnica es deslumbrante, pero los temas son cortos y se apoyan en loops de beat más que en desarrollo: impresiona más de lo que evoluciona dentro de cada tema, de New Levels New Devils (2018) a Remember That You Will Die (2022). Entrada: New Levels New Devils.", p: 3, origin: "rec", pick: true, y: 2010, via: "PTH" },
  { name: "Plini", genre: "Prog / Instrumental", desc: "Prog instrumental australiano de guitarra melódica y atmosférica, luminoso; An Unnameable Desire (2026) es su último disco. Entrada: Handmade Cities.", p: 3, origin: "rec", pick: true, y: 2013, via: "PTH" },
  { name: "Intervals", genre: "Prog / Instrumental", desc: "Prog metal instrumental canadiense de guitarra melódica y limpia sobre base djent, luminoso y pulido. Entrada: The Shape of Colour.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Chon", genre: "Jazz Fusion", desc: "Math rock y fusión instrumental de California: guitarras con tapping y armonía de jazz en líneas que se entrelazan, cálido y melódico, con groove. Grow (2015), Homey (2017) y Chon (2019). Entrada: Grow.", origin: "rec", pick: true, p: 2, y: 2008, via: "PTH" },
  { name: "Covet", genre: "Melodic Math Rock", desc: "Math rock instrumental liderado por Yvette Young, de tapping a dos manos y afinaciones abiertas: brillante y melódico. Entrada: Effloresce.", p: 3, origin: "rec", pick: true, female: true, y: 2014, via: "PTH" },
  { name: "Kayo Dot", genre: "Avant-garde / Experimental", desc: "El proyecto de Toby Driver tras maudlin of the Well: cada disco es otro terreno, del metal de cámara de Choirs of the Eye (2003) al jazz-rock ambiental de Blue Lambency Downward, el metal pesado de Hubardo (2013) o el synth de Plastic House on Base of Sky. Muy desigual, con cumbres enormes en Choirs of the Eye, Dowsing Anemone with Copper Tongue y Hubardo. Entrada: Choirs of the Eye.", p: 2, origin: "rec", pick: true, y: 2003, via: "Dream Theater", c: 1 },
  { name: "maudlin of the Well", genre: "Avant-garde Metal", desc: "El primer proyecto de Toby Driver: metal que se abre a jazz, cámara y ambient dentro de un mismo tema, con trompeta, clarinete y chelo escritos como voces y no como adorno, y estructuras largas que pasan del riff pesado a pasajes casi en silencio. My Fruit Psychobells... (1999), Bath y Leaving Your Body Map (los dos de 2001, pensados como pareja) y Part the Second (2009), publicado gratis, sostienen el nivel. Entrada: Bath.", p: 1, origin: "rec", pick: true, y: 1996, via: "Dream Theater", c: 1 },
  { name: "Riverside", genre: "Prog Rock / Metal", desc: "Prog polaco donde el bajo de Mariusz Duda lleva la melodía tanto como la voz: líneas que conducen los temas sobre teclados densos y guitarras de sostenido largo, entre la melancolía atmosférica y el riff pesado. Ocho discos y ninguno flojo: la trilogía Reality Dream (Out of Myself, Second Life Syndrome y Rapid Eye Movement, 2003-2007), Anno Domini High Definition (2009), el más pesado y complejo, el giro setentero de Shrine of New Generation Slaves, Love, Fear and the Time Machine, Wasteland (2018), tras la muerte del guitarrista Piotr Grudziński, e ID.Entity (2023). Entrada: Second Life Syndrome, luego Anno Domini High Definition.", p: 1, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Obscura", genre: "Technical Death Metal", desc: "Death técnico donde el bajo fretless lleva contramelodía propia en vez de doblar la guitarra, con armonía neoclásica escrita y cambios de compás constantes. De Cosmogenesis (2009) a Omnivium, Akróasis, Diluvium y A Valediction (2021) es una racha sobresaliente; el debut, Retribution, es más verde y A Sonication (2025), con formación nueva casi entera, baja claramente. Entrada: Cosmogenesis, luego Omnivium.", origin: "rec", pick: true, p: 1, y: 2002, via: "Dream Theater" },
  { name: "Beyond Creation", genre: "Technical Death Metal", desc: "El bajo fretless, de Dominic Lapointe en los dos primeros discos, hace líneas melódicas propias que compiten con la guitarra en vez de acompañarla, sobre death técnico con cambios de compás continuos. The Aura (2011) y Earthborn Evolution (2014) son la cumbre y Algorythm (2018) queda algo por debajo. Entrada: Earthborn Evolution.", origin: "rec", pick: true, p: 1, y: 2005, via: "Dream Theater" },
  { name: "Pagan's Mind", genre: "Prog Power Metal", desc: "Prog power noruego de concepto de ciencia ficción, con teclados y voz limpia potente: técnico, pero de estructura power. Entrada: Celestial Entrance.", p: 3, origin: "rec", pick: true, y: 1996, via: "Dream Theater" },
  { name: "Communic", genre: "Prog Metal", desc: "Prog metal noruego oscuro y pesado, de riff y composiciones largas, en la órbita de Nevermore. Entrada: Conspiracy in Mind.", p: 3, origin: "rec", pick: true, y: 2003, via: "Dream Theater" },
  { name: "Voyager", genre: "Prog Metal", desc: "Prog metal australiano con sintetizadores ochenteros y estribillos grandes: accesible, con algo de djent debajo. Entrada: Ghost Mile.", p: 3, origin: "rec", pick: true, y: 1999, via: "Dream Theater" },
  { name: "Cynic", genre: "Prog Metal / Jazz Fusion", desc: "Death metal con acordes de novena y trece, bajo fretless llevando contramelodía, batería de fraseo jazzístico y voz con vocoder tratada como un instrumento más. Focus (1993) y Traced in Air (2008), separados por quince años, sostienen esa escritura al máximo; Kindly Bent to Free Us (2014), más cercano al rock atmosférico, y Ascension Codes (2021), el primero tras la muerte de Sean Reinert y Sean Malone en 2020, bajan claramente. Entrada: Focus.", origin: "rec", pick: true, p: 2, y: 1987, via: "Dream Theater", c: 3 },
  { name: "Thank You Scientist", genre: "Prog Rock / Fusion", desc: "No es prog con adornos, es un ensemble de verdad: violín eléctrico, trompeta y saxo como voces compositivas junto a la guitarra de Tom Monda, con escritura de fusión densa y cambios constantes. Terraformer es el disco más ambicioso. Cambio de formación: Salvatore Marrano se fue en 2023 y desde finales de 2024 canta Daimon Alexandrius, multiinstrumentista que además aporta flauta y sitar. Entra por Stranger Heads Prevail o Terraformer.", origin: "rec", p: 1, y: 2009, c: 2 },
  { name: "Allegaeon", genre: "Technical Melodic Death", desc: "Death técnico y melódico de Colorado con temática científica: solos neoclásicos vertiginosos, pasajes de guitarra clásica y estructuras que cambian mucho. Elements of the Infinite (2014), Proponent for Sentience (2016), Apoptosis (2019) y Damnum (2022) son lo mejor; The Ossuary Lens (2025) es el último. Entrada: Elements of the Infinite.", origin: "rec", pick: true, p: 2, y: 2008, via: "Trivium" },
  { name: "Vektor", genre: "Technical Thrash Metal", desc: "Thrash técnico con riffs encadenados en estructuras largas y una voz aguda y rasposa que divide a la gente. Los tres discos van a más: Black Future (2009) ya era denso, Outer Isles (2011) lo apretó, y Terminal Redux (2016) es un conceptual de más de setenta minutos con coros limpios y pasajes casi de rock progresivo sin soltar la velocidad. Preparan para 2027 una precuela de Terminal Redux, su primer disco en once años. Entrada: Terminal Redux.", origin: "rec", p: 1, y: 2003, c: 2 },
  { name: "Darkest Hour", genre: "Melodic Death / Metalcore", desc: "Metalcore y melodeath con devoción por At the Gates: guitarras gemelas melódicas sobre agresión. Entrada: The Mark of the Judas.", origin: "rec", pick: true, p: 3, y: 1995, via: "Trivium" },
  { name: "Unearth", genre: "Metalcore", desc: "Metalcore de Massachusetts de riff y pegada thrash, con solos melódicos: muy parejo y muy sólido, pero siempre dentro del molde. Entrada: III: In the Eyes of Fire.", p: 3, origin: "rec", pick: true, y: 1998, via: "Trivium" },
  { name: "Nervosa", genre: "Thrash / Death Metal", desc: "Thrash y death brasileño agresivo y veloz, fundado y liderado por mujeres, de estructura directa. Entrada: Downfall of Mankind.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "Trivium" },
  { name: "Lutharo", genre: "Melodic Death / Thrash", desc: "Death/thrash melodico canadiense con Krista Shipperbottom, limpio + gutural sobre instrumentales veloces.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Trivium" },
  { name: "Beck", genre: "Alt Rock / Eclectic", desc: "El camaleón del rock alternativo: cada disco es otro género, del collage de samples de Odelay (1996) y Midnite Vultures al folk triste de Sea Change (2002) y Morning Phase, con producciones muy trabajadas. Odelay, Mutations, Midnite Vultures, Sea Change y Guero son la cumbre; Colors y Hyperspace (2019) bajan. Entrada: Odelay, luego Sea Change.", p: 2, origin: "rec", pick: true, y: 1988, via: "Cage the Elephant", c: 1 },
  { name: "The Flaming Lips", genre: "Psych Rock", desc: "Psicodelia de Oklahoma que pasó del ruido de los ochenta al pop espacial orquestado de The Soft Bulletin (1999) y Yoshimi Battles the Pink Robots (2002), y de ahí a la oscuridad de Embryonic (2009), con Steven Drozd, que también toca teclados y compone, a la batería. Muy desigual: Zaireeka se reparte en cuatro discos para sonar a la vez, lo de 2013 a 2019 baja y American Head (2020) recupera el nivel. Entrada: The Soft Bulletin.", p: 2, origin: "rec", pick: true, y: 1983, via: "Cage the Elephant", c: 1 },
  { name: "Yeah Yeah Yeahs", genre: "Indie / Garage Rock", desc: "Garage punk neoyorquino con Karen O al frente y la guitarra de Nick Zinner haciendo de banda entera, que luego giró al dance rock y a lo atmosférico. Fever to Tell (2003) e It's Blitz! (2009). Entrada: Fever to Tell.", p: 3, origin: "rec", pick: true, female: true, y: 2000, via: "Cage the Elephant", c: 1 },
  { name: "Osees", genre: "Garage Psych Rock", desc: "La banda hiperprolífica de John Dwyer, con dos baterías en directo: garage psicodélico de riffs frenéticos, jams motorik y, en la etapa reciente, giros al prog y al krautrock pesado. Floating Coffin (2013), Mutilator Defeated at Last, Orc (2017) y A Foul Form (2022) son de lo mejor de una obra enorme. Entrada: Orc.", p: 2, origin: "rec", pick: true, y: 1997, via: "Cage the Elephant" },
  { name: "White Denim", genre: "Garage / Jam Rock", desc: "Garage rock de Austin con fusión jazz, prog y jams técnicas: cambios de compás y guitarras en contrapunto con alma de garaje. Fits (2009), D (2011) y Corsicana Lemonade (2013) son la cumbre; lo posterior es más irregular. Entrada: D.", p: 2, origin: "rec", pick: true, y: 2006, via: "Cage the Elephant" },
  { name: "Ty Segall", genre: "Garage Rock / Psych", desc: "Garage prolífico de California: fuzz, psicodelia y melodía, a veces glam y a veces casi prog. Melted (2010) y Manipulator (2014). Entrada: Manipulator.", origin: "rec", pick: true, p: 3, y: 2008, via: "Cage the Elephant" },
  { name: "The Kills", genre: "Garage Blues Rock", desc: "Dúo de garage blues crudo y minimalista con Alison Mosshart y la guitarra y caja de ritmos de Jamie Hince. Entrada: Midnight Boom.", origin: "rec", pick: true, female: true, p: 3, y: 2001, via: "Cage the Elephant" },
  { name: "Spoon", genre: "Indie Rock", desc: "Indie rock de Austin minimalista y de groove, con la batería de Jim Eno muy al frente y arreglos que quitan más de lo que ponen. Muy parejos: Girls Can Tell (2001), Kill the Moonlight, Gimme Fiction, Ga Ga Ga Ga Ga (2007) y They Want My Soul (2014). Entrada: Kill the Moonlight.", origin: "rec", pick: true, p: 3, y: 1993, via: "Cage the Elephant" },
  { name: "Alabama Shakes", genre: "Blues Rock / Soul", desc: "Brittany Howard canta con un rango y una aspereza enormes, y en Sound & Color la banda abandona el revival de blues rock por arreglos de vibráfono, cuerda y ritmos partidos. Entrada: Sound & Color.", origin: "rec", pick: true, female: true, p: 2, y: 2009, via: "Cage the Elephant" },
  { name: "Brittany Howard", genre: "Soul / Funk / Psych", desc: "La voz de Alabama Shakes en solitario: soul, funk, gospel y psicodelia con baterías desplazadas y arreglos que se deshacen y se rearman dentro de la canción. Jaime (2019) y What Now (2024). Entrada: Jaime.", p: 3, origin: "rec", pick: true, female: true, y: 2019, via: "Cage the Elephant" },
  { name: "Loathe", genre: "Metalcore / Shoegaze", desc: "Guitarras muy graves y capas de shoegaze sobre pasajes ambientales con sintetizador, alternando voz limpia y gritada, con un manejo del tono y de la textura que es de lo mejor del género. Eso es lo que dominan: el paisaje sonoro, más que la complejidad rítmica. The Cold Sun (2017), I Let It In and It Took Everything (2020), la cumbre, The Things They Believe (2021), ambiental e instrumental, y A Stranger to You (julio de 2026), su disco más variado, del industrial al R&B. Entrada: I Let It In and It Took Everything.", origin: "rec", p: 2, y: 2014, c: 1 },
  { name: "Veil of Maya", genre: "Djent / Prog Metalcore", desc: "De deathcore técnico a djent progresivo y luego a melodía limpia: riffs sincopados de ocho cuerdas y cambios de métrica con la batería de Sam Applebaum muy al frente. The Common Man's Collapse (2008), [id] y Matriarch (2015) son lo mejor; los discos con más voz limpia, de False Idol a [m]other (2021), quedan algo por debajo. Entrada: [id].", p: 2, origin: "rec", pick: true, y: 2004, via: "Metalcore", c: 1 },
  { name: "Misery Signals", genre: "Progressive Metalcore", desc: "Metalcore progresivo de melodías largas: guitarras que tejen arpegios sobre riffs pesados y cambios de compás, con estructuras que crecen en vez de repetirse. Of Malice and the Magnum Heart (2004), Mirrors y Controller (2008) son la cumbre; Absent Light (2013) y Ultraviolet (2020) bajan. Entrada: Of Malice and the Magnum Heart.", p: 2, origin: "rec", pick: true, y: 2002, via: "Metalcore" },
  { name: "Defeater", genre: "Melodic Hardcore", desc: "Hardcore melodico con un concepto narrativo que atraviesa toda su discografia, pero el concepto esta en las letras: musicalmente es hardcore melodico directo, sin complejidad instrumental. Travels.", origin: "rec", pick: true, p: 3, y: 2008, via: "Metalcore" },
  { name: "Counterparts", genre: "Melodic Hardcore / Metalcore", desc: "Metalcore y hardcore melódico canadiense de intensidad real: guitarras que tejen melodías sobre riffs rápidos, cambios de dinámica bruscos y la voz de Brendan Murphy siempre al límite. Siete discos muy parejos, de The Difference Between Hell and Home (2013) y Tragedy Will Find Us a You're Not You Anymore (2017), Nothing Left to Love (2019) y A Eulogy for Those Still Here (2022). Entrada: You're Not You Anymore.", p: 2, origin: "rec", pick: true, y: 2007, via: "Metalcore" },
  { name: "Employed to Serve", genre: "Metalcore", desc: "Metalcore británico pesado y con groove, con Justine Jones al frente: riffs de raíz metálica, cambios de tempo bruscos y breakdowns que no caen donde se espera. The Warmth of a Dying Sun (2017), Eternal Forward Motion (2019) y Conquering (2021). Entrada: Eternal Forward Motion.", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Metalcore" },
  { name: "Conquer Divide", genre: "Metalcore", desc: "Metalcore moderno con dos vocalistas femeninas, melódico y con pegada, pero instrumentalmente sigue la plantilla del género. Entrada: Slow Burn.", origin: "rec", pick: true, female: true, p: 3, y: 2013, via: "Metalcore" },
  { name: "Zao", genre: "Metallic Hardcore", desc: "Metalcore de raíz hardcore con disonancia y atmósfera: riffs que se deshacen en feedback, pasajes lentos casi de doom y la voz desgarrada de Daniel Weyandt. Muy parejo durante casi treinta años: Where Blood and Fire Bring Rest (1998), Liberate Te Ex Inferis, The Funeral of God (2004), The Fear Is What Keeps Us Here, grabado con Steve Albini, The Well-Intentioned Virus (2016) y The Crimson Corridor (2021). Entrada: The Funeral of God.", p: 2, origin: "rec", pick: true, y: 1993, via: "Metalcore" },
  { name: "In Mourning", genre: "Progressive Melodic Death", desc: "Melodeath progresivo sueco con temas de ocho y nueve minutos que se desarrollan en vez de repetir estribillo, y tres guitarras repartiéndose líneas distintas en vez de doblarse. Muy parejos: Shrouded Divine (2008), The Weight of Oceans (2012), Afterglow (2016), Garden of Storms (2019) y The Immortal (agosto de 2025). Entrada: The Weight of Oceans.", origin: "rec", pick: true, p: 1, y: 2000, via: "Be'lakor" },
  { name: "Ghost Brigade", genre: "Atmospheric Melodic Death", desc: "Melodeath atmosférico finlandés con peso de sludge y doom, muy emotivo, con guitarras limpias entrelazadas con lo pesado. Isolation Songs (2009) y Until Fear No Longer Defines Us (2011) son la cumbre. Entrada: Until Fear No Longer Defines Us.", origin: "rec", pick: true, p: 2, y: 2005, via: "Be'lakor" },
  { name: "Swallow the Sun", genre: "Death / Doom Metal", desc: "Death y doom atmosférico finlandés, melancólico y cinematográfico: guitarras lentas en capas, voz que alterna limpio y gutural y temas largos de crecimiento. Muy bien hecho, pero más de atmósfera que de complejidad. New Moon (2009) y el triple Songs from the North (2015). Entrada: New Moon.", p: 3, origin: "rec", pick: true, y: 2000, via: "Be'lakor" },
  { name: "Barren Earth", genre: "Progressive Death Metal", desc: "Death progresivo finlandés con prog setentero, órgano y pasajes acústicos, melódico y aventurero. Curse of the Red River (2010), The Devil's Resolve, On Lonely Towers (2015) y A Complex of Cages. Entrada: Curse of the Red River.", p: 2, origin: "rec", pick: true, y: 2007, via: "Be'lakor" },
  { name: "Amorphis", genre: "Melodic Death / Prog", desc: "Se movieron de death brutal a prog psicodélico con teclados setenteros y voz limpia, y de ahí a un melodeath melódico con modos folclóricos finlandeses metidos en la melodía, no como adorno: las líneas de guitarra siguen escalas del Kalevala y por eso suenan raras dentro del metal. Tomi Joutsen alterna gutural y limpio dentro del mismo tema como recurso estructural. Far from the Sun (2003) es el punto bajo; desde Eclipse (2006) están muy parejos hasta Halo (2022) y Borderland (2025). Entrada: Tales from the Thousand Lakes, luego Elegy.", origin: "rec", p: 1, y: 1990, c: 1 },
  { name: "Disillusion", genre: "Progressive Death Metal", desc: "Death progresivo alemán de temas largos y épicos con voz limpia y gutural. Back to Times of Splendor (2004) es la cumbre, Gloria (2006) gira a la electrónica y el rock alternativo, y la vuelta con The Liberation (2019) y Ayam (2022) recupera el nivel. Entrada: Back to Times of Splendor.", p: 2, origin: "rec", pick: true, y: 1994, via: "Be'lakor" },
  { name: "Wintersun", genre: "Symphonic Melodic Death", desc: "El proyecto de Jari Mäenpää: melodeath sinfónico con capas y capas de orquestación, técnica muy alta y temas larguísimos. Wintersun (2004), con la batería de Kai Hahto, es el más directo y técnico; Time I (2012) y Time II (2024) son grandilocuentes, y The Forest Seasons (2017) baja. Entrada: Wintersun.", origin: "rec", pick: true, p: 2, y: 2004, via: "Be'lakor" },
  { name: "Edge of Sanity", genre: "Progressive Death Metal", desc: "El grupo de Dan Swanö: death sueco que se fue abriendo a melodía, voz limpia y prog. The Spectral Sorrows (1993) y Purgatory Afterglow son sólidos, y Crimson (1996) es una sola pieza de cuarenta minutos de death progresivo, singular en su momento; Infernal y Cryptic bajan, y Crimson II (2003) recupera el nivel. Entrada: Crimson.", p: 2, origin: "rec", pick: true, y: 1989, via: "Be'lakor", c: 3 },
  { name: "Sojourner", genre: "Atmospheric Folk Metal", desc: "Metal atmosferico/folk con voces femenina y masculina, cinematografico y de viaje epico.", origin: "rec", pick: true, female: true, p: 3, y: 2015, via: "Be'lakor" },
  { name: "Of Montreal", genre: "Baroque Psych Pop", desc: "Pop psicodelico barroco extravagante y flamboyante; cada disco un experimento. Hissing Fauna.", origin: "rec", pick: true, p: 2, y: 1996, via: "Panic!", c: 1 },
  { name: "Janelle Monae", genre: "Art Pop / Funk", desc: "Discos conceptuales teatrales que saltan de género dentro del mismo disco: R&B, funk, pop, rock psicodélico y oberturas orquestales. The ArchAndroid (2010) es la cumbre y Dirty Computer (2018) está cerca; The Age of Pleasure (2023) es más sencillo. Entrada: The ArchAndroid.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Panic!", c: 1 },
  { name: "Rufus Wainwright", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco y orquestal, teatral y operistico, arreglos lujosos. Want One.", origin: "rec", pick: true, p: 2, y: 1998, via: "Panic!" },
  { name: "The Decemberists", genre: "Baroque Indie Folk", desc: "Indie folk barroco y literario, narrativo, con rock opera (The Hazards of Love). The Crane Wife.", origin: "rec", pick: true, p: 2, y: 2000, via: "Panic!" },
  { name: "The Divine Comedy", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco e ingenioso de Neil Hannon, orquestal con humor y clase. Casanova.", origin: "rec", pick: true, p: 3, y: 1989, via: "Panic!" },
  { name: "Mika", genre: "Baroque Pop", desc: "Pop teatral barroco influenciado por Queen: falsete y arreglos exuberantes. Life in Cartoon Motion.", origin: "rec", pick: true, p: 3, y: 2007, via: "Panic!" },
  { name: "Foxy Shazam", genre: "Glam Rock / Theatrical", desc: "Glam rock teatral desquiciado, frontman entre Freddie y Meat Loaf, con vientos y piano. The Church of Rock and Roll.", origin: "rec", pick: true, p: 3, y: 2004, via: "Panic!" },
  { name: "Marina", genre: "Art Pop", desc: "Art pop teatral con albumes conceptuales (Electra Heart). Dramatica y melodica.", origin: "rec", pick: true, female: true, p: 3, y: 2009, via: "Panic!" },
  { name: "Regina Spektor", genre: "Baroque / Anti-Folk", desc: "Anti-folk barroco de piano, excentrico y teatral, estructuras imprevisibles.", origin: "rec", pick: true, female: true, p: 3, y: 2001, via: "Panic!" },
  { name: "The Struts", genre: "Glam Rock", desc: "Revival de glam rock con devocion a Queen: himnos, falsetes, teatralidad anthemic.", origin: "rec", pick: true, p: 3, y: 2012, via: "Panic!" },
  { name: "The Darkness", genre: "Glam Rock", desc: "Glam rock revival Queen-worship con falsete, tongue-in-cheek.", origin: "rec", pick: true, p: 3, y: 2000, via: "Panic!" },
  { name: "Electric Light Orchestra", genre: "Baroque Orchestral Pop", desc: "Pop orquestal barroco beatlesco. Raiz de Pretty. Odd.", origin: "rec", pick: true, p: 2, y: 1970, via: "Panic!" },
  { name: "The Zombies", genre: "Baroque Psych Pop", desc: "Pop barroco psicodelico sesentero (Odessey and Oracle). Raiz de Pretty. Odd.", origin: "rec", pick: true, p: 2, y: 1961, via: "Panic!" },
  { name: "The Mars Volta", genre: "Prog / Psych Rock", desc: "Piezas de diez y quince minutos que cambian de sección sin transición, con Omar Rodríguez-López escribiendo la parte de todos y una sección rítmica tocando salsa y jazz por debajo del rock. De-Loused in the Comatorium (2003), Frances the Mute y Amputechture son lo mejor; The Bedlam in Goliath, Octahedron y Noctourniquet bajan un escalón, y desde el disco homónimo de 2022 y Lucro sucio; Los ojos del vacío (2025) giraron a algo más suave, latino y atmosférico. Entrada: De-Loused in the Comatorium.", origin: "rec", pick: true, p: 2, y: 2001, via: "Muse", c: 1 },
  { name: "Biffy Clyro", genre: "Alt Rock", desc: "Rock alternativo escocés que en sus primeros discos escribía en compases impares y con cambios bruscos: Blackened Sky (2002), The Vertigo of Bliss e Infinity Land (2004) son los más retorcidos, Puzzle (2007) y Only Revolutions lo llevan al estadio sin perder ingenio, y desde Ellipsis (2016) la escritura se simplifica y baja. Entrada: Infinity Land, luego Puzzle.", p: 2, origin: "rec", pick: true, y: 1995, via: "Muse", c: 1 },
  { name: "Karnivool", genre: "Prog Rock / Metal", desc: "Australianos. Grooves sostenidos en métricas desplazadas con capas de guitarra que entran y salen, y estructuras que no vuelven al estribillo. Sound Awake (2009) es la cumbre e In Verses (2026), su vuelta tras trece años, está cerca; Themata (2005) todavía arrastra el rock alternativo de su época y Asymmetry (2013), más fragmentado y experimental, queda por debajo. Entrada: Sound Awake.", origin: "rec", pick: true, p: 2, y: 1997, via: "Muse", c: 2 },
  { name: "dredg", genre: "Alt / Prog Rock", desc: "Alt/prog rock atmosferico y conceptual, arreglos cuidadisimos. El Cielo.", origin: "rec", pick: true, p: 3, y: 1993, via: "Muse" },
  { name: "Mew", genre: "Prog / Dream Pop", desc: "Daneses de falsete etéreo y producción lujosa, con compases poco habituales metidos dentro de canciones de dream pop. Entrada: And the Glass Handed Kites.", p: 3, origin: "rec", pick: true, y: 1995, via: "Muse" },
  { name: "Oceansize", genre: "Prog / Post-Rock", desc: "Prog británico de tres guitarras: capas que entran y salen sobre compases impares sostenidos durante minutos, crescendos largos y la batería de Mark Heron llevando métricas desplazadas. Effloresce (2003), Everyone Into Position (2005) y Frames (2007) están los tres al mismo nivel y cada uno cambia el enfoque: el primero es space rock expansivo, el segundo aprieta en canciones y Frames son piezas largas de construcción paciente. Self Preserved While the Bodies Float Up (2010), más directo y pesado, baja algo; se separaron en 2011. Entrada: Frames.", p: 1, origin: "rec", pick: true, y: 1998, via: "Muse" },
  { name: "Anathema", genre: "Atmospheric Prog Rock", desc: "De doom metal a prog atmosferico emotivo y sinfonico, crescendos enormes, voces masc/fem. Precioso, pero compositivamente simple en su etapa moderna: vive del clima emocional mas que del interes instrumental. Weather Systems.", origin: "rec", pick: true, female: true, p: 2, y: 1990, via: "Muse" },
  { name: "Pure Reason Revolution", genre: "Prog Rock / Electronic", desc: "Prog rock con electronica y armonias masc/fem. Cruza prog con electronica con gusto. The Dark Third.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Muse" },
  { name: "Evanescence", genre: "Symphonic / Gothic Rock", desc: "Rock sinfonico/gotico dramatico con piano y la voz de Amy Lee. Drama orquestal anthemic. Fallen.", origin: "rec", pick: true, female: true, p: 3, y: 1995, via: "Muse" },
  { name: "Creeper", genre: "Horror Punk / Theatrical", desc: "Horror-punk teatral con discos conceptuales narrados: personajes recurrentes, interludios hablados y saltos de estilo entre punk, glam y balada de piano dentro del mismo álbum. Sanguivore (2023) se fue directamente al rock de vampiros con estructuras largas. Entrada: Eternity in Your Arms.", origin: "rec", pick: true, p: 3, y: 2014, via: "Ice Nine Kills", c: 1 },
  { name: "Crown the Empire", genre: "Theatrical Metalcore", desc: "Metalcore teatral y cinematográfico con discos conceptuales, pero debajo del dramatismo orquestal la escritura es bastante estándar: la teatralidad es envoltorio, no sustancia instrumental. Entrada: The Resistance: Rise of the Runaways.", origin: "rec", pick: true, p: 3, y: 2010, via: "Ice Nine Kills" },
  { name: "New Years Day", genre: "Gothic Metalcore", desc: "Metalcore gótico y teatral con Ash Costello y estética de terror, de estructura muy directa. Entrada: Malevolence.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Ice Nine Kills" },
  { name: "Type O Negative", genre: "Gothic / Doom Metal", desc: "Gótico y doom neoyorquino con humor negro: riffs lentos y pesados, los teclados de Josh Silver haciendo de orquesta, armonías vocales a lo Beatles y la voz grave de Peter Steele, en temas largos y teatrales. Muy parejos: Bloody Kisses (1993), October Rust (1996), World Coming Down (1999) y Life Is Killing Me; Steele murió en 2010. Entrada: October Rust.", origin: "rec", pick: true, p: 2, y: 1989, via: "Ice Nine Kills" },
  { name: "In This Moment", genre: "Theatrical Groove Metal", desc: "Metal sinfónico y groove ultrateatral con Maria Brink al frente y directos de ritual de terror: el peso está en la puesta en escena más que en la escritura instrumental. Blood (2012) y Black Widow (2014).", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Ice Nine Kills" },
  { name: "Wednesday 13", genre: "Horror Punk / Metal", desc: "Horror punk/metal con tematica de cine B de terror, teatral y divertido (tambien Murderdolls).", origin: "rec", pick: true, p: 3, y: 2004, via: "Ice Nine Kills" },
  { name: "Mors Principium Est", genre: "Technical Melodic Death", desc: "Melodeath técnico finlandés con solos neoclásicos brillantes y riffs muy rápidos. Muy parejos: The Unborn (2005), ...and Death Said Live (2012), Embers of a Dying World (2017), con Andy Gillion a la guitarra, Seven (2020) y Darkness Invisible (2025). Entrada: Embers of a Dying World.", origin: "rec", pick: true, p: 2, y: 1999, via: "In Flames" },
  { name: "Disarmonia Mundi", genre: "Melodic Death / Electronic", desc: "Melodeath sueco-italiano (con Bjorn Strid en limpio) que integra electronica con gusto, sin EDM puro. Mind Tricks.", origin: "rec", pick: true, p: 3, y: 2000, via: "In Flames" },
  { name: "Cellar Darling", genre: "Folk Rock", desc: "Folk-prog melodico de Anna Murphy (ex-Eluveitie), aventurero instrumentalmente. This Is the Sound.", origin: "rec", pick: true, female: true, p: 2, y: 2016, via: "In Flames" }
];

// ===========================================================================
// === TANDA 2 (junio 2026) — más y mejores recos, calibradas a tu perfil ===
// Rellena huecos evidentes y extiende tus venas declaradas. Nada repetido.
// ===========================================================================
const TANDA_2 = [
  // ----- PROG FUNDACIONAL que te faltaba (la raíz de 'cada disco un mundo') -----
  { name: "King Crimson", genre: "Prog Rock", desc: "Lo concreto de cada etapa: en los setenta, mellotron y saxo sobre improvisación libre; en los ochenta, la formación con Adrian Belew monta dos guitarras tocando patrones entrelazados en métricas distintas a la vez, inspirados en el gamelán indonesio, con Bruford a la batería electrónica; en los noventa, doble trío, con dos guitarras, dos bajos y dos baterías simultáneas. Fripp toca con púa y digitación cruzada, casi sin vibrato. Entrada: Red o Discipline.", origin: "rec", pick: true, p: 1, y: 1968, via: "Prog raíces", c: 1 },
  { name: "Gentle Giant", genre: "Prog Rock", desc: "El contrapunto vocal está escrito como una fuga: cuatro o cinco voces entrando por turnos con líneas distintas, no armonizando en bloque. Y los músicos se intercambian instrumentos dentro del tema, con violín, chelo, vibráfono y flauta de pico apareciendo como voces reales. Octopus, The Power and the Glory y Free Hand sostienen ese nivel. Entrada: Octopus.", origin: "rec", pick: true, p: 1, y: 1970, via: "Prog raíces", c: 1 },
  { name: "Jethro Tull", genre: "Prog Rock", desc: "Ian Anderson usa la flauta como instrumento principal de una banda de rock, no como color, y escribe en compases impares heredados del folk británico. Thick as a Brick y A Passion Play son cada uno una sola pieza que ocupa el disco entero, y en Songs from the Wood giraron a un folk eléctrico con mandolina que era prácticamente otra banda. Entrada: Thick as a Brick.", origin: "rec", pick: true, p: 1, y: 1967, via: "Prog raíces" },
  { name: "Van der Graaf Generator", genre: "Prog Rock", desc: "Prog sin guitarra durante tramos largos, sostenido por órgano y saxo, muy disonante y con la voz de Peter Hammill llevando la tensión. Pawn Hearts tiene A Plague of Lighthouse Keepers ocupando una cara entera. Entra por Pawn Hearts o Godbluff.", origin: "rec", p: 1, y: 1967, c: 2 },
  { name: "Camel", genre: "Prog Rock", desc: "Prog melódico donde la guitarra de Andy Latimer canta la melodía en lugar de la voz: frases largas y sostenidas, muy vocales, sobre teclados cálidos. The Snow Goose es un disco entero instrumental que narra un cuento sin una sola letra, y ahí queda claro que la banda escribe temas que vuelven transformados en vez de canciones. Bello y narrativo, poco agresivo. Entrada: Moonmadness o The Snow Goose.", origin: "rec", pick: true, p: 2, y: 1971, via: "Prog raíces" },
  { name: "Magma", genre: "Zeuhl / Avant Prog", desc: "Piezas de veinte minutos construidas por acumulación: un coro repite células cortas sobre armonía de jazz mientras todo se va apretando hasta el clímax, con la batería de Christian Vander como motor compositivo y no como acompañamiento (su pulso viene de Coltrane) y el bajo sosteniendo ostinatos durante la pieza entera. Hipnótico y agobiante a propósito, y esa forma de construir no tiene par fuera de sus propios discípulos. Lo sostienen de Mekanïk Destruktïw Kommandöh y Köhntarkösz hasta Kartëhl (2022). Entrada: Mekanïk Destruktïw Kommandöh.", origin: "rec", p: 1, y: 1969, c: 3 },
  { name: "Cardiacs", genre: "Avant-garde / Experimental", desc: "[Comodín] Lo llaman pronk, punk cruzado con prog: cambian de compás cada pocos compases sin avisar y sin que suene a ejercicio, con armonía que salta a acordes inesperados y varias voces cantando líneas distintas a la vez, todo a velocidad de punk y con un tono luminoso que choca con lo retorcido que es por dentro. De The Seaside a A Little Man and a House and the Whole World Window (1988), On Land and in the Sea, Heaven Born and Ever Bright, Sing to God (1996) y Guns no hay disco flojo, y LSD (2025), terminado tras la muerte de Tim Smith, está a la altura. Entrada: A Little Man and a House and the Whole World Window.", origin: "rec", p: 1, y: 1977, c: 3 },

  // ----- PROG MODERNO (veta Tool / Leprous / Haken / Porcupine Tree) -----
  { name: "Soen", genre: "Prog Metal", desc: "Metal progresivo sueco de grooves hipnóticos en métrica desplazada, con la batería de Martin Lopez construyendo los temas desde el ritmo y la voz de Joel Ekelöf muy al frente. De Lotus (2019) a Reliance (enero de 2026). Entrada: Lotus.", p: 2, origin: "rec", pick: true, y: 2010, via: "Tool/Leprous" },
  { name: "Vola", genre: "Prog Metal / Synth", desc: "Daneses que cruzan riffs de djent con estribillos de synth-pop y producción muy pulida: la guitarra hace de base rítmica y la canción manda sobre la escritura instrumental. Pegadizo y bien hecho, pero de complejidad moderada. Entrada: Witness.", p: 3, origin: "rec", pick: true, y: 2006, via: "Tool/Leprous", c: 2 },
  { name: "Steven Wilson", genre: "Prog Rock / Art", desc: "El cerebro de Porcupine Tree en solitario: del prog al pop art al electrónico. Cada disco cambia de piel. Productor exquisito. Su banda solista trae a Marco Minnemann en bateria y Guthrie Govan en guitarra. Requiem for a Village sale el 6 de noviembre de 2026.", origin: "rec", pick: true, p: 1, y: 2008, via: "Tool/Leprous", c: 1 },
  { name: "Bent Knee", genre: "Avant Art Rock", desc: "Art rock de Boston que salta de lo íntimo a lo explosivo dentro del tema, con la voz enorme de Courtney Swain, violín, bajo y batería escritos en capas y armonías que no resuelven donde se espera. Shiny Eyed Babies (2014), Say So, Land Animal (2017) y You Know What They Mean son la etapa fuerte. Entrada: Land Animal.", p: 2, origin: "rec", pick: true, female: true, y: 2009, via: "Tool/Leprous", c: 1 },
  { name: "Frost*", genre: "Prog Metal", desc: "Prog británico moderno liderado desde el teclado por Jem Godfrey: temas largos con ganchos pop, humor y producción de lujo, pero con secciones instrumentales densas de teclado y guitarra que cambian de métrica. Milliontown (2006), con su pieza titular de veintiséis minutos, Falling Satellites (2016), Day and Age (2021) y Life in the Wires (2024), un disco conceptual, sostienen el nivel; Experiments in Mass Appeal (2008) es el más flojo. Entrada: Milliontown.", p: 2, origin: "rec", pick: true, y: 2004, via: "Tool/Leprous" },

  // ----- PROG / SLUDGE / POST-METAL ATMOSFÉRICO (pilares que te faltan) -----
  { name: "Baroness", genre: "Sludge / Prog Metal", desc: "Sludge que se abrió al prog y al rock: guitarras armonizadas a dos voces, cambios de sección largos y una batería que empuja más que marca. Cada disco lleva un color, de Red y Blue a Purple, Gold & Grey y Stone (2023), y el nivel se mantiene de uno a otro. Entrada: Blue Record.", p: 2, origin: "rec", pick: true, y: 2003, via: "Post-metal", c: 1 },
  { name: "Elder", genre: "Stoner / Prog Rock", desc: "Pasaron de stoner doom a prog psicodélico instrumental y luminoso, y cada disco se aleja más del anterior: los temas duran diez o doce minutos y se desarrollan sin volver al riff inicial. Entrada: Reflections of a Floating World.", origin: "rec", pick: true, p: 2, y: 2006, via: "Post-metal", c: 1 },
  { name: "Boris", genre: "Experimental / Drone", desc: "Trío japonés que cambia de género disco a disco: drone de amplificador en Amplifier Worship y Flood (2000), rock pesado en Akuma no Uta y Pink (2005), colaboraciones con Sunn O))), shoegaze y pop, y la vuelta al peso en NO (2020). La batería de Atsuo y los volúmenes extremos son la constante. Entrada: Pink, luego Flood.", p: 2, origin: "rec", pick: true, y: 1992, via: "Post-metal", c: 1 },
  { name: "Neurosis", genre: "Post-Metal / Sludge", desc: "Temas de diez minutos construidos por acumulación: una figura de guitarra se repite creciendo en capas y volumen hasta reventar, con percusión tribal, teclados y samples de fondo y varias voces gritando a la vez. De Souls at Zero (1992) y Enemy of the Sun a Through Silver in Blood (1996), Times of Grace, A Sun That Never Sets, The Eye of Every Storm y Given to the Rising (2007) es una racha enorme; Honor Found in Decay y Fires Within Fires bajan, y An Undying Love for a Burning World (marzo de 2026), con Aaron Turner en lugar de Scott Kelly, recupera el nivel. Entrada: Through Silver in Blood o Times of Grace.", origin: "rec", p: 1, y: 1985, c: 2 },
  { name: "Isis", genre: "Post-Metal", desc: "Post-metal donde el riff se repite sin variar mientras todo lo demás cambia alrededor, así que el movimiento viene de las capas y no de la progresión. Oceanic y Panopticon son discos conceptuales con arco, no colecciones de temas. Entrada: Oceanic.", origin: "rec", pick: true, p: 2, y: 1997, via: "Post-metal" },
  { name: "Russian Circles", genre: "Post-Metal / Instrumental", desc: "Post-metal instrumental de tres personas, sin voz: Mike Sullivan construye con loops de guitarra en capas mientras Dave Turncrantz toca una batería muy protagonista, y Brian Cook al bajo con distorsión hace de segunda guitarra. Del susurro al muro. Entrada: Memorial.", origin: "rec", pick: true, p: 2, y: 2004, via: "Post-metal" },
  { name: "Godspeed You! Black Emperor", genre: "Post-Rock", desc: "Piezas de veinte minutos divididas en movimientos con nombre, construidas por acumulación lentísima: entra un motivo, se van sumando capas de guitarra, violín y contrabajo con arco durante minutos, y el clímax llega tras una espera deliberadamente larga. Usan grabaciones de campo (voces de la calle, predicadores, ruido) como material temático y no como adorno, y el conjunto se acerca más a la música de cámara que al rock. Colectivo de Montreal, sin cantante y sin solista. Entra por Lift Your Skinny Fists Like Antennas to Heaven.", origin: "rec", p: 1, y: 1994, c: 2 },
  { name: "Pallbearer", genre: "Doom Metal", desc: "Doom de Arkansas melódico y emotivo, con dos guitarras armonizadas en temas largos y la voz limpia de Brett Campbell. Sorrow and Extinction (2012), Foundations of Burden (2014), la cumbre, Heartless, Forgotten Days y Mind Burns Alive (2024). Entrada: Foundations of Burden.", origin: "rec", pick: true, p: 2, y: 2008, via: "Post-metal" },
  { name: "YOB", genre: "Doom / Psych Metal", desc: "Doom psicodélico de Oregón de Mike Scheidt: riffs colosales y lentos que se estiran en temas de veinte minutos, con la voz pasando del grito al canto agudo casi meditativo. Muy parejos de The Illusion of Motion (2004) a The Great Cessation, Atma, Clearing the Path to Ascend (2014) y Our Raw Heart (2018), tras una enfermedad grave de Scheidt. Entrada: Clearing the Path to Ascend.", origin: "rec", pick: true, p: 2, y: 1996, via: "Post-metal" },

  // ----- AVANT / DISONANTE / JAZZ-METAL (tu veta Mr. Bungle / Dog Fashion al extremo) -----
  { name: "Igorrr", genre: "Avant-garde / Breakcore", desc: "[Comodín] Gautier Serre mezcla breakcore, ópera barroca, death metal y música balcánica en una misma canción, con voz lírica femenina contra guturales y baterías a velocidades imposibles junto a acordeón y clave. Hallelujah (2012), Savage Sinusoid (2017), Spirituality and Distortion (2020) y Amen (2025). Entrada: Savage Sinusoid.", p: 2, origin: "rec", pick: true, y: 2005, via: "Mr. Bungle", c: 3 },
  { name: "Secret Chiefs 3", genre: "Avant-garde / Experimental", desc: "El proyecto de Trey Spruance, de Mr. Bungle: surf, música persa e india, metal, bandas sonoras y electrónica, con cada disco montado sobre otra instrumentación y escalas de Oriente Medio escritas con la precisión de un arreglo de cámara. Nueve discos sin uno flojo, de First Grand Constitution and Bylaws (1996) y Book M a Book of Horizons, Book of Souls: Folio A (2013) y los de sus subgrupos, como Traditionalists o Ishraqiyun. Entrada: Book of Horizons.", p: 1, origin: "rec", pick: true, y: 1995, via: "Mr. Bungle", c: 1 },
  { name: "Sleepytime Gorilla Museum", genre: "Avant-garde Metal", desc: "[Comodín] Avant-metal que salta de casi silencio a violencia total dentro de un mismo compás, con compases impares constantes, contrapunto de verdad entre guitarra, violín, bajo y percusión, y voces habladas, cantadas y gritadas repartidas entre varios miembros; sus instrumentos construidos están dentro del arreglo, dando percusiones y drones que un kit normal no da. Grand Opening and Closing (2001), Of Natural History (2004), In Glorious Times (2007) y, diecisiete años después, Of the Last Human Being (2024), a la altura de los mejores. Entrada: Of Natural History.", origin: "rec", p: 1, y: 1999, c: 3 },
  { name: "Estradasphere", genre: "Avant-garde / Eclectic", desc: "Eclecticismo de la escuela de Mr. Bungle: surf, metal, klezmer, bluegrass, jazz y música de videojuego dentro del mismo tema, con violín, saxo y trompeta tocando unísonos rapidísimos. It's Understood (2000), Buck Fever, Quadrophonic y Palace of Mirrors (2006), el más compuesto. Entrada: Palace of Mirrors.", p: 2, origin: "rec", pick: true, y: 1998, via: "Mr. Bungle", c: 1 },
  { name: "Naked City", genre: "Avant-garde Jazz", desc: "Composición por fichas: cada corte dura entre uno y quince segundos y el conjunto salta de lounge a grindcore sin transición, pero todo está escrito y ensayado hasta poder tocarse igual dos veces, con Joey Baron sosteniendo cambios de tempo cada pocos segundos. Naked City y Torture Garden (1990), Grand Guignol, Heretic y Radio (1993) sostienen esa exigencia; Leng Tch'e, una sola pieza lenta de grind, y Absinthe, ambiental, son experimentos más áridos. Entrada: Naked City, luego Grand Guignol.", origin: "rec", pick: true, p: 1, y: 1988, via: "Mr. Bungle", c: 1 },
  { name: "Imperial Triumphant", genre: "Avant-garde Metal / Jazz", desc: "Neoyorquinos. Acordes de jazz disonante dentro del black y el death, con la batería de Kenny Grohowski a contratiempo del riff, el bajo de Steve Blanco con líneas propias y arreglos de metales y coro escritos. De Abyssal Gods (2015) y Vile Luxury a Alphaville (2020), Spirit of Ecstasy y Goldstar (2025) sostienen la misma escritura; solo el debut, Abominamentvm, queda por debajo. Entrada: Alphaville.", p: 1, origin: "rec", pick: true, y: 2005, via: "Mr. Bungle", c: 2 },
  { name: "White Ward", genre: "Avant-garde Metal / Jazz", desc: "Black metal atmosférico de Odesa con saxofón de jazz noir como segunda voz, pasajes de piano y bajo en clave de jazz y post-rock, en temas largos que alternan blast beat y club de madrugada. Futility Report (2017), Love Exchange Failure (2019) y False Light (2022), los tres muy bien recibidos. Entrada: Love Exchange Failure.", p: 2, origin: "rec", pick: true, y: 2012, via: "Mr. Bungle" },
  { name: "Shining (NOR)", genre: "Avant-garde Jazz Metal", desc: "De Oslo: empezaron como cuarteto de jazz acústico y Jørgen Munkeby los llevó al blackjazz, metal industrial con saxo desbocado, compases cambiantes y batería de jazz tocando a velocidad de black. In the Kingdom of Kitsch You Will Be a Monster (2005), Grindstone y Blackjazz (2010) son la cumbre y One One One (2013) la versión más compacta; Animal (2018) giró al rock de estribillo y es lo más flojo. Entrada: Blackjazz.", p: 2, origin: "rec", pick: true, y: 1999, via: "Mr. Bungle", c: 3 },
  { name: "Gorguts", genre: "Dissonant Death Metal", desc: "Riffs disonantes construidos sobre intervalos que no resuelven, con Luc Lemay escribiendo por bloques que no vuelven en vez de por estrofas. De Considered Dead (1991) y The Erosion of Sanity al extremo del ruido controlado de Obscura (1998), From Wisdom to Hate y Colored Sands (2013), reconstruido con un cuarteto de cuerda escrito, más el EP de una sola pieza Pleiades' Dust (2016): veinticinco años moviendo el terreno. Entrada: Colored Sands, luego Obscura.", origin: "rec", pick: true, p: 1, y: 1989, via: "Mr. Bungle", c: 3 },
  { name: "Ulcerate", genre: "Dissonant Death Metal", desc: "Neozelandeses. Los riffs no tienen centro tonal y la batería de Jamie Saint Merat toca contra ellos en vez de marcarlos, así que la tensión no resuelve nunca. Lo afinan disco a disco sin repetirse: Everything Is Fire (2009), The Destroyers of All, Vermis, Shrines of Paralysis (2016), Stare Into Death and Be Still (2020) y Cutting the Throat of God (2024). Entrada: Stare Into Death and Be Still.", origin: "rec", pick: true, p: 1, y: 2000, via: "Mr. Bungle" },
  { name: "Oranssi Pazuzu", genre: "Psychedelic Black Metal", desc: "No es black metal con efectos encima: el motor rítmico es krautrock, con bajo y batería repitiendo un patrón hipnótico durante minutos mientras las capas de sintetizador y guitarra se van deformando por encima, y de ahí meten prog, acid house, jazz y ruido de vanguardia sin que ninguna sección vuelva igual. Muy parejos de Kosmonument (2011) a Valonielu, Värähtelijä (2016), Mestarin kynsi (2020), donde menos black metal hay y más raro suena, y Muuntautuja (2024). Finlandeses. Entrada: Mestarin kynsi o Värähtelijä.", origin: "rec", p: 1, y: 2007, c: 1 },
  { name: "Deathspell Omega", genre: "Avant-garde Black Metal", desc: "[Comodín] Riffs construidos sobre tritonos e intervalos que no resuelven, con el compás cambiando dentro de la misma frase y varias guitarras tocando figuras distintas que se cruzan sin encajar del todo, sobre una batería que marca subdivisiones contra el riff en vez de con él. El resultado es que no puedes anticipar dónde cae el golpe siguiente, y eso es intencional. Franceses y anónimos. Los dos primeros discos, Infernal Battles (2000) e Inquisitors of Satan (2002), son black ortodoxo y crudo; el cambio empieza en Si monumentum requires, circumspice (2004), y Fas (2007) y Paracletus (2010) son la cumbre. The Synarchy of Molten Bones (2016), The Furnaces of Palingenesia (2019) y The Long Defeat (2022), más lento y melódico, siguen a gran nivel. Entrada: Paracletus o Fas.", origin: "rec", p: 1, y: 1998, c: 3 },

  // ----- TECH / PROG DEATH que te faltaba -----
  { name: "Children of Bodom", genre: "Melodic Death / Power", desc: "Alexi Laiho y el teclista Janne Wirman se pasaban la voz principal el uno al otro, tocando pasajes neoclásicos al unísono y luego turnándose solos como si fuera un duelo, con líneas tomadas de la armonía barroca y de la menor armónica sobre base de melodeath rápido. Tratar el teclado como segunda guitarra solista casi nadie lo hacía. Laiho murió el 29 de diciembre de 2020, a los 41. Entra por Hatebreeder o Follow the Reaper.", origin: "heard", p: 1, y: 1993, c: 2 },
  { name: "Archspire", genre: "Technical Death Metal", desc: "Death técnico canadiense a velocidad imposible y preciso como un reloj, con la voz de Oliver Rae Aleron escupiendo sílabas como una ametralladora. Relentless Mutation (2017), Bleed the Future (2021) y Too Fast to Die (abril de 2026), con Spencer Moore a la batería, son la cumbre; los primeros quedan por debajo. Entrada: Bleed the Future.", p: 2, origin: "rec", pick: true, y: 2009, via: "Tech death" },
  { name: "First Fragment", genre: "Technical Death / Neoclassical", desc: "Death técnico neoclásico de Quebec con guitarra de flamenco y bajo fretless muy presente: shred melódico, armonía barroca y compases cambiantes. Dasein (2016) y Gloire éternelle (2021), la cumbre. Entrada: Gloire éternelle.", p: 2, origin: "rec", pick: true, y: 2007, via: "Tech death" },
  { name: "Alkaloid", genre: "Progressive Death Metal", desc: "Supergrupo alemán de death progresivo y técnico con Hannes Grossmann a la batería y Christian Münzner a la guitarra, ex de Obscura y Necrophagist: temática cósmica, compases cambiantes y ambición compositiva. The Malkuth Grimoire (2015), Liquid Anatomy (2018) y Numen (2023). Entrada: Liquid Anatomy.", p: 2, origin: "rec", pick: true, y: 2014, via: "Tech death" },
  { name: "Black Crown Initiate", genre: "Progressive Death Metal", desc: "Death progresivo de Pensilvania con alternancia de voz limpia y gutural, riffs técnicos y pasajes atmosféricos en la estela de Opeth. The Wreckage of Stars (2014), Selves We Cannot Forgive y Violent Portraits of Doomed Escape (2020). Entrada: Selves We Cannot Forgive.", p: 2, origin: "rec", pick: true, y: 2012, via: "Tech death" },
  { name: "The Faceless", genre: "Progressive Death / Tech", desc: "Death progresivo y técnico californiano: riffs de mucha técnica, voz vocoder y limpia entre guturales y estructuras largas. Akeldama (2006) y Planetary Duality (2008) son la cumbre; Autotheism (2012) y In Becoming a Ghost (2017) bajan algo. Entrada: Planetary Duality.", p: 2, origin: "rec", pick: true, y: 2004, via: "Tech death" },
  { name: "Gorod", genre: "Technical Death Metal", desc: "Death técnico de Burdeos con groove jazzístico y melodía: riffs de Mathieu Pascal que cambian de compás con un aire casi bailable y armonía luminosa dentro de lo extremo. Muy parejos de Leading Vision (2006) y Process of a New Decline a A Maze of Recycled Creeds, Æthra, The Orb (2023) y The Ember Gone (agosto de 2026). Entrada: A Maze of Recycled Creeds.", p: 2, origin: "rec", pick: true, y: 1997, via: "Tech death" },

  // ----- FOLK / MELODEATH ÉPICO -----
  { name: "Ensiferum", genre: "Folk / Power Metal", desc: "Folk/melodeath finlandés épico: melodías de guitarra a dos voces sobre acordeón y coros heroicos, con estructuras largas de aire narrativo. Entrada: Iron o Victory Songs.", origin: "rec", pick: true, p: 3, y: 1995, via: "Melodeath" },

  // ----- METALCORE / POST-HARDCORE MODERNO (huecos clave) -----
  { name: "Northlane", genre: "Metalcore / Electronic", desc: "Metalcore progresivo australiano que viró a electrónica atmosférica: Singularity (2013) y Node son djent de riff sincopado, y Alien (2019), el mejor, y Obsidian lo cruzan con sintetizadores industriales; Anemoia salió en 2026. Cada disco se reinventa, pero la escritura instrumental es más de textura que de complejidad. Entrada: Alien.", p: 3, origin: "rec", pick: true, y: 2009, via: "Metalcore", c: 1 },
  { name: "Polaris", genre: "Metalcore", desc: "Metalcore melódico australiano, emotivo y muy pulido, pero justo ese pulido es el problema: ejecuta la plantilla impecablemente sin salirse de ella. The Mortal Coil (2017), The Death of Me (2020) y Fatalism (2023), tras la muerte de su guitarrista Ryan Siew. Entrada: The Death of Me.", origin: "rec", pick: true, p: 3, y: 2012, via: "Metalcore" },
  { name: "Thornhill", genre: "Metalcore / Atmospheric", desc: "Metalcore atmosférico australiano en la estela de Deftones: guitarras graves con capas de reverb, groove sensual y voz limpia muy al frente. The Dark Pool (2019), Heroine (2022) y BODIES (2025), muy parejos. Entrada: The Dark Pool.", p: 2, origin: "rec", pick: true, y: 2016, via: "Metalcore" },
  { name: "Silent Planet", genre: "Metalcore / Atmospheric", desc: "Metalcore atmosférico y literario: riffs disonantes y rítmicos, pasajes de ambiente con capas de guitarra y letras densísimas, con dinámica de cine. Everything Was Sound (2016), When the End Began (2018), Iridescent (2021) y Superbloom (2023), cada uno más ambicioso. Entrada: Iridescent.", p: 2, origin: "rec", pick: true, y: 2009, via: "Metalcore" },
  { name: "Invent Animate", genre: "Metalcore / Prog", desc: "Metalcore progresivo y etéreo de Texas: riffs de djent pesados bajo capas de guitarra ambiental y melodías soñadoras, con alternancia de voces. Greyview (2020) y Heavener (2023), los dos a gran nivel. Entrada: Heavener.", p: 2, origin: "rec", pick: true, y: 2011, via: "Metalcore" },
  { name: "Currents", genre: "Metalcore / Djent", desc: "Metalcore y djent moderno de Connecticut, emotivo y pesado, con groove y gancho: riffs sincopados bien escritos dentro del molde. The Place I Feel Safest (2017), The Way It Ends (2020) y The Death We Seek (2023). Entrada: The Way It Ends.", p: 3, origin: "rec", pick: true, y: 2011, via: "Metalcore" },
  { name: "Circa Survive", genre: "Prog Post-Hardcore", desc: "Post-hardcore progresivo: las guitarras de Colin Frangicetto y Brendan Ekstrom tejen arpegios y delays en capas sobre compases cambiantes, con la batería de Stephen Clifford muy activa y la voz etérea de Anthony Green flotando encima. Juturna (2005), On Letting Go y Blue Sky Noise (2010) son la cumbre, y Descensus y The Amulet (2017) están cerca. Se separaron en 2022 y anunciaron un concierto de reunión para septiembre de 2026. Entrada: Juturna.", p: 2, origin: "rec", pick: true, y: 2004, via: "Metalcore" },
  { name: "Thrice", genre: "Post-Hardcore / Alt Rock", desc: "Del post-hardcore técnico al rock experimental y atmosférico, con cambios reales de disco a disco. The Artist in the Ambulance (2003) y Vheissu (2005) son la cumbre, The Alchemy Index (cuatro volúmenes, uno por elemento) su proyecto más ambicioso, y de Beggars a Horizons/East y Horizons/West (2025) mantienen un nivel alto y estable. Entrada: Vheissu.", p: 2, origin: "rec", pick: true, y: 1998, via: "Metalcore" },

  // ----- INSTRUMENTAL PROG / FUSIÓN (tu lado 'instrumental interesante') -----
  { name: "Scale the Summit", genre: "Prog / Instrumental", desc: "Prog metal instrumental sin voz: dos guitarras tocando líneas melódicas independientes que se cruzan, con Mark Michell al bajo haciendo contrapunto en vez de doblar. Todo melódico y paisajístico, sin agresividad. Entrada: The Migration.", p: 3, origin: "rec", pick: true, y: 2004, via: "Instrumental" },
  { name: "The Aristocrats", genre: "Jazz Fusion / Instrumental", desc: "Trío de fusión instrumental con Guthrie Govan a la guitarra, Bryan Beller al bajo y Marco Minnemann a la batería: los tres componen, y los temas saltan de estilo y de compás con mucho humor. Muy parejos: The Aristocrats (2011), Culture Clash (2013), Tres Caballeros (2015), You Know What...? (2019) y Duck (2024). Entrada: Culture Clash.", origin: "rec", pick: true, p: 2, y: 2011, via: "Instrumental" },

  // ----- HIP-HOP ECLÉCTICO (extiende tu RM / Agust D / Hamilton) -----
  { name: "Kendrick Lamar", genre: "Hip-Hop / Jazz Rap", desc: "To Pimp a Butterfly usa más músicos en vivo que samples: Terrace Martin dirigiendo, con Robert Glasper al piano, Ambrose Akinmusire a la trompeta, Kamasi Washington al saxo (y arreglando y dirigiendo las cuerdas) y Thundercat al bajo, los tres últimos ya en el catálogo. Solos de jazz que aparecen sin avisar, cambios de compás dentro del tema y grooves que respiran como banda tocando en directo en vez de repetir un loop. Entra por To Pimp a Butterfly.", origin: "rec", p: 1, y: 2011, c: 1 },
  { name: "Tyler, the Creator", genre: "Hip-Hop / Neo-Soul", desc: "Arregla y produce él, y cada disco monta una paleta distinta: IGOR va de sintetizador saturado y coros, Flower Boy usa armonía de jazz con acordes extendidos, y CHROMAKOPIA vuelve a lo percusivo. Entrada: IGOR.", origin: "rec", pick: true, p: 2, y: 2009, via: "RM/BTS", c: 1 },
  { name: "Death Grips", genre: "Experimental Hip-Hop", desc: "[Comodín] Quien está a la batería es Zach Hill, el mismo de Hella, y no programa, toca en vivo a una densidad brutal por debajo de bases distorsionadas hasta el recorte digital, con la voz de MC Ride gritada y saturada al mismo nivel que los instrumentos en vez de por encima. La mezcla está deliberadamente en rojo. Abrasivo y agotador a propósito. Entra por The Money Store.", origin: "rec", p: 2, y: 2010, c: 3 },
  { name: "clipping.", genre: "Experimental Hip-Hop", desc: "Rap sobre bases hechas con ruido y grabaciones de campo en vez de samples musicales: hay temas construidos solo con estática, silbidos o el sonido de un incendio, y Daveed Diggs rapea encima a velocidad muy alta. Conceptual y de ciencia ficción. Entrada: Splendor & Misery.", origin: "rec", pick: true, p: 2, y: 2010, via: "RM/BTS" },
  { name: "JPEGMAFIA", genre: "Experimental Hip-Hop", desc: "Se produce él todo, y las bases cambian de estructura a mitad de tema: cortes secos, samples que entran desafinados y silencios colocados donde debería seguir el ritmo. Entrada: All My Heroes Are Cornballs.", origin: "rec", pick: true, p: 2, y: 2015, via: "RM/BTS", c: 1 },

  // ----- K-ROCK / K-ECLÉCTICO (extiende tu BTS / RM) -----
  { name: "Xdinary Heroes", genre: "K-Rock / Pop", desc: "Banda de K-rock de verdad, con instrumentos tocados y no idol-pop: dos guitarras, teclado, bajo y batería, saltando entre pop punk, prog, electrónica y balada teatral, a veces dentro del mismo tema. Comparten cantante entre varios miembros. Es de lo poco del ecosistema coreano montado como banda tocando. Entrada: Livelock.", origin: "rec", pick: true, p: 2, y: 2021, via: "BTS", c: 1 },
  { name: "Day6", genre: "K-Rock / Power Pop", desc: "Banda surcoreana de rock/power-pop con composición sólida y emotiva. Melódica y honesta.", origin: "rec", pick: true, p: 3, y: 2015, via: "BTS" },
  { name: "Epik High", genre: "Hip-Hop (Korea)", desc: "Hip-hop coreano cinematográfico, con Tablo escribiendo textos largos sobre producción de piano y cuerda. Melódico y emotivo más que complejo. Entrada: Shoebox.", origin: "rec", pick: true, p: 3, y: 2001, via: "BTS" },

  // ----- SYMPHONIC / GOTHIC CON VOZ FEMENINA (extiende tu filtro ♀) -----
  { name: "Within Temptation", genre: "Symphonic / Gothic Metal", desc: "Symphonic/gothic con la voz de Sharon den Adel, épico y cinematográfico. Mother Earth, The Heart of Everything.", origin: "rec", pick: true, female: true, p: 3, y: 1996, via: "Symphonic fem" },
  { name: "The Gathering", genre: "Atmospheric / Symphonic Rock", desc: "De death/doom a rock atmosférico onírico con Anneke van Giersbergen. Mandylion. Cada disco evoluciona.", origin: "rec", pick: true, female: true, p: 2, y: 1989, via: "Symphonic fem" },
  { name: "Lacuna Coil", genre: "Gothic / Symphonic Metal", desc: "Gótico melódico italiano con voces dual (Cristina Scabbia). Atmosférico y pegadizo.", origin: "rec", female: true, p: 3, y: 1994, via: "Symphonic fem" },
  { name: "Tarja", genre: "Symphonic Metal", desc: "La ex-voz operística de Nightwish en solitario: soprano de formación clásica sobre metal sinfónico con orquesta, más dramático y menos pop que su etapa en la banda. Entrada: My Winter Storm. (voz femenina)", origin: "rec", female: true, p: 3, y: 2005, via: "Symphonic fem" },

  // ----- EXPERIMENTAL / MATH / ART ROCK (extiende alt-J / Radiohead / King Gizzard) -----
  { name: "black midi", genre: "Experimental Rock", desc: "Rock experimental londinense de math rock, jazz y prog en caída libre, con Morgan Simpson a la batería llevando la banda: cambia de subdivisión y de dinámica cada pocos compases y hace de motor compositivo, no de base. Tres discos, Schlagenheim (2019), Cavalcade (2021) y Hellfire (2022), cada uno más escrito y más teatral que el anterior, sin bajar. En agosto de 2024 anunciaron un parón indefinido y Geordie Greep siguió en solitario con The New Sound. Entrada: Cavalcade, luego Hellfire.", p: 1, origin: "rec", pick: true, y: 2017, via: "Radiohead/alt-J", c: 1 },
  { name: "Black Country, New Road", genre: "Experimental / Chamber Rock", desc: "Rock de cámara londinense: violín, saxo, piano y dos guitarras en crescendos largos que cruzan post-rock, klezmer y folk. For the First Time y Ants from Up There (los dos de 2022) son con Isaac Wood a la voz; tras su marcha, Forever Howlong (2025) reparte la voz entre tres miembros y gira hacia algo más barroco y luminoso. Entrada: Ants from Up There.", p: 2, origin: "rec", pick: true, y: 2018, via: "Radiohead/alt-J" },
  { name: "Battles", genre: "Math Rock / Experimental", desc: "Math rock instrumental hipnótico: bucles de guitarra y teclado construidos en directo y superpuestos hasta que el patrón se desfasa, con John Stanier (el de Helmet) tocando en vivo contra esos loops y con su famoso plato colocado absurdamente alto. Entrada: Mirrored.", origin: "rec", pick: true, p: 2, y: 2002, via: "Radiohead/alt-J" },

  // ----- DARKSYNTH (extiende tu Dance with the Dead) -----
  { name: "Perturbator", genre: "Darksynth / Synthwave", desc: "Arpegios de sintetizador sobre bombo a negras, capas de pads oscuros y estructura de estrofa y estribillo sin voz. Está muy bien producido y la atmósfera cyberpunk funciona, pero el género es pastiche ochentero por diseño: el atractivo es la estética y la nostalgia, no la escritura. Entra por The Uncanny Valley.", origin: "rec", p: 3, y: 2012, c: 2 },
  { name: "Carpenter Brut", genre: "Darksynth / Synthwave", desc: "Bajado con el resto del synthwave. Es el más agresivo de los tres: mete guitarras distorsionadas y batería real encima del sintetizador, y algunos temas tiran casi a heavy. Pero la base sigue siendo la misma fórmula de arpegio y bombo a negras, con la película ochentera como referente principal. Entretenidísimo, poco exigente. Entra por Leather Teeth.", origin: "rec", p: 3, y: 2012, c: 2 },

  // ----- TEATRAL / ECLÉCTICO EXTRA -----
  { name: "Babymetal", genre: "J-Pop Metal / Avant", desc: "J-pop de ídolos con metal técnico detrás: la banda de apoyo toca power, djent y metalcore con mucha precisión mientras las voces llevan melodías de pop japonés. La fusión es el recurso y las canciones tienen estructura de pop. Babymetal (2014), Metal Resistance y Metal Galaxy (2019). Entrada: Babymetal.", p: 3, origin: "rec", pick: true, female: true, y: 2010, via: "Teatral", c: 2 },
  { name: "Puscifer", genre: "Alt / Electronic Rock", desc: "Electrónica lenta y de bajo profundo con trip-hop, cabaret y ambiente de desierto, con voces masculina y femenina alternando y hablando tanto como cantando, y arreglos que dejan mucho hueco en lugar de llenar. Es lo opuesto a Tool: poco denso, muy espacioso y con humor deliberado. Entrada: Money Shot.", origin: "rec", pick: true, p: 3, y: 2003, via: "Teatral" }
];

// ===========================================================================
// === TANDA 3 (junio 2026) — EL REPASO: 2ª vuelta de cada rama + barrido =====
// internacional. Backlog que quedó pendiente del chat "Musica". Sin repetir
// nada del catálogo ni de NEW_RECS/TANDA_2. Marco de 3 categorías aplicado.
// ===========================================================================
const TANDA_3 = [
  // ----- MUSICALES (2ª vuelta + internacionales) -----
  { name: "Natasha, Pierre & the Great Comet of 1812", genre: "Musical / Electropop Opera", desc: "Ópera electropop sobre un fragmento de Guerra y Paz, con folk, clásica rusa, rock, electrónica e indie conviviendo en la misma obra y orquestaciones densas. La electrónica es teatral, no de pista de baile, y la banda toca repartida entre el público. ▸ Versión: el elenco original Off-Broadway de 2013 (con Phillipa Soo, la más completa); el de Broadway de 2016 trae a Josh Groban como Pierre.", origin: "rec", pick: true, p: 1, y: 2012, via: "Musicales", c: 1 },
  { name: "Ride the Cyclone", genre: "Musical / Pastiche", desc: "Musical de culto oscuro donde cada canción es el pastiche de un género distinto (cabaret, synth-pop, balada ucraniana, hip-hop). El eclecticismo es la gracia. [Cat 1] ▸ Versión: la grabación del elenco original de 2016; buena parte de su culto creció desde ahí.", origin: "rec", pick: true, p: 3, y: 2015, via: "Musicales", c: 1 },
  { name: "Caroline, or Change", genre: "Musical (Jeanine Tesori)", desc: "Through-sung que mezcla Motown, blues, klezmer, spirituals y clásica en los 60. Compositivamente riquísimo, protagonista femenina. [Cat 1] ▸ Versión: el Original Broadway Cast de 2004 (Tonya Pinkins); el revival de 2021 con Sharon D. Clarke es igual de aclamado.", origin: "rec", pick: true, female: true, p: 2, y: 2003, via: "Musicales", c: 1 },
  { name: "Into the Woods", genre: "Musical (Sondheim)", desc: "Los personajes tienen motivos propios que se transforman y se cruzan, así que en los números de conjunto suenan varias líneas melódicas distintas a la vez y cada una identifica a quien la canta. El segundo acto desmonta el cuento que el primero construyó, y la música hace lo mismo con sus temas. Sondheim. ▸ Versión: el Original Broadway Cast de 1987 (Bernadette Peters, completo); la película de Disney de 2014 recorta canciones.", origin: "rec", pick: true, p: 2, y: 1987, via: "Musicales" },
  { name: "Sunday in the Park with George", genre: "Musical (Sondheim)", desc: "La escritura imita la técnica del cuadro: notas cortas y repetidas que por separado no son melodía y que forman la textura al superponerse, igual que los puntos de Seurat forman la imagen. Y el segundo acto cambia de época y de lenguaje musical entero. Sondheim. ▸ Versión: el Original Broadway Cast de 1984 (Mandy Patinkin y Bernadette Peters, la definitiva).", origin: "rec", pick: true, p: 1, y: 1984, via: "Musicales" },
  { name: "Assassins", genre: "Musical (Sondheim)", desc: "Sondheim oscuro: pastiche de estilos musicales americanos a lo largo de la historia. ▸ Versión: el elenco del revival de Broadway de 2004 (mas completo, añade 'Something Just Broke'); o el Off-Broadway original de 1990.", origin: "rec", pick: true, p: 2, y: 1990, via: "Musicales" },
  { name: "Adam Guettel", genre: "Musical / Compositor", desc: "De los compositores más sofisticados (nieto de R. Rodgers): armonías lujosas. 'The Light in the Piazza' (orquestal casi clásico), 'Floyd Collins' (folk/bluegrass disonante). ▸ Versión: es un compositor, no un musical: empieza por 'The Light in the Piazza' (Original Broadway Cast de 2005), luego 'Floyd Collins' (elenco original).", origin: "rec", pick: true, p: 2, y: 1996, via: "Musicales" },
  { name: "Jason Robert Brown", genre: "Musical / Compositor", desc: "Escritura intrincada con jazz y pop. 'The Last Five Years' (narrativa no lineal, piano virtuoso), 'Parade'. ▸ Versión: compositor: empieza por 'The Last Five Years' (elenco Off-Broadway original de 2002); para 'Parade', el revival de 2023 con Ben Platt o el original de 1998.", origin: "rec", pick: true, p: 2, y: 1995, via: "Musicales" },
  { name: "Next to Normal", genre: "Musical / Rock", desc: "Rock-musical dramático sobre salud mental: partitura de rock sólida y devastadora, nada de fórmula. ▸ Versión: el Original Broadway Cast Recording de 2009 (Alice Ripley, la definitiva).", origin: "rec", pick: true, p: 3, y: 2008, via: "Musicales" },
  { name: "The Band's Visit", genre: "Musical / Jazz-Árabe", desc: "Atmosférico y sutil: jazz cruzado con música árabe (banda egipcia varada en Israel). Instrumentación única y delicada. ▸ Versión: el Original Broadway Cast Recording de 2018 (Katrina Lenk y Tony Shalhoub).", origin: "rec", pick: true, p: 2, y: 2016, via: "Musicales" },
  { name: "The Rocky Horror Show", genre: "Musical / Glam Rock", desc: "Glam rock teatral camp con devoción al rock and roll de los cincuenta y a la ciencia ficción de serie B, con banda de rock en vivo y números que parodian estilos concretos. ▸ Versión: el soundtrack de la película de 1975 con Tim Curry, la icónica.", origin: "rec", pick: true, p: 3, y: 1973, via: "Musicales" },
  { name: "Little Shop of Horrors", genre: "Musical (Alan Menken)", desc: "Comedia de terror con planta carnívora, escrita por Alan Menken en clave doo-wop, Motown y rock sesentero, con un trío de coristas que hace de coro griego comentando la acción. ▸ Versión: el Original Off-Broadway Cast de 1982 (Ellen Greene); el soundtrack de la película de 1986 (también Ellen Greene) es otra gran opción.", origin: "rec", pick: true, female: true, p: 3, y: 1982, via: "Musicales" },
  { name: "Bat Out of Hell: The Musical", genre: "Musical / Rock Opera", desc: "Recoge las canciones de Jim Steinman (el de Meat Loaf): bombast rock operística. Teatralidad-Queen al máximo. ▸ Versión: el Original Cast de 2018; pero ojo, la fuente son los álbumes 'Bat Out of Hell' de Meat Loaf (ya en la página), superiores al musical.", origin: "rec", pick: true, p: 3, y: 2017, via: "Musicales" },
  { name: "Starmania", genre: "Musical / Ópera Rock (FR)", desc: "Ópera rock francesa clásica y sofisticada, ambiciosa y melódica. ▸ Versión: el álbum concepto original de 1978 (Daniel Balavoine, France Gall, la clásica); el revival de 2022 para una producción moderna.", origin: "rec", pick: true, p: 3, y: 1979, via: "Musicales" },
  { name: "Mozart, l'opéra rock", genre: "Musical / Rock (FR)", desc: "Musical de rock sobre Mozart que cruza lo clásico con el rock y la teatralidad. [Cat 1] ▸ Versión: la grabación del elenco original de 2009 (con L'Assasymphonie de Florent Mothe como gran momento).", origin: "rec", pick: true, p: 3, y: 2009, via: "Musicales", c: 1 },
  { name: "Tanz der Vampire", genre: "Musical / Gótico (DE)", desc: "Musical gótico de vampiros con música de Jim Steinman: bombast teatral, coros enormes y baladas de estructura larga reutilizando material de su repertorio de rock. ▸ Versión: el elenco original de Viena de 1997 (en alemán, la definitiva); evita la adaptación de Broadway de 2002 (Dance of the Vampires), que fracasó.", origin: "rec", pick: true, p: 3, y: 1997, via: "Musicales" },
  { name: "Elisabeth", genre: "Musical / Gótico (AT)", desc: "Musical oscuro y gótico (la Emperatriz Sisi con la Muerte como personaje), dramático y sombrío. ▸ Versión: el elenco original de Viena de 1992 (Pia Douwes y Uwe Kröger, la clásica); el revival vienés de 2005 también es muy querido.", origin: "rec", pick: true, p: 3, y: 1992, via: "Musicales" },

  // ----- QUEEN PESADO (2ª vuelta + internacionales) -----
  { name: "Rhapsody of Fire", genre: "Symphonic Power Metal (IT)", desc: "Symphonic power italiano bombástico: orquesta, coros, narrativa de fantasía y shred neoclásico (Luca Turilli). Ópera épica cinematográfica con guitarras. Symphony of Enchanted Lands.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Powerwolf", genre: "Power Metal (DE)", desc: "Power teatral con órgano de iglesia, coros enormes y temática licantrópica camp. Coros apilados puro espíritu Queen. Blessed & Possessed.", origin: "rec", pick: true, p: 3, y: 2004, via: "Queen pesado" },
  { name: "Edguy", genre: "Power Metal (DE)", desc: "La banda principal de Tobias Sammet (Avantasia): power melódico y teatral con humor y gancho. Hellfire Club.", origin: "rec", pick: true, p: 3, y: 1992, via: "Queen pesado" },
  { name: "Beast in Black", genre: "Melodic / Power Metal (FI)", desc: "Metal ultra-teatral (ex-Battle Beast) que cruza power con synthwave ochentero y estribillos enormes. Berserker.", origin: "rec", pick: true, p: 3, y: 2015, via: "Queen pesado" },
  { name: "Dimmu Borgir", genre: "Symphonic Black Metal (NO)", desc: "Black sinfónico grandioso y bombástico, con orquesta y coros monumentales. Majestuosidad oscura épica. Death Cult Armageddon.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Haggard", genre: "Symphonic / Classical Metal (DE)", desc: "Colectivo de hasta 20 músicos: death/doom CON orquesta y coro clásicos reales tocando música casi medieval/barroca. Awaking the Centuries. [Comodín]", origin: "rec", pick: true, p: 2, y: 1991, via: "Queen pesado", c: 3 },
  { name: "Stolen Babies", genre: "Avant-garde Metal", desc: "Metal avant teatral de Los Ángeles con acordeón, la voz versátil de Dominique Persi y estética de circo oscuro: cabaret y metal alternando dentro del tema. There Be Squabbles Ahead (2006) y Naught (2012). Entrada: There Be Squabbles Ahead.", p: 3, origin: "rec", pick: true, female: true, y: 2002, via: "Queen pesado" },
  { name: "Carach Angren", genre: "Symphonic Black Metal (NL)", desc: "Black sinfónico cinematográfico con narrativas de terror (cada disco una historia de fantasmas). Banda sonora de horror.", origin: "rec", pick: true, p: 2, y: 2003, via: "Queen pesado" },
  { name: "Delain", genre: "Symphonic Metal (NL)", desc: "Symphonic melódico y luminoso con Charlotte Wessels, gran gancho vocal. Veta Within Temptation.", origin: "rec", pick: true, female: true, p: 3, y: 2002, via: "Queen pesado" },
  { name: "Xandria", genre: "Symphonic Metal (DE)", desc: "Symphonic operístico dramático y orquestal con voz femenina. Veta sinfónica teatral.", origin: "rec", pick: true, female: true, p: 3, y: 1997, via: "Queen pesado" },
  { name: "Versailles", genre: "Symphonic Power / Visual Kei (JP)", desc: "Visual kei japonés barroco y teatral, con guitarras gemelas neoclásicas. Queen-meets-Japón.", origin: "rec", pick: true, p: 3, y: 2007, via: "Queen pesado" },
  { name: "Devil Doll", genre: "Avant-garde Rock Opera (SI/IT)", desc: "[Comodín] Cada disco es UNA sola pieza de entre cuarenta y setenta minutos, sin cortes, escrita por Mr. Doctor para banda de rock más orquesta, coro y piano, con la voz pasando de susurro a grito y de narración hablada a canto lírico, en inglés e italiano mezclados. Del primer álbum se prensó una única copia. La estructura es de ópera, no de rock. Entrada: Sacrilegium o Dies Irae.", p: 2, origin: "rec", pick: true, y: 1987, via: "Queen pesado", c: 3 },
  { name: "Tristania", genre: "Symphonic / Gothic Metal (NO)", desc: "Symphonic/gothic con voces femenina limpia y gutural, dramático y orquestal.", origin: "rec", pick: true, female: true, p: 3, y: 1996, via: "Queen pesado" },
  { name: "Twilight Force", genre: "Symphonic Power Metal (SE)", desc: "Symphonic power de fantasía, bombástico y melódico al extremo.", origin: "rec", pick: true, p: 3, y: 2011, via: "Queen pesado" },

  // ----- GOJIRA (2ª vuelta + internacionales) -----
  { name: "Cave In", genre: "Alt / Space / Prog Metal", desc: "De Boston, y cambiaron de piel de verdad: del metalcore caótico de Until Your Heart Stops (1998) al space rock de Jupiter (2000), al rock alternativo y de vuelta al peso en Heavy Pendulum (2022). El bajista Caleb Scofield murió en 2018 y su último material salió en Final Transmission. Entrada: Jupiter.", p: 2, origin: "rec", pick: true, y: 1995, via: "Gojira", c: 1 },
  { name: "Textures", genre: "Prog / Djent (NL)", desc: "Holandeses de riff percusivo y groove sincopado, de la órbita de Meshuggah y Gojira, con capas atmosféricas y voz que alterna limpio y gutural; Silhouettes (2008) y Dualism (2011) son su cumbre. Volvieron tras una década con Genotype (enero de 2026). Entrada: Silhouettes.", p: 2, origin: "rec", pick: true, y: 2001, via: "Gojira" },
  { name: "Oceans of Slumber", genre: "Prog / Doom Metal", desc: "De Houston, fundada por el baterista Dobber Beverly, que compone desde la batería con dinámica de doom y fraseo técnico; la voz de Cammie Beverly lleva el peso melódico sobre prog y doom de aire gótico sureño. Entrada: The Banished Heart.", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Gojira" },
  { name: "Hypno5e", genre: "Cinematic Post-Metal (FR)", desc: "Prog/post-metal atmosférico y cinematográfico con narración hablada y cambios brutales de dinámica. Casi una película sonora.", origin: "rec", pick: true, p: 2, y: 2003, via: "Gojira" },
  { name: "Astronoid", genre: "Dream Thrash / Blackgaze", desc: "Thrash de velocidad extrema con atmósfera de shoegaze y voces limpias soñadoras, pesado y bello a la vez. Entrada: Air.", origin: "rec", pick: true, p: 3, y: 2012, via: "Gojira" },
  { name: "Brutus", genre: "Post-Metal / Post-Hardcore (BE)", desc: "Trío belga de post-metal y post-hardcore con Stefanie Mannaerts cantando y tocando la batería a la vez: crescendos largos, guitarras en capas y una batería que empuja los temas. Burst (2017), Nest (2019) y Unison Life (2022). Entrada: Nest.", p: 2, origin: "rec", pick: true, female: true, y: 2013, via: "Gojira" },
  { name: "Toundra", genre: "Post-Rock / Post-Metal (ES)", desc: "Post-rock/metal instrumental cinematográfico y pesado, construcciones épicas.", origin: "rec", pick: true, p: 2, y: 2007, via: "Gojira" },
  { name: "Jardín de la Croix", genre: "Math / Post-Rock (ES)", desc: "Math/post-rock instrumental técnico y enérgico, riffs entrelazados complejos.", origin: "rec", pick: true, p: 2, y: 2008, via: "Gojira" },
  { name: "sleepmakeswaves", genre: "Post-Rock / Metal (AU)", desc: "Post-rock/metal instrumental dinámico, de lo etéreo a lo demoledor.", origin: "rec", pick: true, p: 3, y: 2006, via: "Gojira" },

  // ----- BEHEMOTH (2ª vuelta + internacionales / escena polaca) -----
  { name: "Tribulation", genre: "Blackened Death / Gothic (SE)", desc: "De death crudo a un death gótico y teatral, casi rock gótico con guturales: guitarras melódicas en armonía, órgano y atmósfera de cine de terror antiguo. Cada disco se aleja del anterior, de The Formulas of Death (2013) a The Children of the Night (2015), Down Below, Where the Gloom Becomes Sound y Sub Rosa in Æternum (2024). Entrada: The Children of the Night.", p: 2, origin: "rec", pick: true, y: 2005, via: "Behemoth", c: 1 },
  { name: "Emperor", genre: "Symphonic Black Metal (NO)", desc: "Ihsahn escribe riffs de tremolo que cambian de armonía cada pocos compases en lugar de repetir un patrón, con teclados que doblan y contradicen a la guitarra a la vez, y estructuras que se acumulan sin volver al principio; la batería de Trym va a una densidad que tapa el compás a propósito. Anthems to the Welkin at Dusk está grabado como un muro donde cuesta separar los instrumentos, y eso es intencional. Entra por In the Nightside Eclipse, luego Anthems.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Nile", genre: "Technical Death Metal", desc: "Death técnico con temática e instrumentación del antiguo Egipto: pasajes de escalas orientales, coros rituales y la batería de George Kollias, de las más rápidas y precisas del género. Black Seeds of Vengeance (2000), In Their Darkened Shrines y Annihilation of the Wicked (2005) son la cumbre, At the Gate of Sethu (2012) el bajón, y The Underworld Awaits Us All (2024) recupera el nivel. Entrada: Annihilation of the Wicked.", p: 2, origin: "rec", pick: true, y: 1993, via: "Behemoth" },
  { name: "Mgła", genre: "Atmospheric Black Metal (PL)", desc: "Black metal atmosférico polaco muy cohesivo: riffs de trémolo melódicos y melancólicos repetidos hasta la hipnosis, con la batería de Darkside, muy musical y llena de redobles, como motor. With Hearts Toward None (2012), Exercises in Futility (2015) y Age of Excuse (2019). Entrada: Exercises in Futility.", origin: "rec", pick: true, p: 2, y: 2000, via: "Behemoth" },
  { name: "Dissection", genre: "Melodic Blackened Death (SE)", desc: "Death y black melódico sueco: trémolos de guitarra con melodías de raíz clásica sobre blast beats, frío y majestuoso. The Somberlain (1993) y Storm of the Light's Bane (1995) son la obra fuerte; Reinkaos (2006) queda muy por debajo. Entrada: Storm of the Light's Bane.", p: 2, origin: "rec", pick: true, y: 1989, via: "Behemoth" },
  { name: "Watain", genre: "Black Metal (SE)", desc: "Black metal sueco ortodoxo y ritualista, oscuro y ceremonial, de riffs rápidos bien escritos dentro del molde. Casus Luciferi (2003) y Lawless Darkness (2010) son lo mejor. Entrada: Lawless Darkness.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Immolation", genre: "Dissonant Death Metal", desc: "Death disonante de Nueva York: los riffs de Robert Vigna se retuercen en intervalos raros y cambios de tempo, con armonías torcidas a propósito, y la batería (Steve Shalaty desde 2003) sigue esos giros en vez de marcar. Doce discos sin un bajón serio, de Dawn of Possession (1991) y Here in After a Close to a World Below (2000), Unholy Cult, Majesty and Decay, Atonement (2017), Acts of God y Descent (abril de 2026). Entrada: Close to a World Below.", p: 1, origin: "rec", pick: true, y: 1988, via: "Behemoth" },
  { name: "Myrkur", genre: "Atmospheric Black Metal (DK)", desc: "Black atmosférico y folk nórdico de Amalie Bruun, que alterna lo etéreo con la crudeza del black y arreglos folk. Mareridt (2017) y Folkesange (2020). Entrada: Mareridt.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Behemoth" },
  { name: "Batushka", genre: "Ritual Black Metal (PL)", desc: "[Comodín] Black metal con cantos ortodoxos eslavos, estructurado como una liturgia: teatral, hipnótico y ceremonial. Litourgiya (2015) es el disco que importa; después la banda se partió en dos por una disputa entre sus miembros. Entrada: Litourgiya.", origin: "rec", pick: true, p: 3, y: 2015, via: "Behemoth", c: 3 },
  { name: "Schammasch", genre: "Avant-garde Black Metal (CH)", desc: "Black de vanguardia suizo de tono ritual: del black extremo a pasajes ambientales y meditativos, con coros y estructuras largas. Triangle (2016) es un triple que recorre ese arco entero. Entrada: Triangle.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Chelsea Wolfe", genre: "Doom / Gothic Rock", desc: "Doom, gótico y folk atmosférico y oscuro con su voz hipnótica, de producción densa pero de escritura sencilla. Abyss (2015) y She Reaches Out to She Reaches Out to She (2024). Entrada: Abyss.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "Behemoth" },
  { name: "Hate", genre: "Blackened Death Metal (PL)", desc: "Blackened death polaco majestuoso, de trémolos y blast beats con melodías oscuras, en la línea de Behemoth. Anaclasis (2005) y Morphosis son lo mejor. Entrada: Anaclasis.", origin: "rec", pick: true, p: 3, y: 1990, via: "Behemoth" },
  { name: "Vader", genre: "Death Metal (PL)", desc: "Death metal clásico polaco, veloz y contundente, muy parejo durante tres décadas: riffs de thrash acelerado y batería a toda velocidad dentro de una estructura de manual. The Ultimate Incantation (1992), De Profundis (1995) y Litany (2000) son lo mejor. Entrada: De Profundis.", origin: "rec", pick: true, p: 3, y: 1983, via: "Behemoth" },
  { name: "Azarath", genre: "Blackened Death Metal (PL)", desc: "Blackened death polaco del batería de Behemoth, Inferno: brutal, veloz y muy bien tocado, dentro del molde. Entrada: Blasphemers' Maledictions.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Blut Aus Nord", genre: "Experimental Black Metal (FR)", desc: "Black metal experimental francés, prácticamente de una sola persona, Vindsval: guitarras disonantes que se deforman como líquido, cajas de ritmos industriales y, según el disco, atmósfera o ruido. De The Work Which Transforms God (2003) a la trilogía 777 (2011-2012), con un disco metálico, uno industrial y uno atmosférico, Hallucinogen (2019) y Disharmonium (2022); la serie Memoria Vetusta es su cara más melódica. Entrada: The Work Which Transforms God.", origin: "rec", p: 1, y: 1995, c: 1 },
  { name: "The Great Old Ones", genre: "Atmospheric Black Metal (FR)", desc: "Black atmosférico francés de temática lovecraftiana, cinematográfico y envolvente, con tres guitarras. EOD: A Tale of Dark Legacy (2017) es la cumbre. Entrada: EOD: A Tale of Dark Legacy.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Cult of Fire", genre: "Ritual Black Metal (CZ)", desc: "Black metal checo de temática hindú, con letras en sánscrito e instrumentos indios integrados en un black atmosférico y ceremonial. Entrada: Ascetic Meditation of Death (2013).", origin: "rec", pick: true, p: 2, y: 2011, via: "Behemoth" },
  { name: "Furia", genre: "Avant-garde Black Metal (PL)", desc: "Black metal polaco de vanguardia con letras en polaco muy poéticas, riffs que se retuercen hacia el rock y la psicodelia y estructuras que cambian de un disco a otro. Księżyc milczy luty (2016) es la referencia. Entrada: Księżyc milczy luty.", origin: "rec", pick: true, p: 2, y: 2003, via: "Behemoth", c: 1 },

  // ----- PROTEST THE HERO (3ª vuelta + internacionales) -----
  { name: "Tera Melos", genre: "Math Rock / Experimental", desc: "Math rock experimental y juguetón, técnico y caótico pero melódico, cambia de textura constantemente. Patagonian Rats. [Cat 1]", origin: "rec", pick: true, p: 2, y: 2004, via: "PTH", c: 1 },
  { name: "The Number Twelve Looks Like You", genre: "Mathcore", desc: "Mathcore caótico y ecléctico que salta del jazz a la brutalidad a lo melódico en segundos. Nuclear. Sad. Nuclear. [Cat 1]", origin: "rec", pick: true, p: 3, y: 2003, via: "PTH", c: 1 },
  { name: "After the Burial", genre: "Djent / Prog Metalcore", desc: "Djent y metalcore progresivo de Minnesota: riffs de ocho cuerdas en polirritmia, solos técnicos y groove muy pesado. Rareform (2008) es la cumbre, e In Dreams, Wolves Within y Dig Deep (2016) sostienen el nivel; su guitarrista y compositor Justin Lowe murió en 2015. Entrada: Rareform.", p: 2, origin: "rec", pick: true, y: 2004, via: "PTH" },
  { name: "Tricot", genre: "Math Rock (JP)", desc: "Math rock japonés con voz femenina: ritmos intrincados, guitarras entrelazadas y melodías brillantes, energía luminosa. 3, A N D.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "PTH" },
  { name: "Vexed", genre: "Prog Metalcore (UK)", desc: "Metalcore progresivo británico con Megan Targett a la voz: riffs djent técnicos y agresivos con pasajes melódicos. Culling Culture (2021) y Negative Energy (2023). Entrada: Culling Culture.", p: 2, origin: "rec", pick: true, female: true, y: 2019, via: "PTH" },
  { name: "Sithu Aye", genre: "Prog / Instrumental (UK)", desc: "Prog y djent instrumental británico, brillante y de mucho tapping, luminoso y melódico.", origin: "rec", pick: true, p: 3, y: 2011, via: "PTH" },
  { name: "Standards", genre: "Math Rock / Instrumental", desc: "Dúo instrumental de Los Ángeles, formado en 2017: Marcos Mena hace todo el trabajo armónico con tapping a dos manos sobre batería, sin bajo, y las piezas duran dos minutos y no se repiten. Todos sus discos llevan título de fruta. Entrada: Fruit Town.", origin: "rec", pick: true, p: 3, y: 2017, via: "PTH" },
  { name: "Tigran Hamasyan", genre: "Jazz / Prog (AM)", desc: "Pianista armenio que cruza jazz, folk armenio y un groove de riff casi metalero: la mano izquierda toca patrones en métricas impares contra la derecha y los temas cambian de compás sin aviso. Lo sostiene en discos muy distintos: Red Hail (2009) y Shadow Theater con banda y voz, Mockroot (2015) y The Call Within (2020) en lo más cercano al prog metal, An Ancient Observer casi a piano solo y The Bird of a Thousand Voices (2024) como obra conceptual. Solo los discos de cámara más contemplativos bajan la intensidad. Entrada: Mockroot.", p: 1, origin: "rec", pick: true, y: 2006, via: "PTH", c: 3 },
  { name: "Paledusk", genre: "Prog Metalcore (JP)", desc: "Metalcore japonés caótico y ecléctico: salta de breakdown a jazz, pop, electrónica y hardcore en pocos segundos, con guitarras técnicas y mucho humor. Happy Talk, Palehell y sus EPs. Entrada: Palehell.", p: 2, origin: "rec", pick: true, y: 2015, via: "PTH", c: 1 },
  { name: "Elephant Gym", genre: "Math Rock (TW)", desc: "Taiwaneses, instrumentales. El bajo de KT Chang no marca la raíz: lleva la melodía principal con acordes y armónicos mientras la guitarra hace figuras cortas por encima, sobre métricas que cambian sin que suene forzado. Entrada: Underwater.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "PTH" },
  { name: "toe", genre: "Math Rock (JP)", desc: "Math rock instrumental jazzy y melódico, intrincado pero cálido.", origin: "rec", pick: true, p: 2, y: 2000, via: "PTH" },
  { name: "David Maxim Micić", genre: "Prog / Djent (RS)", desc: "Guitarrista serbio de prog y djent instrumental cinematográfico: melodía de guitarra muy cantable sobre base djent y arreglos orquestales. Bien escrito, pero luminoso y de complejidad más melódica que rítmica. Entrada: Bilo.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Disperse", genre: "Prog / Fusion (PL)", desc: "Prog polaco luminoso de guitarra limpia y tapping, con fusión suave y voz: técnico pero amable, en la línea de Plini. Entrada: Living Mirrors.", p: 3, origin: "rec", pick: true, y: 2007, via: "PTH" },
  { name: "mouse on the keys", genre: "Math / Jazz (JP)", desc: "Math/jazz instrumental de piano, intenso y elegante.", origin: "rec", pick: true, p: 2, y: 2006, via: "PTH" },

  // ----- DREAM THEATER (2ª vuelta + internacionales) -----
  { name: "Madder Mortem", genre: "Prog / Doom (NO)", desc: "Prog y doom noruego construido alrededor de la voz de Agnete Kjølsrud, que pasa del susurro al grito sin perder el control, con guitarras que saltan de lo pesado a lo atmosférico y a pasajes casi folk dentro del mismo tema. Mercury (1999) es el más verde; de All Flesh Is Grass (2001) y Deadlands a Desiderata, Eight Ways, Red in Tooth and Claw, Marrow y Old Eyes, New Heart (2024) el nivel no baja. Entrada: Deadlands.", p: 2, origin: "rec", pick: true, female: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Subterranean Masquerade", genre: "Oriental Prog Metal (IL)", desc: "Prog israelí que mezcla death, prog, folk de Oriente Medio y jazz en temas largos, con voces limpias y guturales y escalas orientales que salen de la escritura, no de un adorno encima. Suspended Animation Dreams (2005), The Great Bazaar (2015), Vagabond (2017) y Mountain Fever (2021). Entrada: Suspended Animation Dreams.", p: 2, origin: "rec", pick: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Evergrey", genre: "Prog / Power Metal (SE)", desc: "Prog y power sueco oscuro y melancólico, de identidad emocional fuerte y buena guitarra; Architects of a New Weave (2026) sigue esa línea. Entrada: The Inner Circle.", p: 3, origin: "rec", pick: true, y: 1995, via: "Dream Theater" },
  { name: "Angra", genre: "Prog / Power Metal (BR)", desc: "Power y prog brasileño que integra percusión y ritmos de su país en temas técnicos: Holy Land (1996) los mete en la estructura misma de los temas, y Temple of Shadows (2004), conceptual, es su disco más complejo. De Rebirth a Ømni (2018) y Cycles of Pain (2023) mantienen la ambición, con baterías de primera como Aquiles Priester y Bruno Valverde; Aqua (2010) es el bajón. Entrada: Holy Land, luego Temple of Shadows.", p: 2, origin: "rec", pick: true, y: 1991, via: "Dream Theater" },
  { name: "Galneryus", genre: "Power / Prog Metal (JP)", desc: "Power y prog japonés de virtuosismo extremo: la guitarra neoclásica de Syu y los teclados de Yuhki se doblan y se contestan en secciones instrumentales largas, con estructura de power metal pero mucha más densidad instrumental de lo habitual en el género. Lo sostienen en más de quince discos, de The Flag of Punishment (2003) a Resurrection (2010), el primero con Masatoshi Ono a la voz, Angel of Salvation (2012), Under the Force of Courage (2015) y Union Gives Strength (2021). Entrada: Resurrection.", p: 2, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Kingcrow", genre: "Prog Metal (IT)", desc: "Prog italiano atmosférico y melódico, de texturas muy cuidadas y ritmo contenido. Entrada: Eidos.", p: 3, origin: "rec", pick: true, y: 1996, via: "Dream Theater" },
  { name: "Iamthemorning", genre: "Chamber Prog (RU)", desc: "Prog de cámara ruso: el piano de Gleb Kolyadin, de formación clásica y escritura muy virtuosa, lleva la armonía y el contrapunto junto a cuerdas y maderas, bajo la voz cristalina de Marjana Semkina. Sin peso de metal, pero con arreglos que cambian de clima dentro de la canción. ~ (2012), Belighted (2014), Lighthouse (2016), con Gavin Harrison a la batería, y The Bell (2019) sostienen el nivel. Entrada: Lighthouse.", p: 2, origin: "rec", pick: true, female: true, y: 2010, via: "Dream Theater" },
  { name: "Anubis Gate", genre: "Prog Metal (DK)", desc: "Prog metal danés melódico y atmosférico, sólido y luminoso, dentro de la escuela clásica del género. Entrada: Andromeda Unchained.", p: 3, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Adagio", genre: "Neoclassical Prog Metal (FR)", desc: "Prog metal neoclásico francés: guitarra de escalas barrocas y teclados sinfónicos, virtuoso y oscuro pero de estructura power. Entrada: Underworld.", p: 3, origin: "rec", pick: true, y: 2000, via: "Dream Theater" },
  { name: "Andromeda", genre: "Technical Prog Metal (SE)", desc: "Prog metal sueco técnico y oscuro, de la escuela de Dream Theater pero más pesado: largas secciones instrumentales donde guitarra y teclado se doblan y se contestan en compases cambiantes. Extension of the Wish (2001), II=I (2003) y Chimera (2006) son su etapa fuerte. Entrada: II=I.", p: 2, origin: "rec", pick: true, y: 1999, via: "Dream Theater" },
  { name: "Liquid Tension Experiment", genre: "Prog / Instrumental", desc: "Prog metal instrumental sin formato canción: teclado y guitarra se intercambian el papel principal y el Chapman Stick de Tony Levin da un bajo de ataque distinto al normal. La mitad es composición de verdad (Acid Rain, Universal Mind) y la otra mitad jams de estudio donde el virtuosismo va por delante de la idea. Entrada: el primer disco (1998).", origin: "rec", p: 2, y: 1997, c: 2 },
  { name: "Goblin", genre: "Prog Rock / Soundtrack (IT)", desc: "Prog italiano instrumental hecho para cine de terror: patrones cortos de teclado y bajo repetidos en métricas irregulares que crean tensión por acumulación en vez de por melodía. Entrada: Profondo Rosso.", origin: "rec", pick: true, p: 2, y: 1972, via: "Dream Theater" },

  // ----- TRIVIUM (2ª vuelta + internacionales) -----
  { name: "Carcass", genre: "Melodic Death (UK)", desc: "De goregrind ilegible a Heartwork, con guitarras gemelas armonizadas y solos escritos como melodía y no como exhibición. Symphonies of Sickness (1989) y Necroticism (1991) ya encadenaban riffs en estructuras largas, Heartwork (1993) es la cumbre y Swansong (1996), con su giro al rock, baja; Surgical Steel (2013) y Torn Arteries (2021) volvieron con esa escritura intacta. Entrada: Heartwork.", origin: "rec", pick: true, p: 1, y: 1985, via: "Trivium", c: 1 },
  { name: "Testament", genre: "Thrash Metal", desc: "Alex Skolnick viene del jazz y eso se nota en sus solos, que son melódicos y con desarrollo en vez de ráfagas, y ese es el mejor argumento que tienen. Pero por debajo es thrash de la Bay Area muy bien hecho y bastante ortodoxo, con riffs de palm mute, estructuras de estrofa y estribillo y poca sorpresa rítmica. Excelente dentro del molde. Para Bellum (octubre de 2025), con el joven Chris Dovas a la batería, fue de los discos de thrash mejor recibidos del año. Entrada: The New Order o The Legacy.", origin: "rec", p: 2, y: 1983, c: 2 },
  { name: "Annihilator", genre: "Technical Thrash (CA)", desc: "Thrash técnico alrededor de Jeff Waters, guitarrista virtuoso: riffs intrincadísimos y solos vertiginosos. Alice in Hell (1989) y Never, Neverland (1990) son lo que importa; después, con cambios constantes de formación, es muy irregular. Entrada: Alice in Hell.", origin: "rec", pick: true, p: 2, y: 1984, via: "Trivium" },
  { name: "Coroner", genre: "Progressive Thrash (CH)", desc: "Thrash suizo tocado con lógica de jazz: Tommy Vetterli mete acordes de jazz y solos de fraseo casi clásico sobre riffs que cambian de compás a mitad, y la batería subdivide contra la guitarra en vez de marcar el galope. De Punishment for Decadence a No More Color y Mental Vortex cada disco aprieta más, Grin (1993) lo abre a groove y textura, y Dissonance Theory (2025), su vuelta tras treinta y dos años con Diego Rappachietti a la batería, supera en ambición a Grin según la crítica. Entrada: Mental Vortex.", p: 1, origin: "rec", pick: true, y: 1985, via: "Trivium", c: 2 },
  { name: "Kalmah", genre: "Melodic Death (FI)", desc: "Melodeath finlandés con shred neoclásico a dos guitarras y teclados que se turnan los solos, en la línea de Children of Bodom pero con un aire folk propio. Muy parejos de Swamplord (2000) a Swampsong (2003), The Black Waltz, 12 Gauge, Seventh Swamphony y Kalmah (2023). Entrada: Swampsong.", origin: "rec", pick: true, p: 2, y: 1998, via: "Trivium" },
  { name: "Aephanemer", genre: "Symphonic Melodic Death (FR)", desc: "Melodeath sinfónico francés con Marion Bascoul a la voz: melodías muy trabajadas, guitarras neoclásicas y orquestación. Prokopton (2019), A Dream of Wilderness (2021), la cumbre, y Utopie (2025). Entrada: A Dream of Wilderness.", origin: "rec", pick: true, female: true, p: 2, y: 2014, via: "Trivium" },
  { name: "God Forbid", genre: "Melodic Metalcore / Thrash", desc: "Metalcore y thrash melódico de Nueva Jersey con guitarras gemelas y groove, en la línea de Ascendancy e In Waves de Trivium. IV: Constitution of Treason (2005) es su disco más ambicioso, un concepto entero. Entrada: IV: Constitution of Treason.", p: 3, origin: "rec", pick: true, y: 1996, via: "Trivium" },
  { name: "Mekong Delta", genre: "Technical / Prog Thrash (DE)", desc: "Thrash técnico alemán escrito como música de cámara: el bajista y compositor Ralph Hubert mete compases imposibles, contrapunto entre guitarras y adaptaciones de piezas clásicas, como Una noche en el Monte Pelado de Músorgski. The Music of Erich Zann (1988) y Dances of Death (1990) son lo más ambicioso. Entrada: Dances of Death.", p: 2, origin: "rec", pick: true, y: 1985, via: "Trivium" },
  { name: "Watchtower", genre: "Progressive Thrash", desc: "El bajo de Doug Keyser no acompaña: lleva líneas independientes mientras la batería cambia de compás dentro de la frase, sobre thrash tocado con lógica de jazz. Solo tienen dos discos, Energetic Disassembly (1985) y Control and Resistance (1989), y los dos sostienen esa escritura. Entrada: Control and Resistance.", origin: "rec", pick: true, p: 1, y: 1982, via: "Trivium", c: 3 },
  { name: "Crystal Viper", genre: "Heavy / Power Metal (PL)", desc: "Heavy/power clásico con Marta Gabriel, melódico y épico.", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Trivium" },
  { name: "Walls of Jericho", genre: "Metalcore / Hardcore", desc: "Metalcore y hardcore de Detroit con Candace Kucsulain al frente: crudo, rápido y con pegada, de estructura muy directa. Entrada: With Devils Amongst Us All.", origin: "rec", pick: true, female: true, p: 3, y: 1998, via: "Trivium" },

  // ----- AVENGED SEVENFOLD (repaso de la rama madre) -----
  { name: "Buckethead", genre: "Avant / Instrumental Guitar", desc: "Guitarrista de técnica enorme, con tapping, killswitch y fraseo de shred, y una obra de más de trescientos discos que salta del metal al funk, al ambient y a lo avant. Es muy desigual: lo mejor está en Monsters and Robots (1999), Colma, Electric Tears, Enter the Chicken y Crime Slunk Scene, y buena parte de la serie de pikes es improvisación de relleno. Entrada: Crime Slunk Scene.", p: 2, origin: "rec", pick: true, y: 1991, via: "A7X", c: 1 },
  { name: "Marty Friedman", genre: "Instrumental Guitar (US/JP)", desc: "El ex-Megadeth en solitario: virtuoso con fraseo exótico (escalas japonesas/árabes) y discos instrumentales eclécticos. Tokyo Jukebox, Inferno.", origin: "rec", pick: true, p: 2, y: 1988, via: "A7X" },
  { name: "Lovebites", genre: "Power / Melodic Metal (JP)", desc: "Banda femenina: power/melodic con guitarras gemelas neoclásicas vertiginosas, muy en la onda de los solos de City of Evil. Electric Pentagram.", origin: "rec", pick: true, female: true, p: 3, y: 2016, via: "A7X" },
  { name: "The Warning", genre: "Hard Rock / Alt Metal (MX)", desc: "Trío de hermanas de Monterrey: Daniela a la guitarra y voz, Alejandra al bajo y Paulina a la batería, que además canta principal en varios temas mientras toca. Hard rock técnico con riffs ajustados, cambios de tempo dentro de la canción y armonías vocales a tres. Empezaron subiendo versiones a internet siendo niñas y acabaron girando con bandas grandes. Entrada: Error o Keep Me Fed.", origin: "rec", pick: true, female: true, p: 2, y: 2013, via: "A7X" },
  { name: "Band-Maid", genre: "Hard Rock (JP)", desc: "Hard rock japonés técnico y ajustadísimo: riffs intrincados con paradas al milímetro, dos guitarras repartiéndose líneas distintas y una batería que sostiene cambios constantes. Entrada: World Domination.", origin: "rec", pick: true, female: true, p: 2, y: 2013, via: "A7X" },
  { name: "Black Label Society", genre: "Blues / Heavy Metal", desc: "Zakk Wylde, virtuoso del blues-metal: riffs pesados y solos con feeling. The Blessed Hellride.", origin: "rec", pick: true, p: 3, y: 1998, via: "A7X" },
  { name: "Steve Vai", genre: "Instrumental Guitar", desc: "Virtuoso teatral e instrumental que hace 'cantar' a la guitarra, melódico y experimental. La cumbre del instrumento. Passion and Warfare.", origin: "rec", pick: true, p: 2, y: 1984, via: "A7X" },
  { name: "Nemophila", genre: "Melodic Death / Metal (JP)", desc: "Banda femenina: metal/melodeath con voz que alterna limpio potente y gutural, guitarras técnicas y energía. Seize the Fate.", origin: "rec", pick: true, female: true, p: 3, y: 2019, via: "A7X" },

  // ----- CAGE THE ELEPHANT (2ª vuelta + internacionales) -----
  { name: "Café Tacvba", genre: "Alt Rock (MX)", desc: "Rock alternativo mexicano que cambia de lenguaje dentro de la misma canción: en Re (1994), un disco doble, cruzan huapango, son jarocho, norteño, ska, punk y fusión jazz, y El Aparato arranca como huapango, entra un sintetizador y termina en cuerdas y cantos panafricanos. Café Tacvba (1992), Re, Revés/Yo soy (1999), la cumbre experimental, y Cuatro caminos (2003) sostienen ese nivel; de Sino (2007) a Jei Beibi (2017) la escritura se vuelve más de canción y baja. Entrada: Re.", origin: "rec", pick: true, p: 1, y: 1989, via: "Cage the Elephant", c: 1 },
  { name: "Pond", genre: "Psych Rock (AU)", desc: "Psych rock australiano ecléctico y prolífico, colorido y experimental, con miembros que pasaron por Tame Impala. The Weather (2017). Entrada: The Weather.", p: 3, origin: "rec", pick: true, y: 2008, via: "Cage the Elephant", c: 1 },
  { name: "Unknown Mortal Orchestra", genre: "Psych / Funk (NZ/US)", desc: "Psicodelia y funk lo-fi de Ruban Nielson, un guitarrista muy bueno: melodías retorcidas, groove y atmósfera cálida, con una producción casera deliberadamente saturada. II (2013) y Multi-Love (2015) son lo mejor. Entrada: Multi-Love.", origin: "rec", pick: true, p: 3, y: 2010, via: "Cage the Elephant" },
  { name: "The Black Angels", genre: "Psych Rock", desc: "Psych rock oscuro de Austin, de drones y riffs repetidos hasta la hipnosis. Passover (2006). Entrada: Passover.", origin: "rec", pick: true, p: 3, y: 2004, via: "Cage the Elephant" },
  { name: "Warpaint", genre: "Atmospheric Indie Rock", desc: "Banda femenina: atmosférico e hipnótico con guitarras entrelazadas, bajo protagonista y ritmos intrincados. Sutil y moody. The Fool.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Cage the Elephant" },
  { name: "Blues Pills", genre: "Blues / Psych Rock (SE)", desc: "Blues/psych retro con Elin Larsson (voz poderosa) y guitarra con feeling. Cálido y orgánico. Lady in Gold.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },
  { name: "Fontaines D.C.", genre: "Post-Punk (IE)", desc: "Post-punk irlandés que fue de lo crudo y recitado a lo texturado y ambicioso disco a disco, con guitarras cada vez más tratadas y arreglos más amplios; en Romance ya hay sintetizadores y cuerda. Entrada: Skinty Fia.", origin: "rec", pick: true, p: 2, y: 2014, via: "Cage the Elephant" },
  { name: "Hinds", genre: "Garage Rock (ES)", desc: "Banda madrileña de garage rock crudo y melódico, con armonías vocales y energía desenfadada. Entrada: Leave Me Alone.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },

  // ----- METALCORE (2ª vuelta + internacionales) -----
  { name: "The Chariot", genre: "Chaotic Metalcore", desc: "Metalcore grabado casi en directo y a propósito sin cuadricular, con cortes bruscos a silencio, feedback usado como parte del tema y estructuras que no repiten el estribillo ni una vez. Josh Scogin grita por encima de riffs que se desmontan a mitad. De Everything Is Alive (2004) a The Fiancée, Wars and Rumors of Wars, Long Live (2010) y One Wing (2012) cada disco es más escrito; hay más energía que desarrollo, pero no hay uno flojo. Entrada: Long Live.", origin: "rec", p: 2, y: 2003, c: 1 },
  { name: "Poison the Well", genre: "Metalcore", desc: "Pioneros del metalcore de Florida que fueron metiendo melodía, atmósfera y rarezas en cada disco: riffs de hardcore que se abren a guitarras limpias y ambientes, con estructuras que no se repiten. The Opposite of December (1999), Tear from the Red y You Come Before You (2003) son la base, Versions (2007) y The Tropic Rot (2009) lo llevan a sitios raros, y Peace in Place (marzo de 2026), tras diecisiete años, recupera la rabia. Entrada: You Come Before You.", p: 2, origin: "rec", pick: true, y: 1997, via: "Metalcore", c: 1 },
  { name: "Converge", genre: "Metalcore / Mathcore", desc: "Kurt Ballou escribe riffs disonantes que cambian de figura cada pocos segundos y nunca vuelven al mismo sitio, y Ben Koller toca la batería como una voz más, cambiando de patrón bajo el mismo riff y metiendo redobles que rompen el compás en vez de marcarlo. Jane Doe alterna esa violencia con pasajes largos y lentos dentro del mismo disco. Ballou además graba a media escena desde su propio estudio. Entra por Jane Doe.", origin: "rec", p: 1, y: 1990, c: 2 },
  { name: "Botch", genre: "Mathcore", desc: "Riffs angulares en métricas que no se repiten y canciones que acaban en un sitio distinto del que empezaron, sin volver nunca a la primera sección. American Nervoso y We Are the Romans funcionan igual. Entrada: We Are the Romans.", origin: "rec", pick: true, p: 1, y: 1993, via: "Metalcore" },
  { name: "Novelists", genre: "Prog Metalcore (FR)", desc: "Metalcore progresivo francés, melódico y técnico, con riffs djent pulidos y estribillos de voz limpia: bien hecho, pero dentro del molde del género y sin la escritura de los mejores. De Souvenirs (2015) y Noir a C'est la vie, Déjà Vu (2022) y CODA (2025), ya con Camille Contreras a la voz. Entrada: Noir.", p: 3, origin: "rec", pick: true, y: 2013, via: "Metalcore" },
  { name: "Pupil Slicer", genre: "Mathcore / Grind (UK)", desc: "Mathcore y grind caótico y técnico con Kate Davies, que en el segundo disco gira hacia lo progresivo y lo atmosférico. Mirrors (2021) y Blossom (2023). Entrada: Blossom.", p: 2, origin: "rec", pick: true, female: true, y: 2019, via: "Metalcore" },
  { name: "Frontierer", genre: "Dissonant Mathcore", desc: "Mathcore disonante y glitchy: capas de guitarra recortadas digitalmente, samples de ruido metidos como percusión y riffs que cambian de figura cada compás, todo mezclado como una pared saturada. Abrasivo de principio a fin. Entrada: Unloved.", origin: "rec", pick: true, p: 2, y: 2012, via: "Metalcore" },
  { name: "Vildhjarta", genre: "Thall / Djent (SE)", desc: "Thall: afinaciones gravísimas, riffs de ritmo entrecortado que funcionan casi como percusión y capas de ambiente disonante entre golpe y golpe. Måsstaden (2011), Måsstaden under vatten (2021) y + Där skogen sjunger under evighetens granar + (2025). Entrada: Måsstaden under vatten.", p: 2, origin: "rec", pick: true, y: 2005, via: "Metalcore" },
  { name: "Dream State", genre: "Melodic Post-Hardcore (UK)", desc: "Post-hardcore y metalcore melódico británico, emotivo y dinámico, dentro de la fórmula del género: lo distintivo es la voz, no la escritura instrumental. Entrada: Primrose Path.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Metalcore" },

  // ----- BE'LAKOR / MELODEATH ATMOSFÉRICO (2ª vuelta + internacionales) -----
  { name: "Katatonia", genre: "Atmospheric Prog Metal (SE)", desc: "Empezaron en el doom-death y acabaron en un rock atmosférico y melancólico de capas de guitarra limpia y voz baja: instrumentalmente es contención deliberada, no complejidad, con el interés en la textura y en cómo la batería sostiene tempos lentos. Anders Nyström, cofundador y guitarrista durante casi treinta y cinco años, se fue en marzo de 2025; Nightmares as Extensions of the Waking State salió tres meses después. Entrada: The Great Cold Distance.", origin: "rec", p: 2, y: 1991, c: 1 },
  { name: "Borknagar", genre: "Prog Folk / Viking Metal (NO)", desc: "Black y viking noruego que fue incorporando prog: voces limpias en armonía a varias voces contra guturales, teclados de Lars Nedland haciendo contrapunto y estructuras largas con cambios de clima. Empiricism (2001) y Winter Thrice (2016) son dos etapas del mismo crecimiento. Entrada: Empiricism.", p: 2, origin: "rec", pick: true, y: 1995, via: "Be'lakor", c: 1 },
  { name: "An Abstract Illusion", genre: "Prog Death (SE)", desc: "Death progresivo sueco atmosférico y sinfónico, con teclados y canciones larguísimas que son viajes completos. Illuminate the Path (2016) y Woe (2022) son la cumbre, y The Sleeping City (2025) queda algo por debajo. Entrada: Woe.", p: 2, origin: "rec", pick: true, y: 2013, via: "Be'lakor" },
  { name: "Eternal Storm", genre: "Prog Melodic Death (ES)", desc: "Madrileños de melodeath progresivo y atmosférico en la órbita de Be'lakor: temas largos que se desarrollan en vez de repetir, con guitarras limpias entre lo pesado. Come the Tide (2019) y A Giant Bound to Fall (2024). Entrada: Come the Tide.", origin: "rec", pick: true, p: 2, y: 2008, via: "Be'lakor" },
  { name: "October Tide", genre: "Melodic Death/Doom (SE)", desc: "Nacido de Jonas Renkse y Fredrik Norrman, de Katatonia: death/doom melancólico con guitarras melódicas lentas. Rain Without End (1997) es la cumbre; desde A Thin Shell (2010), con Norrman al mando, sigue a buen nivel. Entrada: Rain Without End.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Moonsorrow", genre: "Pagan / Folk Metal (FI)", desc: "Pagan/folk con canciones épicas larguísimas (10-30 min) que son odiseas atmosféricas. Kivenkantaja.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Draconian", genre: "Gothic Doom Metal (SE)", desc: "Gothic doom sueco atmosférico y melancólico con voz femenina limpia y gutural masculina. Lento y hermoso, dentro del molde. Entrada: Sovran.", origin: "rec", pick: true, female: true, p: 3, y: 1994, via: "Be'lakor" },
  { name: "Trees of Eternity", genre: "Gothic Doom (SE/FI)", desc: "Doom gótico atmosférico con la voz etérea de Aleah Stanbridge; un solo disco, Hour of the Nightingale (2016), publicado tras su muerte. Melancólico y lento. Entrada: Hour of the Nightingale.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Be'lakor" },
  { name: "Fractal Universe", genre: "Prog Death (FR)", desc: "Death progresivo francés con saxofón y jazz integrados en la estructura, técnico y ambicioso. Rhizomes of Insanity (2019) y The Impassable Horizon (2021). Entrada: The Impassable Horizon.", p: 2, origin: "rec", pick: true, y: 2014, via: "Be'lakor" },

  // ----- PANIC! AT THE DISCO (2ª vuelta + internacionales) -----
  { name: "David Bowie", genre: "Art Rock / Glam (UK)", desc: "En Low la cara B son piezas casi instrumentales con los sintetizadores tratados como textura y sin estructura de canción; en Heroes la guitarra de Robert Fripp está grabada con retroalimentación controlada según la distancia al amplificador; y Blackstar lo grabó con el cuarteto de jazz de Donny McCaslin, con el saxo llevando líneas principales en compases irregulares. Ziggy y Aladdin Sane tienen a Mick Ronson escribiendo los arreglos de cuerda. Cinco décadas cambiando de sistema. Entra por Low o Blackstar.", origin: "rec", p: 1, y: 1967, c: 1 },
  { name: "Roxy Music", genre: "Art / Glam Rock (UK)", desc: "Art-glam sofisticado y elegante (Ferry + Eno): teatral, experimental y melódico. For Your Pleasure, Avalon. [Cat 1]", origin: "rec", pick: true, p: 2, y: 1971, via: "Panic!", c: 1 },
  { name: "Scott Walker", genre: "Baroque / Avant Pop", desc: "De crooner barroco orquestal a la vanguardia más oscura. Scott 1 a Scott 4 (1967-1969) son canción de cámara con arreglos de cuerda muy escritos y su voz de barítono al frente; tras unos setenta de discos de encargo muy flojos, Nite Flights (1978) abre la etapa final, que en Tilt (1995), The Drift (2006) y Bish Bosch (2012) es disonancia, silencio y percusión rara al servicio de una voz casi operística. Entrada: Scott 4, luego Tilt.", p: 2, origin: "rec", pick: true, y: 1967, via: "Panic!", c: 1 },
  { name: "10cc", genre: "Art Pop (UK)", desc: "Art pop barroco e ingenioso de los 70, instrumentalmente inventivo y juguetón. Queen-adjacent. The Original Soundtrack.", origin: "rec", pick: true, p: 2, y: 1972, via: "Panic!" },
  { name: "Sufjan Stevens", genre: "Baroque Chamber Pop", desc: "Folk de cámara con orquestaciones ornamentadas (vientos, cuerdas, coros), conceptual y delicado. Para el lado barroco de Pretty.Odd. Illinois.", origin: "rec", pick: true, p: 2, y: 2000, via: "Panic!" },
  { name: "Father John Misty", genre: "Baroque Singer-Songwriter", desc: "Singer-songwriter barroco-orquestal, teatral, ingenioso y mordaz, arreglos lujosos. I Love You, Honeybear.", origin: "rec", pick: true, p: 3, y: 2012, via: "Panic!" },
  { name: "Andrew Bird", genre: "Baroque Chamber Pop", desc: "Chamber pop barroco con violín, silbidos y arreglos intrincados; sofisticado y peculiar. Armchair Apocrypha.", origin: "rec", pick: true, p: 2, y: 1996, via: "Panic!" },
  { name: "Tori Amos", genre: "Baroque Piano Pop", desc: "El piano lleva la armonía completa sin banda debajo en buena parte de su obra, con compases que cambian dentro de la frase y una voz que salta de registro contra ese piano en vez de apoyarse en él. Little Earthquakes, Boys for Pele y From the Choirgirl Hotel son tres planteamientos distintos del mismo instrumento. Entrada: Boys for Pele.", origin: "rec", pick: true, female: true, p: 2, y: 1990, via: "Panic!" },
  { name: "Babasónicos", genre: "Alt Rock (AR)", desc: "Rock alternativo argentino ecléctico y sensual, de producción muy trabajada, que se reinventa: de la psicodelia de Trance Zomba y Dopádromo a Miami (1999), Jessico (2001) e Infame (2003), la cumbre, y Anoche y Mucho; lo último baja. Entrada: Jessico.", p: 2, origin: "rec", pick: true, y: 1991, via: "Panic!" },
  { name: "Fiona Apple", genre: "Art / Baroque Pop", desc: "Pop de piano barroco-jazzístico, intrincado, ecléctico y experimental, estructuras imprevisibles. 'Fetch the Bolt Cutters' es una obra maestra de la rareza. [Comodín]", origin: "rec", pick: true, female: true, p: 2, y: 1996, via: "Panic!", c: 3 },
  { name: "The Tiger Lillies", genre: "Dark Cabaret (UK)", desc: "Dark cabaret de tres personas: acordeón, contrabajo y percusión mínima bajo el falsete grotesco de Martyn Jacques, con temática siniestra y fraseo de cabaret de Weimar. Sin guitarra y sin batería de rock. Entrada: Shockheaded Peter.", origin: "rec", pick: true, p: 3, y: 1989, via: "Panic!" },
  { name: "Dir En Grey", genre: "Visual Kei / Experimental (JP)", desc: "Japoneses que empezaron en el visual kei y se convirtieron en metal extremo y progresivo: estructuras largas que pasan de la brutalidad a la balada, afinaciones graves y la voz de Kyo, que va del falsete al gutural con un rango casi sin par. Uroboros (2008) y Dum Spiro Spero (2011) son la cumbre, con Kisou, Vulgar, Arche y The Insulated World cerca; el debut, Gauze, y The Marrow of a Bone quedan por debajo. Entrada: Uroboros.", p: 2, origin: "rec", pick: true, y: 1997, via: "Panic!" },

  // ----- MUSE (2ª vuelta + internacionales) -----
  { name: "Twelve Foot Ninja", genre: "Eclectic Prog Metal (AU)", desc: "Prog metal australiano de eclecticismo desbocado: salta a funk, latin, reggae, jazz y djent dentro de una misma canción, con técnica y humor. Divertido y bien tocado, pero el salto de estilo es el recurso y las secciones duran poco: Silent Machine (2012), Outlier (2016) y Vengeance (2021). Entrada: Silent Machine.", p: 3, origin: "rec", pick: true, y: 2008, via: "Muse", c: 1 },
  { name: "Archive", genre: "Electronic / Prog Rock (UK)", desc: "Rock electrónico y prog de escala cinematográfica: temas largos que crecen por capas y arreglos orquestales reales, con la voz rotando entre varios cantantes de disco a disco. Entrada: Controlling Crowds.", origin: "rec", pick: true, p: 2, y: 1994, via: "Muse" },
  { name: "Zoé", genre: "Psych Alt Rock (MX)", desc: "Rock alternativo mexicano psicodélico y espacial, atmosférico y de producción cuidada. Memo Rex Commander y el Corazón Atómico de la Vía Láctea (2006) y Reptilectric (2008) son la cumbre. Entrada: Memo Rex Commander y el Corazón Atómico de la Vía Láctea.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Elbow", genre: "Orchestral Alt Rock (UK)", desc: "Alt rock orquestal de Manchester, sofisticado y emotivo, de arreglos muy cuidados y crescendos grandes, pero de escritura contenida. The Seldom Seen Kid (2008). Entrada: The Seldom Seen Kid.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Placebo", genre: "Alt Rock (UK)", desc: "Alt rock británico dramático y andrógino, de riffs directos y melancolía. Placebo (1996) y Without You I'm Nothing (1998) son lo mejor. Entrada: Without You I'm Nothing.", p: 3, origin: "rec", pick: true, y: 1994, via: "Muse" },
  { name: "Amplifier", genre: "Space / Prog Rock (UK)", desc: "Space/prog rock denso y riffero, hipnótico y pesado. Para el lado Origin of Symmetry. The Octopus.", origin: "rec", pick: true, p: 3, y: 1999, via: "Muse" },
  { name: "VUUR", genre: "Prog Metal (NL)", desc: "Prog metal pesado y dramático construido alrededor de la voz de Anneke van Giersbergen. Entrada: In This Moment We Are Free – Cities.", p: 3, origin: "rec", pick: true, female: true, y: 2016, via: "Muse" },
  { name: "65daysofstatic", genre: "Post-Rock / Electronic (UK)", desc: "Post-rock con electrónica integrada, math rock e intensidad, construcciones que estallan. Electrónica al servicio de la música. The Fall of Math.", origin: "rec", pick: true, p: 2, y: 2001, via: "Muse" },
  { name: "Stream of Passion", genre: "Prog Metal (MX/NL)", desc: "Prog metal melódico y atmosférico con Marcela Bovio, mexicana de formación clásica: dramático y elegante, pero dentro del molde del metal gótico sinfónico. Entrada: Embrace the Storm.", p: 3, origin: "rec", pick: true, female: true, y: 2005, via: "Muse" },

  // ----- ICE NINE KILLS (2ª vuelta + internacionales) -----
  { name: "Bilmuri", genre: "Eclectic Metalcore", desc: "Metalcore cruzado con country, saxo, pop y electrónica, pero por debajo del disfraz la escritura es de canción con estribillo: bien hecha y muy divertida, sin ambición instrumental. Entrada: Goners.", origin: "rec", p: 3, y: 2016, c: 2 },
  { name: "Lord of the Lost", genre: "Gothic Industrial Metal (DE)", desc: "Saltan entre gotico, industrial, sinfonico, glam y pop oscuro, pero ese salto es de estetica y de vestuario, no de estructura: la escritura por debajo sigue siendo la misma cancion de rock con gancho. La critica de Blood and Glitter lo dijo sin rodeos, que era una version abreviada de Scorpions y Rammstein sin originalidad propia. Quedaron ultimos en Eurovision 2023. Teatralidad alta, ambicion instrumental baja.", origin: "rec", p: 3, y: 2007, c: 2 },
  { name: "King Diamond", genre: "Theatrical Heavy Metal (DK)", desc: "Andy LaRocque escribe guitarras armonizadas con giros neoclásicos y las canciones encadenan varias partes sin repetirlas. Pero el peso de la banda está en la narración y la puesta en escena más que en la escritura instrumental, y Mercyful Fate hace lo mismo instrumentalmente y mejor. Abigail (1987) es la cumbre y de Fatal Portrait (1986) a The Eye (1990) no bajan; lo posterior es más irregular. Su disco nuevo, Saint Lucifer's Hospital 1920, se espera para 2027. Entrada: Abigail.", origin: "rec", p: 2, y: 1985, c: 2 },
  { name: "Lorna Shore", genre: "Symphonic Deathcore", desc: "Deathcore sinfónico de escala cinematográfica: orquestación con coro y cuerda escrita como capa protagonista, no de fondo, sobre blast beats constantes, y Will Ramos alternando gutural profundo, agudo desgarrado y ese trino gutural que lo hizo famoso. Grandilocuente hasta el exceso, y a propósito. Entrada: Pain Remains.", origin: "rec", pick: true, p: 2, y: 2009, via: "Ice Nine Kills" },
  { name: "Deathstars", genre: "Industrial Gothic Metal (SE)", desc: "Metal industrial gótico teatral, oscuro y con groove, estética de glam siniestro. Termination Bliss.", origin: "rec", pick: true, p: 3, y: 2000, via: "Ice Nine Kills" },
  { name: "Once Human", genre: "Melodic Death / Metalcore", desc: "Melodeath/metalcore con Lauren Hart, agresivo y melódico con voz versátil (limpio + gutural). Scar Weaver.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Ice Nine Kills" },
  { name: "Mercyful Fate", genre: "Theatrical Heavy Metal (DK)", desc: "Hank Shermann y Michael Denner escriben temas de siete y ocho minutos encadenando cuatro o cinco secciones distintas que no vuelven, con guitarras armonizadas en intervalos incómodos y cambios de tempo dentro de la frase, cuando en 1984 el resto del heavy hacía estrofa y estribillo. Melissa (1983) y Don't Break the Oath (1984) son la cumbre, y a la vuelta In the Shadows (1993) y Time (1994) están a su altura; Into the Unknown, Dead Again y 9 (1999) bajan un poco. Preparan disco nuevo, el primero desde 1999. Entrada: Don't Break the Oath.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Fearless Vampire Killers", genre: "Horror Glam Punk (UK)", desc: "Glam punk/rock de terror con concepto narrativo (vampiros, una saga), teatral y melódico. Espíritu conceptual-horror de INK.", origin: "rec", pick: true, p: 3, y: 2008, via: "Ice Nine Kills" },
  { name: "Lordi", genre: "Hard Rock / Horror (FI)", desc: "Hard rock de monstruos con disfraces y teatralidad de terror serie B. Pegadizo y camp (ganaron Eurovisión).", origin: "rec", pick: true, p: 3, y: 1992, via: "Ice Nine Kills" },

  // ----- IN FLAMES (2ª vuelta + internacionales) -----
  { name: "Myrath", genre: "Oriental Prog Metal (TN)", desc: "Power y prog tunecino con instrumentación y escalas de Oriente Medio integradas en los arreglos, cuerdas, percusión y los melismas de Zaher Zorgati, sobre una base de power metal melódico. Suena exótico, pero la estructura es de estribillo grande y el nivel es parejo de Legacy (2016) y Shehili (2019) a Karma (2024). Entrada: Legacy.", p: 3, origin: "rec", pick: true, y: 2006, via: "In Flames", c: 2 },
  { name: "Orbit Culture", genre: "Melodic Death / Groove (SE)", desc: "Suecos de melodeath moderno cruzado con el groove de Gojira: riffs muy pesados y rítmicos, atmósfera y voces limpias. Nija (2020) es la cumbre; Descent (2023) y Death Above Life (octubre de 2025). Entrada: Nija.", origin: "rec", pick: true, p: 2, y: 2013, via: "In Flames" },
  { name: "Wolfheart", genre: "Melodic Death (FI)", desc: "Melodeath atmosférico 'winter metal' de Tuomas Saukkonen: épico, frío y con melodías preciosas. Wolves of Karelia.", origin: "rec", pick: true, p: 3, y: 2013, via: "In Flames" },
  { name: "Dimension Zero", genre: "Melodic Death (SE)", desc: "Proyecto de Jesper Strömblad (cerebro melódico del In Flames clásico): melodeath agresivo y veloz, puro Gotemburgo. Para el lado Jester Race/Colony. Silent Night Fever.", origin: "rec", pick: true, p: 3, y: 1995, via: "In Flames" },
  { name: "Norther", genre: "Melodic Death (FI)", desc: "Melodeath con teclados y shred neoclásico, melódico y enérgico, veta Children of Bodom. Mirror of Madness.", origin: "rec", pick: true, p: 3, y: 1996, via: "In Flames" },
  { name: "Frantic Amber", genre: "Melodic Death (SE)", desc: "Melodeath de Gotemburgo liderado por mujeres (Elizabeth Andrews), agresivo y melódico con buenas guitarras. Bellatrix.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "In Flames" },
  { name: "Mercenary", genre: "Melodic Death / Power (DK)", desc: "Daneses de melodeath cruzado con power y prog: temas largos con mucha melodía vocal limpia y aguda, teclados y guitarras que cambian de sección. De Everblack (2002) a 11 Dreams (2004), la cumbre, The Hours That Remain y Architect of Lies (2008); desde Metamorphosis (2011) bajan. Entrada: 11 Dreams.", origin: "rec", pick: true, p: 2, y: 1991, via: "In Flames" },

  // ----- SIAMES (cierre del repaso + barrido latino/atmosférico) -----
  { name: "Usted Señálemelo", genre: "Alt Rock (AR)", desc: "Trío argentino de rock alternativo técnico y atmosférico, con guitarras en capas, sintetizadores y cambios de compás, que cambia mucho de un disco a otro.", p: 2, origin: "rec", pick: true, y: 2012, via: "Siames", c: 1 },
  { name: "Beach House", genre: "Dream Pop", desc: "Dream pop de Baltimore: capas de órgano y guitarras con reverb bajo la voz de Victoria Legrand, lujoso y melancólico pero de escritura estática. Teen Dream (2010) y Bloom (2012). Entrada: Teen Dream.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Siames" },
  { name: "Hello Seahorse!", genre: "Alt Rock (MX)", desc: "Alt rock mexicano con Lo Blondo a la voz, atmosférico y electrónico, de texturas interesantes. Entrada: Bestia.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Siames" },
  { name: "DIIV", genre: "Dream Pop / Shoegaze", desc: "Dream pop y shoegaze de Brooklyn con guitarras entrelazadas e hipnóticas. Oshin (2012), Deceiver (2019) y Frog in Boiling Water (2024). Entrada: Deceiver.", p: 3, origin: "rec", pick: true, y: 2011, via: "Siames" },
  { name: "Bándalos Chinos", genre: "Indie Pop/Rock (AR)", desc: "Indie pop y rock argentino sofisticado y de groove, de producción cuidada. Entrada: Bach.", origin: "rec", pick: true, p: 3, y: 2009, via: "Siames" },
  { name: "Rhye", genre: "Atmospheric Soul / Indie", desc: "Soul atmosférico y sensual, sofisticado y minimalista pero con arreglos elegantes. Para el lado nocturno. Woman, Blood.", origin: "rec", pick: true, p: 3, y: 2012, via: "Siames" },
  { name: "Wild Beasts", genre: "Art Rock (UK)", desc: "Art rock con falsete distintivo, guitarras angulares e intrincadas y atmósfera sensual-oscura. Smother, Two Dancers.", origin: "rec", pick: true, p: 2, y: 2004, via: "Siames" },
  { name: "Mitski", genre: "Indie Rock", desc: "Indie rock que va de lo íntimo a lo explosivo, con arreglos creativos: Puberty 2 (2016) y Be the Cowboy (2018). Entrada: Be the Cowboy.", p: 3, origin: "rec", pick: true, female: true, y: 2012, via: "Siames" },
  { name: "Diamante Eléctrico", genre: "Alt / Blues Rock (CO)", desc: "Colombianos: alt y blues rock con groove, riffs sucios y atmósfera, con la voz rasgada de Juan Galeano y una producción que deja mucho aire. Ganadores de varios Latin Grammy. Entrada: Buitres.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "Siames" }
];

// ===========================================================================
// === TANDA 4 (junio 2026) — Iron Maiden + Dethklok + Death metal (anti-CC)
// + 1ª vuelta de Siames que faltaba. Campos nuevos: p (prioridad 1-4),
// y (año formación/estreno), via (rama de origen de la recomendación).
// ===========================================================================
const TANDA_4 = [
  // ----- IRON MAIDEN (bajo líder / épico-narrativo / prog) -----
  { name: "Thin Lizzy", genre: "Hard Rock (IE)", y: 1969, p: 1, via: "Iron Maiden", desc: "Phil Lynott canta y toca el bajo a la vez, con líneas melódicas que se mueven contra la voz en vez de sostenerla, y las dos guitarras tocan armonizadas en terceras como una sola voz doble. Jailbreak, Johnny the Fox y Black Rose sostienen esa escritura. Entrada: Jailbreak.", origin: "rec", pick: true },
  { name: "Voivod", genre: "Prog / Avant Metal (CA)", y: 1982, p: 2, via: "Iron Maiden", desc: "Acordes disonantes abiertos de Piggy sobre la batería de Away, que mete cambios de compás y fraseo de jazz dentro del thrash, y un bajo que va por su cuenta en vez de doblar el riff. El mapa es desigual: Killing Technology (1987), Dimension Hatröss y Nothingface son un metal espacial sin par, y Angel Rat y The Outer Limits lo llevan a un prog más limpio; de Negatron (1995) a Infini (2009) la escritura se vuelve más directa y plana, y es lo más flojo. Con Chewy a la guitarra recuperan el nivel en Target Earth (2013), The Wake (2018) y Synchro Anarchy (2022). Entrada: Nothingface.", origin: "rec", pick: true, c: 3 },
  { name: "Atheist", genre: "Tech Death / Jazz Fusion", y: 1987, p: 1, via: "Iron Maiden", desc: "[Comodín] Death técnico cruzado con fusión jazz, con el bajo fretless como co-líder, Roger Patterson en Piece of Time y Tony Choy en Unquestionable Presence tras la muerte de Patterson, y Steve Flynn a la batería cambiando de compás sin parar. Piece of Time (1990), Unquestionable Presence (1991) y Elements (1993), con percusión latina, son la cumbre; Jupiter (2010), la vuelta, baja algo. Entrada: Unquestionable Presence.", origin: "rec", pick: true, c: 3 },
  { name: "Primus", genre: "Funk Metal / Experimental", y: 1984, p: 2, via: "Iron Maiden", desc: "[Comodín] Les Claypool toca el bajo como instrumento líder, con slap, tapping y armónicos llevando el tema entero mientras la guitarra de Larry LaLonde hace de textura y la batería va contra el bajo en vez de con él. Frizzle Fry (1990), Sailing the Seas of Cheese y Tales from the Punchbowl son la cumbre y The Desaturating Seven (2017) está cerca; Pork Soda, el Brown Album y Antipop bajan, y el disco de Willy Wonka es de versiones. Tim Alexander dejó la batería a finales de 2024 y desde febrero de 2025 la toca John Hoffman. Entrada: Sailing the Seas of Cheese.", origin: "rec", pick: true, c: 3 },
  { name: "Diamond Head", genre: "NWOBHM (UK)", y: 1976, p: 2, via: "Iron Maiden", desc: "NWOBHM ambicioso y de riff: Lightning to the Nations (1980), con temas largos que cambian de sección, es media base del thrash, y Metallica versionó cuatro de sus canciones. Lo que vino después, de Borrowed Time a la vuelta, es irregular. Entrada: Lightning to the Nations.", origin: "rec", pick: true },
  { name: "Satan", genre: "NWOBHM (UK)", y: 1980, p: 1, via: "Iron Maiden", desc: "NWOBHM técnico: Russ Tippins y Steve Ramsey escriben riffs muy enrevesados y dos guitarras que se reparten melodía y contramelodía, con cambios de sección continuos y una base rítmica que no se limita a galopar. Court in the Act (1983) es de los grandes discos del heavy británico, y lo raro es que la vuelta está a su altura: Life Sentence (2013), Atom by Atom (2015), Cruel Magic (2018), Earth Infernal (2022) y Songs in Crimson (2024), sin un disco flojo. Entrada: Court in the Act, luego Life Sentence.", origin: "rec", pick: true },
  { name: "Cirith Ungol", genre: "Epic Heavy / Doom", y: 1972, p: 3, via: "Iron Maiden", desc: "Heavy y doom épico de culto de California, con la voz rasgada y singular de Tim Baker. King of the Dead (1984) y One Foot in Hell, y la vuelta con Forever Black (2020), aclamada. Entrada: King of the Dead.", origin: "rec", pick: true },
  { name: "Slough Feg", genre: "Celtic Heavy Metal", y: 1990, p: 2, via: "Iron Maiden", desc: "Heavy metal de San Francisco con las guitarras gemelas de Thin Lizzy, escalas y aires del folk celta y la época de Di'Anno en Iron Maiden: temas con muchas secciones y galope, cantados con voz de narrador. Muy parejos de Twilight of the Idols (1998) a Down Among the Deadmen (2000), Traveller (2003), un disco conceptual de ciencia ficción, y Hardworlder (2007). Entrada: Traveller.", origin: "rec", pick: true },
  { name: "Atlantean Kodex", genre: "Epic Heavy Metal (DE)", y: 2005, p: 2, via: "Iron Maiden", desc: "Epic metal alemán monumental y atmosférico: temas largos, lentos y narrativos, con guitarras gemelas y coros. The Golden Bough (2010), The White Goddess (2013), la cumbre, y The Course of Empire (2019). Entrada: The White Goddess.", origin: "rec", pick: true },
  { name: "Visigoth", genre: "Epic Heavy Metal", y: 2010, p: 2, via: "Iron Maiden", desc: "Epic heavy metal de Salt Lake City, melódico, épico y con pegada: The Revenant King (2015) y Conqueror's Oath (2018). Entrada: Conqueror's Oath.", origin: "rec", pick: true },
  { name: "Eternal Champion", genre: "Epic Heavy Metal", y: 2012, p: 2, via: "Iron Maiden", desc: "Epic heavy metal de Texas, de espada y brujería, con riffs muy bien escritos y la voz de Jason Tarpey: The Armor of Ire (2016) y Ravening Iron (2020). En marzo de 2026 sacaron el EP Friend of War y anunciaron su tercer disco para este año. Entrada: Ravening Iron.", origin: "rec", pick: true },
  { name: "Nevermore", genre: "Prog / Power Metal", y: 1992, p: 2, via: "Iron Maiden", desc: "Metal progresivo y oscuro de Seattle: Jeff Loomis escribe riffs de siete cuerdas con disonancia y solos técnicos, y Van Williams toca con dinámica real bajo la voz dramática de Warrel Dane. Dead Heart in a Dead World (2000) y This Godless Endeavor (2005) son lo más completo. Warrel Dane murió en 2017. Entrada: Dead Heart in a Dead World.", origin: "rec", pick: true },
  { name: "Crimson Glory", genre: "Prog Metal", y: 1982, p: 2, via: "Iron Maiden", desc: "Metal progresivo de los ochenta construido sobre la voz aguda de Midnight, que canta como un instrumento solista por encima de guitarras gemelas armonizadas y estructuras de varias partes. Su obra fuerte son dos discos, Crimson Glory (1986) y Transcendence (1988); lo posterior pierde ese nivel. Entrada: Transcendence.", origin: "rec", pick: true },
  { name: "Khemmis", genre: "Doom / Heavy Metal", y: 2012, p: 3, via: "Iron Maiden", desc: "Doom y heavy melódico de Denver con guitarras gemelas y mucha emoción, muy parejo pero dentro del molde. Hunted (2016). Entrada: Hunted.", origin: "rec", pick: true },
  { name: "Unto Others", genre: "Gothic Heavy Metal", y: 2017, p: 2, via: "Iron Maiden", desc: "Heavy melódico con tinte gótico y post-punk que evoluciona disco a disco, antes llamados Idle Hands: Mana (2019, como Idle Hands), Strength (2021) y Never, Neverland (2024). Entrada: Strength.", origin: "rec", pick: true },
  { name: "Sadus", genre: "Technical Thrash", y: 1984, p: 2, via: "Iron Maiden", desc: "Thrash con el bajo fretless de Steve DiGiorgio al frente, melódico y vertiginoso bajo riffs muy rápidos. Illusions (1988), Swallowed in Black (1990) y A Vision of Misery (1992), los tres a gran nivel; lo de 1997 y 2006 baja, y The Shadow Inside (2023) vuelve bien. Entrada: Swallowed in Black.", origin: "rec", pick: true },
  { name: "Smoulder", genre: "Epic Doom Metal (CA)", y: 2013, p: 3, via: "Iron Maiden", desc: "Doom y heavy épico canadiense de espada y brujería, con Sarah Ann al frente, grandilocuente y dentro del molde. Entrada: Times of Obscene Evil and Wild Daring.", origin: "rec", pick: true, female: true },
  { name: "In Solitude", genre: "Heavy / Gothic Metal (SE)", y: 2002, p: 2, via: "Iron Maiden", desc: "De culto a Mercyful Fate a un heavy oscuro con post-punk gótico: In Solitude (2008), The World. The Flesh. The Devil (2011) y Sister (2013), cada uno distinto del anterior. Se separaron en 2015. Entrada: Sister.", origin: "rec", pick: true, c: 1 },

  // ----- DETHKLOK (melodeath técnico-melódico / batería monstruosa) -----
  { name: "Brendon Small's Galaktikon", genre: "Melodic Death / Prog", y: 2012, p: 2, via: "Dethklok", desc: "El mismo cerebro (Brendon Small) + Gene Hoglan, como ópera espacial: más melódico y progresivo, sin la caricatura. 'Dethklok desatado'. Galaktikon I y II.", origin: "rec", pick: true },
  { name: "The Black Dahlia Murder", genre: "Melodic Death", y: 2001, p: 2, via: "Dethklok", desc: "Melodeath de Michigan rápido y técnico, con riffs de trémolo melódicos, blast beats y la voz de Trevor Strnad alternando grave y agudo. Muy parejos de Nocturnal (2007) a Verminous (2020); Strnad murió en 2022, y Servitude (2024), con Brian Eschbach a la voz, mantiene el nivel. Entrada: Nocturnal.", origin: "rec", pick: true },
  { name: "Inferi", genre: "Technical Melodic Death", y: 2006, p: 2, via: "Dethklok", desc: "Tech death melódico de Nashville, épico y teatral, con shred neoclásico a dos guitarras y teclados orquestales. The Path of Apotheosis (2014) es la cumbre; Revenant (2018), Vile Genesis (2021) y Heaven Wept (2026) siguen la línea. Entrada: The Path of Apotheosis.", origin: "rec", pick: true },
  { name: "Arsis", genre: "Technical Melodic Death", y: 2000, p: 2, via: "Dethklok", desc: "Death melódico y técnico con leads neoclásicos vertiginosos, y la escritura de guitarra de James Malone en el debut es densa y melódica a la vez. Pero la carrera no lo sostiene: A Celebration of Guilt (2004) tuvo elogio casi unánime y lo que vino después se recibió bastante peor, con Starve for the Devil descrito como más simple que lo anterior. Entra por A Celebration of Guilt.", origin: "rec", pick: true },
  { name: "Aenimus", genre: "Prog / Tech Death", y: 2009, p: 2, via: "Dethklok", desc: "Death técnico y progresivo sinfónico y conceptual de California, melódico y muy técnico. Entrada: Dreamcatcher.", origin: "rec", pick: true },
  { name: "Equipoise", genre: "Neoclassical Tech Death", y: 2016, p: 2, via: "Dethklok", desc: "Supergrupo de death técnico neoclásico con guitarra de raíz flamenca y shred melódico. Demiurgus (2019). Entrada: Demiurgus.", origin: "rec", pick: true },
  { name: "Gloryhammer", genre: "Symphonic Power Metal", y: 2010, p: 3, via: "Dethklok", desc: "Power metal cómico-épico de fantasía (magos, batallas cósmicas) pero técnicamente impecable. El paralelo 'comedia + música en serio'. Return to the Kingdom of Fife (2023).", origin: "rec", pick: true },
  { name: "Powerglove", genre: "Instrumental / VGM Metal", y: 2005, p: 3, via: "Dethklok", desc: "Metal instrumental de música de videojuegos, técnico y juguetón.", origin: "rec", pick: true },
  { name: "Aether Realm", genre: "Melodic Death / Folk", y: 2011, p: 2, via: "Dethklok", desc: "Melodeath y folk de Carolina del Norte con guitarras muy técnicas y un rango real, de lo épico y serio a lo cómico, sin perder identidad. Tarot (2017) y Redneck Vikings from Hell (2020); Season of Bloodshed es de 2026. Entrada: Tarot.", origin: "rec", pick: true },

  // ----- DEATH METAL (el anti-Cannibal Corpse: claridad, sustancia, evolución) -----
  { name: "Blood Incantation", genre: "Progressive Death Metal", y: 2011, p: 1, via: "Death metal", desc: "Piezas de veinte minutos construidas por secciones que no vuelven, con la producción abierta a propósito para que se distinga cada capa. Starspawn (2016) y Hidden History of the Human Race (2019) son death progresivo de primer nivel, Timewave Zero (2022) es un disco ambiental de sintetizadores, y Absolute Elsewhere (2024) integra el sintetizador analógico como instrumento estructural, con la crítica muy dividida entre la euforia y el rechazo. Entrada: Hidden History of the Human Race.", origin: "rec", pick: true, c: 1 },
  { name: "Bolt Thrower", genre: "Death Metal (UK)", desc: "Riffs a medio tiempo muy graves sobre doble bombo sencillo, melodías de guitarra cortas y efectivas, y un peso enorme sostenido sin cambiar de marcha. Hacían una sola cosa a propósito y la hacían muy bien, pero de complejidad instrumental hay poca. Entra por Those Once Loyal.", origin: "rec", p: 3, y: 1986, c: 2 },
  { name: "Pestilence", genre: "Death / Jazz Fusion (NL)", y: 1986, p: 2, via: "Death metal", desc: "Evolucionaron de thrash-death a death con fusión jazz: en Spheres (1993) meten sintetizador de guitarra y bajo fretless, con armonía que se sale del género por completo. Malleus Maleficarum (1988), Consuming Impulse, Testimony of the Ancients y Spheres son cuatro discos de primer nivel, cada uno distinto; la vuelta desde 2009 es muy floja. Entrada: Testimony of the Ancients, luego Spheres.", origin: "rec", pick: true, c: 1 },
  { name: "Entombed", genre: "Death / Death'n'Roll (SE)", y: 1987, p: 2, via: "Death metal", desc: "Inventaron el sonido de guitarra sierra del death sueco en Left Hand Path (1990) y Clandestine, y luego viraron al death'n'roll en Wolverine Blues (1993), un cambio de género real. Lo posterior es desigual, con buenos discos como Uprising y Morning Star. Entrada: Left Hand Path.", origin: "rec", pick: true, c: 1 },
  { name: "Tomb Mold", genre: "Progressive Death (CA)", y: 2016, p: 2, via: "Death metal", desc: "De Toronto: pasaron del death de la vieja escuela de Primordial Malignity (2017) y Manor of Infinite Forms a un death progresivo, atmosférico y con aire de jazz en Planetary Clairvoyance (2019) y The Enduring Spirit (2023). Entrada: The Enduring Spirit.", origin: "rec", pick: true, c: 1 },
  { name: "Horrendous", genre: "Progressive Death Metal", y: 2009, p: 2, via: "Death metal", desc: "Death de Filadelfia con melodía, progresión y composición excelente, en una producción limpia y cálida; cada disco crece. Ecdysis (2014), Anareta (2015), Idol (2018) y Ontological Mysterium (2023). Entrada: Anareta.", origin: "rec", pick: true },
  { name: "Sweven (Morbus Chron)", genre: "Progressive Death (SE)", y: 2007, p: 2, via: "Death metal", desc: "Morbus Chron pasó del death de la vieja escuela de Sleepers in the Rift (2011) al death psicodélico y progresivo de Sweven (2014), atmosférico y bello, y su cantante y guitarrista Robert Andersson siguió esa línea con el proyecto Sweven en The Eternal Resonance (2020). Entrada: Sweven.", origin: "rec", pick: true, c: 1 },
  { name: "Autopsy", genre: "Death / Doom Metal", y: 1987, p: 2, via: "Death metal", desc: "Death y doom sucios con muchísimo carácter: tempos que pasan del arrastre al galope, riffs raros y memorables y Chris Reifert tocando la batería y cantando. Severed Survival (1989) y Mental Funeral (1991) son la cumbre, y la vuelta desde Macabre Eternal (2011) mantiene un nivel sólido. Entrada: Mental Funeral.", origin: "rec", pick: true },
  { name: "Asphyx", genre: "Death / Doom (NL)", y: 1987, p: 2, via: "Death metal", desc: "Death y doom holandés demoledor, de riffs memorables y la voz inconfundible de Martin van Drunen, con la pesadez al servicio de la identidad. The Rack (1991) y Last One on Earth son la cumbre, y Deathhammer (2012) y Necroceros (2021) mantienen el nivel. Entrada: The Rack.", origin: "rec", pick: true },
  { name: "Defeated Sanity", genre: "Brutal Tech Death (DE)", y: 1994, p: 2, via: "Death metal", desc: "Brutal death alemán con armonía de jazz y fusión y una batería espectacular, la de su fundador Lille Gruber, que cambia de figura constantemente bajo riffs de subdivisión retorcida. Passages into Deformity (2013), Disposal of the Dead // Dharmata (2016), la mitad de ella de death técnico de la vieja escuela, The Sanguinary Impetus (2020) y Chronicles of Lunacy (2024) son la cumbre. Entrada: Passages into Deformity.", origin: "rec", pick: true },
  { name: "Artificial Brain", genre: "Dissonant Tech Death", y: 2011, p: 2, via: "Death metal", desc: "Death técnico disonante y cósmico de Nueva York: riffs de acordes abiertos y disonantes que se estiran como ciencia ficción, con la batería cambiando de figura sin parar. Labyrinth Constellation (2014), Infrared Horizon y Artificial Brain (2022); Antillia sale en noviembre de 2026. Entrada: Labyrinth Constellation.", origin: "rec", pick: true },
  { name: "Demilich", genre: "Avant Death Metal (FI)", y: 1990, p: 2, via: "Death metal", desc: "[Comodín] Death finlandés de otro planeta: una voz gutural tan grave que parece un efecto, riffs de guitarra con cambios de compás y figuras que nadie más tocaba en 1993, y títulos kilométricos. Un solo disco, Nespithe (1993), y nada suena igual. Entrada: Nespithe.", origin: "rec", pick: true, c: 3 },
  { name: "StarGazer", genre: "Avant Death / Black (AU)", y: 1997, p: 2, via: "Death metal", desc: "[Comodín] Death y black avant australiano donde el bajo de Damon Good lleva la voz principal con fraseo jazzístico y sonido limpio, no distorsionado, sobre estructuras que no se repiten y batería de aire progresivo. The Scream That Tore the Sky (2005), A Great Work of Ages (2010) y Psychic Secretions (2014), muy parejos. Entrada: A Great Work of Ages.", origin: "rec", pick: true, c: 3 },

  // ----- SIAMES 1ª vuelta (atmosférico/moody, electrónica bien integrada) -----
  { name: "M83", genre: "Electronic / Shoegaze (FR)", y: 2001, p: 2, via: "Siames", desc: "Rock atmosférico/shoegaze que mutó a lo anthemic-electrónico cinematográfico. Electrónica al servicio de la emoción, nunca EDM gratuito. Hurry Up, We're Dreaming.", origin: "rec", pick: true, c: 1 },
  { name: "The Neighbourhood", genre: "Alt Rock / Moody", y: 2011, p: 3, via: "Siames", desc: "Alt rock oscuro y atmosférico de California con toques de R&B y electrónica, de canciones sencillas y producción muy cuidada. I Love You. (2013) y Wiped Out! (2015). Entrada: Wiped Out!", origin: "rec", pick: true },
  { name: "Half Moon Run", genre: "Indie Rock (CA)", y: 2010, p: 2, via: "Siames", desc: "Indie canadiense de arreglos intrincados: armonías vocales a tres voces, percusiones repartidas entre varios miembros y guitarras que se cruzan en ritmos desplazados. Dark Eyes (2012) y Sun Leads Me On (2015) son lo mejor. Entrada: Dark Eyes.", origin: "rec", pick: true },
  { name: "Daughter", genre: "Indie / Atmospheric (UK)", y: 2010, p: 3, via: "Siames", desc: "Indie atmosférico británico: guitarras con reverb que se construyen en crescendos y la voz frágil de Elena Tonra. Bonito y cinematográfico, pero de escritura sencilla. If You Leave (2013), Not to Disappear y Stereo Mind Game (2023). Entrada: If You Leave.", origin: "rec", pick: true, female: true },
  { name: "London Grammar", genre: "Atmospheric Pop (UK)", y: 2012, p: 2, via: "Siames", desc: "Producción minimalista de verdad: dejan huecos enormes entre los elementos, con guitarra tratada, sintetizador de una sola nota sostenida y percusión mínima, para que la voz de contralto de Hannah Reid ocupe todo el espacio. Es atmósfera y contención, no complejidad. Entrada: If You Wait.", origin: "rec", pick: true, female: true },
  { name: "Men I Trust", genre: "Dream Pop / Indie (CA)", y: 2014, p: 2, via: "Siames", desc: "Dream pop de Montreal con acordes de jazz, el bajo de Jessy Caron llevando grooves melódicos y una atmósfera nocturna: más interesante instrumentalmente de lo que parece por la calma. Oncle Jazz (2019), Untourable Album y la pareja Equus Asinus y Equus Caballus (2025). Entrada: Oncle Jazz.", origin: "rec", pick: true, female: true },
  { name: "Crumb", genre: "Psych Indie / Jazz", y: 2016, p: 3, via: "Siames", desc: "Indie psicodélico de Brooklyn con acordes de jazz, líneas de bajo que se mueven solas y una atmósfera densa y onírica. Jinx (2019), Ice Melt (2021) y AMAMA (2024). Entrada: Jinx.", origin: "rec", pick: true, female: true },
  { name: "The Marías", genre: "Dream Pop / Psych Soul", y: 2016, p: 3, via: "Siames", desc: "Dream pop y soul psicodélico de Los Ángeles, bilingüe, con producción muy cuidada y arreglos elegantes pero sencillos. CINEMA (2021) y Submarine (2024). Entrada: Submarine.", origin: "rec", pick: true, female: true },
  { name: "Khruangbin", genre: "Psych Funk / Instrumental", y: 2010, p: 3, via: "Siames", desc: "Trío de funk psicodélico casi instrumental: el bajo de Laura Lee lleva el groove, la guitarra de Mark Speer toma escalas tailandesas, surf y dub, y la batería es mínima a propósito. Atmosférico y elegante, pero sencillo por dentro. Con Todo el Mundo (2018) y A La Sala (2024). Entrada: Con Todo el Mundo.", origin: "rec", pick: true },
  { name: "Sir Sly", genre: "Alt / Electronic Rock", y: 2012, p: 3, via: "Siames", desc: "Alt rock electrónico oscuro y melancólico, con la voz muy procesada y bases de sintetizador amplias. Formato canción de radio. Entrada: Don't You Worry, Honey.", origin: "rec", pick: true },
  { name: "Joywave", genre: "Indie Electronic Rock", y: 2010, p: 3, via: "Siames", desc: "Indie electrónico y alt rock de Rochester, atmosférico y sarcástico. Entrada: Content.", origin: "rec", pick: true },
  { name: "Metronomy", genre: "Indie Electronic (UK)", y: 1999, p: 3, via: "Siames", desc: "Indie electrónico británico que cambia de piel entre discos, con groove raro y producción ingeniosa, dentro de la canción pop. The English Riviera (2011). Entrada: The English Riviera.", origin: "rec", pick: true, c: 1 },
  { name: "El Mató a un Policía Motorizado", genre: "Indie / Noise Pop (AR)", y: 2003, p: 3, via: "Siames", desc: "Indie y noise pop argentino de La Plata, atmosférico y melódico, de guitarras con fuzz en capas y canciones sencillas. La síntesis O'Konor (2017). Entrada: La síntesis O'Konor.", origin: "rec", pick: true }
];

