const REPASO_2026 = [
  // ----- RAÍCES PERDIDAS / ART ROCK -----
  { name: "Björk", genre: "Art Pop / Experimental", y: 1993, p: 2, c: 1, female: true, via: "Art rock", desc: "Cada disco monta un sistema instrumental distinto y compone dentro de él: Homogenic son cuerdas contra beats rotos, Vespertine microbeats y arpa, Medúlla casi solo voces, Utopia un banco de flautas, y la voz va escrita como línea melódica compleja, no como recitado encima. De Debut (1993) a Post, Homogenic y Vespertine (2001) es una racha impecable; después alterna aciertos como Vulnicura con discos más dispersos como Volta o Fossora. Entrada: Homogenic.", origin: "rec", pick: true },
  { name: "Talking Heads", genre: "Art Rock / Post-Punk", y: 1975, p: 1, c: 1, via: "Art rock", desc: "De post-punk esquelético a orquesta polirrítmica en cuatro años. Remain in Light está construido al revés de lo normal: cada músico toca una sola figura corta que se repite sin variar, y la pieza surge de superponerlas hasta que se desfasan entre sí, con Chris Frantz y Tina Weymouth sosteniendo un groove afrobeat inalterable mientras Adrian Belew mete guitarra tratada por encima. Byrne canta como si declamara. Entrada: Remain in Light.", origin: "rec", pick: true },
  { name: "Peter Gabriel", genre: "Art Rock / Prog", y: 1977, p: 2, c: 1, via: "Art rock", desc: "En solitario fue mucho más raro que en Genesis: en su tercer disco prohibió los platillos a Phil Collins y de ahí salió el sonido de batería con compuerta que marcó los ochenta, y el cuarto se construye sobre el Fairlight y polirritmias de percusión africana. So y Us lo llevaron al pop sin perder esa base rítmica. Entrada: III (Melt).", origin: "rec", pick: true },
  { name: "Tom Waits", genre: "Experimental / Art Rock", y: 1973, p: 2, c: 1, via: "Art rock", desc: "De crooner de jazz a una percusión de chatarrería: desde Swordfishtrombones (1983) graba con marimbas, objetos metálicos y bombos golpeados, sobre la guitarra angulosa de Marc Ribot y metales desafinados a propósito, con su voz rota como centro teatral. Swordfishtrombones, Rain Dogs, Bone Machine (1992), Mule Variations y Blood Money (2002) son la etapa fuerte. Entrada: Rain Dogs.", origin: "rec", pick: true },
  { name: "Deep Purple", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Raíces perdidas", desc: "Jon Lord toca el órgano Hammond a través de amplificadores Marshall y con distorsión, así que compite con la guitarra en volumen y timbre en lugar de acompañar, y él y Blackmore se turnan solos largos improvisados en directo como si fuera un duelo de jazz. Ian Paice a la batería toca con mano izquierda rapidísima y swing, no a golpe recto. Entrada: Machine Head, y Made in Japan para los duelos.", origin: "rec", pick: true },
  { name: "Portishead", genre: "Trip-Hop / Experimental", y: 1991, p: 2, c: 1, female: true, via: "Art rock", desc: "Trip-hop de Bristol con instrumentación de verdad: scratches y samples de bandas sonoras sobre batería tocada y guitarras de spaghetti western, bajo la voz de Beth Gibbons. Dummy (1994) y Portishead (1997) fijan el género, y once años después Third (2008) lo rompe con krautrock motorik y sintetizadores abrasivos. Entrada: Third, luego Dummy.", origin: "rec", pick: true },
  { name: "Brian Eno", genre: "Ambient / Art Rock", desc: "En los discos de canción como Another Green World alterna piezas cortas de rock angular con miniaturas instrumentales tratadas hasta que el instrumento original no se reconoce, y en los ambientales monta bucles de cinta de duraciones distintas que se desfasan entre sí, de modo que la combinación tarda horas en repetirse y la pieza nunca suena igual dos veces. Esa idea del desfase sostiene toda su obra, de Here Come the Warm Jets a Music for Airports a los discos generativos recientes. Entra por Another Green World o Music for Airports.", origin: "rec", p: 1, y: 1971, c: 1 },
  { name: "Massive Attack", genre: "Trip-Hop / Electronic", y: 1988, p: 2, via: "Art rock", desc: "Mezzanine: el bajo dub como cimiento de todo, claustrofobico y oscuro. Prometieron material nuevo para 2026, fisico y digital pero fuera de Spotify. Entrada: Mezzanine.", origin: "rec", pick: true },
  { name: "Arca", genre: "Experimental / Electronic", y: 2012, p: 3, c: 1, female: true, via: "Art rock", desc: "Alejandra Ghersi: electrónica de diseño sonoro fragmentado, con el reguetón, la ópera y el club deconstruidos sin métrica estable y su voz procesada encima. Arca (2017) y la serie KiCk (2020-2021). Es electrónica pura, donde la textura y la producción pesan más que la escritura instrumental. Entrada: KiCk i.", origin: "rec", pick: true },
  { name: "SOPHIE", genre: "Experimental / Electronic", y: 2013, p: 3, c: 1, female: true, via: "Art rock", desc: "Inventó un lenguaje de diseño sonoro: en vez de samples, sintetizaba texturas físicas (metal golpeado, plástico, burbujas) desde cero, dentro de canciones de pop. Su único disco es Oil of Every Pearl's Un-Insides (2018); murió en 2021. Electrónica pura, más de textura que de escritura instrumental. Entrada: Oil of Every Pearl's Un-Insides.", origin: "rec", pick: true },
  { name: "Captain Beefheart", genre: "Avant-garde / Experimental", y: 1964, p: 1, c: 3, via: "Art rock", desc: "[Comodín] Blues del Delta desmontado: en Trout Mask Replica (1969) cada instrumento toca en su propio compás y tonalidad a la vez, con dos guitarras que se cruzan en líneas angulosas escritas nota a nota y la batería de John French sosteniendo el conjunto. Lo sostienen Safe as Milk, Lick My Decals Off, Baby, Clear Spot y, tras el bache de los dos discos de 1974 (Unconditionally Guaranteed y Bluejeans & Moonbeams), Shiny Beast, Doc at the Radar Station e Ice Cream for Crow (1982), el último. Entrada: Clear Spot, luego Trout Mask Replica.", origin: "rec", pick: true },
  { name: "Dead Can Dance", genre: "Art Pop / Ethereal / Gothic", desc: "[Comodín] Piezas lentas y modales sobre instrumentación medieval, bizantina y del norte de África, construidas por repetición y drone, con la voz flotando encima. Muy bello y muy hipnótico, pero armónicamente estático y sin apenas desarrollo ni cambios de estructura: es atmósfera, no complejidad, en un mundo sonoro que no tiene par. Entra por Within the Realm of a Dying Sun.", origin: "rec", p: 3, y: 1981, c: 3 },
  { name: "The Residents", genre: "Avant-garde / Experimental", desc: "[Comodín] Deconstruyen la canción popular americana dejándola deliberadamente tosca y desafinada, con electrónica primitiva, melodías de canción infantil retorcidas y voces procesadas hasta lo desagradable. Es incómodo a propósito y estructuralmente simple. Eskimo (1979) y The Commercial Album son lo más logrado de una obra enorme y muy irregular. Entrada: Eskimo.", origin: "rec", p: 3, y: 1969, c: 3 },

  // ----- CANTERBURY / RIO / ZEUHL -----
  { name: "Soft Machine", genre: "Prog Rock / Jazz Fusion", y: 1966, p: 1, c: 1, via: "Canterbury/RIO", desc: "Mutacion brutal en cuatro anos: de pop psicodelico a suites de jazz-rock (Third son cuatro caras, una sola pieza cada una) a fusion instrumental pura. Robert Wyatt era el baterista Y el cantante. Sacaron Thirteen en marzo de 2026. Entrada: Third.", origin: "rec", pick: true },
  { name: "Gong", genre: "Prog Rock / Psychedelic", y: 1967, p: 2, c: 1, via: "Canterbury/RIO", desc: "De la trilogia Radio Gnome (space-whimsy psicodelico) a Pierre Moerlen's Gong, que era otra banda: fusion liderada por vibrafono y percusion. Pocas discografias se parten tan en dos. Entrada: Angel's Egg, luego Gazeuse!", origin: "rec", pick: true },
  { name: "Robert Wyatt", genre: "Art Rock / Prog", y: 1970, p: 3, c: 1, via: "Canterbury/RIO", desc: "Tras Soft Machine y Matching Mole, su obra en solitario convierte los teclados y la percusión en texturas: Rock Bottom (1974) son piezas lentas y frágiles sobre capas de teclado, con la trompeta de Mongezi Feza y la viola de Fred Frith entrando como voces sueltas. Es un disco único, pero lo que sigue, de Ruth Is Stranger Than Richard a Shleep y Comicopera, es sobre todo canción frágil de voz y textura, con poca sustancia instrumental. Entrada: Rock Bottom.", origin: "rec", pick: true },
  { name: "Hatfield and the North", genre: "Prog Rock (Canterbury)", y: 1972, p: 2, via: "Canterbury/RIO", desc: "El corazon calido del Canterbury: Pip Pyle (bateria), Richard Sinclair (bajo y voz), Dave Stewart (teclados). Complejidad con humor, y las Northettes usadas como textura instrumental. Entrada: The Rotters' Club.", origin: "rec", pick: true },
  { name: "National Health", genre: "Prog Rock (Canterbury)", y: 1975, p: 2, via: "Canterbury/RIO", desc: "El mismo Dave Stewart en modo compositor de camara: casi todo instrumental, escritura densa y sin concesiones. Es el Canterbury mas cercano al prog metal antes de que existiera. Entrada: Of Queues and Cures.", origin: "rec", pick: true },
  { name: "Henry Cow", genre: "Avant-garde / Experimental", y: 1968, p: 1, via: "Canterbury/RIO", desc: "Avant-prog cruzado con música de cámara y free jazz: partes escritas nota a nota que se abren de golpe a improvisación colectiva, con la guitarra de Fred Frith, el fagot de Lindsay Cooper, la batería de Chris Cutler y compases que no se asientan nunca. Legend (1973), In Praise of Learning (1975), con Dagmar Krause a la voz, y Western Culture (1979), el más compuesto, son la cumbre; Unrest (1974), con más montaje de estudio e improvisación, queda algo por debajo. Entrada: Western Culture, luego In Praise of Learning.", origin: "rec", pick: true, c: 2 },
  { name: "Univers Zero", genre: "Avant-garde / Chamber Rock", y: 1974, p: 1, via: "Canterbury/RIO", desc: "Música de cámara oscura tocada por un grupo de rock: fagot, armonio, violín, clarinete y bajo sobre la batería de Daniel Denis, que fundó y dirige el grupo y hace que el pulso mande sobre todo, en piezas que suenan a réquiem gótico en compases irregulares. Lo sostienen cuarenta años sin un disco flojo, de 1313 (1977) y Heresie a Uzed, Heatwave, The Hard Quest, Implosion y Phosphorescent Dreams (2014). Entrada: Heresie, luego Uzed.", origin: "rec", pick: true, c: 2 },
  { name: "Present", genre: "Avant-garde / Chamber Rock", y: 1979, p: 1, via: "Canterbury/RIO", desc: "El grupo que montó Roger Trigaux al dejar Univers Zero: rock de cámara más agresivo e hipnótico, con riffs disonantes repetidos en compases impares hasta volverse trance y piano, guitarra y batería golpeando juntos como una sola máquina. Prácticamente math rock en 1980. Triskaïdékaphobie (1980), Le poison qui rend fou (1985), No. 6, High Infidelity, Barbaro (ma non troppo) (2009) y su disco de 2024 sostienen ese nivel. Entrada: Triskaïdékaphobie, luego Barbaro.", origin: "rec", pick: true },
  { name: "Banco del Mutuo Soccorso", genre: "Prog Rock (IT)", y: 1969, p: 1, via: "Canterbury/RIO", desc: "Dos teclistas a la vez repartiéndose líneas distintas en lugar de doblarse, con Francesco Di Giacomo cantando en registro casi operístico por encima de estructuras que encadenan secciones sin repetirlas. Los tres primeros discos, Banco, Darwin! e Io Sono Nato Libero, mantienen esa densidad. Entrada: Darwin!", origin: "rec", pick: true },
  { name: "Koenjihyakkei", genre: "Avant-garde / Zeuhl (JP)", desc: "[Comodín] Es Magma tocado al doble de velocidad: temas que cambian de compás cada pocos segundos, bajo y teclado al unísono en intervalos incómodos, voces femeninas operísticas en idioma inventado y Tatsuya Yoshida a una batería que no baja el ritmo. Cinco discos y ninguno flojo, de Hundred Sights of Koenji (1994) y II a Viva Koenji!, Angherr Shisspa (2005) y Dhorimviskha (2018). Entrada: Angherr Shisspa.", origin: "rec", p: 1, y: 1991, c: 3 },
  { name: "Ruins", genre: "Avant-garde / Zeuhl (JP)", y: 1985, p: 2, c: 3, via: "Canterbury/RIO", desc: "[Comodín] Dúo de bajo y batería, sin guitarra ni teclados: Tatsuya Yoshida, el de Koenjihyakkei, toca y canta en un idioma inventado sobre un bajo distorsionado que hace de riff, en temas de zeuhl-punk que cambian de compás cada pocos segundos. La obra es enorme y desigual: Burning Stone (1992), Hyderomastgroningem (1995), Symphonica (1998) y Pallaschtom (2000) son lo mejor, y buena parte del resto y de las colaboraciones repite la fórmula. Entrada: Hyderomastgroningem.", origin: "rec", pick: true },
  { name: "Area", genre: "Avant Prog / Jazz Rock (IT)", desc: "Jazz-rock italiano de los setenta y de lo más difícil de seguir del género: modos griegos y balcánicos sobre compases impares que cambian dentro del mismo tema, con secciones de free jazz donde la banda se suelta y vuelve a encajar, y Demetrio Stratos usando la voz como un instrumento más, con armónicos y registros que no suenan a canto convencional. Los cinco discos con él, de Arbeit Macht Frei (1973) a Caution Radiation Area, Crac!, Maledetti y 1978 gli dei se ne vanno, gli arrabbiati restano!, sostienen esa densidad; tras su muerte en 1979, Tic & Tac y Chernobyl 7991 quedan muy por debajo. Entrada: Arbeit Macht Frei.", origin: "rec", p: 1, y: 1972, c: 3 },

  // ----- FUSIÓN JAZZ -----
  { name: "Mahavishnu Orchestra", genre: "Jazz Fusion", y: 1971, p: 2, via: "Fusión jazz", desc: "Billy Cobham toca compases imposibles con potencia de rock y no de jazz, y Jan Hammer al teclado y Jerry Goodman al violín se turnan solos con John McLaughlin a velocidad absurda, todo sobre armonía modal india. The Inner Mounting Flame (1971) y Birds of Fire (1973) son dos de los discos más importantes de la fusión, y The Lost Trident Sessions (grabado en 1973, publicado en 1999) está a su altura. La segunda formación, con Apocalypse (1974) y Visions of the Emerald Beyond (1975), sigue a buen nivel; Inner Worlds (1976) divide, y los dos discos de los ochenta con el mismo nombre bajan mucho. Entrada: The Inner Mounting Flame.", origin: "rec", pick: true },
  { name: "Weather Report", genre: "Jazz Fusion", y: 1970, p: 2, via: "Fusión jazz", desc: "Jaco Pastorius convirtió el bajo fretless en voz cantante principal, con armónicos y acordes, mientras Joe Zawinul usaba los sintetizadores como sección de vientos y Wayne Shorter escribía y soplaba por encima. El grupo cambió de formato varias veces, de la improvisación abstracta de los primeros discos a la escritura densa de Black Market y Heavy Weather. El mapa: de Weather Report (1971) a Heavy Weather (1977), más Night Passage (1980), a gran nivel; Mr. Gone (1978) y la última etapa, de Weather Report (1982) a This Is This (1986), bajan mucho. Entrada: Black Market, luego Heavy Weather.", origin: "rec", pick: true },
  { name: "Return to Forever", genre: "Jazz Fusion", y: 1972, p: 1, via: "Fusión jazz", desc: "Stanley Clarke usa el bajo como voz solista con la agilidad de un saxo, desde 1973 Lenny White lleva la batería con potencia de rock, y las piezas están escritas con temas que vuelven transformados entre los solos, no como cabeza-solo-cabeza. De Return to Forever (1972) a Romantic Warrior (1976) no hay disco flojo; solo Musicmagic (1977), con sección de vientos y más canción, baja. Entrada: Romantic Warrior.", origin: "rec", pick: true },
  { name: "Brand X", genre: "Jazz Fusion", y: 1975, p: 2, via: "Fusión jazz", desc: "Phil Collins tocando fusión de verdad, con compases compuestos y mucho swing, y Percy Jones al bajo fretless, uno de los grandes ignorados del instrumento: líneas melódicas retorcidas, con armónicos y glissandos, en la órbita de Jaco pero más raro. Unorthodox Behaviour (1976), Moroccan Roll (1977) y Masques (1978) son la cumbre; de Product (1979) en adelante bajan. Entrada: Unorthodox Behaviour.", origin: "rec", pick: true },
  { name: "Snarky Puppy", genre: "Jazz Fusion / Funk", y: 2004, p: 2, via: "Fusión jazz", desc: "Big band de fusión grabada en directo en el estudio, con público, dirigida por el bajista Michael League: secciones de vientos y teclados muy escritas, varios baterías y percusionistas y solos que crecen sobre grooves complejos pero respirables. We Like It Here (2014), Culcha Vulcha (2016), Empire Central (2022) y Somni (2025), con la Metropole Orkest. Entrada: We Like It Here, empezando por Lingus.", origin: "rec", pick: true },
  { name: "Hiatus Kaiyote", genre: "Jazz Funk / Soul", y: 2011, p: 2, female: true, via: "Fusión jazz", desc: "Nai Palm al frente de un soul futurista con desplazamientos rítmicos salvajes y armonía retorcida bajo melodías preciosas, con el bajo de Paul Bender muy al frente. Muy parejos: Choose Your Weapon (2015), Mood Valiant (2021) y Love Heart Cheat Code (2024). Entrada: Choose Your Weapon.", origin: "rec", pick: true },
  { name: "Jaga Jazzist", genre: "Jazz Fusion / Electronic (NO)", y: 1994, p: 2, via: "Fusión jazz", desc: "Nu jazz noruego: una big band de unos diez músicos cruzada con post-rock y electrónica bien integrada, con capas y capas de arreglo. A Livingroom Hush (2001), What We Must (2005), One-Armed Bandit (2010) y Pyramid (2020). Entrada: A Livingroom Hush.", origin: "rec", pick: true },
  { name: "DOMi & JD Beck", genre: "Jazz Fusion", y: 2018, p: 2, female: true, via: "Fusión jazz", desc: "Dúo de teclados y batería: DOMi toca armonía de jazz densa con técnica de conservatorio y JD Beck es un fenómeno de la batería, con precisión casi de máquina y fraseo de beat. NOT TiGHT (2022) y WHO ASKED? (31 de julio de 2026), con orquesta en varios temas y una versión instrumental aparte, You Asked!. Entrada: NOT TiGHT.", origin: "rec", pick: true },
  { name: "Egberto Gismonti", genre: "Jazz / Fusion (BR)", y: 1969, p: 2, c: 1, via: "Fusión jazz", desc: "Brasileño que cruza clásica de conservatorio, jazz y música indígena amazónica, y compone igual para piano de concierto que para guitarra de diez cuerdas, con bajo, armonía y melodía tocados a la vez. Muy parejo en ECM: Dança das Cabeças (1977, a dúo con Naná Vasconcelos), Sol do Meio Dia y Infância. Entrada: Dança das Cabeças.", origin: "rec", pick: true },

  // ----- INDUSTRIAL / POST-ROCK -----
  { name: "Talk Talk", genre: "Art Rock / Post-Rock", y: 1981, p: 1, c: 1, via: "Post-rock", desc: "La reinvencion definitiva: de hits de synth-pop a inventar el post-rock. Grabaron Spirit of Eden un ano entero a oscuras con musicos de jazz improvisando, y luego EDITARON ese material hasta volverlo composicion. Entrada: Spirit of Eden.", origin: "rec", pick: true },
  { name: "Swans", genre: "Experimental / Post-Punk", y: 1982, p: 1, c: 1, via: "Industrial", desc: "La sustancia es la construcción por acumulación: piezas de veinte minutos donde una célula de bajo y batería se repite hasta que el cambio de un solo elemento reordena la pieza entera, con percusión metálica y guitarras en afinaciones abiertas. Los primeros discos, de Filth (1983) a Holy Money, son más brutales que ricos; desde Children of God (1987) y Soundtracks for the Blind (1996), y sobre todo en la etapa reunida, de The Seer (2012) y To Be Kind a The Glowing Man, The Beggar y Birthing (2025), está su mejor escritura. Birthing cerró esa era y el directo final sale en octubre de 2026. Entrada: To Be Kind.", origin: "rec", pick: true },
  { name: "Ministry", genre: "Industrial Metal", desc: "Al Jourgensen empezo haciendo synth-pop (un disco del que reniega publicamente), paso por EBM y termino inventando el metal industrial de guitarras. Se acaba: el decimoseptimo disco, Hate To Go (Take Out or Delivery), sale el 30 de octubre de 2026 y es el ultimo; la gira de despedida europea arranca en abril de 2027 con Die Krupps de invitados. Jourgensen: estoy en paz con que se acabo. Entra por The Land of Rape and Honey o Psalm 69.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Godflesh", genre: "Industrial Metal", desc: "Metal industrial con caja de ritmos en lugar de baterista como decisión estética, riffs lentísimos repetidos sin variación y un bajo enorme que lleva la armonía mientras la guitarra hace de bloque. Se está cerrando: Decay, su décimo disco y penúltimo, salió el 25 de septiembre de 2026 en Relapse, y el último se graba a finales de 2026. Ya no habrá directos de Godflesh (Broadrick pasó por cirugía abdominal), aunque Jesu y JK Flesh siguen. Entra por Streetcleaner.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Skinny Puppy", genre: "Industrial / Electronic", desc: "El pulso nunca es del todo mecánico ni del todo humano: cEvin Key toca en directo una percusión armada con batería acústica, bidones y módulos electrónicos, y la superpone a las secuencias. Y usa el sampler como collage narrativo, no como adorno: las voces y los ruidos cuentan algo en vez de rellenar. Cuarenta y un años sosteniendo esa escritura, hasta la gira de despedida de diciembre de 2023. Entra por Too Dark Park o Last Rights.", origin: "rec", p: 1, y: 1982, c: 2 },
  { name: "Einstürzende Neubauten", genre: "Industrial / Experimental", desc: "[Comodín] Percusión de metal golpeado, muelles y tubos, que da timbres que ninguna batería puede dar, y sobre eso la voz hablada de Blixa Bargeld en alemán. Pero por debajo de esos timbres las piezas son dispersas y repetitivas, con silencios largos y poco desarrollo; los discos recientes son incluso tranquilos y con forma de canción. Es arte sonoro más que complejidad compuesta, con un timbre que no tiene par. Rampen (apm), de abril de 2024, está armado con improvisaciones de su gira de 2022 y lo financiaron sus oyentes; Josefine Lukschy entró al bajo en 2026. Entra por Halber Mensch.", origin: "rec", p: 3, y: 1980, c: 3 },
  { name: "Author & Punisher", genre: "Industrial Doom", origin: "rec", y: 2004, p: 2, c: 2, via: "Industrial", desc: "Doom industrial de una sola persona: tempo lentísimo y aplastante con la percusión rígida como una máquina, sin swing ninguno, y la voz procesada hasta volverse otra capa de la masa. La dinámica va a tirones en vez de fluir, y eso es lo que lo separa del drone. Entrada: Beastland." },
  { name: "Coil", genre: "Industrial / Experimental", desc: "[Comodín] Time Machines son cuatro drones de tonos de sintetizador oscilando en ciclo, una hora entera pensada para alterar la percepción del tiempo de quien escucha. En Musick to Play in the Dark aparecen el Optigan, cajas de ritmo antiguas y síntesis granular muy manipulada de Drew McDowall, y las piezas se sostienen sobre timbre y duración en vez de sobre melodía. Industrial esotérico y ritual, difícil pero de una pieza. Entrada: Musick to Play in the Dark.", origin: "rec", p: 2, y: 1982, c: 3 },
  { name: "Slint", genre: "Post-Rock / Math Rock", y: 1986, p: 3, via: "Post-rock", desc: "Spiderland (1991) fijó el post-rock y el math rock americano: dinámicas de silencio a violencia, compases desplazados y voz hablada. Es austero a propósito: la gracia está en la tensión y en cómo se retiene, no en la riqueza instrumental, y Tweez (1989), el debut, está muy por debajo. Entrada: Spiderland.", origin: "rec", pick: true },
  { name: "This Heat", genre: "Post-Punk / Experimental", desc: "Piezas que arrancan como post-punk y se desmontan en bucles de cinta, drones de órgano y percusión sola, sin volver nunca al punto de partida, con Charles Hayward tocando la batería como voz principal y no como base. Solo dos discos, This Heat (1979) y Deceit (1981), más el EP Health and Efficiency, y los dos sostienen esa escritura: el primero más abstracto y de montaje, Deceit más tenso y rítmico. Entrada: Deceit.", origin: "rec", p: 1, y: 1976, c: 1 },
  { name: "Tortoise", genre: "Post-Rock / Jazz", y: 1990, p: 2, via: "Post-rock", desc: "Post-rock cruzado con jazz, dub y krautrock: dos baterías a la vez, vibráfono, marimba y John McEntire en la producción. De lo más complejo y menos obvio del género. Millions Now Living Will Never Die (1996) y TNT (1998) son la cumbre; a mediados de los 2000 bajan, y vuelven bien con The Catastrophist (2016) y Touch (octubre de 2025), su primer disco en nueve años. Entrada: Millions Now Living Will Never Die.", origin: "rec", pick: true },
  { name: "Sigur Rós", genre: "Post-Rock (IS)", desc: "Post-rock lentísimo de crescendo, con guitarra frotada generando un colchón sostenido, falsete muy agudo encima y cuerdas y metales entrando en las cimas. Es de una belleza enorme, pero armónicamente estático y de estructura simple: siempre la misma curva de crecer y estallar. Entra por Ágætis byrjun.", origin: "rec", p: 3, y: 1994, c: 2 },
  { name: "Mogwai", genre: "Post-Rock (UK)", y: 1995, p: 1, via: "Post-rock", desc: "Treinta años y once discos moviéndose de verdad: de la dinámica silencio-a-muro de Young Team a los discos con electrónica y voz procesada, a las bandas sonoras. La constante es que las piezas se construyen por presión acumulada y no por estribillo, casi siempre sin voz. The Bad Fire salió en enero de 2025. Entrada: Young Team.", origin: "rec", pick: true },
  { name: "Mono", genre: "Post-Rock (JP)", y: 1999, p: 2, via: "Post-rock", desc: "Pasaron del post-rock de dinamica suave/muro a composicion orquestal real con secciones de cuerda escritas. Grabaron Snowdrop en septiembre de 2025 en Electrical Audio. Entrada: Hymn to the Immortal Wind.", origin: "rec", pick: true },
  { name: "A Silver Mt. Zion", genre: "Post-Rock / Chamber", y: 1999, p: 2, via: "Post-rock", desc: "El proyecto hermano de Godspeed You! Black Emperor, pero con voz humana quebrada, cuerdas y una crudeza emocional que GY!BE nunca permite. Entrada: Horses in the Sky.", origin: "rec", pick: true },
  { name: "Don Caballero", genre: "Math Rock / Instrumental", desc: "Instrumental sin voz, y aquí la batería de Damon Che es el motor compositivo: toca patrones que cambian de métrica bajo riffs de guitarra repetidos, con redobles largos que funcionan como frase melódica, de modo que la tensión viene de la percusión y no de la armonía. Las guitarras trabajan en bucles entrelazados que se desfasan entre sí. Y lo sostienen de For Respect a What Burns Never Returns a American Don, tres discos con la misma lógica y distinto grado de densidad. Entra por What Burns Never Returns.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Fantômas", genre: "Avant-garde Metal", y: 1998, p: 2, c: 3, via: "Art rock", desc: "[Comodín] Mike Patton con Dave Lombardo a la batería, Buzz Osborne y Trevor Dunn: metal escrito como partitura, con cortes brutales y la voz como instrumento sin letra. Fantômas (1999) son viñetas de cómic hechas música y Suspended Animation (2005) un calendario de dibujos animados; The Director's Cut (2001) son versiones de bandas sonoras y Delìrivm Cordia (2004), una sola pieza de 74 minutos, es el más árido. Entrada: Fantômas.", origin: "rec", pick: true },

  // ----- BLACKGAZE / ATMOSFÉRICO -----
  { name: "Alcest", genre: "Blackgaze / Shoegaze (FR)", desc: "Capas de guitarra con chorus y delay formando un colchón brillante, voz limpia y suave de Neige casi susurrada y solo a ratos trémolo y blast beats por debajo. Es de las cosas más bellas del metal, pero es paisaje y contraste, no complejidad. Écailles de lune (2010), Shelter, Kodama (2016) y Les Chants de l'Aurore (2024). Entrada: Écailles de lune.", origin: "rec", p: 2, y: 2000, c: 2 },
  { name: "Deafheaven", genre: "Blackgaze / Post-Metal", y: 2010, p: 2, c: 1, via: "Blackgaze", desc: "Sunbather (2013) cruza black metal con shoegaze y post-rock, y desde ahí evolucionan: New Bermuda, más pesado, Ordinary Corrupt Human Love, más luminoso, Infinite Granite (2021), que elimina los gritos por completo y es el más flojo, y Lonely People with Power (2025), que vuelve al peso. Entrada: Sunbather.", origin: "rec", pick: true },
  { name: "Agalloch", genre: "Atmospheric Black / Folk", y: 1995, p: 1, via: "Blackgaze", desc: "Cinco discos y ninguno flojo, con un arco claro: de la crudeza de Pale Folklore a la construcción larga de The Mantle y Ashes Against the Grain, donde acústicas y eléctricas se alternan dentro del mismo tema y las piezas se desarrollan por dinámica y no metiendo un riff nuevo cada vez. Entrada: The Mantle.", origin: "rec", pick: true },

  // ----- LATINOAMÉRICA -----
  { name: "Luis Alberto Spinetta", genre: "Prog / Art Rock (AR)", y: 1967, p: 1, c: 1, via: "Latinoamérica", desc: "Guitarrista y compositor que cambió de lenguaje en cada proyecto sin bajar nunca la exigencia armónica: psicodelia en Almendra, rock pesado y retorcido en Pescado Rabioso (Artaud, 1973), jazz-prog oscuro de trío en Invisible (El jardín de los presentes) y fusión de acordes abiertos en Spinetta Jade (Alma de diamante). Lo que une todo es una armonía de jazz aplicada al rock, con progresiones que no resuelven donde se espera. Murió en 2012. Entrada: Artaud.", origin: "rec", pick: true },
  { name: "Charly García", genre: "Prog / Art Rock (AR)", y: 1972, p: 2, c: 1, via: "Latinoamérica", desc: "De Sui Generis al prog puro de La Máquina de Hacer Pájaros y al jazz-rock de Serú Girán, con Pedro Aznar al bajo fretless llevando líneas melódicas, y de ahí a un solista que absorbe new wave y funk sin perder su armonía de piano. Su racha de los ochenta, Yendo de la cama al living (1982), Clics modernos, Piano bar y Parte de la religión (1987), es de lo más alto del rock en español; de mediados de los noventa en adelante la escritura se deshace. Entrada: Bicicleta (Serú Girán), luego Clics modernos.", origin: "rec", pick: true },
  { name: "Os Mutantes", genre: "Psych Rock / Tropicália (BR)", desc: "Psicodelia brasileña que mete bossa nova, orquestación, distorsión y collage de cinta dentro de la misma canción, con armonías vocales a tres voces y cambios de tono bruscos que rompen la canción a mitad y la recomponen en otro estilo. Absurdo a propósito y radical para su año. De Os Mutantes (1968) a Mutantes, A Divina Comédia ou Ando Meio Desligado (1970), Jardim Elétrico y Mutantes e Seus Cometas no País do Baurets (1972) es una racha impecable; los discos de la vuelta, de Haih (2009) a Zzyzx, quedan muy por debajo. Entrada: Os Mutantes (1968).", origin: "rec", p: 2, y: 1966, c: 1 },
  { name: "Meridian Brothers", genre: "Experimental / Cumbia (CO)", y: 1998, p: 2, c: 1, via: "Latinoamérica", desc: "Eblis Álvarez desarma la cumbia, la salsa y el vallenato y los rearma con electrónica lo-fi, guitarras con efectos y armonía torcida a propósito, con un humor absurdo que no rebaja la escritura. Colombiano y reconocido fuera: Desesperanza (2012), ¿Dónde estás María? (2017) y Cumbia Siglo XXI (2020). Entrada: ¿Dónde estás María?", origin: "rec", pick: true },
  { name: "Divididos", genre: "Hard Rock / Folk (AR)", y: 1988, p: 2, via: "Latinoamérica", desc: "Power trio argentino: riff pesadisimo con folklore andino integrado de verdad, no de adorno. Sacaron disco nuevo en noviembre de 2025, el primero en 15 anos. Entrada: La Era de la Boludez.", origin: "rec", pick: true },
  { name: "Los Jaivas", genre: "Prog Rock / Folk (CL)", y: 1963, p: 1, via: "Latinoamérica", desc: "Prog andino: charango, zampona y trutruca dentro de estructuras progresivas. Alturas de Machu Picchu (1981) musicaliza el poema de Neruda. Gira de 45 aniversario en 2026-2027. Entrada: Alturas de Machu Picchu.", origin: "rec", pick: true },
  { name: "Fulano", genre: "Jazz Rock / Avant (CL)", y: 1984, p: 2, via: "Latinoamérica", desc: "Jazz-rock chileno instrumental y disonante, con saxo, flauta, teclados y una sección rítmica muy ágil, más la voz de Arlette Jequier en algunos temas: prácticamente el RIO latinoamericano, con carga política. Fulano (1987), En el búnker (1989), El infierno de los payasos (1993) y Trabajos inútiles (1997) son la etapa fuerte; Animal en extinción (2015) baja. Entrada: El infierno de los payasos.", origin: "rec", pick: true },
  { name: "Congreso", genre: "Jazz Fusion / Folk (CL)", y: 1969, p: 2, via: "Latinoamérica", desc: "Fusion chilena desde 1969, liderada por un baterista (Sergio Tilo Gonzalez), por eso el pulso manda sobre todo. Jazz, prog y folclor latinoamericano en la misma frase. Entrada: Viaje por la Cresta del Mundo.", origin: "rec", pick: true },
  { name: "Milton Nascimento", genre: "Jazz / MPB (BR)", y: 1967, p: 2, via: "Latinoamérica", desc: "Clube da Esquina (1972), a medias con Lô Borges: armonía brasileña de una complejidad que desarma, con acordes que modulan por sitios inesperados, arreglos de cuerda y guitarras de Minas Gerais, y una de las voces más impresionantes que han existido. Milagre dos Peixes (1973) y Minas (1975) están al mismo nivel. Entrada: Clube da Esquina.", origin: "rec", pick: true },
  { name: "Aterciopelados", genre: "Alt Rock (CO)", y: 1990, p: 2, female: true, via: "Latinoamérica", desc: "Andrea Echeverri y Héctor Buitrago: rock alternativo colombiano que mete bambuco, cumbia, rock y electrónica con identidad propia. El Dorado (1995), La pipa de la paz (1996) y Caribe atómico (1998) son la cumbre; luego giran a lo electrónico y lo folk. Entrada: La pipa de la paz.", origin: "rec", pick: true },
  { name: "Kraken", genre: "Heavy / Prog Metal (CO)", y: 1984, p: 3, via: "Latinoamérica", desc: "Heavy metal de Medellín, pionero en Colombia: temas épicos de varias secciones, guitarras dobladas, teclados y la voz de Elkin Ramírez, de registro casi operístico, llevando letras poéticas en español al centro de la canción. La escritura es la del heavy clásico de los ochenta, y su peso está en la voz y en lo que significó para el rock en español más que en la complejidad instrumental. Elkin murió en 2017 y la banda siguió; Kraken VII salió en 2024. Entrada: Kraken II.", origin: "rec", pick: true },
  { name: "Triana", genre: "Prog Rock / Flamenco (ES)", y: 1974, p: 2, via: "Latinoamérica", desc: "Prog andaluz: flamenco de verdad (cante jondo, compas) dentro de estructuras de rock progresivo. Fusion real, no decorado turistico. Entrada: El Patio.", origin: "rec", pick: true },
  { name: "Hermeto Pascoal", genre: "Avant-garde Jazz (BR)", desc: "[Comodín] Multiinstrumentista brasileño que escribía armonía de jazz sobre ritmos del nordeste (baião, frevo, forró) en métricas cambiantes, con temas que pasan de un unísono endiablado de flauta, saxo y teclado a improvisación colectiva y vuelven a encajar. Sacaba melodía del habla: transcribía la entonación de una frase y la armonizaba como tema. A Música Livre de Hermeto Pascoal (1973), Slaves Mass, Zabumbê-bum-á, Cérebro Magnético, Lagoa da Canoa, Município de Arapiraca y Brasil Universo (1986) sostienen un nivel altísimo. Murió el 13 de septiembre de 2025, a los 89 años. Entrada: Slaves Mass.", origin: "rec", p: 1, y: 1964, c: 3 },
  { name: "Los Pirañas", genre: "Psych / Instrumental (CO)", y: 2010, p: 2, via: "Latinoamérica", desc: "Trio instrumental colombiano: Eblis Alvarez, Mario Galeano (Frente Cumbiero) y Pedro Ojeda (Romperayo). Guitarra surf-psicodelica retorcida sobre ritmos caribenos y champeta. Entrada: Una Oportunidad mas de triunfar en la vida (2025).", origin: "rec", pick: true },
  { name: "Los Saicos", genre: "Garage / Punk (PE)", y: 1964, p: 3, via: "Latinoamérica", desc: "Peru, 1965: proto-punk una decada antes del punk. Demolicion es un grito distorsionado que no tenia derecho a existir en esa fecha. Su valor es historico mas que compositivo. Entrada: las grabaciones recopiladas.", origin: "rec", pick: true },
  { name: "Santa Sabina", genre: "Gothic / Prog Rock (MX)", y: 1989, p: 2, female: true, via: "Latinoamérica", desc: "Rock gótico-progresivo mexicano con Rita Guerrero, cantante de formación clásica: teatralidad oscura, arreglos con cuerda y estructuras largas, cantado en español. Entrada: Symbolvm.", origin: "rec", pick: true },
  { name: "Caifanes", genre: "Alt Rock (MX)", y: 1987, p: 2, via: "Latinoamérica", desc: "Rock oscuro mexicano con percusión prehispánica integrada de verdad, la guitarra de Alejandro Marcovich con escalas de raíz árabe y la voz de Saúl Hernández. Cuatro discos y los cuatro a gran nivel: Caifanes (1988), El Diablito, El Silencio (1992), producido por Adrian Belew, y El Nervio del Volcán (1994). Entrada: El Silencio.", origin: "rec", pick: true },
  { name: "Uchpa", genre: "Hard Rock / Blues (PE)", y: 1993, p: 2, via: "Latinoamérica", desc: "Hard rock y blues cantado integramente en quechua, fusionado con huayno, jarawi y pumpin. El nombre significa cenizas, por lo que quedo tras el conflicto armado peruano; su lider Fredy Ortiz fue policia en esa guerra. Entrada: Qauka Kausay.", origin: "rec", pick: true },
  { name: "Secos & Molhados", genre: "Glam Rock / MPB (BR)", y: 1971, p: 2, via: "Latinoamérica", desc: "Glam teatral de 1973 con maquillaje facial completo y la voz de Ney Matogrosso, un contratenor de registro agudisimo, sobre poesia brasilena musicalizada. Vendieron mas que los Beatles en Brasil ese ano. Entrada: su homonimo de 1973.", origin: "rec", pick: true },

  // ----- ASIA -----
  { name: "Sheena Ringo", genre: "Art Pop / Jazz (JP)", desc: "Escribe y arregla ella los discos, y esos arreglos son de verdad (big band de jazz con sección de metales escrita, orquesta de pop de era Showa, electrónica), con armonía que se sale del pop japonés estándar y una voz que fuerza el timbre a propósito. Matiz: Tokyo Jihen no es su banda de acompañamiento sino un grupo donde los demás también componen. Entra por Kalk Samen Kuri no Hana.", origin: "rec", p: 2, y: 1998, c: 1, female: true },
  { name: "Boredoms", genre: "Noise / Experimental (JP)", y: 1986, p: 2, c: 1, via: "Asia", desc: "Yamantaka Eye llevó la banda del ruido impenetrable de Soul Discharge y Pop Tatari al trance tribal de Super Ae (1998) y Vision Creation Newsun (1999), piezas largas de repetición con varias baterías a la vez. Después vinieron Seadrum/House of Sun y los conciertos 77 Boadrum, con 77 bateristas en espiral. Entrada: Vision Creation Newsun.", origin: "rec", pick: true },
  { name: "Susumu Hirasawa", genre: "Prog / Electronic (JP)", desc: "[Comodín] Suena a prog electrónico hiperactivo: secuencias muy rápidas y capas de coros procesados de su propia voz apiladas hasta formar un muro, todo sobre escalas del sudeste asiático que le dan giros melódicos que no salen del repertorio occidental. Es denso y agotador en el buen sentido, con muy poco aire. Compuso para Satoshi Kon (Paprika) y para Berserk. unZIP (oct 2025) es su primer Kaku P-MODEL en siete años. Entra por Siren.", origin: "rec", p: 2, y: 1979, c: 3 },
  { name: "Yellow Magic Orchestra", genre: "Synth Pop / Electronic (JP)", y: 1978, p: 2, c: 1, via: "Asia", desc: "Sakamoto, Hosono y Takahashi inventaron el technopop trabajando con un secuenciador Roland MC-8 en una época en que había que programar cada nota como datos numéricos, y Takahashi tocaba la batería encima con una precisión mecánica deliberada para casar con la máquina. Armonía de Sakamoto tomada de la clásica y del exotica. Terminaron sampleados por medio hip-hop y por toda la electrónica de Detroit. Entrada: Solid State Survivor.", origin: "rec", pick: true },
  { name: "Ling Tosite Sigure", genre: "Math Rock / Post-Hardcore (JP)", y: 2002, p: 1, female: true, via: "Asia", desc: "Trio de math post-hardcore: TK a la guitarra y falsete desgarrado, 345 al bajo y grito, y Pierre Nakano en una bateria que es de lo mas impresionante del rock moderno, con precision de metronomo dentro del caos. Entrada: just A moment.", origin: "rec", pick: true },
  { name: "Ningen Isu", genre: "Doom / Heavy Metal (JP)", y: 1987, p: 2, via: "Asia", desc: "Devoción a Black Sabbath desde 1987, pero con kimonos, estética yokai y letras de literatura japonesa, con riffs de doom y heavy setentero muy bien tocados. Mahoroba (noviembre de 2025) es su disco número 24. Entrada: Mahoroba.", origin: "rec", pick: true },
  { name: "Silica Gel", genre: "Art Rock / Psych (KR)", y: 2013, p: 2, via: "Asia", desc: "Art rock psicodelico coreano; ganaron Musician of the Year 2024 en los Korean Music Awards. Su tercer disco Ballad of You salio en agosto de 2026. Entrada: Power Andre 99.", origin: "rec", pick: true },
  { name: "Omnipotent Youth Society", genre: "Post-Rock / Folk Rock (CN)", y: 1996, p: 2, via: "Asia", desc: "Post-rock/folk-rock con arreglos de vientos y una densidad compositiva rarisima para el rock chino. Inside the Cable Temple vendio 200.000 copias en medio dia. Doce anos entre discos porque graban hasta quedar conformes. Entrada: el homonimo de 2010.", origin: "rec", pick: true },
  { name: "Chthonic", genre: "Symphonic Black Metal (TW)", y: 1995, p: 2, via: "Asia", desc: "Black metal sinfonico con erhu integrado de verdad y tematica de historia taiwanesa; su vocalista Freddy Lim llego a ser legislador nacional. Entrada: Takasago Army.", origin: "rec", pick: true },
  { name: "Fishmans", genre: "Dub / Psych Pop (JP)", y: 1987, p: 2, via: "Asia", desc: "Dub y psicodelia japonesa: bajo y batería de dub muy presentes, teclados y guitarras en capas y la voz aguda de Shinji Sato flotando encima. Kūchū Camp (1996), Long Season (1996), una sola pieza de 35 minutos que se despliega sin repetirse, y Uchū Nippon Setagaya (1997) son la cumbre; Sato murió en 1999, a los 33. Entrada: Long Season.", origin: "rec", pick: true },
  { name: "Senyawa", genre: "Experimental / Folk (ID)", desc: "[Comodín] Dos personas, nada más. Rully Shabara pasa de canto gutural a grito con técnicas vocales extendidas, y Wukir Suryadi hace de base con un instrumento de bambú, piel y cuerdas de acero que pasa por distorsión. El resultado es ritual, crudo e intensísimo de timbre, pero las piezas son de estructura mínima: una idea que se repite y crece, que impacta más de lo que desarrolla. Entra por Alkisah.", origin: "rec", p: 2, y: 2010, c: 3 },
  { name: "Jambinai", genre: "Post-Metal / Folk (KR)", y: 2009, p: 1, via: "Asia", desc: "El geomungo, el haegeum y el piri llevan las líneas principales, no adornan, y eso lo sostienen en toda su discografía: pasan de casi silencio a muros de distorsión manteniendo los instrumentos coreanos al frente, con piezas que crecen por acumulación de capas en vez de volver a un estribillo. Coreanos. Entrada: A Hermitage.", origin: "rec", pick: true },
  { name: "Envy", genre: "Screamo / Post-Rock (JP)", y: 1992, p: 2, via: "Asia", desc: "Screamo cruzado con post-rock: crescendos enormes con spoken word en japones encima. Entrada: A Dead Sinking Story.", origin: "rec", pick: true },
  { name: "Melt-Banana", genre: "Noise / Punk (JP)", y: 1992, p: 2, female: true, via: "Asia", desc: "Noise punk a hipervelocidad: canciones de 30 segundos ejecutadas con precision de reloj suizo, con la voz de Yasuko Onuki usada como instrumento agudo. Entrada: Fetch.", origin: "rec", pick: true },
  { name: "Ichiko Aoba", genre: "Folk / Chamber (JP)", y: 2010, p: 2, female: true, via: "Asia", desc: "Folk de camara de delicadeza extrema pero compositivamente denso: Windswept Adan es un ciclo entero sobre una isla imaginaria. Luminescent Creatures (feb 2025) lo hizo con el pianista Taro Umebayashi dirigiendo un ensamble. Entrada: Windswept Adan.", origin: "rec", pick: true },
  { name: "Acid Mothers Temple", genre: "Psych Rock / Drone (JP)", y: 1995, p: 3, via: "Asia", desc: "Colectivo psicodélico japonés hiperprolífico: drones cósmicos, la guitarra de Kawabata Makoto y jams de veinte minutos que se desarman. Entrada: La Novia.", origin: "rec", pick: true },
  { name: "Second Hand Rose", genre: "Folk Rock / Teatral (CN)", y: 1999, p: 3, via: "Asia", desc: "Rock con errenzhuan, la opera folclorica del noreste chino, y un frontman travestido con estetica de teatro popular. Fusion real, no cosmetica. Entrada: su homonimo.", origin: "rec", pick: true },

  // ----- DOOM / GÓTICO -----
  { name: "Ulver", genre: "Experimental / Electronic (NO)", desc: "La reinvención es de verdad la más extrema de la música pesada (black metal noruego, folk acústico, electrónica, trip-hop, cámara, ambient y synth-pop ochentero), pero reinventarse mucho no es lo mismo que ser complejo. Hoy suenan a sintetizadores cálidos y producción impecable sobre estructuras de canción bastante directas, con la voz de Kristoffer Rygg al frente: hermoso y muy bien hecho, no exigente. Neverland (dic 2025) es completamente electrónico. Entra por Bergtatt, luego Perdition City.", origin: "rec", p: 2, y: 1993, c: 1 },
  { name: "Paradise Lost", genre: "Gothic / Death Doom (UK)", desc: "Death/doom a medio tiempo con melodías de guitarra muy cantables y armonías gemelas por encima, y voz que alterna limpio grave y gutural. Es melódico y pesado, pero no busca complejidad rítmica ni estructural. La categoría 1 se queda porque la reinvención sí es real, y de las gordas: inventaron el gothic metal con Gothic (1991), se fueron al synth-pop y el darkwave con Host perdiendo media base de fans, y volvieron al death/doom sin pedir perdón. Ascension salió en 2025. Entra por Gothic.", origin: "rec", p: 2, y: 1988, c: 1 },
  { name: "My Dying Bride", genre: "Death Doom (UK)", desc: "Doom lentísimo con el violín como voz principal y no de adorno, largos desarrollos de diez minutos y la voz desgarrada de Aaron Stainthorpe alternando lamento y gutural. Es de una tristeza enorme y muy bien ejecutado, pero estructuralmente es repetición y crecimiento, no complejidad. Turn Loose the Swans (1993), The Angel and the Dark River y The Dreadful Hours (2001) son lo mejor, y A Mortal Binding (2024) mantiene el nivel. Entrada: Turn Loose the Swans.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Candlemass", genre: "Epic Doom Metal (SE)", desc: "Riffs de Leif Edling lentísimos y enormes, repetidos con muy poca variación para que pesen, con la voz operística de Messiah Marcolin encima como contraste. El efecto depende de la repetición y del volumen, no del desarrollo: es doom épico de manual porque ellos escribieron el manual. Entra por Nightfall.", origin: "rec", p: 2, y: 1984, c: 2 },
  { name: "Theatre of Tragedy", genre: "Gothic / Doom Metal (NO)", y: 1993, p: 3, c: 1, female: true, via: "Doom/Gótico", desc: "Pioneros del dueto de voz femenina limpia contra gutural, el molde que luego usan Draconian y Tristania, y después se fueron al electropop industrial con Musique. Entrada: Velvet Darkness They Fear.", origin: "rec", pick: true },
  { name: "Tiamat", genre: "Gothic / Psych Metal (SE)", y: 1987, p: 3, c: 1, via: "Doom/Gótico", desc: "Pasaron del death metal sueco al rock gótico y psicodélico atmosférico, lento y espacial. Wildhoney (1994) es el punto de giro y lo mejor; lo posterior, de A Deeper Kind of Slumber a The Scarred People (2012), es más atmósfera que escritura. Entrada: Wildhoney.", origin: "rec", pick: true },
  { name: "Sleep", genre: "Stoner / Doom Metal", y: 1990, p: 2, via: "Doom/Gótico", desc: "Stoner y doom de riffs gigantes y lentísimos: Sleep's Holy Mountain (1992), Dopesmoker (2003), una sola pieza de 63 minutos que la discográfica rechazó y tardó años en salir, y The Sciences (2018). Al Cisneros y Matt Pike montaron después Om y High on Fire. Entrada: Dopesmoker.", origin: "rec", pick: true },
  { name: "Electric Wizard", genre: "Stoner / Doom Metal (UK)", y: 1993, p: 3, via: "Doom/Gótico", desc: "Dopethrone (2000): la afinación más grave y el sonido más sucio y saturado del doom. No es complejo, es interesante: una identidad sonora que no se confunde con nada. Come My Fanatics... (1997) está a la altura. Entrada: Dopethrone.", origin: "rec", pick: true },
  { name: "Saint Vitus", genre: "Doom Metal", y: 1978, p: 3, via: "Doom/Gótico", desc: "Uno de los dos pilares americanos del doom tradicional de los ochenta, con Wino al frente y una crudeza deliberada. Born Too Late (1986). Entrada: Born Too Late.", origin: "rec", pick: true },
  { name: "Trouble", genre: "Psychedelic Doom Metal", y: 1979, p: 3, via: "Doom/Gótico", desc: "El otro pilar americano del doom de los ochenta, más melódico y psicodélico que Saint Vitus. Psalm 9 (1984) y Manic Frustration (1992). Entrada: Psalm 9.", origin: "rec", pick: true },
  { name: "SubRosa", genre: "Doom Metal / Chamber", y: 2005, p: 2, female: true, via: "Doom/Gótico", desc: "Doom de Salt Lake City con dos violines eléctricos como instrumentos principales, no de adorno: disonantes y chirriantes, tejiendo las melodías sobre riffs lentos, liderado por mujeres. More Constant Than the Gods (2013) y For This We Fought the Battle of Ages (2016). Entrada: More Constant Than the Gods.", origin: "rec", pick: true },
  { name: "Messa", genre: "Doom Metal / Jazz (IT)", y: 2014, p: 2, female: true, via: "Doom/Gótico", desc: "Doom italiano con saxofón, jazz y escalas de Oriente Medio, con la voz de Sara Bianchin encima: de lo más inquieto instrumentalmente del género hoy. Feast for Water (2018), Close (2022) y The Spin (2025). Entrada: Close.", origin: "rec", pick: true },
  { name: "Warning", genre: "Doom Metal (UK)", y: 1994, p: 2, via: "Doom/Gótico", desc: "Doom británico de Patrick Walker: la repetición convertida en duelo, con riffs lentos y la voz al frente. Watching from a Distance (2006) es de los discos más devastadores del género, y Rituals of Shame (junio de 2026), su primer disco en veinte años, está a la altura. Entrada: Watching from a Distance.", origin: "rec", pick: true },
  { name: "40 Watt Sun", genre: "Doom / Slowcore (UK)", y: 2009, p: 3, via: "Doom/Gótico", desc: "El proyecto de Patrick Walker, de Warning, despojando el doom hasta casi lo acústico, con canciones larguísimas, lentas y desnudas. Muy emotivo, pero mínimo por dentro. The Inside Room (2011) y Perfect Light (2016). Entrada: The Inside Room.", origin: "rec", pick: true },
  { name: "Bell Witch", genre: "Funeral Doom Metal", y: 2010, p: 1, c: 3, via: "Doom/Gótico", desc: "[Comodín] Dúo de bajo y batería, sin guitarra: Dylan Desmond toca un bajo de seis cuerdas con tapping que cubre todo el rango, melodía y armonía, y Jesse Shreibman lleva la batería y el órgano. Longing (2012), Four Phantoms, Mirror Reaper (2017), una sola pieza de 84 minutos en memoria de su batería fallecido Adrian Guerra, y Future's Shadow Part 1: The Clandestine Gate (2023). Entrada: Mirror Reaper.", origin: "rec", pick: true },
  { name: "Ahab", genre: "Funeral Doom Metal (DE)", y: 2004, p: 2, via: "Doom/Gótico", desc: "Funeral doom náutico alemán: discos conceptuales completos basados en Moby-Dick, y luego en Poe y Verne, lentos, inmensos y literarios, con voz limpia y gutural. The Call of the Wretched Sea (2006) y The Boats of the Glen Carrig (2015) son la cumbre. Entrada: The Call of the Wretched Sea.", origin: "rec", pick: true },
  { name: "Skepticism", genre: "Funeral Doom Metal (FI)", y: 1991, p: 2, via: "Doom/Gótico", desc: "Funeral doom finlandés con órgano de iglesia como instrumento principal, a velocidad de procesión, que fundó el género. Stormcrowfleet (1995) y Lead and Aether (1998) son la cumbre. Entrada: Stormcrowfleet.", origin: "rec", pick: true },
  { name: "Virgin Black", genre: "Gothic Doom Metal (AU)", y: 1995, p: 2, via: "Doom/Gótico", desc: "Gothic doom australiano con orquesta y coro reales: su trilogía Requiem está compuesta con estructura de misa de réquiem de verdad. Teatral y operístico al extremo. Entrada: Requiem - Mezzo Forte.", origin: "rec", pick: true },
  { name: "Esoteric", genre: "Funeral Doom Metal (UK)", y: 1992, p: 2, via: "Doom/Gótico", desc: "Funeral doom psicodélico británico: piezas de veinte a treinta minutos con capas de guitarra procesada que se deshacen, densas de textura y no solo lentas. Muy parejos: Epistemological Despondency (1994), The Maniacal Vale, Subconscious Dissolution into the Continuum, The Pernicious Enigma, A Pyrrhic Existence (2019). Entrada: The Maniacal Vale.", origin: "rec", pick: true },

  // ----- HIP-HOP / JAZZ MODERNO -----
  { name: "Outkast", genre: "Hip-Hop / Funk", y: 1992, p: 1, c: 1, via: "Hip-hop/Jazz", desc: "Del rap sureño al funk psicodélico con instrumentación en vivo, y cada disco cambia de sistema: ATLiens es espacial y mínimo, Aquemini mete banda tocando, Stankonia acelera hasta rozar el drum and bass, y Speakerboxxx/The Love Below es un doble donde cada mitad es un disco solista distinto. André 3000 abandonó el rap y hoy saca discos de flauta. Entrada: Aquemini.", origin: "rec", pick: true },
  { name: "Flying Lotus", genre: "Experimental Hip-Hop / Jazz", y: 2006, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "Sobrino-nieto de Alice Coltrane. Del beat-tape al jazz fusión con banda real (You're Dead!, con Herbie Hancock): programación de ritmos que se descuadra a propósito, con capas de jazz tocado encima. Fue quien produjo y lanzó a Thundercat. Entrada: Cosmogramma.", origin: "rec", pick: true },
  { name: "Madlib", genre: "Hip-Hop / Jazz", y: 1993, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "El productor camaleon absoluto; y como Yesterdays New Quintet se invento un quinteto de jazz falso donde toca el mismo todos los instrumentos y le puso nombre a cada musico ficticio. Entrada: Shades of Blue.", origin: "rec", pick: true },
  { name: "Shabaka Hutchings", genre: "Jazz / Experimental (UK)", y: 2011, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "Saxofonista británico: lideró Sons of Kemet, con tuba y dos baterías tocando a la vez sobre ritmos caribeños y de jazz, y The Comet Is Coming, jazz cósmico con sintetizador, y en 2023 dejó el saxo por las flautas para grabar música de cámara meditativa en Perceive Its Beauty, Acknowledge Its Grace. Entrada: Your Queen Is a Reptile (Sons of Kemet).", origin: "rec", pick: true },
  { name: "MF DOOM", genre: "Hip-Hop / Rap", y: 1988, p: 1, via: "Hip-hop/Jazz", desc: "Rimas internas densísimas con esquemas que cruzan el final del verso en vez de cerrarlo, sobre producción de collage: diálogos de dibujos animados de los sesenta y bucles de jazz oscuro. Y no es un disco suelto: Operation Doomsday, MM..FOOD y Madvillainy con Madlib sostienen lo mismo, además de lo que sacó como Viktor Vaughn y King Geedorah, cada uno con otra voz y otra producción. Murió en 2020. Entrada: Madvillainy.", origin: "rec", pick: true },
  { name: "The Roots", genre: "Hip-Hop / Jazz Rap", desc: "Hip-hop tocado por una banda en vivo en lugar de programado, y ahí está la diferencia: Questlove toca el groove ligeramente detrás del pulso, dejando que respire en vez de cuadrarlo, y el bajo y los teclados responden a la voz como en un grupo de jazz. Y evolucionaron de verdad: undun es un disco conceptual narrado en orden cronológico inverso que cierra con un cuarteto de cuerdas. Entra por Things Fall Apart o undun.", origin: "rec", p: 1, y: 1987, c: 2 },
  { name: "A Tribe Called Quest", genre: "Jazz Rap / Hip-Hop", y: 1985, p: 2, via: "Hip-hop/Jazz", desc: "Pioneros del sampleo de jazz, pero el dato clave: en The Low End Theory metieron a Ron Carter tocando contrabajo de verdad (el bajista de Miles Davis) en un disco de rap de 1991. Entrada: The Low End Theory.", origin: "rec", pick: true },
  { name: "Kamasi Washington", genre: "Jazz / Spiritual Jazz", desc: "Jazz espiritual modal con coro y cuerdas encima, tempos que respiran y solos largos sobre una armonía bastante estable. Es majestuoso y emocionante, pero armónicamente más sencillo que Coltrane o Mingus. The Epic (2015), Heaven and Earth (2018) y Fearless Movement (2024). Entrada: The Epic.", origin: "rec", p: 2, y: 2004, c: 2 },
  { name: "BADBADNOTGOOD", genre: "Jazz / Hip-Hop", y: 2010, p: 2, via: "Hip-hop/Jazz", desc: "Trio de jazz salido del mundo del hip-hop; Talk Memory tiene arreglos orquestales del brasileno Arthur Verocai. Han grabado con Ghostface Killah y Tyler. Entrada: IV, luego Talk Memory.", origin: "rec", pick: true },
  { name: "Makaya McCraven", genre: "Jazz / Experimental", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Baterista y productor: graba sesiones de improvisación de jazz en vivo y luego las corta y reensambla como si fueran beats, así que es composición por edición con la batería al mando. In the Moment (2015), Universal Beings (2018) e In These Times (2022). Entrada: Universal Beings.", origin: "rec", pick: true },
  { name: "billy woods", genre: "Experimental Hip-Hop", y: 2002, p: 2, via: "Hip-hop/Jazz", desc: "La escritura mas densa y abstracta del rap actual sobre produccion disonante y hostil. GOLLIWOG (2025) fue llamado por Pitchfork una obra maestra de horrorcore. Con ELUCID forma Armand Hammer. Entrada: Maps.", origin: "rec", pick: true },
  { name: "Little Simz", genre: "Hip-Hop / Jazz Rap (UK)", y: 2010, p: 2, female: true, via: "Hip-hop/Jazz", desc: "Albumes narrativos con arreglos orquestales reales (cuerdas y coros). Lotus (junio 2025) trae jazz, punk y funk, con Yussef Dayes de invitado a la bateria. Entrada: Sometimes I Might Be Introvert.", origin: "rec", pick: true },
  { name: "J Dilla", genre: "Hip-Hop / Instrumental", desc: "[Comodín] Programaba la batería deliberadamente desalineada, sin cuantizar, dejando el bombo y la caja caídos unos milisegundos fuera de la rejilla, de modo que el groove cojea y respira como si lo tocara una persona cansada. Eso cambió cómo se toca el instrumento: hoy los bateristas estudian el Dilla time como técnica y una generación entera de soul y hip-hop se construyó sobre esa idea. Donuts son 31 piezas de loops que armó en una cama de hospital con un sampler portátil, y salió tres días antes de que muriera. Entra por Donuts.", origin: "rec", p: 1, y: 1995, c: 3 },
  { name: "Irreversible Entanglements", genre: "Free Jazz / Experimental", y: 2015, p: 2, female: true, via: "Hip-hop/Jazz", desc: "Free jazz improvisado con la poesía hablada de Moor Mother encima: político e incendiario, con saxo y trompeta en contrapunto libre sobre contrabajo y batería. Who Sent You? (2020) y Protect Your Light (2023). Entrada: Who Sent You?", origin: "rec", pick: true },
  { name: "Standing on the Corner", genre: "Experimental / Jazz", y: 2016, p: 3, via: "Hip-hop/Jazz", desc: "Colectivo experimental de Nueva York: collage de jazz, soul, ruido, gospel y grabaciones de campo, sin formato de canción. Entrada: Red Burns.", origin: "rec", pick: true },
  { name: "Ezra Collective", genre: "Jazz / Afrobeat (UK)", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Jazz londinense con afrobeat, reggae y calipso, liderado por el baterista Femi Koleoso, con su hermano TJ al bajo; ganaron el Mercury Prize de 2023 con Where I'm Meant to Be. Here Because of Hope (11 de septiembre de 2026), en tres movimientos que siguen la música negra de África al Caribe y a Londres, entró número uno en Reino Unido. Entrada: Where I'm Meant to Be.", origin: "rec", pick: true },
  { name: "Saul Williams", genre: "Industrial Hip-Hop / Poesía", y: 1998, p: 2, via: "Hip-hop/Jazz", desc: "Poeta que hace hip-hop industrial: palabra hablada y rap sobre bases de ruido y percusión industrial, con un disco entero producido por Trent Reznor. Entrada: The Inevitable Rise and Liberation of NiggyTardust!", origin: "rec", pick: true },

  // ----- THRASH TÉCNICO / DEATH CLÁSICO -----
  { name: "Napalm Death", genre: "Grindcore / Industrial", desc: "Grindcore, o sea velocidad y brevedad extremas sobre riffs deliberadamente simples, sin desarrollo. Lo que sí vale es que no se quedaron quietos en cuarenta años: metieron industrial, pasajes de ruido y disonancia real a partir de Fear Emptiness Despair, y el blast beat que inventó Mick Harris cuenta porque cambia cómo suena todo lo que vino después. Sacaron disco a medias con los Melvins, Savage Imperial Death March, en abril de 2026. Entrada: Utopia Banished.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Kreator", genre: "Thrash Metal (DE)", desc: "Thrash rápido con melodías de guitarra épicas encima del riff y voz rasposa de Mille Petrozza, muy bien ejecutado y bastante directo de estructura. De Pleasure to Kill (1986) a Coma of Souls (1990) está lo mejor; los discos experimentales de los noventa bajan, vuelven bien de Violent Revolution (2001) a Phantom Antichrist (2012), y Hate Über Alles (2022) y Krushers of the World (enero de 2026) quedan por debajo. Entrada: Coma of Souls.", origin: "rec", p: 2, y: 1982, c: 1 },
  { name: "Hypocrisy", genre: "Melodic Death Metal (SE)", y: 1990, p: 2, c: 1, via: "Thrash/Death", desc: "Peter Tägtgren llevó la banda del death brutal a un death melódico atmosférico, casi espacial, con temática de abducciones, y en paralelo montó Pain, puro metal industrial. Muy parejos de Abducted (1996) a Virus (2005) y Worship (2021); solo Catch 22 (2002) baja. Entrada: Abducted.", origin: "rec", pick: true },
  { name: "Dark Angel", genre: "Technical Thrash Metal", desc: "Aquí la batería ES la escritura: Gene Hoglan compone las partes como si fueran riffs, con patrones que cambian de figura bajo el mismo riff de guitarra y subdivisiones que desplazan el acento, y por eso los temas duran ocho minutos sin repetirse. Darkness Descends (1986) y Leave Scars (1989) son la cumbre y Time Does Not Heal (1991) está cerca; We Have Arrived (1985) es más básico. Volvieron en septiembre de 2025 con Extinction Level Event, su primer disco desde 1991, dedicado a Jim Durkin, muerto en 2023, y está claramente por debajo. Entrada: Darkness Descends.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Obituary", genre: "Death Metal", desc: "Death metal de Florida a medio tiempo, muy afinado hacia abajo, con riffs sencillos que se quedan en el bolsillo del ritmo y la voz agónica de John Tardy. Una sola cosa, hecha muy bien, más centrada en el ambiente que en la ejecución. Slowly We Rot (1989) y Cause of Death (1990) son la cumbre. Entrada: Cause of Death.", origin: "rec", p: 3, y: 1984, c: 2 },
  { name: "Suffocation", genre: "Brutal Technical Death", desc: "El brutal death que sí está construido: Terrance Hobbs escribe riffs que se desarrollan y se recolocan en lugar de amontonarse, con cambios de tempo dentro del tema y secciones que vuelven transformadas, y la batería sostiene esa arquitectura en lugar de solo golpear. Effigy of the Forgotten (1991), Breeding the Spawn y Pierced from Within (1995) son la cumbre, y de Souls to Deny (2004) a Blood Oath y ...Of the Dark Light (2017) mantienen el nivel; Pinnacle of Bedlam y Hymns from the Apocrypha (2023) bajan algo. Entrada: Effigy of the Forgotten o Pierced from Within.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Cryptopsy", genre: "Technical Death Metal (CA)", desc: "Death técnico canadiense donde la batería de Flo Mounier es el eje: alterna blast beats con figuras sincopadas que cambian bajo el mismo riff y varía la subdivisión dentro del compás, con riffs disonantes que no repiten. Blasphemy Made Flesh (1994), None So Vile (1996), con la voz de Lord Worm, y Whisper Supremacy (1998) son la cumbre; And Then You'll Beg (2000) y sobre todo The Unspoken King (2008), con giro al deathcore, son el bajón, y de As Gomorrah Burns (2023) a An Insatiable Violence (2025) recuperan el nivel. Entrada: None So Vile.", origin: "rec", p: 2, y: 1988, c: 2 },
  { name: "Cryptic Shift", genre: "Technical Death / Thrash (UK)", y: 2015, p: 2, via: "Thrash/Death", desc: "Death técnico y thrash con fusión de jazz, de guitarras a lo Allan Holdsworth y estructuras desmesuradas. Visitations from Enceladus (2020) y Overspace & Supertime (2026), cinco temas en ochenta y dos minutos, uno de más de media hora, recibido como uno de los discos de death del año. Entrada: Overspace & Supertime.", origin: "rec", pick: true },
  { name: "Destruction", genre: "Technical Thrash Metal (DE)", y: 1982, p: 2, via: "Thrash/Death", desc: "El más técnico del trío alemán: Schmier canta y toca el bajo a la vez, con líneas que se van por su cuenta en vez de seguir la guitarra. De Infernal Overkill (1985) a Release from Agony (1987) está lo mejor, y la vuelta con All Hell Breaks Loose (2000) y The Antichrist (2001) también. Birth of Malice salió en marzo de 2025. Entrada: Eternal Devastation.", origin: "rec", pick: true },
  { name: "Sodom", genre: "Thrash Metal (DE)", y: 1981, p: 2, via: "Thrash/Death", desc: "El más crudo, directo y punk del trío alemán, y muy parejo: de Persecution Mania (1987) y Agent Orange (1989) a Genesis XIX (2020). Sacaron The Arsonist en junio de 2025 y entraron en hiato indefinido justo después. Entrada: Agent Orange.", origin: "rec", pick: true },
  { name: "Overkill", genre: "Thrash Metal", y: 1980, p: 2, via: "Thrash/Death", desc: "Más de cuarenta años con altibajos claros: de Feel the Fire (1985) a Horrorscope (1991) a gran nivel, un bajón en los noventa y los dos mil, y otro pico de Ironbound (2010) a Scorched (2023). D.D. Verni lleva el bajo tan al frente que muchas veces él es el riff principal, y Bobby Blitz sigue cantando agudísimo. Entrada: Horrorscope.", origin: "rec", pick: true },
  { name: "Toxik", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Thrash técnico casi imposible: Josh Christian tocaba en 1987 cosas que no tenían sentido para la época, con arreglos que rozan el prog. World Circus (1987) y Think This (1989) son la cumbre; volvieron con Dis Morta (2022), algo por debajo. Entrada: Think This.", origin: "rec", pick: true },
  { name: "Forbidden", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Twisted into Form (1990): thrash con armonías vocales reales, arreglos que respiran y Paul Bostaph, luego en Slayer, en una batería muy por encima de la media del género. Forbidden Evil (1988) está cerca; los noventa bajan, y Omega Wave (2010) vuelve bien. El 23 de octubre sale Forbidden, su primer disco en dieciséis años. Entrada: Twisted into Form.", origin: "rec", pick: true },
  { name: "Bloodbath", genre: "Death Metal (SE)", y: 1998, p: 2, via: "Thrash/Death", desc: "Supergrupo sueco fundado por miembros de Katatonia, con Mikael Åkerfeldt a la voz al inicio y Nick Holmes, de Paradise Lost, desde 2014: death de la vieja escuela hecho por gente que normalmente compone prog. Nightmares Made Flesh (2004) es la cumbre. Entrada: Nightmares Made Flesh.", origin: "rec", pick: true },
  { name: "Martyr", genre: "Technical Death Metal (CA)", y: 1994, p: 1, via: "Thrash/Death", desc: "Death técnico de Quebec con Daniel Mongrain a la guitarra, luego guitarrista de Voivod, y su hermano François al bajo: armonía rarísima, riffs de raíz jazzística y compases cambiantes en la línea de Cynic y Atheist. Tres discos y los tres sobresalientes: Hopeless Hopes (1997), Warp Zone (2000) y Feeding the Abscess (2006). Entrada: Warp Zone.", origin: "rec", pick: true },
  { name: "Believer", genre: "Technical Thrash Metal", desc: "[Comodín] No es thrash con un violín de adorno al final: en Sanity Obscure (1990) hay una pieza con soprano clásica y cuarteto de cuerda encima del riff, y Dimensions (1993) abre con una suite de cámara de varios movimientos antes de que entre la banda, todo escrito para que las cuerdas lleven contrapunto contra la guitarra en vez de doblarla. El riff de fondo ya es técnico y de compás cambiante por su cuenta. Nadie más hizo esto en el thrash. Pero son esos dos discos: el debut, Extraction from Mortality (1989), es thrash más corriente, y la vuelta con Gabriel (2009) y Transhuman (2011) baja. Entrada: Sanity Obscure.", origin: "rec", p: 2, y: 1986, c: 3 },
  { name: "Spiral Architect", genre: "Progressive Death Metal (NO)", desc: "Un solo disco, A Sceptic's Universe (2000): compases que cambian sin parar, estructuras que no se repiten y polirritmias con contrapunto real, con Asgeir Mickelson guiando los cambios a la batería y Lars Norberg tocando líneas de bajo independientes, en la línea de Watchtower cruzado con Psychotic Waltz. La voz de Øyvind Hægeland es un gusto adquirido. Entrada: A Sceptic's Universe.", origin: "rec", p: 2, y: 1993, c: 2 },
  { name: "Incantation", genre: "Death Metal", y: 1989, p: 2, via: "Thrash/Death", desc: "Death cavernoso que alterna blast beats con doom arrastrado dentro de la misma canción, con riffs que suenan grabados dentro de una cueva. Onward to Golgotha (1992), Mortal Throne of Nazarene y Diabolical Conquest (1998) son la cumbre; lo posterior es desigual, con buenos momentos en Vanquish in Vengeance (2012) y Unholy Deification (2023). Entrada: Onward to Golgotha.", origin: "rec", pick: true },
  { name: "Terrorizer", genre: "Grindcore / Death Metal", y: 1986, p: 3, via: "Thrash/Death", desc: "World Downfall (1989): un solo disco esencial de grindcore, grabado con Pete Sandoval, luego en Morbid Angel, definiendo lo que significaba rápido en 1989. Los discos de la vuelta quedan muy por debajo. Entrada: World Downfall.", origin: "rec", pick: true },
  { name: "Deicide", genre: "Death Metal", y: 1987, p: 4, via: "Thrash/Death", desc: "Pionero indiscutible, pero formulaico y construido sobre el shock mas que sobre la musica; no evoluciona entre discos. Va al nivel de contexto junto a Cannibal Corpse. Su unico gancho real es Steve Asheim en la bateria. Entrada: Legion.", origin: "rec", pick: true },

  // ----- GUITARRA INSTRUMENTAL -----
  { name: "Dixie Dregs", genre: "Prog Rock / Fusion", y: 1970, p: 1, c: 1, via: "Guitarra instrumental", desc: "Instrumental entero, sin una sola voz, mezclando bluegrass, prog, fusión y música clásica dentro del mismo tema, con violín y guitarra turnándose la melodía y una sección rítmica que cambia de estilo por debajo. What If, Dregs of the Earth y Free Fall funcionan igual. Entrada: What If.", origin: "rec", pick: true },
  { name: "Shawn Lane", genre: "Jazz Fusion / Instrumental", y: 1985, p: 2, c: 1, via: "Guitarra instrumental", desc: "Una velocidad a la guitarra casi sin comparación, pero eso es lo de menos: lo que importa son los ritmos búlgaros e indios y la microtonalidad, sobre todo en el trío con el bajista Jonas Hellborg y el batería Jeff Sipe, que suena mejor que su obra en solitario. Murió en 2003, a los 40. Entrada: Temporal Analogues of Paradise (1996, con Hellborg y Sipe).", origin: "rec", pick: true },
  { name: "Freak Kitchen", genre: "Prog Metal (SE)", y: 1992, p: 2, c: 1, via: "Guitarra instrumental", desc: "Metal progresivo sueco con humor negro: Mattias IA Eklundh escribe riffs en compases impares con cuartos de tono y fraseo derivado del konnakol indio, así que la guitarra suena rítmica y descolocada a la vez. Técnica extrema al servicio de canciones raras, no del lucimiento. Entrada: Land of the Freaks.", origin: "rec", pick: true },
  { name: "Allan Holdsworth", genre: "Jazz Fusion / Instrumental", y: 1969, p: 1, via: "Guitarra instrumental", desc: "Construye los solos con escalas simétricas y acordes de más de cuatro notas que no pertenecen a la tonalidad de la base, y el legato es tan continuo que no se oye el ataque de cada nota: suena más a viento que a guitarra. Lo sostiene de I.O.U. (1982) a Metal Fatigue, Atavachron, Sand, Secrets, Hard Hat Area y The Sixteen Men of Tain (2000), y también en su etapa con Soft Machine y Bruford. Quedan fuera Velvet Darkness (1977), que él mismo repudió, y Flat Tire (2001), más flojo. Entrada: Metal Fatigue.", origin: "rec", pick: true },
  { name: "Jason Becker", genre: "Neoclassical / Instrumental", desc: "Su ficha era estuvo en Cacophony con Marty Friedman (personal) y su historia con la ELA (biografía), sin una palabra de cómo suena, y su historia es admirable pero no es un criterio musical. Cómo suena, en dos etapas muy distintas: Perpetual Burn es shred neoclásico de 1988, arpegios barridos a velocidad extrema sobre armonía menor armónica, o sea virtuosismo como fin, igual que Planet X. Lo posterior, dictado nota a nota con los ojos, es otra cosa: piezas orquestales con arreglo de cuerda y desarrollo temático real, y ahí sí hay composición. Entra por Triumphant Hearts antes que por Perpetual Burn.", origin: "rec", p: 2, y: 1986, c: 2 },
  { name: "Guthrie Govan", genre: "Jazz Fusion / Instrumental", y: 2006, p: 2, via: "Guitarra instrumental", desc: "El guitarrista de The Aristocrats en solitario: Erotic Cakes (2006), su único disco propio, es una clase magistral de fusión con sentido del humor, del jazz-rock al funk y el metal. Entrada: Erotic Cakes.", origin: "rec", pick: true },
  { name: "Panzerballett", genre: "Jazz Metal (DE)", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Jazz metal alemán de Jan Zehrfeld: riffs de djent y metal en compases imposibles, saxo, guitarra y batería en unísonos rapidísimos y armonía de jazz, con temas ajenos, de ABBA a estándares de jazz o Meshuggah, reescritos hasta volverse otra cosa. Muy parejos: Starke Stücke (2008), Tank Goodness (2012), Breaking Brain, Planet Z (2020) y Übercode Œuvre (2025), con varios baterías invitados, de Virgil Donati a Marco Minnemann y Anika Nilles. Entrada: Tank Goodness.", origin: "rec", pick: true },
  { name: "Tribal Tech", genre: "Jazz Fusion", y: 1984, p: 2, via: "Guitarra instrumental", desc: "Scott Henderson toca la guitarra desde el blues pero sale de la tonalidad a cada frase, Gary Willis lleva el bajo fretless como segunda voz y Kirk Covington la batería con fraseo de jazz y peso de rock. Muy parejos durante toda su obra, de Dr. Hee (1987) a Illicit (1992), Reality Check (1995), Thick (1999), improvisado casi entero en el estudio, y X (2012). Entrada: Illicit.", origin: "rec", pick: true },
  { name: "Béla Fleck and the Flecktones", genre: "Jazz Fusion / Bluegrass", desc: "Béla Fleck toca líneas de bebop en un banjo de cinco cuerdas, un instrumento que no está pensado para esa armonía, y Victor Wooten al bajo usa doble pulgar y slap melódico para llevar contramelodías en vez de acompañar. Es virtuosismo enorme sobre estructuras de fusión bastante convencionales y con groove accesible, y ahí está el techo comparado con Mahavishnu o Weather Report. Los dos primeros discos (1990-1991) y Outbound (2000) son lo mejor. Entrada: Flight of the Cosmic Hippo.", origin: "rec", p: 2, y: 1988, c: 2 },
  { name: "Blotted Science", genre: "Technical Death / Instrumental", desc: "[Comodín] Metal instrumental sin una sola voz, con riffs atonales y angulares que no resuelven nunca donde esperas, cambios de compás continuos y el bajo de Alex Webster haciendo líneas propias en vez de doblar la guitarra. Es denso y agotador de seguir, en el buen sentido. Lo compuso Ron Jarzombek, de Watchtower, con un sistema de doce tonos propio. The Machinations of Dementia (2007) y el EP The Animation of Entomology (2011). Entrada: The Machinations of Dementia.", origin: "rec", p: 2, y: 2007, c: 3 },
  { name: "Michael Manring", genre: "Jazz Fusion / Instrumental", y: 1986, p: 2, c: 3, via: "Guitarra instrumental", desc: "[Comodín] Cambia la afinación de las cuerdas mientras toca, así que la armonía se mueve por debajo de una nota que sigue sonando: un solo bajo haciendo melodía, bajo y armonía a la vez, sin overdubs. Entrada: Soliloquy.", origin: "rec", pick: true },
  { name: "Stick Men", genre: "Prog Rock / Instrumental", y: 2007, p: 2, via: "Guitarra instrumental", desc: "Tony Levin (King Crimson) al Chapman Stick, Pat Mastelotto (King Crimson) a la bateria y Markus Reuter al touch guitar. Instrumentos de tapping que cubren bajo y armonia a la vez: el trio suena como un sexteto. Entrada: Deep.", origin: "rec", pick: true },
  // ----- AÑADIDOS POR PETICIÓN DE KEN -----
  { name: "Spawn of Possession", genre: "Technical Death Metal (SE)", y: 1997, p: 1, via: "Thrash/Death", desc: "Death técnico sueco de riffs laberínticos y tono neoclásico que se pliegan sobre sí mismos, sin caer en la velocidad por la velocidad. Tres discos y los tres sobresalientes: Cabinet (2003), Noctambulant (2006) e Incurso (2012), su obra maestra; cuatro de sus miembros siguieron en 2024 como Retromorphosis. Entrada: Incurso.", origin: "rec", pick: true },
  { name: "Retromorphosis", genre: "Technical Death Metal (SE)", y: 2024, p: 2, via: "Thrash/Death", desc: "La continuación real de Spawn of Possession: cuatro de los cinco miembros de su formación final se reagruparon en 2024 bajo este nombre, y Psalmus Mortis (2025) retoma justo donde quedó Incurso. Entrada: Psalmus Mortis.", origin: "rec", pick: true },
  { name: "Dying Fetus", genre: "Brutal Technical Death", y: 1991, p: 2, via: "Thrash/Death", desc: "John Gallagher compone toda la música y su estilo de riff es de los más reconocibles y técnicos del death brutal: figuras de groove con desplazamientos que cambian de subdivisión dentro del compás, con el bajo siguiéndolas nota a nota y una batería muy técnica. La fórmula es estable, pero el nivel sube con los años: Destroy the Opposition (2000) y Stop at Nothing son la base, y Reign Supreme (2012), Wrong One to Fuck With (2017) y Make Them Beg for Death (2023) son la cumbre. Entrada: Reign Supreme.", origin: "rec", pick: true },
  { name: "Consider the Source", genre: "Prog Fusion / Instrumental", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Trío instrumental de Nueva York: guitarra de doble mástil sin trastes tocando escalas árabes y turcas con cuartos de tono sobre estructuras de prog y fusión, con bajo y batería en compases impares. World War Trio, publicado en tres partes, es su obra más ambiciosa. Entrada: World War Trio.", origin: "rec", pick: true }
];

// ===========================================================================
// === INSTRUMENTISTAS Y COMPOSITORAS (ago 2026) =============================
// Eje distinto al de "voz femenina": aquí la mujer ES la sustancia
// instrumental o compositiva. Todas justificadas por el instrumento, la
// técnica o el sistema de composición, nunca por quién es.
// ===========================================================================
const INSTRUMENTISTAS = [
  { name: "Hiromi", genre: "Jazz Fusion (JP)", y: 1999, p: 1, via: "Mujeres instrumentistas", desc: "Pianista y compositora que cruza stride, post-bop, rock progresivo, clásica y fusión dentro de una misma pieza, con técnica descomunal. En el Trio Project, con Anthony Jackson al bajo de seis cuerdas y Simon Phillips a la batería, los tres instrumentos son protagonistas, y con Sonicwonder cambió a un cuarteto con trompeta y electrónica: Sonicwonderland (2023) y Out There (2025). Muy pareja disco a disco. Entrada: Move, o Alive.", origin: "rec", pick: true, female: true },
  { name: "Jlin", genre: "Electronic / Experimental", y: 2011, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Salió del footwork de Chicago y lo convirtió en composición: polirritmias de percusión programada que se superponen y se desplazan, con la complejidad rítmica como materia prima. Perspective, escrita para el ensamble Third Coast Percussion, fue finalista del Pulitzer de música en 2023; Black Origami (2017) y Akoma (2024), con Björk y Philip Glass, son sus discos. Es electrónica pura, sin instrumento tocado. Entrada: Black Origami, luego Akoma.", origin: "rec", pick: true, female: true },
  { name: "Mary Halvorson", genre: "Avant-garde Jazz / Guitar", y: 2002, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Guitarrista de jazz de sonido propio: púa percusiva, saltos de cuerda y un pedal de delay manipulado como pitch-shifter, así que las notas se doblan y se tuercen a mitad, con escritura para sexteto y octeto llena de contrapunto. Amaryllis y Belladonna (2022) y Cloudward (2024). Entrada: Amaryllis.", origin: "rec", pick: true, female: true },
  { name: "Sarah Longfield", genre: "Prog / Instrumental", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Guitarrista de ocho cuerdas con enfoque pianístico: tapping a dos manos que usa el mástil como un teclado, con línea de bajo y melodía a la vez sobre base djent. Disparity (2018) es donde mejor se oye. Entrada: Disparity.", origin: "rec", pick: true, female: true },
  { name: "Anika Nilles", genre: "Jazz Fusion / Prog", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Baterista y compositora alemana; su banda Nevell hace fusión de jazz, funk y prog escrita por ella, construida sobre polirritmias (3 contra 4, 4 contra 3) usadas como material compositivo y no como adorno. Tres discos: Pikalar (2017), For a Colorful Soul (2020) y False Truth (2025). Tocó con Jeff Beck y es la baterista de la gira de regreso de Rush en 2026. Entrada: For a Colorful Soul.", origin: "rec", pick: true, female: true },
  { name: "Anna Meredith", genre: "Electronic / Art Pop (UK)", desc: "Compositora escocesa de formación clásica (escribió para la BBC Symphony antes de esto) que se pasó a la electrónica sin dejar de componer como compositora: FIBS son cuarenta y cinco minutos donde la métrica se reinventa casi en cada sección, con clarinete, tuba, chelo y sintetizadores entrando y saliendo como voces de una partitura en vez de como capas de producción. Nominada al Mercury por FIBS, y Varmints ganó el Scottish Album of the Year por delante de Franz Ferdinand y Chvrches. Entra por FIBS.", origin: "rec", p: 1, y: 2012, c: 1 },
  { name: "Lucrecia Dalt", genre: "Experimental / Electronic (CO)", y: 2005, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Colombiana, de las artistas experimentales más respetadas del momento: electrónica, bolero y percusión trabajados como textura y ritmo, con la voz casi hablada. ¡Ay! (2022) fue disco del año para The Wire, y A Danger to Ourselves (2025) lo construyó con el percusionista Alex Lázaro sobre la interacción de líneas de bajo, ritmos y textura. Entrada: ¡Ay!", origin: "rec", pick: true, female: true },
  { name: "Wendy Carlos", genre: "Synth / Electronic", y: 1968, p: 1, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Buscando sistemáticamente picos de consonancia fuera del temperamento occidental dio con tres escalas que NO se repiten a la octava, alfa, beta y gamma; las usó en Beauty in the Beast (1986) y suenan genuinamente ajenas, porque la referencia armónica que el oído espera no existe. Antes de eso, Switched-On Bach: mil cien horas grabando cada voz por separado en un Moog monofónico y montándolas a mano, dando expresión línea a línea en vez de teclear acordes. Compuso para La Naranja Mecánica, El Resplandor y Tron. Entrada: Switched-On Bach, luego Beauty in the Beast.", origin: "rec", pick: true, female: true },
  { name: "Delia Derbyshire", genre: "Experimental / Electronic", y: 1962, p: 3, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Creó el tema de Doctor Who en 1963 cortando y empalmando cinta a mano, midiendo longitudes físicas, antes de que existieran los sintetizadores comerciales: electrónica de osciladores y montaje, con melodías y ritmos que suenan mucho más modernos que su fecha. Su obra es fragmentaria, sobre todo música para la BBC; el único disco propiamente dicho es An Electric Storm (1969), de White Noise. Entrada: An Electric Storm.", origin: "rec", pick: true, female: true },
  { name: "Kylesa", genre: "Sludge / Psych Metal", y: 2001, p: 2, via: "Mujeres instrumentistas", desc: "Sludge de Savannah con dos baterías a la vez, abiertas a izquierda y derecha en la mezcla, y Laura Pleasants a la guitarra y la voz junto a Phillip Cope. Static Tensions (2009) y Spiral Shadow (2010) son la cumbre; tras un parón desde 2016 volvieron a los escenarios en 2025. Entrada: Spiral Shadow.", origin: "rec", pick: true, female: true },
  { name: "Zeena Parkins", genre: "Avant-garde / Experimental", y: 1984, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Toca el arpa fuera de todo lo que se supone que hace: estira las cuerdas más allá de su rango para doblar la afinación, las prepara con objetos y las enruta por procesamiento analógico y digital, pasando de texturas delicadas a retroalimentación distorsionada dentro de una misma pieza. Improvisación libre, no repertorio. Ha trabajado con Björk y Anthony Braxton. Entrada: The Adorables.", origin: "rec", pick: true, female: true },
  { name: "Kali Malone", genre: "Clásica moderna / Órgano (US)", y: 2014, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Compone para órgano de tubos con sistemas de afinación históricos y entonación justa, reinterpretando métodos de polifonía de hace siglos: acordes que cambian muy despacio y batimientos entre voces que se oyen como ritmo. The Sacrificial Code (2019) y Does Spring Hide Its Joy (2023), este con Stephen O'Malley a la guitarra y Lucy Railton al chelo. Entrada: The Sacrificial Code.", origin: "rec", pick: true, female: true },
  { name: "Ikue Mori", genre: "Experimental / Electronic", y: 1977, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Montó DNA, banda clave del no-wave, con una batería completamente propia: kit mínimo, todo el peso en los toms, patrones entrecortados pero propulsivos. Luego improvisó con cajas de ritmos y encontró cómo hacerlas sonar rotas quitándoles la cuantización, y hacia 2000 pasó al portátil. Lleva décadas colaborando con John Zorn.", origin: "rec", pick: true, female: true },
  { name: "Terri Lyne Carrington", genre: "Jazz / Fusion", y: 1989, p: 2, via: "Mujeres instrumentistas", desc: "Baterista, compositora y productora, no solo intérprete: cuatro Grammys, NEA Jazz Master, y fundó el Berklee Institute of Jazz and Gender Justice. The Mosaic Project (2011), Money Jungle: Provocative in Blue (2013) y Waiting Game (2019) son lo mejor; We Insist 2025!, con Christie Dashiell, reimagina la Freedom Now Suite de Max Roach y estuvo nominado al Grammy de 2026. Entrada: The Mosaic Project.", origin: "rec", pick: true, female: true },
  { name: "Divide and Dissolve", genre: "Doom Metal / Instrumental (AU)", y: 2015, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Takiaya Reed toca saxofón y guitarra y Sylvie Nehill la batería: doom instrumental con el saxo como instrumento pesado, no como adorno jazzístico. Gas Lit (2021) e Insatiable (2023). Entrada: Gas Lit.", origin: "rec", pick: true, female: true },
  { name: "Hildur Guðnadóttir", genre: "Clásica moderna / Chelo (IS)", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Chelista de formación clásica cuya obra se construye desde el chelo: capas de chelo procesado, drones y voz en piezas lentas de mucha densidad armónica. Antes de las bandas sonoras tocó y grabó con Sunn O))), Throbbing Gristle, Pan Sonic y Múm, así que viene del drone y lo industrial. Without Sinking (2009), Saman y las bandas sonoras de Chernobyl y Joker (2019). Entrada: Without Sinking.", origin: "rec", pick: true, female: true },
  { name: "Esperanza Spalding", genre: "Jazz Fusion / Prog", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Bajista, compositora y vocalista: canta mientras toca líneas de contrabajo y bajo eléctrico que van por su cuenta. Emily's D+Evolution (2016) es un disco conceptual de prog angular con guitarra eléctrica, fusión rítmicamente densa y cambios de acorde poco ortodoxos, lo más complejo de su obra. Entrada: Emily's D+Evolution.", origin: "rec", pick: true, female: true },
  { name: "Kaki King", genre: "Instrumental / Math Rock", y: 2003, p: 2, via: "Mujeres instrumentistas", desc: "Guitarrista que viene de la batería y usa la guitarra como instrumento rítmico: la toca plana sobre el regazo, con tapping a dos manos y golpes percusivos sobre la caja, así que melodía, bajo y percusión salen a la vez del mismo instrumento. Legs to Make Us Longer (2004) es donde esa escritura sale más clara; después se abre a banda, lap steel y piezas audiovisuales. Entrada: Legs to Make Us Longer.", origin: "rec", pick: true, female: true },
  { name: "Meshell Ndegeocello", genre: "Jazz / Soul / Funk", y: 1993, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Bajista, compositora y productora con una carrera que ha cambiado de piel muchas veces, del funk y el neo soul de Plantation Lullabies (1993) a Comet, Come to Me y sus discos de Blue Note, y muy pareja en todas. The Omnichord Real Book (2023) ganó el primer Grammy al mejor disco de jazz alternativo: doble, sin género fijo, entre neo soul, funk, afrobeat, hip-hop y experimental. Le siguió No More Water: The Gospel of James Baldwin (2024), y el 2 de octubre sale Synonym, un disco de duetos. Entrada: The Omnichord Real Book.", origin: "rec", pick: true, female: true },
  { name: "BIG|BRAVE", genre: "Experimental / Sludge Metal (CA)", y: 2012, p: 2, via: "Mujeres instrumentistas", desc: "Robin Wattie a la guitarra y la voz en un trío de Montreal que hace metal hipnótico y monolítico cruzado con drone y folk. Vital (2021) y nature morte (2023) son la cumbre; en 2025 sacaron OST, improvisado e instrumental, y en junio de 2026 in grief or in hope, un disco sin batería construido sobre armónicos y amplificadores. Entrada: Vital.", origin: "rec", pick: true, female: true },
  { name: "Crypta", genre: "Death Metal (BR)", y: 2019, p: 3, via: "Mujeres instrumentistas", desc: "Death metal brasileño fundado por Fernanda Lira, al bajo y la voz, y Luana Dametto, a la batería, ambas ex de Nervosa. Dos discos sólidos y bien recibidos, competentes pero dentro de la plantilla del género. Entrada: Shades of Sorrow.", origin: "rec", pick: true, female: true }
];

// ===========================================================================
// === BARRIDO ANCESTRAL Y DE CONTENEDORES (ago 2026) ========================
// Encontrado con el método nuevo: en vez de preguntar "que saco esta banda",
// enumerar ancestros de los tier 1, sellos, productores, festivales, premios
// y escenas, y cruzar hacia atras. Saco ~215 ausentes; esto es lo que pasa
// el filtro #1. Lote 1.
// ===========================================================================
const ANCESTROS = [
  // ----- LOS ANCESTROS DE TUS TIER 1 -----
  { name: "Queen", genre: "Art Rock / Hard Rock", desc: "Brian May graba capas de guitarra armonizadas entre sí para imitar una sección de metales o una orquesta, escribiendo cada voz por separado, y las canciones encadenan secciones sin volver al estribillo. The Prophet's Song lleva un canon vocal a varias voces hecho solo con la voz de Mercury superpuesta. Y reinventaban de disco a disco: ópera, funk, rockabilly, synth-pop, gospel. Entra por A Night at the Opera, luego Jazz.", origin: "rec", p: 1, y: 1970, c: 1 },
  { name: "Miles Davis", genre: "Jazz Fusion", y: 1955, p: 1, c: 1, via: "Ancestros", desc: "Cambió de sistema cinco veces y en cada uno escribió algo que antes no existía: el nonet de Birth of the Cool, el quinteto de hard bop, Kind of Blue montado sobre modos en vez de sobre cambios de acorde, el segundo quinteto tocando sin cifrado fijo, y Bitches Brew grabado como improvisación larga y armado después en la mesa de edición. De 1955 a 1975 casi no hay disco flojo, On the Corner incluido; los de los ochenta, de Decoy y You're Under Arrest a Tutu, Amandla y Doo-Bop, bajan mucho. Entrada: Kind of Blue, luego Bitches Brew.", origin: "rec", pick: true },
  { name: "Celtic Frost", genre: "Avant-garde Metal / Thrash (CH)", desc: "Into the Pandemonium (1987) metió orquesta completa, soprano, timbales y cuerdas en un disco de metal extremo, más una versión de new wave y percusión tribal, cuando eso no se hacía. Tom G. Warrior lo explicó así: odiaban los límites no escritos de la escena metal. Y no es solo el arreglo: los riffs van a medios tiempos pesadísimos con acentos desplazados y su famoso golpe de voz corta la frase en sitios raros. To Mega Therion (1985) es la otra cumbre, y Monotheist (2006) volvió a cambiarlo todo otra vez. La excepción es Cold Lake (1988), un giro al glam que el propio Warrior repudió. Entrada: Into the Pandemonium, luego To Mega Therion.", origin: "rec", p: 1, y: 1984, c: 1 },
  { name: "Bathory", genre: "Black Metal / Viking Folk (SE)", desc: "Tempos lentos y machacones, coros épicos de una sola voz multiplicada, pasajes acústicos entre medias y una grabación cruda a propósito, hecha casi entera por una sola persona. Es enorme de atmósfera y deliberadamente primitivo de ejecución. Entra por Hammerheart.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "Can", genre: "Krautrock / Experimental (DE)", y: 1968, p: 2, c: 1, via: "Ancestros", desc: "El krautrock más rítmico: Jaki Liebezeit tocaba un kit de jazz casi solo de toms y caja, en patrones hipnóticos que apenas cambian, y sobre ellos el bajo de Holger Czukay y la guitarra de Michael Karoli improvisan y se montan después en la edición de cinta. Monster Movie (1969), Tago Mago, Ege Bamyasi, Future Days y Soon Over Babaluma (1974) son cinco discos seguidos de primer nivel; desde Flow Motion (1976) la escritura se diluye hacia un rock más convencional y lo de 1977 a 1989 es lo más flojo. Entrada: Tago Mago, luego Future Days.", origin: "rec", pick: true },
  { name: "Killing Joke", genre: "Post-Punk / Industrial (UK)", y: 1978, p: 1, c: 1, via: "Ancestros", desc: "Acordes abiertos de guitarra repetidos como un solo gesto sobre un bajo que lleva la melodía y una batería casi tribal: la canción avanza por presión acumulada y no por progresión de acordes. Y lo han sostenido cuarenta años, del post-punk metálico del debut de 1980 al disco de 2003 y a Pylon (2015). Geordie Walker murió en 2023. Entrada: Killing Joke (1980).", origin: "rec", pick: true },
  { name: "Led Zeppelin", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Ancestros", desc: "John Bonham toca detrás del pulso con un sonido de bombo enorme y un pie derecho que hace tresillos rapidísimos con un solo pedal, y su forma de colocar el golpe es de las más estudiadas que existen; John Paul Jones toca bajo, teclados y mandolina, y escribe los arreglos. Y los discos son más raros de lo que su fama sugiere: el III es folk acústico y Houses of the Holy tiene funk y reggae. Entrada: Physical Graffiti.", origin: "rec", pick: true },
  { name: "Motörhead", genre: "Heavy Metal / Speed (UK)", y: 1975, p: 2, via: "Ancestros", desc: "El puente entre punk y metal del que sale el thrash: velocidad, el bajo distorsionado de Lemmy tocado como guitarra rítmica y el doble bombo de Phil Taylor. No es complejo, es inconfundible. Lemmy murió en diciembre de 2015 y el grupo terminó ahí. Entrada: Ace of Spades, luego Overkill.", origin: "rec", pick: true },
  { name: "Possessed", genre: "Death / Thrash Metal", y: 1983, p: 2, via: "Ancestros", desc: "Seven Churches (1985) es, para mucha gente, el primer disco de death metal: thrash acelerado con voz gutural y riffs cromáticos que anticipan el género. Entrada: Seven Churches.", origin: "rec", pick: true },
  { name: "Wishbone Ash", genre: "Hard Rock (clásico)", y: 1969, p: 2, via: "Ancestros", desc: "Inventaron la armonía de guitarras gemelas: dos guitarras solistas tocando líneas armonizadas en lugar de una solista y una rítmica, la técnica que luego definen Thin Lizzy e Iron Maiden. Argus (1972) es el disco donde queda establecida. Entrada: Argus.", origin: "rec", pick: true },
  { name: "Blue Öyster Cult", genre: "Hard Rock (clásico)", y: 1967, p: 2, c: 1, via: "Ancestros", desc: "Rock ocultista con letras crípticas y conceptos de ciencia ficción, mucho más raro y literario de lo que su fama de banda de un solo éxito sugiere; Ghost viene directamente de aquí. Imaginos es un disco conceptual delirante. Entrada: Secret Treaties.", origin: "rec", pick: true },
  { name: "Mayhem", genre: "Black Metal (NO)", y: 1984, p: 2, via: "Ancestros", desc: "Black metal noruego en su forma definitiva: De Mysteriis Dom Sathanas (1994) tiene la batería de Hellhammer con blast beats de precisión casi mecánica y riffs de trémolo disonantes, y los discos posteriores se fueron a terrenos más raros: Grand Declaration of War (2000) y Ordo ad Chao (2007), experimentales, Esoteric Warfare y Daemon, más clásicos, y Liturgy of Death (2026). Entrada: De Mysteriis Dom Sathanas.", origin: "rec", pick: true },
  { name: "Darkthrone", genre: "Black Metal (NO)", y: 1986, p: 2, c: 1, via: "Ancestros", desc: "Pilar del black noruego que además muta de verdad: empezaron como death metal técnico en Soulside Journey (1991), se pasaron al black más crudo posible en A Blaze in the Northern Sky, Under a Funeral Moon y Transilvanian Hunger (1994), y desde The Cult Is Alive (2006) hacen crust y heavy metal setentero. Pocas discografías cambian tanto de piel. Entrada: A Blaze in the Northern Sky.", origin: "rec", pick: true },
  { name: "Melvins", genre: "Sludge / Experimental", desc: "Cómo suenan: riffs bajísimos tocados a tempos absurdamente lentos y estirados hasta incomodar, con Dale Crover haciendo de batería una parte protagonista y no una base, y una discografía que salta del drone más pesado al punk más rápido y a discos de puro ruido, a veces dentro del mismo álbum. Sacaron disco conjunto con Napalm Death en 2026. Entra por Bullhead, luego Lysol.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "My Bloody Valentine", genre: "Shoegaze / Dream Pop (IE)", y: 1983, p: 2, via: "Ancestros", desc: "Kevin Shields inventó la técnica de glide guitar, tocando con la palanca de trémolo durante todo el acorde para que suene desafinado y líquido, y la usó para apilar capas hasta que la guitarra se vuelve textura. Tres discos: Isn't Anything (1988), Loveless (1991), la cumbre, y m b v (2013), veintidós años después. De ahí salen el blackgaze y parte del sonido de Deftones. Entrada: Loveless.", origin: "rec", pick: true },
  { name: "Sonic Youth", genre: "Noise Rock / Experimental", y: 1981, p: 2, c: 1, via: "Ancestros", desc: "Guitarras en afinaciones alternativas inventadas canción a canción, preparadas con baquetas y destornilladores, que suenan a disonancias abiertas y a feedback controlado en vez de acordes, sobre la batería de Steve Shelley. EVOL (1986), Sister, Daydream Nation (1988) y Goo son la cumbre; lo posterior alterna discos notables como Murray Street con otros más rutinarios. Entrada: Daydream Nation.", origin: "rec", pick: true },
  { name: "The Velvet Underground", genre: "Art Rock / Experimental", y: 1965, p: 3, c: 1, via: "Ancestros", desc: "La viola eléctrica con drone de John Cale, que venía de la vanguardia minimalista, metida dentro de canciones de rock en 1967, con la batería de Moe Tucker de pie y sin platillos marcando un pulso primitivo. The Velvet Underground & Nico y White Light/White Heat (1968), con los diecisiete minutos de ruido y repetición de Sister Ray, son lo radical; después se vuelven una banda de canciones. Su peso es más de influencia que de escritura instrumental. Entrada: White Light/White Heat.", origin: "rec", pick: true },
  { name: "Throbbing Gristle", genre: "Industrial / Experimental (UK)", y: 1975, p: 2, c: 1, via: "Ancestros", desc: "No hay canción: construyen con cinta, sintetizador y voz procesada sobre estructuras que no vuelven, y en 20 Jazz Funk Greats el disfraz de música ligera de ascensor es parte de la pieza, no una broma aparte. Cuatro discos de estudio y ninguno se parece al anterior. Escucha incómoda a propósito. Entrada: 20 Jazz Funk Greats.", origin: "rec", pick: true },
  { name: "Helmet", genre: "Alt Metal / Noise Rock", y: 1989, p: 2, via: "Ancestros", desc: "Page Hamilton venía del jazz y aplicó esa formación a riffs de una sola nota, staccato y con los silencios colocados como parte del ritmo: el groove está en lo que no suena. Strap It On, Meantime y Betty funcionan con la misma mecánica. Entrada: Meantime.", origin: "rec", pick: true },
  { name: "Funkadelic", genre: "Funk / Psych Rock", y: 1968, p: 2, c: 1, via: "Ancestros", desc: "Funk psicodélico con guitarras de rock: el solo de Eddie Hazel en Maggot Brain, diez minutos grabados de una sola toma, es de los grandes de la guitarra, y de aquí vienen OutKast, Thundercat y Flying Lotus. Entrada: Maggot Brain.", origin: "rec", pick: true },
  { name: "Fela Kuti", genre: "Afrobeat / Funk (NG)", y: 1969, p: 2, via: "Ancestros", desc: "Inventó el afrobeat cruzando ritmos africanos con improvisación de jazz: polirritmia, secciones de metales y desarrollos instrumentales de veinte y treinta minutos sobre la batería de Tony Allen. Brian Eno le presentó su música a Talking Heads y de ahí salió la polirritmia de Remain in Light. Entrada: Zombie.", origin: "rec", pick: true },
  { name: "Pentagram", genre: "Doom Metal", y: 1971, p: 3, via: "Ancestros", desc: "Proto-doom americano que grabó en los setenta sin publicar casi nada, y por eso su influencia llegó tarde. Riffs de Sabbath lentos y sencillos: más valor histórico que instrumental. Relentless (1985) y Day of Reckoning (1987). Entrada: Relentless.", origin: "rec", pick: true },
  { name: "Glenn Branca", genre: "Avant-garde / Experimental", y: 1979, p: 2, c: 3, via: "Ancestros", desc: "[Comodín] Compuso sinfonías para orquestas de guitarras eléctricas, cien de ellas en la 13 y la 16: el material no son acordes sino masas de armónicos que baten entre sí, con la afinación como parte de la composición y crescendos que se vuelven casi físicos. En sus grupos tocaron Thurston Moore y Lee Ranaldo, y su sello publicó los primeros discos de Swans. Entrada: The Ascension.", origin: "rec", pick: true },

  // ----- SELLOS, PRODUCTORES Y ESCENAS -----
  { name: "Zu", genre: "Avant-garde / Jazz Metal (IT)", y: 1997, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Trío romano de saxofón barítono, bajo y batería, sin guitarra: instrumentación de jazz con la agresión del metal extremo, todo instrumental, con bajo y saxo atacando riffs al unísono. Bromio (1999) y Carboniferous (2009), editado por Ipecac, son la cumbre. Entrada: Carboniferous.", origin: "rec", pick: true },
  { name: "Behold... The Arctopus", genre: "Prog / Instrumental", desc: "Metal instrumental de Brooklyn escrito con la lógica de la música clásica del siglo XX: sin voz, con Colin Marston a la Warr guitar cubriendo bajo y guitarra a la vez y motivos atonales superpuestos en métricas distintas, de una densidad brutal. Skullgrid (2007) es la referencia; Horrorscension (2012) se vuelve tan abstracto que cuesta seguirlo, y Cognitive Emancipation (2016) y Hapeleptic Overtrove (2020) recuperan parte del foco. Entrada: Skullgrid.", origin: "rec", p: 2, y: 2001, c: 2 },
  { name: "Amenra", genre: "Post-Metal / Sludge (BE)", y: 1999, p: 2, via: "Sellos y escenas", desc: "Post-metal belga y núcleo del colectivo Church of Ra: su serie de Masses construye cada tema por acumulación hasta el estallido, con la voz desgarrada de Colin H. van Eeckhout y pasajes casi en silencio. Mass V, Mass VI (2017) y De doorn (2021). Entrada: Mass VI.", origin: "rec", pick: true },
  { name: "Thinking Plague", genre: "Avant-garde / Chamber Rock", y: 1982, p: 2, via: "Sellos y escenas", desc: "RIO americano de Mike Johnson: música de cámara disonante con vientos, voz femenina y guitarra en contrapunto, en compases que no se asientan y con armonía cercana a la clásica del siglo XX. In This Life (1989), In Extremis (1998) y A History of Madness (2003) son la cumbre; los dos primeros y Decline and Fall quedan por debajo. Entrada: In Extremis.", origin: "rec", pick: true },
  { name: "Samla Mammas Manna", genre: "Avant-garde / Chamber Rock (SE)", y: 1969, p: 1, via: "Sellos y escenas", desc: "Uno de los cinco grupos del concierto fundacional del Rock in Opposition, en 1978: virtuosismo con referencias circenses y humor absurdo, comparado con la escritura de Zappa, con los teclados de Lars Hollmer y la guitarra de Coste Apetrea corriendo en unísonos rapidísimos sobre cambios de compás constantes e instrumentos raros en el rock. Samla Mammas Manna (1971), Måltid (1973), Klossa Knapitatet (1974) y los discos como Zamla Mammaz Manna sostienen ese nivel; Kaka (1999), la vuelta, baja algo. Entrada: Måltid.", origin: "rec", pick: true },
  { name: "Nik Bärtsch's Ronin", genre: "Jazz Fusion / Chamber (CH)", y: 2001, p: 2, via: "Sellos y escenas", desc: "Pianista suizo con un concepto propio que llama ritual groove music: piezas modulares numeradas, patrones entrelazados en compases pares e impares que se superponen y pulsos polimétricos. Minimalismo a lo Steve Reich con el groove de un grupo de funk. Stoa (2006), Holon (2008), Llyrìa (2010) y Awase (2018). Entrada: Stoa.", origin: "rec", pick: true },
  { name: "Virus", genre: "Avant-garde Metal (NO)", y: 2000, p: 2, via: "Sellos y escenas", desc: "Czral hizo primero Ved Buens Ende, black avant de acordes disonantes, y luego Virus para llevarlo más lejos del metal: guitarras disonantes y angulosas de la escuela del Voivod de Nothingface, un bajo protagonista que reclama atención constante y su voz grave. Carheart (2003), The Black Flux, The Agent That Shapes the Desert (2011) y Memento Collider (2016). Entrada: Carheart.", origin: "rec", pick: true },
  { name: "Pyrrhon", genre: "Dissonant Death Metal", y: 2008, p: 2, via: "Sellos y escenas", desc: "Death disonante de Brooklyn, comparable a Gorguts y Ulcerate pero con más grindcore y math rock encima, con la batería y la guitarra de Dylan DiLella tirando cada una por su lado. De The Mother of Virtues (2014) a What Passes for Survival, Abscess Time y Exhaust (2024), cada disco más extremo. Entrada: The Mother of Virtues.", origin: "rec", pick: true },
  { name: "Ad Nauseam", genre: "Dissonant Death Metal (IT)", desc: "La guitarra derecha y la izquierda viven bajo ritmos distintos y se cortan mutuamente a través de los compases, unificándose solo en los clímax, con una afinación propia para alejarse de los patrones melódicos habituales y una armonía que se oye heredera de Stravinsky, Xenakis, Scelsi y Ligeti. Dos discos, Nihil Quam Vacuitas Ordinatum Est (2015) e Imperative Imperceptible Impulse (2021), el mejor. Durísimo de escuchar. Entrada: Imperative Imperceptible Impulse.", origin: "rec", p: 1, y: 2011, c: 2 },
  { name: "Il Balletto di Bronzo", genre: "Prog Rock (IT)", y: 1969, p: 2, via: "Sellos y escenas", desc: "Tienes Banco y Area en ① y faltaba el lado negro del prog italiano. Ys (1972) es uno de los rarisimos ejemplos de prog italiano oscuro: Gianni Leone, descrito como una especie de Keith Emerson italiano, teje una trama opresiva y claustrofobica con organo, moog, mellotron y espineta. Entrada: Ys.", origin: "rec", pick: true },
  { name: "Motorpsycho", genre: "Prog Rock / Psych (NO)", y: 1989, p: 2, c: 1, via: "Sellos y escenas", desc: "Veintiocho discos y rara vez pasan dos anos sin material nuevo, saltando de psych pesado a prog a hard rock setentero. Su homonimo de 2025 es doble y una resena lo llamo el mejor disco progresivo del ano; en febrero de 2026 sacaron The Gaia II Space Corps. Antes, la trilogia The Tower / The Crucible / The All Is One. Entrada: The Tower.", origin: "rec", pick: true },
  { name: "Shakti", genre: "Jazz Fusion (IN)", desc: "Fusión indo-británica de John McLaughlin con L. Shankar al violín y Zakir Hussain a la tabla. Todo va montado sobre talas, los ciclos rítmicos indios de siete, nueve o más tiempos, y el violín y la guitarra se turnan frases construidas sobre esos ciclos, con pasajes de konnakol (percusión recitada con la voz) marcando la subdivisión antes de tocarla. Es de lo rítmicamente más complejo del catálogo entero, y lo sostienen desde los tres discos de los setenta hasta This Moment (2023), su primer disco de estudio en 46 años. Zakir Hussain murió en diciembre de 2024 y McLaughlin dio el grupo por terminado; Mind Explosion (2025), grabado en la gira del 50 aniversario, es el cierre. Entrada: A Handful of Beauty.", origin: "rec", p: 1, y: 1973, c: 2 },
  { name: "Konono Nº1", genre: "Experimental / Funk (CD)", y: 1966, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Tres likembes congoleños repartidos en grave, medio y agudo tocan patrones cortos que se repiten y se desfasan entre sí, así que la música avanza por el roce entre las tres capas y no por acordes, sobre percusión de ollas, sartenes y piezas de coche. Y la decisión que lo define: adoptaron como material las distorsiones que su propio equipo producía sin querer. Entrada: Congotronics.", origin: "rec", pick: true },

  // ----- LA DECADA QUE FALTABA: 2020s -----
  { name: "The Callous Daoboys", genre: "Mathcore / Avant-garde", y: 2016, p: 2, via: "Escena 2020s", desc: "Mathcore con violinista fundadora (Amber Christman) y saxofon (Rich Castillo) dentro de la formacion, no de invitados. I Don't Want to See You in Heaven (mayo 2025) los llevo a estatus casi legendario y a muchas listas de disco del ano. Es la linea Dillinger, Fall of Troy y Number Twelve actualizada, con instrumentacion ampliada. Entrada: Celebrity Therapist.", origin: "rec", pick: true },
  { name: "Slift", genre: "Psych Rock / Prog (FR)", y: 2016, p: 2, via: "Escena 2020s", desc: "Trío francés que cruza psych, space rock y stoner con la escala épica del post-rock: riffs repetidos hasta el trance, guitarras con delay en capas y una batería que empuja sin parar. Ummon (2020) e Ilion (2024), editado por Sub Pop, son su cumbre; Fantasia (2026) se recibió más tibio. Entrada: Ilion.", origin: "rec", pick: true },
  { name: "Green Carnation", genre: "Progressive Metal (NO)", y: 1990, p: 2, via: "Escena 2020s", desc: "Noruegos que pasaron del doom a un prog metal de estructuras largas: Light of Day, Day of Darkness (2001) es una sola pieza de sesenta minutos que alterna coros, metal y pasajes acústicos sin perder el hilo. Ahora publican una trilogía entera, A Dark Poem, con Shores of Melancholia (2025) y Sanguis (2026) en Season of Mist. Entrada: Light of Day, Day of Darkness.", origin: "rec", pick: true },
  { name: "Kardashev", genre: "Progressive Deathcore", y: 2012, p: 2, via: "Escena 2020s", desc: "Inventaron lo que llaman deathgaze: deathcore atmosferico cruzado con shoegaze, con dinamica real entre lo brutal y lo etereo. Alunea (abril 2026, Metal Blade) es su tercer disco y secuela narrativa directa del anterior. Entrada: The Baring of Shadows.", origin: "rec", pick: true },
  { name: "Nospūn", genre: "Progressive Metal", y: 2019, p: 2, via: "Escena 2020s", desc: "La crítica los describe combinando los cambios complejos de Between the Buried and Me con la rareza de Devin Townsend y Native Construct. Opus (2023) y el EP Ozai (2025). Entrada: Opus.", origin: "rec", pick: true }
];

