const PRI_GEN_2026 = [
  { name: "Stars of the Lid", genre: "Drone / Instrumental (US)", desc: "Piezas de veinte minutos hechas con cuerda y guitarra procesadas hasta que no queda ataque ni pulso: la música avanza por cómo cambian los armónicos entre sí, no por eventos. Cuatro discos largos con la misma lógica. Brian McBride murió el 25 de agosto de 2023, a los 53. Escucha muy exigente. Entrada: The Tired Sounds of Stars of the Lid.", origin: "rec", p: 3, y: 1993, via: "Post-Rock general", c: 1 },
  { name: "William Basinski", genre: "Ambient / Instrumental (US)", desc: "En The Disintegration Loops los bucles de cinta se van deshaciendo físicamente mientras suenan, y esa degradación es la composición: la pieza cambia porque el soporte se rompe, no porque él toque algo distinto. Entrada: The Disintegration Loops.", origin: "rec", p: 3, y: 1978, via: "Post-Rock general", c: 1 },
  { name: "Gastr del Sol", genre: "Post-Rock / Camara (US)", desc: "David Grubbs y Jim O'Rourke chocan material escrito con musique concrète dentro del mismo tema: la guitarra acústica convive con silencio y ruido sin transición que los una. Entrada: Camoufleur.", origin: "rec", p: 3, y: 1991, via: "Post-Rock general", c: 1 },
  { name: "Jóhann Jóhannsson", genre: "Orquestal / Instrumental (IS)", desc: "Orquesta y electrónica tratadas como un solo instrumento: en IBM 1401 usa grabaciones de un ordenador de los sesenta como base armónica de una obra para cuerda. Islandés. Murió el 9 de febrero de 2018 en Berlín, a los 48. Entrada: IBM 1401, A User Manual.", origin: "rec", p: 2, y: 1999, via: "Post-Rock general", c: 1 },
  { name: "Low", genre: "Slowcore / Post-Rock (US)", desc: "Empezaron llevando la lentitud al extremo como estructura, con dos voces en armonía sobre casi nada, y acabaron en Double Negative y HEY WHAT destruyendo la señal hasta que la voz se rompe. Treinta años y dos bandas distintas dentro de la misma. Mimi Parker murió en noviembre de 2022, a los 55. Entrada: Things We Lost in the Fire.", origin: "rec", p: 2, y: 1993, via: "Post-Rock general", c: 1 },
  { name: "Rodan", genre: "Post-Rock Angular (US)", desc: "De Louisville. Rusty salta de casi silencio a violencia con dos guitarras en afinaciones distintas que se rozan, y las canciones cambian de sección sin preparar el cambio. Un solo disco. Entrada: Rusty.", origin: "rec", p: 2, y: 1992, via: "Post-Rock general", c: 2 },
  { name: "June of 44", genre: "Post-Rock (US)", desc: "Ritmos que se cruzan sin llegar a cuadrar, con trompeta y bajo al frente y la guitarra haciendo textura por detrás. Entrada: Four Great Points.", origin: "rec", p: 3, y: 1994, via: "Post-Rock general", c: 2 },
  { name: "Codeine", genre: "Slowcore / Post-Rock (US)", desc: "Tempos tan lentos que cada golpe de caja se oye como un evento separado, con el bajo sosteniendo la armonía porque la guitarra apenas toca. Entrada: The White Birch.", origin: "rec", p: 3, y: 1989, via: "Post-Rock general", c: 2 },
  { name: "Pelican", genre: "Post-Metal / Instrumental (US)", desc: "Post-metal sin una sola voz en toda su obra: los riffs funcionan como melodía principal y las piezas se desarrollan por capas en vez de por estribillo. Entrada: The Fire in Our Throats Will Beckon the Thaw.", origin: "rec", p: 2, y: 2001, via: "Post-Rock general", c: 2 },
  { name: "We Lost the Sea", genre: "Post-Rock / Instrumental (AU)", desc: "Australianos. Departure Songs son piezas de doce a veinte minutos, instrumentales, con estructura narrativa real: cada una cuenta una historia y no repite el mismo crescendo. Entrada: Departure Songs.", origin: "rec", p: 2, y: 2008, via: "Post-Rock general", c: 2 },
  { name: "Tim Hecker", genre: "Ambient / Instrumental (CA)", desc: "Construye con material orquestal y de órgano saturado hasta el borde del recorte digital, de modo que la distorsión forma parte de la armonía. Entrada: Ravedeath, 1972.", origin: "rec", p: 2, y: 1996, via: "Post-Rock general", c: 2 },
  { name: "Fennesz", genre: "Ambient / Instrumental (AT)", desc: "Austriaco. Guitarra procesada hasta que el error digital es el timbre, con melodía reconocible sonando por debajo del ruido. Entrada: Endless Summer.", origin: "rec", p: 2, y: 1995, via: "Post-Rock general", c: 2 },
  { name: "Ben Frost", genre: "Ambient / Post-Metal (IS)", desc: "Volumen y densidad usados como material compositivo, con cuerda y percusión tratadas hasta perder su origen. Escucha física y difícil. Entrada: By the Throat.", origin: "rec", p: 3, y: 2003, via: "Post-Rock general", c: 2 },
  { name: "Max Richter", genre: "Orquestal / Instrumental (UK)", desc: "Sleep dura ocho horas y está escrito para dormir, con la forma calculada para eso; Recomposed reescribe Vivaldi con material propio en vez de arreglarlo. Entrada: The Blue Notebooks.", origin: "rec", p: 2, y: 2002, via: "Post-Rock general", c: 2 },
  { name: "Ryuichi Sakamoto", genre: "Orquestal / Instrumental (JP)", desc: "De Yellow Magic Orchestra al piano solo a las bandas sonoras, cambiando de sistema cada etapa durante sesenta años, y en los últimos discos trabajando con silencio y ruido ambiente como material. Murió el 28 de marzo de 2023, a los 71. Entrada: async.", origin: "rec", p: 2, y: 1978, via: "Post-Rock general", c: 2 },
  { name: "Mica Levi", genre: "Orquestal / Instrumental (UK)", desc: "En Under the Skin las cuerdas van desafinadas y ralentizadas a propósito, así que la armonía no se asienta nunca y el oído no encuentra dónde apoyarse. Entrada: Under the Skin.", origin: "rec", p: 2, y: 2008, via: "Post-Rock general", c: 2 },
  { name: "Caterina Barbieri", genre: "Instrumental / Secuenciador (IT)", desc: "Italiana. Secuencias de longitud distinta que se desfasan entre sí hasta generar melodías que nadie tocó: el patrón compuesto produce el material. Entrada: Ecstatic Computation.", origin: "rec", p: 3, y: 2014, via: "Post-Rock general", c: 2, female: true },
  { name: "Nisennenmondai", genre: "Post-Rock / Instrumental (JP)", desc: "Trío japonés que repite un patrón mínimo durante quince minutos cambiando solo la textura y la presión, sin melodía ni cambio de acorde. Entrada: N.", origin: "rec", p: 3, y: 1999, via: "Post-Rock general", c: 2, female: true }
];

const MUS_GEN_2026 = [
  { name: "A Little Night Music", genre: "Musical (Sondheim)", desc: "La partitura entera está en 3/4 y sus múltiplos: valses, 6/8, 12/8, sin salirse ni una vez de esa familia métrica, y aun así cada número suena distinto. Restricción formal aplicada a un espectáculo completo. Entrada: Send in the Clowns y el quinteto de apertura. ▸ Versión: el Original Broadway Cast de 1973, con Glynis Johns.", origin: "rec", p: 2, y: 1973, via: "Musicales general", c: 1 },
  { name: "Merrily We Roll Along", genre: "Musical (Sondheim)", desc: "La historia va hacia atrás en el tiempo y la música lo acompaña: los motivos aparecen primero en su versión amarga y se van reconstruyendo hasta llegar a la original al final de la obra. Entrada: Our Time. ▸ Versión: el revival de Broadway de 2023; el disco de 1981 viene de una producción que cerró a las dos semanas.", origin: "rec", p: 2, y: 1981, via: "Musicales general", c: 1 },
  { name: "Illinoise", genre: "Musical / Danza (Sufjan Stevens)", desc: "Todo danza y sin una sola línea de diálogo: el reparto son bailarines y las canciones las cantan tres vocalistas desde la banda, a la vista. Música de Sufjan Stevens con arreglos del compositor y pianista Timo Andres. Llegó a Broadway en abril de 2024. Entrada: Chicago. ▸ Versión: la música es el álbum Illinois de Sufjan Stevens (2005); el montaje le añade los arreglos de Timo Andres.", origin: "rec", p: 2, y: 2023, via: "Musicales general", c: 1 },
  { name: "Ghost Quartet", genre: "Musical / Song Cycle (Dave Malloy)", desc: "Cuatro intérpretes tocando todos los instrumentos, con cuatro historias entrelazadas repartidas como las cuatro caras de un disco doble y motivos que reaparecen cruzados entre ellas. Del mismo autor de Great Comet y Octet. Entrada: cara uno completa. ▸ Versión: la grabación del elenco original, con el propio Malloy tocando.", origin: "rec", p: 3, y: 2014, via: "Musicales general", c: 1 },
  { name: "The Last Five Years", genre: "Musical (Jason Robert Brown)", desc: "Dos líneas temporales corriendo en direcciones opuestas a la vez: ella va del final al principio y él del principio al final, y solo se cruzan en el número central. Para dos intérpretes y banda de cámara. Entrada: The Schmuel Song. ▸ Versión: el elenco original, con Norbert Leo Butz y Sherie Rene Scott.", origin: "rec", p: 2, y: 2001, via: "Musicales general", c: 1 },
  { name: "A Strange Loop", genre: "Musical / Meta (Michael R. Jackson)", desc: "Un musical sobre alguien escribiendo el musical que estás viendo, con los pensamientos del protagonista repartidos entre seis actores que le contestan. Pulitzer de teatro. Entrada: Memory Song. ▸ Versión: el elenco original, con Larry Owens.", origin: "rec", p: 3, y: 2019, via: "Musicales general", c: 1 },
  { name: "Company", genre: "Musical (Sondheim)", desc: "Musical de concepto sin trama lineal: escenas sueltas alrededor de una sola idea. Getting Married Today es un tour de force de patter con tres líneas vocales simultáneas a velocidades distintas. Entrada: Being Alive. ▸ Versión: el Original Broadway Cast de 1970, con Elaine Stritch.", origin: "rec", p: 2, y: 1970, via: "Musicales general", c: 2 },
  { name: "Follies", genre: "Musical (Sondheim)", desc: "El pastiche usado como estructura: cada número imita un estilo concreto de los años veinte o treinta y esa imitación es la que cuenta el presente de los personajes. Entrada: Losing My Mind. ▸ Versión: la grabación del concierto de 1985 en Avery Fisher Hall, que recoge casi toda la partitura; el disco original de 1971 está muy recortado.", origin: "rec", p: 2, y: 1971, via: "Musicales general", c: 2 },
  { name: "Candide", genre: "Musical / Opereta (Bernstein)", desc: "Escritura de opereta de verdad dentro del teatro musical: Glitter and Be Gay es un aria de coloratura completa, y la obertura se toca hoy como pieza de concierto por orquestas sinfónicas. Entrada: la obertura, luego Glitter and Be Gay. ▸ Versión: la que dirigió el propio Bernstein en 1989 con la London Symphony, su versión final revisada y la primera vez que dirigió la obra completa.", origin: "rec", p: 2, y: 1956, via: "Musicales general", c: 2 },
  { name: "The Wild Party", genre: "Musical / Jazz (LaChiusa)", desc: "Cantado de principio a fin, con armonía disonante y jazz de los años veinte tratado en serio en vez de como decorado de época. Michael John LaChiusa. Entrada: Welcome to My Party. ▸ Ojo: hay DOS musicales distintos con ese título estrenados en 2000; este es el de LaChiusa. ▸ Versión: el Original Broadway Cast, con Toni Collette, Mandy Patinkin y Eartha Kitt.", origin: "rec", p: 3, y: 2000, via: "Musicales general", c: 2 },
  { name: "The Light in the Piazza", genre: "Musical (Adam Guettel)", desc: "Lo más complejo armónicamente que ha escrito Guettel: acordes que no resuelven donde se espera y orquestación de cámara con arpa y cuerda, con buena parte del texto en italiano sin traducir. Entrada: Statues and Stories. ▸ Versión: el Original Broadway Cast de 2005, con Victoria Clark y Kelli OHara.", origin: "rec", p: 2, y: 2005, via: "Musicales general", c: 2 },
  { name: "Fun Home", genre: "Musical (Jeanine Tesori)", desc: "Tres actrices interpretan a la misma persona en tres edades y sus líneas se superponen dentro del mismo número, así que la memoria y el presente suenan a la vez. Entrada: Ring of Keys. ▸ Versión: el Original Broadway Cast de 2015.", origin: "rec", p: 2, y: 2013, via: "Musicales general", c: 2 },
  { name: "Kimberly Akimbo", genre: "Musical (Jeanine Tesori)", desc: "Tesori escribiendo en formato pequeño y con humor negro, con números de conjunto que encajan varias voces en contrapunto sobre una base de banda reducida. Entrada: Great Adventure. ▸ Versión: el Original Broadway Cast de 2023.", origin: "rec", p: 3, y: 2022, via: "Musicales general", c: 2 },
  { name: "City of Angels", genre: "Musical / Jazz (Cy Coleman)", desc: "Partitura de big band de jazz real, y los dos mundos de la obra (la novela negra y la vida del escritor) tienen paleta armónica distinta, así que se distinguen de oído. Entrada: You Can Always Count on Me. ▸ Versión: el Original Broadway Cast de 1989.", origin: "rec", p: 2, y: 1989, via: "Musicales general", c: 2 },
  { name: "Cabaret", genre: "Musical (Kander y Ebb)", desc: "Los números del club comentan la trama desde fuera en vez de avanzarla, y el arreglo se va pudriendo conforme avanza la obra. Entrada: Willkommen. ▸ Versión: el Original Broadway Cast de 1966 para la partitura tal como se escribió; el revival de 1998 con Alan Cumming reordena números y cambia el tono.", origin: "rec", p: 3, y: 1966, via: "Musicales general", c: 2 },
  { name: "The Music Man", genre: "Musical (Meredith Willson)", desc: "Rock Island es habla rítmica sobre el ritmo de un tren, sin melodía ninguna, y Lida Rose y Will I Ever Tell You son dos canciones distintas cantadas a la vez en contrapunto real. Entrada: Rock Island. ▸ Versión: el Original Broadway Cast de 1957, con Robert Preston.", origin: "rec", p: 3, y: 1957, via: "Musicales general", c: 2 },
  { name: "Carousel", genre: "Musical (Rodgers y Hammerstein)", desc: "Abre con un vals largo en vez de obertura, y el Soliloquy son ocho minutos compuestos de corrido que no repiten sección ni vuelven a un estribillo. Entrada: Soliloquy. ▸ Versión: el Original Broadway Cast de 1945 es la histórica; la del montaje del National Theatre de 1993 está mucho mejor grabada.", origin: "rec", p: 3, y: 1945, via: "Musicales general", c: 2 },
  { name: "Rise and Fall of the City of Mahagonny", genre: "Musical / Ópera (Kurt Weill)", desc: "La obra grande de Weill y Brecht, y es directamente ópera: números cerrados con orquesta, armonía ácida y una banda de jazz metida dentro del foso. Threepenny es la puerta; esta es la obra. Entrada: Alabama Song. ▸ Versión: la grabación de 1956 con Lotte Lenya, la voz para la que Weill escribió.", origin: "rec", p: 3, y: 1930, via: "Musicales general", c: 2 }
];

const NU_GEN_2026 = [
  { name: "Laibach", genre: "Industrial / Martial (SI)", desc: "Eslovenos. Reescriben himnos, canciones pop y discos enteros como música marcial, así que el arreglo ES la obra: hicieron Let It Be tema a tema y un disco completo de The Sound of Music. Cuarenta y cinco años sin parar, con Opus Dei Revisited (2024), Alamut (2025) y el disco de baile Musick (2026). Entrada: Opus Dei.", origin: "rec", p: 2, y: 1980, via: "Nu Metal/Industrial general", c: 1 },
  { name: "Nurse With Wound", genre: "Industrial / Collage (UK)", desc: "Steven Stapleton lleva desde 1978 haciendo collage de cinta y musique concrète, con una discografía enorme donde casi ningún disco se parece al anterior. Escucha muy exigente y sin pulso al que agarrarse. Entrada: Soliloquy for Lilith.", origin: "rec", p: 3, y: 1978, via: "Nu Metal/Industrial general", c: 1 },
  { name: "Test Dept", genre: "Industrial / Percusion (UK)", desc: "Ensemble de percusión que usa chatarra y maquinaria industrial como fuente de sonido, y de forma mucho más rítmica que sus contemporáneos: hay patrones y desarrollo, no solo golpes. Con metales y coro encima. Entrada: The Unacceptable Face of Freedom.", origin: "rec", p: 3, y: 1981, via: "Nu Metal/Industrial general", c: 1 },
  { name: "Merzbow", genre: "Noise Industrial (JP)", desc: "Masami Akita trata el ruido saturado como material compositivo y no como efecto: la pieza avanza por cambios de densidad y de espectro dentro de la masa. Cientos de discos publicados. De lo más difícil del catálogo. Entrada: Pulse Demon.", origin: "rec", p: 3, y: 1979, via: "Nu Metal/Industrial general", c: 1 },
  { name: "The Berzerker", genre: "Industrial Extremo (AU)", desc: "De Melbourne. En el primer disco no hay batería humana: una caja de ritmos distorsionada a velocidades imposibles hace todo el trabajo, y ese timbre define la banda entera. Entrada: The Berzerker.", origin: "rec", p: 3, y: 1995, via: "Nu Metal/Industrial general", c: 1 },
  { name: "Front 242", genre: "EBM / Industrial (BE)", desc: "Belgas. La estructura ES el patrón programado: la máquina no acompaña sino que compone, y las capas de secuencia entran y salen para construir la forma. Se retiraron de los escenarios con una gira de despedida que acabó en Bruselas en enero de 2025, tras más de cuarenta años. Entrada: Front by Front.", origin: "rec", p: 2, y: 1981, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Nitzer Ebb", genre: "EBM / Industrial (UK)", desc: "EBM reducido a voz y percusión con casi nada más: sin armonía apenas, todo el peso en el patrón y en el grito. Douglas McCarthy murió en junio de 2025, a los 58. Entrada: That Total Age.", origin: "rec", p: 3, y: 1982, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Clock DVA", genre: "Industrial / Electronico (UK)", desc: "Del industrial de cinta al electro con saxofón, cambiando de forma varias veces a lo largo de la carrera en vez de asentarse. Entrada: Thirst.", origin: "rec", p: 3, y: 1978, via: "Nu Metal/Industrial general", c: 2 },
  { name: "SPK", genre: "Industrial (AU)", desc: "Australianos. Empezaron en el ruido más agresivo y acabaron haciendo synthpop de baile: son dos bandas distintas dentro de la misma discografía. Entrada: Leichenschrei.", origin: "rec", p: 3, y: 1978, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Psychic TV", genre: "Industrial / Psych (UK)", desc: "Genesis P-Orridge con una obra enorme que va del ritual y la cinta al acid house, sin quedarse quieta en ningún sitio. Entrada: Dreams Less Sweet.", origin: "rec", p: 3, y: 1981, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Die Krupps", genre: "Industrial Metal / EBM (DE)", desc: "Alemanes. Guitarra de metal encajada sobre secuenciación EBM sin que ninguna de las dos ceda terreno: el riff y la máquina llevan el mismo peso. Entrada: II: The Final Option.", origin: "rec", p: 3, y: 1980, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Pitchshifter", genre: "Industrial Metal / Drum n Bass (UK)", desc: "Metal industrial con programación de drum and bass real por debajo, con los breaks cortados y colocados, no un loop de adorno. Entrada: www.pitchshifter.com.", origin: "rec", p: 3, y: 1989, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Samael", genre: "Industrial Metal (CH)", desc: "Suizos. Pasaron de black metal a industrial con orquestación programada y caja de ritmos: Passage suena a otra banda distinta del debut, y el cambio es de escritura, no de producción. Entrada: Passage.", origin: "rec", p: 2, y: 1987, via: "Nu Metal/Industrial general", c: 2 },
  { name: "The Bug", genre: "Industrial / Dub (UK)", desc: "Kevin Martin construye con sub-bajo extremo y dancehall: el peso del grave es el material con el que compone, no un efecto añadido, y encima entran vocalistas invitados. Entrada: London Zoo.", origin: "rec", p: 2, y: 1997, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Atari Teenage Riot", genre: "Industrial / Breakbeat (DE)", desc: "Alec Empire trata el sampler como instrumento agresivo: breakbeats a ciento ochenta pulsaciones saturados hasta el recorte, con tres voces gritando encima. Entrada: Delete Yourself.", origin: "rec", p: 2, y: 1992, via: "Nu Metal/Industrial general", c: 2 },
  { name: "HEALTH", genre: "Industrial / Noise Pop (US)", desc: "Pasaron del noise rock al pop industrial con una producción que hace irreconocibles las fuentes: no sabes qué instrumento estás oyendo y esa ambigüedad es el punto. Entrada: DEATH MAGIC.", origin: "rec", p: 3, y: 2005, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Maximum the Hormone", genre: "Nu Metal / Caotico (JP)", desc: "Japoneses. Cambian de género a mitad de tema, del hardcore al pop al funk, con cuatro voces alternándose incluida la batería cantando, y lo tocan apretadísimo. El caos está escrito, no improvisado. Entrada: Bu-ikikaesu.", origin: "rec", p: 2, y: 1998, via: "Nu Metal/Industrial general", c: 2 },
  { name: "Zeni Geva", genre: "Noise Industrial (JP)", desc: "KK Null con dos guitarras en afinaciones raras y batería, sin bajo, y riffs que se repiten hasta deformarse. Japoneses. Entrada: Desire for Agony.", origin: "rec", p: 3, y: 1987, via: "Nu Metal/Industrial general", c: 2 }
];

const MATH_GEN_2026 = [
  { name: "The Locust", genre: "Mathcore / Sintetizador (US)", desc: "Canciones de treinta a sesenta segundos con sintetizador chillón encima, escritas con precisión de partitura: no es caos improvisado, está todo colocado al milímetro y ejecutado a la vez. Discos enteros que duran veinte minutos. Entrada: Plague Soundscapes.", origin: "rec", p: 3, y: 1994, via: "Mathcore general", c: 1 },
  { name: "The Blood Brothers", genre: "Mathcore / Caotico (US)", desc: "Dos vocalistas en registros opuestos alternando y solapándose como si fueran dos instrumentos distintos, con el teclado llevando la armonía en vez de la guitarra y estructuras que no repiten sección. Entrada: Crimes.", origin: "rec", p: 2, y: 1997, via: "Mathcore general", c: 1 },
  { name: "Arab on Radar", genre: "Math Noise Rock (US)", desc: "Sin bajo: dos guitarras entrelazadas en intervalos disonantes que se rozan, sobre batería seca y una voz deliberadamente irritante. Escucha hostil a propósito. Entrada: Yahweh or the Highway.", origin: "rec", p: 3, y: 1994, via: "Mathcore general", c: 1 },
  { name: "Cheer-Accident", genre: "Math Rock / Avant (US)", desc: "Cuarenta años sin que nadie sepa qué son: pasan de prog a pop a ruido de disco a disco, y a veces dentro del mismo tema, con metales y coros escritos. De Chicago. Entrada: Introducing Lemon.", origin: "rec", p: 3, y: 1981, via: "Mathcore general", c: 1 },
  { name: "Extra Life", genre: "Math Rock / Camara (US)", desc: "Charlie Looker escribe las líneas vocales con lógica de polifonía medieval, con melismas y cadencias antiguas, y las monta sobre métricas de math rock y guitarra eléctrica. No suena como nada. Entrada: Secular Works.", origin: "rec", p: 2, y: 2007, via: "Mathcore general", c: 1 },
  { name: "Zazen Boys", genre: "Math Rock / Funk (JP)", desc: "Shutoku Mukai monta funk angular con paradas secas y acentos desplazados, tocado con una precisión casi rígida y con el bajo al frente. Japoneses. Entrada: Zazen Boys 4.", origin: "rec", p: 2, y: 2003, via: "Mathcore general", c: 2 },
  { name: "Gospel", genre: "Mathcore / Prog (US)", desc: "Screamo con órgano de iglesia llevando la armonía y estructura de prog por debajo. The Loser (13 de mayo de 2022) llegó tras más de una década de silencio y es más ambicioso que el debut. Entrada: The Moon Is a Dead World.", origin: "rec", p: 2, y: 2002, via: "Mathcore general", c: 2 },
  { name: "Adebisi Shank", genre: "Math Rock Instrumental (IE)", desc: "Irlandeses, instrumentales y complejos sin una gota de solemnidad: guitarras procesadas con vocoder y sintetizador sobre métricas cambiantes. Entrada: This Is the Second Album of a Band Called Adebisi Shank.", origin: "rec", p: 3, y: 2006, via: "Mathcore general", c: 2 },
  { name: "TTNG", genre: "Math Rock (UK)", desc: "Guitarra limpia en compases impares con la métrica escondida bajo algo que suena amable: hay que contar para darse cuenta de dónde está el uno. Entrada: Animals.", origin: "rec", p: 3, y: 2004, via: "Mathcore general", c: 2 },
  { name: "Ion Dissonance", genre: "Dissonant Mathcore (CA)", desc: "Canadienses. Riffs que cambian de figura cada dos compases sobre una batería que no marca el pulso sino que lo contradice. Entrada: Solace.", origin: "rec", p: 3, y: 2002, via: "Mathcore general", c: 2 },
  { name: "Ithaca", genre: "Mathcore (UK)", desc: "Británicos. Metalcore roto con pasajes melódicos y disonancia sostenida. They Fear Us (29 de julio de 2022) es su segundo y último disco: la banda ya terminó. Entrada: They Fear Us.", origin: "rec", p: 3, y: 2012, via: "Mathcore general", c: 2 },
  { name: "Fawn Limbs", genre: "Mathcore / Noise (FI)", desc: "Extremo y compositivo a la vez, con electrónica y percusión programada metidas dentro del caos en vez de encima. Entrada: Sleeper Vessels.", origin: "rec", p: 3, y: 2015, via: "Mathcore general", c: 2 },
  { name: "Burnt by the Sun", genre: "Mathcore (US)", desc: "Riffs de bloque que paran en seco y arrancan en otro sitio, con groove pesado por debajo del caos. Entrada: Soundtrack to the Personal Revolution.", origin: "rec", p: 3, y: 2000, via: "Mathcore general", c: 2 },
  { name: "Knut", genre: "Mathcore (CH)", desc: "Suizos, angulares y muy secos: producción sin reverb y riffs que se repiten hasta incomodar. Entrada: Terraformer.", origin: "rec", p: 3, y: 1994, via: "Mathcore general", c: 2 },
  { name: "Bitch Magnet", genre: "Math Rock / Noise (US)", desc: "Sooyoung Park con guitarras en afinaciones cruzadas y estructuras que no vuelven al punto de partida, sobre batería de fraseo suelto. Entrada: Umber.", origin: "rec", p: 3, y: 1986, via: "Mathcore general", c: 2 },
  { name: "Craw", genre: "Math Noise Rock (US)", desc: "De Cleveland, densos y literarios, con métrica que cambia sin avisar y dos guitarras que nunca tocan lo mismo. Entrada: Bodies for Strontium 90.", origin: "rec", p: 3, y: 1992, via: "Mathcore general", c: 2 },
  { name: "Time of Orchids", genre: "Math Rock / Avant (US)", desc: "Teclados y voces armonizadas sobre estructuras que se desarman a mitad, entre el prog de cámara y el ruido. Entrada: Namesake Caution.", origin: "rec", p: 3, y: 1999, via: "Mathcore general", c: 2 },
  { name: "LITE", genre: "Math Rock Instrumental (JP)", desc: "Instrumental japonés, apretadísimo y muy rítmico, con la guitarra haciendo figuras cortas que encajan como piezas en vez de melodías largas. Entrada: Phantasia.", origin: "rec", p: 3, y: 2003, via: "Mathcore general", c: 2 }
];

const HH_GEN_2026 = [
  { name: "Shabazz Palaces", genre: "Hip-Hop Abstracto (US)", desc: "Ishmael Butler construye sin batería convencional en buena parte de los temas: las piezas avanzan por capas de sintetizador y percusión suelta que se disuelven a mitad, sin estribillo al que volver. Entrada: Black Up.", origin: "rec", p: 2, y: 2009, via: "Hip-Hop general", c: 1 },
  { name: "cLOUDDEAD", genre: "Hip-Hop Abstracto (US)", desc: "Su primer disco son seis temas de diez minutos, cada uno partido en dos caras de vinilo, con collage ambiental y bucles de cinta por debajo del rap. Escucha rara de verdad. Entrada: cLOUDDEAD.", origin: "rec", p: 3, y: 2000, via: "Hip-Hop general", c: 1 },
  { name: "Injury Reserve", genre: "Hip-Hop Experimental (US)", desc: "By the Time I Get to Phoenix está montado sobre bucles rotos y samples deformados que no cuadran a propósito, con la voz entrando fuera de sitio. Lo grabaron tras morir Stepa J. Groggs en 2020, y en 2023 los dos que quedaban se renombraron By Storm. Entrada: By the Time I Get to Phoenix.", origin: "rec", p: 2, y: 2013, via: "Hip-Hop general", c: 1 },
  { name: "Moor Mother", genre: "Hip-Hop / Free Jazz (US)", desc: "Camae Ayewa cruza free jazz, ruido y poesía recitada, con la voz tratada como una capa más dentro de la masa en vez de ir encima. También está en Irreversible Entanglements. Entrada: Black Encyclopedia of the Air.", origin: "rec", p: 3, y: 2012, via: "Hip-Hop general", c: 1, female: true },
  { name: "Prefuse 73", genre: "Hip-Hop Instrumental / Glitch (US)", desc: "Corta las voces en fragmentos de milisegundos y las usa como percusión afinada, no como letra: la frase original ya no se entiende y se convierte en material rítmico. Entrada: One Word Extinguisher.", origin: "rec", p: 3, y: 2001, via: "Hip-Hop general", c: 1 },
  { name: "Nujabes", genre: "Hip-Hop Instrumental / Jazz (JP)", desc: "Samplea jazz con movimiento armónico real, no un bucle de dos acordes: los temas modulan y las capas entran y salen como en un arreglo. Japonés. Murió el 26 de febrero de 2010 en un accidente de tráfico en Tokio, a los 36. Entrada: Modal Soul.", origin: "rec", p: 2, y: 1995, via: "Hip-Hop general", c: 2 },
  { name: "Wu-Tang Clan", genre: "Hip-Hop (US)", desc: "La producción de RZA: bucles sucios y desafinados a propósito, con pianos que suenan rotos, y nueve MCs de fraseo reconociblemente distinto turnándose sin coro que los una. Entrada: Enter the Wu-Tang.", origin: "rec", p: 2, y: 1992, via: "Hip-Hop general", c: 2 },
  { name: "De La Soul", genre: "Hip-Hop / Sampling (US)", desc: "3 Feet High and Rising tiene una densidad de sampleo que hoy sería imposible de licenciar, con fuentes que van del pop de los sesenta a discos de instrucción de francés. Su catálogo no llegó al streaming hasta el 3 de marzo de 2023. Entrada: 3 Feet High and Rising.", origin: "rec", p: 2, y: 1987, via: "Hip-Hop general", c: 2 },
  { name: "Beastie Boys", genre: "Hip-Hop / Punk Funk (US)", desc: "El disco de 1989 apila cientos de samples por tema, y a partir de Check Your Head tocan ellos los instrumentos: hay discos suyos que son de banda funk en directo, no de rap. Entrada: Paul's Boutique, luego Check Your Head.", origin: "rec", p: 2, y: 1981, via: "Hip-Hop general", c: 2 },
  { name: "Cannibal Ox", genre: "Hip-Hop Abstracto (US)", desc: "The Cold Vein lo produjo entero El-P: bases metálicas y disonantes, más cerca del industrial que del boom bap, con la batería colocada fuera de cuadrícula. Entrada: The Cold Vein.", origin: "rec", p: 2, y: 1998, via: "Hip-Hop general", c: 2 },
  { name: "Aesop Rock", genre: "Hip-Hop Abstracto (US)", desc: "Densidad léxica extrema y un fraseo que atraviesa el compás en vez de caer en el uno, sobre producción de bucles densos. Entrada: None Shall Pass.", origin: "rec", p: 2, y: 1996, via: "Hip-Hop general", c: 2 },
  { name: "Danny Brown", genre: "Hip-Hop Experimental (US)", desc: "Atrocity Exhibition está construido sobre samples de rock y jazz deformados, con la voz en un registro agudo incómodo a propósito y bases que no siguen el patrón esperado. Entrada: Atrocity Exhibition.", origin: "rec", p: 2, y: 2007, via: "Hip-Hop general", c: 2 },
  { name: "Ka", genre: "Hip-Hop (US)", desc: "Muchos de sus temas no llevan batería: solo un bucle sostenido y la voz casi susurrada por encima, así que el peso recae entero en el texto y en el timbre. De Brownsville. Murió el 12 de octubre de 2024, a los 52; era capitán retirado de bomberos y respondió al 11-S. Entrada: The Night Slipped Quietly Through.", origin: "rec", p: 2, y: 2008, via: "Hip-Hop general", c: 2 },
  { name: "Earl Sweatshirt", genre: "Hip-Hop Lo-Fi (US)", desc: "Some Rap Songs son quince temas en veinticinco minutos, con bucles que cortan de golpe sin resolver y la voz mezclada al mismo nivel que la base. Entrada: Some Rap Songs.", origin: "rec", p: 3, y: 2010, via: "Hip-Hop general", c: 2 },
  { name: "Dizzee Rascal", genre: "Hip-Hop / Grime (UK)", desc: "Boy in da Corner lo produjo él mismo con una PlayStation, y los timbres, agudos y metálicos, no se parecen a nada de su época ni de la nuestra. Entrada: Boy in da Corner.", origin: "rec", p: 2, y: 2002, via: "Hip-Hop general", c: 2 },
  { name: "Frank Ocean", genre: "R&B / Hip-Hop (US)", desc: "En Blonde hay canciones enteras sin batería, con la voz multiplicada y afinada en varias direcciones a la vez y estructuras que no vuelven a ninguna sección. Entrada: Blonde.", origin: "rec", p: 2, y: 2010, via: "Hip-Hop general", c: 2 },
  { name: "Erykah Badu", genre: "Neo-Soul / Hip-Hop (US)", desc: "Banda tocando en directo sobre armonía de jazz, con un fraseo vocal que va deliberadamente detrás del tiempo y arreglos que dejan mucho aire. Entrada: Mama Gun.", origin: "rec", p: 2, y: 1997, via: "Hip-Hop general", c: 2, female: true },
  { name: "Calle 13", genre: "Hip-Hop Latino (PR)", desc: "Visitante arregla con orquesta, cuerdas y ritmos latinos tocados, no programados, y cada disco cambia de paleta entera. Puertorriqueños. Entrada: Entren Los Que Quieran.", origin: "rec", p: 2, y: 2004, via: "Hip-Hop general", c: 2 }
];

const PE_GEN_2026 = [
  { name: "Public Image Ltd", genre: "Post-Punk / Dub (UK)", desc: "En Metal Box el bajo dub de Jah Wobble lleva la melodía, la guitarra de Keith Levene toca figuras atonales que no acompañan a nadie y no hay verso ni estribillo: las piezas se sostienen sobre repetición y espacio. Lydon dejó el punk para hacer esto. Entrada: Metal Box.", origin: "rec", p: 2, y: 1978, via: "Punk/Emo general", c: 1 },
  { name: "The Pop Group", genre: "Post-Punk / Dub (UK)", desc: "Punk chocando con free jazz y dub a la vez: la sección rítmica toca patrones bailables mientras la guitarra y el saxo desmontan el tema por encima. Escucha caótica a propósito. Entrada: Y.", origin: "rec", p: 3, y: 1977, via: "Punk/Emo general", c: 1 },
  { name: "Wire", genre: "Punk / Post-Punk (UK)", desc: "Pink Flag son veintiuna canciones en treinta y cinco minutos, muchas de menos de un minuto, cortadas justo cuando la idea se agota. Y en los dos discos siguientes se pasaron al art rock con sintetizadores: tres bandas distintas en tres años. Entrada: Pink Flag, luego 154.", origin: "rec", p: 2, y: 1976, via: "Punk/Emo general", c: 1 },
  { name: "Pere Ubu", genre: "Post-Punk / Garage (US)", desc: "Sintetizador tratado como ruido y musique concrète metidos debajo de rock de garaje, desde 1975, con la voz de David Thomas hablando y chillando fuera de tono a propósito. Thomas murió el 23 de abril de 2025, a los 71. Entrada: The Modern Dance.", origin: "rec", p: 3, y: 1975, via: "Punk/Emo general", c: 1 },
  { name: "Fucked Up", genre: "Punk / Opera Rock (CA)", desc: "David Comes to Life es una ópera rock de dieciocho temas con trama y personajes, tocada como hardcore y con capas de guitarra apiladas hasta formar un muro melódico. Canadienses. Entrada: David Comes to Life.", origin: "rec", p: 2, y: 2001, via: "Punk/Emo general", c: 1 },
  { name: "Mission of Burma", genre: "Post-Punk (US)", desc: "Martin Swope manipulaba cinta en directo desde la mesa como cuarto miembro, así que lo que sonaba era el grupo más su propio eco reprocesado y devuelto fuera de tiempo. Entrada: Vs.", origin: "rec", p: 2, y: 1979, via: "Punk/Emo general", c: 1 },
  { name: "Television", genre: "Punk / Art Rock (US)", desc: "Tom Verlaine y Richard Lloyd tocan contrapunto entrelazado en vez de repartirse ritmo y solo, y Marquee Moon son diez minutos que se desarrollan de verdad, sin repetir sección. Entrada: Marquee Moon.", origin: "rec", p: 2, y: 1973, via: "Punk/Emo general", c: 2 },
  { name: "The Fall", genre: "Post-Punk (UK)", desc: "Repetición como método durante cuarenta años y más de treinta discos, con la formación cambiando sin parar alrededor de Mark E. Smith, que murió en enero de 2018 a los 60. Escucha áspera y monótona a propósito. Entrada: Hex Enduction Hour.", origin: "rec", p: 3, y: 1976, via: "Punk/Emo general", c: 2 },
  { name: "Rudimentary Peni", genre: "Anarcho Punk (UK)", desc: "Nick Blinko escribe piezas de un minuto con armonía genuinamente rara y una voz que no se parece a nada, sobre bajo y batería secos. Entrada: Cacophony.", origin: "rec", p: 3, y: 1980, via: "Punk/Emo general", c: 2 },
  { name: "Crass", genre: "Anarcho Punk (UK)", desc: "Collage de cinta, voz hablada y ruido metidos dentro del formato punk, con estructuras que se cortan y se solapan en vez de encadenar estrofas. Entrada: Penis Envy.", origin: "rec", p: 3, y: 1977, via: "Punk/Emo general", c: 2 },
  { name: "Sunny Day Real Estate", genre: "Emo / Post-Punk (US)", desc: "Emo con compases impares y el bajo de Nate Mendel llevando melodía propia en vez de doblar la guitarra, con dinámica que cae a casi nada y vuelve. Entrada: Diary.", origin: "rec", p: 2, y: 1992, via: "Punk/Emo general", c: 2 },
  { name: "Number Girl", genre: "Punk Angular (JP)", desc: "Shutoku Mukai antes de Zazen Boys: guitarras angulares, paradas secas y una sección rítmica muy adelante en la mezcla. Japoneses. Entrada: School Girl Distortional Addict.", origin: "rec", p: 2, y: 1995, via: "Punk/Emo general", c: 2 },
  { name: "Gilla Band", genre: "Noise Punk (IE)", desc: "Irlandeses. Sacan de la guitarra texturas que no suenan a guitarra, usando pedales y realimentación como fuente de sonido y no como efecto. Acaban de anunciar Pugnello, grabado entre 2022 y 2026 en Dublín. Entrada: The Talkies.", origin: "rec", p: 2, y: 2011, via: "Punk/Emo general", c: 2 },
  { name: "The Armed", genre: "Punk Caotico (US)", desc: "Colectivo anónimo con decenas de colaboradores por disco y una producción tan densa que cuesta distinguir las capas. Entrada: ULTRAPOP.", origin: "rec", p: 3, y: 2009, via: "Punk/Emo general", c: 2 },
  { name: "Turnstile", genre: "Punk / Alt (US)", desc: "NEVER ENOUGH (6 de junio de 2025) mete sintetizadores, percusión latina y pasajes casi de shoegaze dentro del hardcore, con los temas encadenados sin pausa. Ganó el Grammy a mejor álbum de rock. Entrada: GLOW ON.", origin: "rec", p: 2, y: 2010, via: "Punk/Emo general", c: 2 },
  { name: "Hüsker Dü", genre: "Punk Melodico (US)", desc: "Muro de guitarra de Bob Mould con melodía clara por debajo, y Zen Arcade es un doble conceptual de 1984 con piano, cinta al revés y una pieza final de catorce minutos. Entrada: Zen Arcade.", origin: "rec", p: 2, y: 1979, via: "Punk/Emo general", c: 2 },
  { name: "Brainiac", genre: "Noise Punk / Synth (US)", desc: "Sintetizadores rotos y voz procesada con caja de efectos dentro del noise rock, con ritmos que se traban a propósito. Tim Taylor murió en 1997. Entrada: Hissing Prigs in Static Couture.", origin: "rec", p: 3, y: 1992, via: "Punk/Emo general", c: 2 },
  { name: "The Slits", genre: "Post-Punk / Dub (UK)", desc: "Punk reescrito con lógica de dub: mandan el espacio y el bajo, no la velocidad, y la batería deja huecos donde se espera el golpe. Entrada: Cut.", origin: "rec", p: 3, y: 1976, via: "Punk/Emo general", c: 2, female: true }
];

const RC_GEN_2026 = [
  { name: "The Band", genre: "Rock (clásico) / Americana (CA)", desc: "Cinco músicos que cantan todos y se intercambian instrumentos dentro del mismo tema, con el órgano y el saxo de Garth Hudson tocando líneas propias que no acompañan a nadie. Los arreglos están escritos, no montados sobre un riff. Robbie Robertson murió en agosto de 2023 y Garth Hudson en enero de 2025, a los 87: era el último que quedaba vivo. Entrada: The Band.", origin: "rec", p: 2, y: 1967, via: "Rock clasico general", c: 1 },
  { name: "Little Feat", genre: "Rock (clásico) / Slide (US)", desc: "El slide de Lowell George en afinaciones abiertas sobre el piano de Bill Payne, que viene del jazz, y la batería de Richie Hayward tocando ritmos de Nueva Orleans. Los grooves van cruzados, no cuadrados. Entrada: Dixie Chicken.", origin: "rec", p: 2, y: 1969, via: "Rock clasico general", c: 1 },
  { name: "Captain Beyond", genre: "Hard Rock (US)", desc: "Hard rock de 1972 en compases que cambian constantemente, con los temas encadenados en suites sin pausa entre ellos. Entrada: Captain Beyond.", origin: "rec", p: 3, y: 1971, via: "Rock clasico general", c: 1 },
  { name: "Steely Dan", genre: "Rock (clásico) (US)", desc: "Armonía de jazz dentro de canciones de rock: acordes alterados y modulaciones a mitad de estrofa que la melodía disimula, grabadas con músicos de sesión rotatorios en vez de con una banda fija. Walter Becker murió en 2017. Entrada: Aja.", origin: "rec", p: 1, y: 1971, via: "Rock clasico general", c: 1 },
  { name: "Fleetwood Mac", genre: "Blues Rock (UK)", desc: "Empezaron como banda de blues con Peter Green haciendo piezas largas y modales, y acabaron siendo un grupo de pop de armonía a tres voces completamente distinto. Dos discografías dentro de una. Entrada: Then Play On, luego Rumours.", origin: "rec", p: 3, y: 1967, via: "Rock clasico general", c: 1 },
  { name: "The Allman Brothers Band", genre: "Blues Rock / Sureño (US)", desc: "Dos guitarras armonizadas a terceras escritas nota a nota, dos baterías tocando a la vez e improvisación larga de verdad; Whipping Post va en 11/8. Dickey Betts murió en abril de 2024, a los 80. Entrada: At Fillmore East.", origin: "rec", p: 2, y: 1969, via: "Rock clasico general", c: 2 },
  { name: "The Kinks", genre: "Rock (clásico) (UK)", desc: "Ray Davies escribiendo discos conceptuales con arreglos de metales y clavecín cuando el resto del mundo hacía singles sueltos. Entrada: The Village Green Preservation Society.", origin: "rec", p: 2, y: 1963, via: "Rock clasico general", c: 2 },
  { name: "Uriah Heep", genre: "Hard Rock (UK)", desc: "El órgano de Ken Hensley como instrumento principal por delante de la guitarra, y armonías vocales a cinco voces apiladas. Entrada: Demons and Wizards.", origin: "rec", p: 3, y: 1969, via: "Rock clasico general", c: 2 },
  { name: "The Groundhogs", genre: "Blues Rock (UK)", desc: "Tony McPhee monta blues rock que se va por sitios raros, con estructuras que no vuelven y cambios de tempo dentro del tema. Entrada: Split.", origin: "rec", p: 3, y: 1963, via: "Rock clasico general", c: 2 },
  { name: "Van Halen", genre: "Hard Rock (US)", desc: "Eddie usa el tapping a dos manos y los armónicos como vocabulario compositivo, no como truco de solo: aparecen dentro de los riffs. Y Alex toca contra él en vez de acompañarlo. Entrada: Van Halen.", origin: "rec", p: 2, y: 1972, via: "Rock clasico general", c: 2 },
  { name: "Howlin' Wolf", genre: "Blues (US)", desc: "La voz usada como instrumento de percusión y de distorsión, sobre bandas donde Hubert Sumlin toca líneas retorcidas que se salen del patrón de doce compases. Entrada: Moanin' in the Moonlight.", origin: "rec", p: 2, y: 1951, via: "Rock clasico general", c: 2 },
  { name: "Muddy Waters", genre: "Blues (US)", desc: "Electrificó el blues del Delta, y la banda que armó define el formato entero: guitarra, armónica, piano y sección rítmica respondiéndose por turnos en vez de acompañar. Entrada: Hard Again.", origin: "rec", p: 2, y: 1941, via: "Rock clasico general", c: 2 },
  { name: "Son House", genre: "Blues (US)", desc: "Blues del Delta a voz y slide, con el pulso estirándose según la frase en vez de ir a tempo fijo: los compases duran lo que tiene que durar la línea. Entrada: Father of Folk Blues.", origin: "rec", p: 3, y: 1930, via: "Rock clasico general", c: 2 },
  { name: "Albert King", genre: "Blues (US)", desc: "Zurdo tocando una guitarra de diestro dada la vuelta, así que tira de las cuerdas hacia abajo y consigue curvas de nota que no salen de otra manera. Entrada: Born Under a Bad Sign.", origin: "rec", p: 2, y: 1953, via: "Rock clasico general", c: 2 },
  { name: "Free", genre: "Hard Rock / Blues (UK)", desc: "Paul Kossoff toca muy pocas notas con un vibrato enorme y Andy Fraser deja huecos en el bajo: la banda suena por lo que decide no tocar. Entrada: Fire and Water.", origin: "rec", p: 3, y: 1968, via: "Rock clasico general", c: 2 },
  { name: "Rival Sons", genre: "Hard Rock / Blues (US)", desc: "Hard rock moderno grabado en directo y en cinta, sin cuadrícula ni edición: el tempo respira. Entrada: Hollow Bones.", origin: "rec", p: 3, y: 2009, via: "Rock clasico general", c: 2 },
  { name: "Larkin Poe", genre: "Blues Rock (US)", desc: "Dos hermanas con slide y armonías vocales muy cerradas sobre blues rock, con la lap steel llevando las líneas principales. Entrada: Venom & Faith.", origin: "rec", p: 3, y: 2010, via: "Rock clasico general", c: 2, female: true },
  { name: "Buddy Guy", genre: "Blues (US)", desc: "Dinámica extrema dentro del mismo tema: pasa del susurro al grito sin transición, y la guitarra lo sigue con el mismo salto. Entrada: Damn Right, I Got the Blues.", origin: "rec", p: 3, y: 1958, via: "Rock clasico general", c: 2 }
];

const AM_GEN_2026 = [
  { name: "Kyuss", genre: "Stoner Rock (US)", desc: "Tocaban la guitarra por amplificadores de bajo y afinada muy abajo, así que el timbre carga armónicos graves que una guitarra normal no da: ese sonido es la composición, no un efecto añadido después. Entrada: Blues for the Red Sun.", origin: "rec", p: 2, y: 1987, via: "Alt Metal general", c: 1 },
  { name: "Rollins Band", genre: "Alt Metal / Funk (US)", desc: "Melvin Gibbs toca el bajo con lógica de jazz y funk, con líneas que se mueven libres por debajo en vez de doblar el riff, y en la última etapa entra saxofón: hardcore por arriba, fusión por abajo. Entrada: Weight.", origin: "rec", p: 3, y: 1987, via: "Alt Metal general", c: 1 },
  { name: "Earthless", genre: "Stoner Rock Instrumental (US)", desc: "Instrumental, sin voz, con piezas de veinte minutos construidas sobre improvisación en un género donde todo dura cuatro. Isaiah Mitchell sostiene la melodía sin repetirse. Entrada: Rhythms from a Cosmic Sky.", origin: "rec", p: 2, y: 2001, via: "Alt Metal general", c: 1 },
  { name: "Quicksand", genre: "Alt Metal (US)", desc: "Riffs angulares en compases desplazados con el bajo llevando la melodía principal, dentro de algo que por fuera parece alt metal convencional. Entrada: Slip.", origin: "rec", p: 3, y: 1990, via: "Alt Metal general", c: 1 },
  { name: "Pearl Jam", genre: "Grunge (US)", desc: "Dos guitarras que se reparten líneas distintas en vez de ritmo y solo, y Jeff Ament tocando bajos de doce cuerdas y contrabajo eléctrico que cambian el registro grave de tema a tema. Dark Matter salió el 19 de abril de 2024. Entrada: Vs.", origin: "rec", p: 2, y: 1990, via: "Alt Metal general", c: 2 },
  { name: "Screaming Trees", genre: "Grunge / Psych (US)", desc: "La voz grave y enorme de Mark Lanegan sobre psicodelia pesada con órgano, muy lejos del grunge de guitarra sola. Lanegan murió en febrero de 2022, a los 57. Entrada: Sweet Oblivion.", origin: "rec", p: 3, y: 1985, via: "Alt Metal general", c: 2 },
  { name: "Hum", genre: "Alt Metal / Space Rock (US)", desc: "El tono de guitarra es tan denso que funciona como armonía en sí mismo, con melodías limpias flotando encima y la batería muy atrás. Inlet salió por sorpresa en junio de 2020, veintidós años después del anterior. Entrada: You Would Prefer an Astronaut.", origin: "rec", p: 2, y: 1989, via: "Alt Metal general", c: 2 },
  { name: "Clutch", genre: "Stoner Rock (US)", desc: "Neil Fallon canta como si predicara sobre riffs de blues pesado en compases que se desplazan, y llevan treinta años sin repetir disco. Entrada: Blast Tyrant.", origin: "rec", p: 2, y: 1991, via: "Alt Metal general", c: 2 },
  { name: "Incubus", genre: "Alt Metal / Funk (US)", desc: "Los primeros discos meten platos de DJ, didgeridoo y pipa dentro del alt metal, con Mike Einziger escribiendo partes de guitarra poco convencionales. Entrada: Morning View.", origin: "rec", p: 3, y: 1991, via: "Alt Metal general", c: 2 },
  { name: "Colour Haze", genre: "Stoner Rock (DE)", desc: "Alemanes. Stoner con armonía modal y desarrollo largo, tocado como un trío de jazz-rock más que como banda de riffs, y grabado en analógico sin recortar. Entrada: All.", origin: "rec", p: 2, y: 1994, via: "Alt Metal general", c: 2 },
  { name: "Causa Sui", genre: "Stoner Rock / Jam (DK)", desc: "Daneses, instrumentales, con piezas que se estiran y cambian de sección sin corte, entre el jam y la composición escrita. Entrada: Summer Sessions.", origin: "rec", p: 3, y: 2005, via: "Alt Metal general", c: 2 },
  { name: "Blood Ceremony", genre: "Occult Rock (CA)", desc: "La flauta de Alia O'Brien lleva líneas principales dentro del rock oculto, no adorna, y el órgano hace el trabajo armónico en lugar de la guitarra. Canadienses. Entrada: The Eldritch Dark.", origin: "rec", p: 2, y: 2006, via: "Alt Metal general", c: 2, female: true },
  { name: "The Devil's Blood", genre: "Occult Rock (NL)", desc: "Holandeses. Dos guitarras armonizadas en terceras y voz femenina sobre rock oculto de los setenta, con temas que se alargan hasta los diez minutos. Selim Lemouchi murió en 2014, a los 33, y la banda terminó. Entrada: The Thousandfold Epicentre.", origin: "rec", p: 3, y: 2006, via: "Alt Metal general", c: 2, female: true },
  { name: "Monster Magnet", genre: "Stoner Rock (US)", desc: "Space rock pesado con capas de efectos y temas que se alargan sin prisa, más cerca de Hawkwind que del rock alternativo de su época. Entrada: Dopes to Infinity.", origin: "rec", p: 3, y: 1989, via: "Alt Metal general", c: 2 },
  { name: "Stone Temple Pilots", genre: "Grunge / Alt Rock (US)", desc: "Los hermanos DeLeo escriben con más armonía de la que el género pedía, con cambios de acorde que no son los esperables, y cambian de paleta entre discos. Entrada: Purple.", origin: "rec", p: 3, y: 1989, via: "Alt Metal general", c: 2 },
  { name: "Fu Manchu", genre: "Stoner Rock (US)", desc: "Stoner directo con el fuzz como material principal y riffs que se repiten hasta volverse hipnóticos. Entrada: The Action Is Go.", origin: "rec", p: 3, y: 1985, via: "Alt Metal general", c: 2 },
  { name: "Mudhoney", genre: "Grunge (US)", desc: "Fuzz saturado hasta el borde y sentido del humor: el grunge antes de que nadie lo puliera para la radio. Entrada: Superfuzz Bigmuff.", origin: "rec", p: 3, y: 1988, via: "Alt Metal general", c: 2 },
  { name: "All Them Witches", genre: "Stoner Rock / Psych (US)", desc: "Base de jam con estructuras que se deciden sobre la marcha, y un bajo muy protagonista que lleva la melodía cuando la guitarra se va a textura. Entrada: Sleeping Through the War.", origin: "rec", p: 3, y: 2012, via: "Alt Metal general", c: 2 }
];

const SE_GEN_2026 = [
  { name: "Drexciya", genre: "Techno Electronico (US)", desc: "Techno de Detroit construido alrededor de una mitología completa, con tracks deliberadamente crudos y solo de máquina, sin voz ni concesiones melódicas: la textura del sintetizador barato es el material. Entrada: Neptunes Lair.", origin: "rec", p: 3, y: 1989, via: "Synth general", c: 1 },
  { name: "Venetian Snares", genre: "Breakcore Electronico (CA)", desc: "Breakcore en 7/4 durante discos enteros, con samples de cuerda clásica cortados y recolocados dentro de esa métrica y breaks troceados a nivel de milisegundo. Escucha muy exigente. Entrada: Rossz Csillag Alatt Szuletett.", origin: "rec", p: 3, y: 1997, via: "Synth general", c: 1 },
  { name: "Holly Herndon", genre: "Electronic Vocal (US)", desc: "PROTO está hecho con una red neuronal entrenada con las voces de su propio ensemble, que canta junto a ellos: el sistema forma parte de la obra y no solo del proceso. Entrada: PROTO.", origin: "rec", p: 3, y: 2012, via: "Synth general", c: 1, female: true },
  { name: "Manuel Göttsching", genre: "Electronic / Krautrock (DE)", desc: "E2-E4 son cincuenta y ocho minutos improvisados sobre una única secuencia que no cambia, con la guitarra entrando y saliendo por encima durante toda la pieza. Murió el 4 de diciembre de 2022, a los 70. Entrada: E2-E4.", origin: "rec", p: 2, y: 1970, via: "Synth general", c: 1 },
  { name: "Ryoji Ikeda", genre: "Electronic Minimal (JP)", desc: "Compone con tonos sinusoidales y clics en el límite de lo audible: el material es la frecuencia misma, no la melodía. Japonés. Escucha durísima. Entrada: Dataplex.", origin: "rec", p: 3, y: 1995, via: "Synth general", c: 1 },
  { name: "Éliane Radigue", genre: "Electronic Drone (FR)", desc: "Piezas de una hora hechas en un ARP 2500, al que llamaba Jules, que cambian tan despacio que no percibes la transición mientras ocurre. Desde 2001 escribió sobre todo para instrumentos acústicos. Murió el 23 de febrero de 2026, a los 94. Entrada: Trilogie de la Mort.", origin: "rec", p: 3, y: 1970, via: "Synth general", c: 1, female: true },
  { name: "Boards of Canada", genre: "Electronic / Ambient (UK)", desc: "Usan cinta desafinada y con fluctuación como material armónico, así que la afinación va derivando dentro del tema y produce esa sensación de recuerdo deformado. Escoceses. Entrada: Music Has the Right to Children.", origin: "rec", p: 2, y: 1986, via: "Synth general", c: 2 },
  { name: "Oneohtrix Point Never", genre: "Electronic (US)", desc: "Daniel Lopatin cambia de sistema cada disco, del arpegio analógico de Replica al collage de muestras de Garden of Delete: lo constante es que nunca repite método. Entrada: R Plus Seven.", origin: "rec", p: 2, y: 2007, via: "Synth general", c: 2 },
  { name: "Burial", genre: "Electronic / Dubstep (UK)", desc: "La percusión va deliberadamente fuera de cuadrícula, colocada a mano, y las voces están cortadas y repitcheadas hasta perder el sexo y las palabras. El ruido de vinilo y de lluvia forma parte del arreglo. Entrada: Untrue.", origin: "rec", p: 2, y: 2005, via: "Synth general", c: 2 },
  { name: "Tangerine Dream", genre: "Electronic / Berlin School (DE)", desc: "Secuenciadores en forma larga: piezas de veinte minutos donde el patrón se transforma por capas que entran y salen, sin batería ni estructura de canción. Entrada: Phaedra.", origin: "rec", p: 2, y: 1967, via: "Synth general", c: 2 },
  { name: "Klaus Schulze", genre: "Electronic / Berlin School (DE)", desc: "Piezas de treinta minutos construidas sobre secuencias que se desfasan entre sí, con capas de sintetizador que crecen muy despacio. Entrada: Timewind.", origin: "rec", p: 3, y: 1969, via: "Synth general", c: 2 },
  { name: "Amon Tobin", genre: "Electronic / Breakbeat (BR)", desc: "Brasileño. Diseño de sonido intrincado sobre breakbeats troceados, con fuentes grabadas por él mismo y procesadas hasta que no se reconocen. Entrada: Supermodified.", origin: "rec", p: 2, y: 1996, via: "Synth general", c: 2 },
  { name: "Kaitlyn Aurelia Smith", genre: "Synth Modular (US)", desc: "Compone en un Buchla modular, un sistema sin teclado donde la altura se decide con voltajes, así que las melodías salen de patrones y no de tocar notas. Entrada: The Kid.", origin: "rec", p: 3, y: 2012, via: "Synth general", c: 2, female: true },
  { name: "Four Tet", genre: "Electronic (UK)", desc: "Kieran Hebden construye con samples acústicos, sobre todo percusión y arpa, cortados y repetidos hasta formar melodía, con estructuras que crecen por acumulación. Entrada: Rounds.", origin: "rec", p: 2, y: 1997, via: "Synth general", c: 2 },
  { name: "Daft Punk", genre: "Electronic / House (FR)", desc: "Cada disco es otro sistema: Homework es house crudo de caja de ritmos, Discovery está hecho de samples de los setenta filtrados, y Random Access Memories lo grabaron con músicos de sesión en directo. Entrada: Discovery.", origin: "rec", p: 2, y: 1993, via: "Synth general", c: 2 },
  { name: "Laurie Spiegel", genre: "Electronic (US)", desc: "Programaba su propio software de composición y lo usaba como instrumento: el sistema genera el material y ella lo dirige y lo filtra. Entrada: The Expanding Universe.", origin: "rec", p: 3, y: 1969, via: "Synth general", c: 2, female: true },
  { name: "Actress", genre: "Electronic / Techno (UK)", desc: "Techno degradado a propósito: las fuentes suenan como si la grabación estuviera dañada, y esa suciedad es la textura con la que compone. Entrada: Splazsh.", origin: "rec", p: 3, y: 2004, via: "Synth general", c: 2 },
  { name: "Pan Sonic", genre: "Electronic Minimal (FI)", desc: "Finlandeses. Pulsos y tonos puros con silencios largos y sin nada de relleno, tocados con una crudeza casi física. Muy áspero. Entrada: Kulma.", origin: "rec", p: 3, y: 1993, via: "Synth general", c: 2 }
];

